INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10577, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照一定的目的、任务和形式，把分散的人或事物组合成一个整体。", "primary_collocate": null, "pronunciation": "zǔ zhī", "ipa": "tsu˨˩˦ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他把大家组织起来，成立了一个小组。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把力量组织起来。", "target_word": "组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理组织了一支新队伍。", "target_word": "组织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很会组织语言，说话很清楚。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们组织一下这些材料。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们组织起来，要求提高工资。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这些想法组织成一篇文章。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把分散的农民组织起来种地。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要组织好这么多人，不太容易。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察组织人员在山上找孩子。", "target_word": "组织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "组织了", "label": "体标"}, {"form": "组织过", "label": "体标"}, {"form": "组织者", "label": "复合"}, {"form": "組織", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把分散的人或事物按目的组合成整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929f630-bb3e-4acd-8c80-d8e8929653e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10577, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "组织", "is_correct": true, "explanation": "正确：“组织起来”表示把分散的人组合在一起，与“成立了一个小组”相符。"}, {"text": "分散", "is_correct": false, "explanation": "语义：“分散”表示使人或事物散开，与“成立小组”的意思相反。"}, {"text": "拆散", "is_correct": false, "explanation": "语义：“拆散”指打散已有的整体，与“成立”矛盾。"}, {"text": "解散", "is_correct": false, "explanation": "搭配：“解散”不能与“大家……起来”的结构搭配，且与“成立小组”相冲突。"}], "explanations": {"组织": "正确：“组织起来”表示把分散的人组合在一起，与“成立了一个小组”相符。", "分散": "语义：“分散”表示使人或事物散开，与“成立小组”的意思相反。", "拆散": "语义：“拆散”指打散已有的整体，与“成立”矛盾。", "解散": "搭配：“解散”不能与“大家……起来”的结构搭配，且与“成立小组”相冲突。"}, "sentence_index": 0, "correct_answer": "组织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他组织了一碗面条。", "explanation": "这里应该用〈煮〉。“组织”指把分散的人或事物组合成整体，煮面条要用“煮”。"}, {"text": "工人组织了那台机器。", "explanation": "这里应该用〈组装〉。“组织”用于人或分散的事物，把零件装成机器要用“组装”。"}, {"text": "他组织了那辆自行车。", "explanation": "这里应该用〈修理〉。“组织”不用于修理东西，把自行车修好要用“修理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组织", "is_correct": true, "explanation": "正确：“组织成一篇文章”指把零散的想法合成文章，与句意相符。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆成一篇文章”与“想法合成文章”的意思相反。"}, {"text": "删", "is_correct": false, "explanation": "语义：“删”是去掉内容，不能把想法变成一篇文章。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎想法”不能与“成一篇文章”搭配。"}], "explanations": {"组织": "正确：“组织成一篇文章”指把零散的想法合成文章，与句意相符。", "拆": "语义：“拆成一篇文章”与“想法合成文章”的意思相反。", "删": "语义：“删”是去掉内容，不能把想法变成一篇文章。", "打碎": "搭配：“打碎想法”不能与“成一篇文章”搭配。"}, "sentence_index": 6, "correct_answer": "组织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们组织了一座房子。", "explanation": "这里应该用〈建造〉。“组织”指把人或分散的事物组合成整体，盖房子要用“建造”。"}, {"text": "他组织了一杯咖啡。", "explanation": "这里应该用〈冲〉。“组织”指把分散的人或事物组合成整体，冲咖啡要用“冲”。"}, {"text": "我们组织了一扇窗户。", "explanation": "这里应该用〈擦〉。“组织”不用于清洁物体，擦窗户要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想把大家组织下来。", "corrected_sentence": "他想把大家组织起来。", "error_description": "补语错误：“组织”后的趋向补语应为“起来”，表示把分散的人聚到一起，不能用“下来”。应改为“他想把大家组织起来。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察把组织了人员在山上找孩子。", "corrected_sentence": "警察组织了人员在山上找孩子。", "error_description": "“把”字误加：“组织了人员”中动词“组织”前不能加“把”，“把”字句要求“把”后接受事再接动词，这里应删去“把”。正确说法是“警察组织了人员在山上找孩子。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
