INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10578, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由私人投资、经营，不属于国家的企业。", "primary_collocate": null, "pronunciation": "sī yíng qǐ yè", "ipa": "sɹ̩˥ iŋ˧˥ tɕʰi˨˩˦ je˥˩", "syllable_count": 4, "sentences": [{"text": "近年来，一些国际组织与私营企业开始推动数字化农业解决方案，如卫星遥感监测、区块链溯源与移动支付平台，以增强供应链透明度与韧性。", "target_word": "私营企业", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在一家私营企业工作。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家私营企业有五十个员工。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "私营企业的老板是我舅舅。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他父亲经营的私营企业规模很大。", "target_word": "私营企业", "complexity_tier": "T3", "furigana": "tā fùqīn jīngyíng de sī yíng qǐ yè guīmó hěn dà.", "sentence_source": "generated"}, {"text": "她毕业后想去私营企业上班。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家私营企业是三年前开的。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "私营企业需要自己找钱。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸开了一家私营企业。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国有企业和私营企业，你想去哪个？", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "私营企业主", "label": "复合"}, {"form": "私營企業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "私人投资经营、不属于国家的企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929f630-bb3e-4acd-8c80-d8e8929653e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "私营企业", "is_correct": true, "explanation": "正确：句中是“与……推动”的并列主语，指私人投资经营的企业，与“国际组织”并列合理。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作“推动”的主体。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是植物，不能与国际组织并列去推动解决方案。"}, {"text": "小吃", "is_correct": false, "explanation": "搭配：“推动”的施事是机构或人，“小吃”不能与“国际组织”并列作施事。"}], "explanations": {"私营企业": "正确：句中是“与……推动”的并列主语，指私人投资经营的企业，与“国际组织”并列合理。", "天气": "语义：天气是自然现象，不能作“推动”的主体。", "蔬菜": "语义：蔬菜是植物，不能与国际组织并列去推动解决方案。", "小吃": "搭配：“推动”的施事是机构或人，“小吃”不能与“国际组织”并列作施事。"}, "sentence_index": 0, "correct_answer": "私营企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只私营企业是我朋友的。", "explanation": "这里应该用〈家〉。企业这类机构用量词“家”，不用“只”。"}, {"text": "我哥哥是私营企业，每天很忙。", "explanation": "这里应该用〈私营企业主〉。私营企业指机构，不能指人；指经营者要说私营企业主。"}, {"text": "这家基金会是私营企业，专门资助贫困学生。", "explanation": "这里应该用〈非营利组织〉。基金会不以盈利为目的，不属于企业，不能说私营企业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "私营企业", "is_correct": true, "explanation": "正确：私营企业是个人出资开办的企业，与“开”“这家”搭配，句意通顺。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不能被“开”，也不是店铺或公司。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：量词“家”用于店铺、公司，河流应用“条”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能被“开”，也不是机构。"}], "explanations": {"私营企业": "正确：私营企业是个人出资开办的企业，与“开”“这家”搭配，句意通顺。", "学生": "语义：学生是人，不能被“开”，也不是店铺或公司。", "河流": "搭配：量词“家”用于店铺、公司，河流应用“条”。", "书": "语义：书不能被“开”，也不是机构。"}, "sentence_index": 6, "correct_answer": "私营企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我叔叔开了一座私营企业，生意很好。", "explanation": "这里应该用〈家〉。企业用量词“家”，“座”用于建筑、桥梁等，不用于企业。"}, {"text": "我们厂是私营企业，属于国家，由政府管理。", "explanation": "这里应该用〈国有企业〉。私营企业由私人出资经营，不能说属于国家。"}, {"text": "他小时候在私营企业上学。", "explanation": "这里应该用〈私立学校〉。“私营”用于企业，学校、医院应说“私立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我舅舅在一本私营企业当经理。", "corrected_sentence": "我舅舅在一家私营企业当经理。", "error_description": "量词错误：“企业”应用量词“家”，“本”只用于书册。错误在“一本”，应改为“一家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我表哥一家私营企业工作。", "corrected_sentence": "我表哥在一家私营企业工作。", "error_description": "介词错误：处所宾语“一家私营企业”前缺少介词“在”。错误在漏掉“在”，应改为“我表哥在一家私营企业工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
