INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10579, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指将信息、流程或事物转换成计算机可以识别和处理的数字形式。", "primary_collocate": null, "pronunciation": "shù zì huà", "ipa": "ʂu˥˩ tsɨ˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "在全球化与数字化的当代，尽管书面记录与影像媒介主导了信息传播，口头叙事并未消亡，而是以新的形态回归：播客、口述史项目、非物质文化遗产保护运动，皆可视作对原始交流模式的现代回响。", "target_word": "数字化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "近年来，一些国际组织与私营企业开始推动数字化农业解决方案，如卫星遥感监测、区块链溯源与移动支付平台，以增强供应链透明度与韧性。", "target_word": "数字化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "数字化让我们的生活越来越方便。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的数字化做得很好。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字化改变了人们买东西的方式。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的数字化让人不用去柜台排队。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学校的数字化需要很多钱。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在数字化的今天，纸质书还有人买。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的数字化工作已经开始了。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字化给小商店带来了新的机会。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数字化转型", "label": "复合"}, {"form": "数字化时代", "label": "复合"}], "register": "中性", "sense_fingerprint": "数字化:信息或事物转为计算机可处理的数字形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e4321f-de6e-46a4-8743-02c784fb0964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10579, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数字化", "is_correct": true, "explanation": "正确：“全球化与数字化的当代”把两种时代趋势并列，与整段讲信息传播的语境相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：全球化与天气并列不成立，天气不是这段话讨论的时代特征。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是一个空间，不能与“全球化”并列作为时代的特征，句意讲不通。"}, {"text": "烂摊子", "is_correct": false, "explanation": "语域：“烂摊子”口语化，与这段学术化的评论语体不合，也不能和“全球化”并列。"}], "explanations": {"数字化": "正确：“全球化与数字化的当代”把两种时代趋势并列，与整段讲信息传播的语境相合。", "天气": "语义：全球化与天气并列不成立，天气不是这段话讨论的时代特征。", "厨房": "语义：厨房是一个空间，不能与“全球化”并列作为时代的特征，句意讲不通。", "烂摊子": "语域：“烂摊子”口语化，与这段学术化的评论语体不合，也不能和“全球化”并列。"}, "sentence_index": 0, "correct_answer": "数字化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这份表格里的数字化全部删掉了。", "explanation": "这里应该用〈数据〉。数字化指转换为数字形式的过程，不指表格里的数据本身。"}, {"text": "这个算式算出的数字化太大，计算机算不出来。", "explanation": "这里应该用〈结果〉。数字化指转换为数字形式的过程，不指算出的结果。"}, {"text": "他很快记住了这个数字化。", "explanation": "这里应该用〈号码〉。数字化指转换为数字形式的过程，不指要记住的具体号码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10579, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字化", "is_correct": true, "explanation": "正确：“学校的数字化需要很多钱”指学校在信息化方面的投入，与句意相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：学校的天气不是需要花钱的对象，句意讲不通。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠是大片干旱的地域，不能作为学校需要花钱的对象，句意讲不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人或物的高矮外形，与学校需要多少钱的语境无关。"}], "explanations": {"数字化": "正确：“学校的数字化需要很多钱”指学校在信息化方面的投入，与句意相合。", "天气": "语义：学校的天气不是需要花钱的对象，句意讲不通。", "沙漠": "语义：沙漠是大片干旱的地域，不能作为学校需要花钱的对象，句意讲不通。", "身高": "体貌：“身高”指人或物的高矮外形，与学校需要多少钱的语境无关。"}, "sentence_index": 6, "correct_answer": "数字化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让我们背住那些数字化。", "explanation": "这里应该用〈数字〉。数字化指转换为数字形式的过程，不指要背的具体数目。"}, {"text": "这个数字化是加号。", "explanation": "这里应该用〈符号〉。数字化指转换为数字形式的过程，不是加号这样的符号。"}, {"text": "这辆旧自行车数字化了一下，骑起来很轻松。", "explanation": "这里应该用〈修理〉。数字化指转换为数字形式的过程，不能用来指修理实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的数字化了做得很好，效率提高了很多。", "corrected_sentence": "这家公司的数字化做得很好，效率提高了很多。", "error_description": "“了”位置错误。“了”不能放在名词“数字化”之后、动词“做”之前，应删去，说“这家公司的数字化做得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校已经旧资料数字化了。", "corrected_sentence": "学校已经把旧资料数字化了。", "error_description": "句式错误。这里“数字化”作动词用，被处理的对象“旧资料”要用“把”提到动词前，说“把旧资料数字化了”；漏掉“把”，“学校已经旧资料”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
