INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "针对某个问题或困难所制定的具体办法或措施。", "primary_collocate": null, "pronunciation": "jiě jué fāng àn", "ipa": "tɕje˨˩˦ tɕɥe˧˥ faŋ˥ an˥˩", "syllable_count": 4, "sentences": [{"text": "近年来，一些国际组织与私营企业开始推动数字化农业解决方案，如卫星遥感监测、区块链溯源与移动支付平台，以增强供应链透明度与韧性。", "target_word": "解决方案", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "经理想出了一个解决方案。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题还没有解决方案。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们需要更好的解决方案。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给客户提供了一套解决方案。", "target_word": "解决方案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家提出了三个解决方案。", "target_word": "解决方案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么解决方案吗？", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个解决方案又快又便宜。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在讨论解决方案。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请大家写出解决方案。", "target_word": "解决方案", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "解決方案", "label": "繁体"}], "register": "中性", "sense_fingerprint": "针对具体问题制定的办法或措施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929f630-bb3e-4acd-8c80-d8e8929653e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解决方案", "is_correct": true, "explanation": "正确：“推动数字化农业”之后接的是针对问题的具体办法，只有“解决方案”合适。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“推动”的对象应是计划或办法，不能接“海洋”这类自然事物。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不能被“推动”去解决农业问题。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能作为“推动”的对象。"}], "explanations": {"解决方案": "正确：“推动数字化农业”之后接的是针对问题的具体办法，只有“解决方案”合适。", "海洋": "搭配：“推动”的对象应是计划或办法，不能接“海洋”这类自然事物。", "小说": "语义：小说是文学作品，不能被“推动”去解决农业问题。", "咖啡": "语义：咖啡是饮品，不能作为“推动”的对象。"}, "sentence_index": 0, "correct_answer": "解决方案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想出了一只解决方案。", "explanation": "这里应该用〈个〉。“解决方案”用量词“个”或“套”，不用“只”。"}, {"text": "这个问题是一个很大的解决方案。", "explanation": "这里应该用〈难题〉。“解决方案”指解决问题的办法，问题本身要说难题。"}, {"text": "这道数学题的解决方案是三十二。", "explanation": "这里应该用〈答案〉。解决方案指针对问题的办法，数值结果要说答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解决方案", "is_correct": true, "explanation": "正确：“你有什么”后接的是可以拥有的、针对问题的办法，只有“解决方案”合适。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“有”后不接“年龄”，应问“你多大年龄”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景象，不能说“你有什么天空”。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是时间单位，不能作为“有”的宾语来问。"}], "explanations": {"解决方案": "正确：“你有什么”后接的是可以拥有的、针对问题的办法，只有“解决方案”合适。", "年龄": "搭配：“有”后不接“年龄”，应问“你多大年龄”。", "天空": "语义：天空是自然景象，不能说“你有什么天空”。", "星期": "语义：星期是时间单位，不能作为“有”的宾语来问。"}, "sentence_index": 6, "correct_answer": "解决方案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项研究的解决方案表明地球在变暖。", "explanation": "这里应该用〈结论〉。“表明”后接的是结论，解决方案是针对问题的办法，不能表明事实。"}, {"text": "这杯盐水是盐的解决方案。", "explanation": "这里应该用〈溶液〉。化学上盐溶于水形成的混合液叫溶液，“解决方案”指针对问题的办法。"}, {"text": "我们这个周末的解决方案排得很满。", "explanation": "这里应该用〈计划〉。“解决方案”针对问题，安排日程要说计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们想出了两本解决方案。", "corrected_sentence": "他们想出了两个解决方案。", "error_description": "量词错误：“解决方案”用“个”或“套”，“本”用于书册。错误在“两本”，应改为“两个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们找到了这些解决方案们。", "corrected_sentence": "我们找到了这些解决方案。", "error_description": "词缀错误：“们”只用于指人，不能加在无生命名词“解决方案”后。错误在“解决方案们”，应改为“这些解决方案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
