INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10581, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "围绕行星运行的天体，包括天然卫星和人造卫星。", "primary_collocate": null, "pronunciation": "wèi xīng", "ipa": "weɪ˥˩ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "月球是地球的一颗卫星。", "target_word": "卫星", "complexity_tier": "T3", "furigana": "yuè qiú shì dì qiú de yì kē wèi xīng", "sentence_source": "generated"}, {"text": "木星有很多颗卫星。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国又向太空发射了一颗新卫星。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那颗卫星正在绕着地球飞行。", "target_word": "卫星", "complexity_tier": "T3", "furigana": "nà kē wèi xīng zhèng zài rào zhe dì qiú fēi xíng", "sentence_source": "generated"}, {"text": "天气预报常用卫星拍的云图。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗卫星在太空里已经工作了十年。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土星的卫星比地球的多很多。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机地图靠卫星知道你在哪儿。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用望远镜发现了一颗小卫星。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗卫星让山里的人也能上网。", "target_word": "卫星", "complexity_tier": "T3", "furigana": "zhè kē wèi xīng ràng shān lǐ de rén yě néng shàng wǎng", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "人造卫星", "label": "复合"}, {"form": "通信卫星", "label": "复合"}, {"form": "衛星", "label": "繁体"}], "register": "中性", "sense_fingerprint": "围绕行星运行的天体；天然卫星与人造卫星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac8efc8-1461-4dce-be40-9987f9ef42b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行星", "is_correct": false, "explanation": "语义：行星是绕太阳运行的天体，月球绕的是地球，不能说是地球的行星。"}, {"text": "卫星", "is_correct": true, "explanation": "“卫星”指围绕行星运行的天体，月球是地球的天然卫星，量词“颗”可用。"}, {"text": "恒星", "is_correct": false, "explanation": "语义：恒星自身发光，月球本身不发光，不能说是恒星。"}, {"text": "流星", "is_correct": false, "explanation": "语义：流星是大气中燃烧的流星体，不绕行星运行，月球不能说是地球的流星。"}], "explanations": {"行星": "语义：行星是绕太阳运行的天体，月球绕的是地球，不能说是地球的行星。", "卫星": "“卫星”指围绕行星运行的天体，月球是地球的天然卫星，量词“颗”可用。", "恒星": "语义：恒星自身发光，月球本身不发光，不能说是恒星。", "流星": "语义：流星是大气中燃烧的流星体，不绕行星运行，月球不能说是地球的流星。"}, "sentence_index": 0, "correct_answer": "卫星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火星是太阳系的一颗卫星。", "explanation": "这里应该用〈行星〉。卫星是绕行星运转的天体，火星本身绕太阳运行，是行星，不是卫星。"}, {"text": "他是这个国家的卫星，负责保卫首都。", "explanation": "这里应该用〈卫士〉。卫星指绕行星运转的天体，负责保卫的人要用〈卫士〉。"}, {"text": "我们乘坐卫星去月球旅行。", "explanation": "这里应该用〈飞船〉。卫星是绕行星运转的天体，不载人，去月球要乘坐〈飞船〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星星", "is_correct": false, "explanation": "语义：“星星”是对夜空中发光天体的笼统叫法，不表示“绕某颗行星运行的天体”，不能说“土星的星星”。"}, {"text": "星球", "is_correct": false, "explanation": "语义：“星球”指像土星这样的行星本身，不是土星的卫星。"}, {"text": "月球", "is_correct": false, "explanation": "搭配：“月球”专指地球的卫星，不能说“土星的月球”。"}, {"text": "卫星", "is_correct": true, "explanation": "“卫星”指绕行星运行的天体，土星的卫星数量多于地球，符合句意。"}], "explanations": {"星星": "语义：“星星”是对夜空中发光天体的笼统叫法，不表示“绕某颗行星运行的天体”，不能说“土星的星星”。", "星球": "语义：“星球”指像土星这样的行星本身，不是土星的卫星。", "月球": "搭配：“月球”专指地球的卫星，不能说“土星的月球”。", "卫星": "“卫星”指绕行星运行的天体，土星的卫星数量多于地球，符合句意。"}, "sentence_index": 6, "correct_answer": "卫星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太阳是离我们最近的卫星。", "explanation": "这里应该用〈恒星〉。太阳本身是恒星，卫星是绕行星运转的天体，不能用来称呼太阳。"}, {"text": "黑洞是一种很神秘的卫星。", "explanation": "这里应该用〈天体〉。卫星特指绕行星运转的天体，黑洞不绕行星运转，不能称为卫星。"}, {"text": "这颗卫星是我们班的新同学。", "explanation": "这里应该用〈同学〉。卫星指绕行星运转的天体，班里的新成员要说〈同学〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们看到一只卫星在天上飞。", "corrected_sentence": "我们看到一颗卫星在天上飞。", "error_description": "错误：“一只卫星”；正确：“一颗卫星”。“只”用于动物或成对物件中的一个，卫星要用量词“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "土星有很多卫星们。", "corrected_sentence": "土星有很多卫星。", "error_description": "错误：“卫星们”；正确：“卫星”。“们”只用于指人的名词或代词，卫星这类事物名词后不加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
