INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遥感是指在不直接接触目标物体的情况下，通过传感器远距离探测和识别物体信息的技术。", "primary_collocate": null, "pronunciation": "yáo gǎn", "ipa": "jaʊ˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "近年来，一些国际组织与私营企业开始推动数字化农业解决方案，如卫星遥感监测、区块链溯源与移动支付平台，以增强供应链透明度与韧性。", "target_word": "遥感", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "生态学家近年来通过高分辨率遥感数据与基因追踪技术，对蜜蜂的觅食路径、种群遗传结构及其与植物网络的互动关系展开了系统性研究。", "target_word": "遥感", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "遥感卫星在天上拍地面的照片。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用遥感看森林有没有变少。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遥感可以帮农民知道哪块地缺水。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张地图是用遥感做出来的。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震以后，人们用遥感找到了受灾的地方。", "target_word": "遥感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里学习遥感，想研究海洋。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在，遥感能让我们看见很远的冰山。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气预报也会用到遥感的数据。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遥感技术", "label": "复合"}, {"form": "遥感卫星", "label": "复合"}], "register": "书面", "sense_fingerprint": "遥感：用传感器远距离探测物体信息的技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遥感", "is_correct": true, "explanation": "“遥感”是远距离探测技术，与“卫星……监测”搭配，指用卫星探测农业信息。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：“乐趣”指愉快的感受，不能用来做“卫星”的修饰成分去监测。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“风景”指景色，“卫星风景监测”说不通。"}, {"text": "口号", "is_correct": false, "explanation": "搭配：“监测”的对象是可以测量的数据或状况，不说“监测口号”。"}], "explanations": {"遥感": "“遥感”是远距离探测技术，与“卫星……监测”搭配，指用卫星探测农业信息。", "乐趣": "语义：“乐趣”指愉快的感受，不能用来做“卫星”的修饰成分去监测。", "风景": "语义：“风景”指景色，“卫星风景监测”说不通。", "口号": "搭配：“监测”的对象是可以测量的数据或状况，不说“监测口号”。"}, "sentence_index": 0, "correct_answer": "遥感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对远方的家乡有一种很强的遥感。", "explanation": "这里应该用〈思念〉。“遥感”是技术名词，指远距离探测，不指人对远方的感受；表达对远方的感情要用“思念”。"}, {"text": "我每天用遥感刷牙。", "explanation": "这里应该用〈牙刷〉。“遥感”是远距离探测物体信息的技术，不是刷牙的工具；刷牙要用牙刷。"}, {"text": "他很会遥感别人的心事。", "explanation": "这里应该用〈猜〉。“遥感”指用传感器远距离探测物体信息的技术，不能用来读取别人的心事；猜测别人的心事要用“猜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遥感", "is_correct": true, "explanation": "“遥感”指远距离探测，正好说明地震后用什么手段找到受灾地方。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格，不是找受灾地方的手段。"}, {"text": "长相", "is_correct": false, "explanation": "语义：“长相”指人的外貌，不是寻找受灾地方的手段。"}, {"text": "酒量", "is_correct": false, "explanation": "搭配：“用……找到”要用技术或方法，“酒量”是人的饮酒能力，不搭配。"}], "explanations": {"遥感": "“遥感”指远距离探测，正好说明地震后用什么手段找到受灾地方。", "脾气": "语义：“脾气”指性格，不是找受灾地方的手段。", "长相": "语义：“长相”指人的外貌，不是寻找受灾地方的手段。", "酒量": "搭配：“用……找到”要用技术或方法，“酒量”是人的饮酒能力，不搭配。"}, "sentence_index": 6, "correct_answer": "遥感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个遥感我用了很多年，能换台。", "explanation": "这里应该用〈遥控〉。“遥感”是探测技术，不是控制电视换台的工具。"}, {"text": "森林到城市的遥感很远。", "explanation": "这里应该用〈距离〉。“遥感”是探测技术的名称，不用来描述距离；说距离远要用“距离”或“远”。"}, {"text": "他有很强的遥感，一眼就猜到了我的想法。", "explanation": "“遥感”是技术名词，不指人的直觉，这里应该用〈直觉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学了一遥感技术。", "corrected_sentence": "我们学了一种遥感技术。", "error_description": "错误：“一遥感技术”；正确：“一种遥感技术”。数量短语“一”后面必须有量词，“遥感技术”前应加量词“种”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们用一台遥感技术观察海洋。", "corrected_sentence": "我们用一种遥感技术观察海洋。", "error_description": "错误：“一台遥感技术”；正确：“一种遥感技术”。“遥感技术”是技术，应用量词“种”，不用“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
