INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10583, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "持续监视、检测或跟踪某人、某物或某种情况，以便及时了解其状态或变化。", "primary_collocate": null, "pronunciation": "jiān cè", "ipa": "tɕjɛn˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "医生在监测病人的心跳。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天监测河水的变化。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以监测空气的好坏。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们正在监测地震的情况。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表能监测你睡觉的时间。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家监测着这座火山的活动。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有人二十四小时监测着天气。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用仪器监测了他一整夜。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把监测的结果告诉了大家。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "监测显示，今天的空气很好。", "target_word": "监测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "监测着", "label": "体标"}, {"form": "监测了", "label": "体标"}, {"form": "监测过", "label": "体标"}, {"form": "监测站", "label": "复合"}, {"form": "監測", "label": "繁体"}], "register": "中性", "sense_fingerprint": "持续监视检测，以便及时了解状态或变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac8efc8-1461-4dce-be40-9987f9ef42b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忽视", "is_correct": false, "explanation": "语义：医生照看病人，不会“忽视”病人的心跳，句意与医生的职责相反。"}, {"text": "监督", "is_correct": false, "explanation": "搭配：“监督”的对象多是人或工作，不说“监督心跳”。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”需要可供选择的对象，“心跳”不能被挑选。"}, {"text": "监测", "is_correct": true, "explanation": "“监测”指持续检测、跟踪状况的变化，医生用它表示观察病人心跳。"}], "explanations": {"忽视": "语义：医生照看病人，不会“忽视”病人的心跳，句意与医生的职责相反。", "监督": "搭配：“监督”的对象多是人或工作，不说“监督心跳”。", "挑选": "搭配：“挑选”需要可供选择的对象，“心跳”不能被挑选。", "监测": "“监测”指持续检测、跟踪状况的变化，医生用它表示观察病人心跳。"}, "sentence_index": 0, "correct_answer": "监测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在书架上监测那本词典。", "explanation": "这里应该用〈寻找〉。监测是一直观察有没有变化，找东西要用〈寻找〉。"}, {"text": "我出门前监测了一下门锁。", "explanation": "这里应该用〈检查〉。监测指持续跟踪变化，只看一下门锁要用〈检查〉。"}, {"text": "我们坐在操场上监测比赛。", "explanation": "这里应该用〈观看〉。监测是跟踪状况的变化，看比赛要用〈观看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”与句中持续观察天气的意思相反。"}, {"text": "冒犯", "is_correct": false, "explanation": "搭配：“冒犯”的对象是人，不能说冒犯天气。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物等，不说修理天气。"}, {"text": "监测", "is_correct": true, "explanation": "“监测”指持续观察天气变化，与“二十四小时”相符。"}], "explanations": {"逃避": "语义：“逃避”与句中持续观察天气的意思相反。", "冒犯": "搭配：“冒犯”的对象是人，不能说冒犯天气。", "修理": "搭配：“修理”的对象是器物等，不说修理天气。", "监测": "“监测”指持续观察天气变化，与“二十四小时”相符。"}, "sentence_index": 6, "correct_answer": "监测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "记者在监测这件事的真相。", "explanation": "这里应该用〈调查〉。监测多指对客观状况的持续跟踪，查明事件真相要用〈调查〉。"}, {"text": "同学们在礼堂里监测演讲。", "explanation": "这里应该用〈聆听〉。监测是跟踪状况的变化，听演讲要用〈聆听〉。"}, {"text": "他监测了一下自己的书柜。", "explanation": "这里应该用〈整理〉。监测是持续观察状况的变化，收拾书柜要用〈整理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在监测了台风的路径。", "corrected_sentence": "我们正在监测台风的路径。", "error_description": "错误：“正在……了”；正确：“正在监测台风的路径”。“正在”表示动作进行中，与表示完成的“了”冲突，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "气象站每天把监测台风的路径。", "corrected_sentence": "气象站每天监测台风的路径。", "error_description": "错误：「把监测台风的路径」；正确：「监测台风的路径」。「把」后面必须先接宾语，不能直接接动词，应去掉「把」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
