INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10584, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "区块指将事物划分为独立的块状区域，常用于地理、计算机等领域，如区块链中的存储单元。", "primary_collocate": null, "pronunciation": "qū kuài", "ipa": "tɕʰy˥ kʰuai˥˩", "syllable_count": 2, "sentences": [{"text": "在点对点的电力交易中，每一笔交易都会被记录进一个新的区块，供所有参与者查看。", "target_word": "区块", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "新的区块一旦写入，就很难被改动，这让交易记录变得更加可靠。", "target_word": "区块", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "每个区块里都保存着一部分交易记录。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的区块会连在上一个区块后面。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序把数据放进新的区块里保存。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市规划把这里分成了五个区块。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的红色区块表示人很多。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕分成了四个区块，各显示不同内容。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师检查了每个区块的数据有没有错。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地分成了三个区块，卖给不同的公司。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "区块链", "label": "复合"}, {"form": "區塊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "划分出的独立块状区域，尤指区块链中存储数据的单元", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df6c5434-bf82-45b0-9904-96dfe8a36f91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区块", "is_correct": true, "explanation": "“区块”是区块链中存放交易数据的单元，填入“一个新的___”后，与“记录交易”的语境相合。"}, {"text": "食物", "is_correct": false, "explanation": "语义：交易不会被记录进一个“食物”，与句中的数据记录语境不合。"}, {"text": "生态", "is_correct": false, "explanation": "语义：“生态”不是可以存放交易数据的单元，“一个新的生态”与句意不合。"}, {"text": "饲料", "is_correct": false, "explanation": "语义：交易不会被记录进一个“饲料”，与电力交易的数据语境不合。"}], "explanations": {"区块": "“区块”是区块链中存放交易数据的单元，填入“一个新的___”后，与“记录交易”的语境相合。", "食物": "语义：交易不会被记录进一个“食物”，与句中的数据记录语境不合。", "生态": "语义：“生态”不是可以存放交易数据的单元，“一个新的生态”与句意不合。", "饲料": "语义：交易不会被记录进一个“饲料”，与电力交易的数据语境不合。"}, "sentence_index": 0, "correct_answer": "区块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条区块里保存着一部分交易记录。", "explanation": "这里应该用〈个〉。区块作为划分出的单位，量词用“个”；“条”用于长条形的事物，不用于区块。"}, {"text": "我把照片都存进了电脑里的一个区块夹。", "explanation": "这里应该用〈文件夹〉。电脑里存放文件的地方叫文件夹；“区块”指划分出的单元或区域，没有“区块夹”的说法。"}, {"text": "屏幕上掉下来一个个彩色区块。", "explanation": "这里应该用〈方块〉。方块指小而方的块状物，如游戏中掉落的图形；区块指划分出的区域，不用于单个小物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区块", "is_correct": true, "explanation": "“红色区块”指地图上标出的一块区域，表示此处人很多，与句意相合。"}, {"text": "按钮", "is_correct": false, "explanation": "语义：地图上不会用红色按钮来表示人口密度，“按钮”与句中的地图语境不合。"}, {"text": "标题", "is_correct": false, "explanation": "语义：标题是文字的题目，不能在地图上表示人多。"}, {"text": "语气", "is_correct": false, "explanation": "搭配：“红色”不修饰“语气”这类抽象的说话方式，“地图上的红色语气”不成立。"}], "explanations": {"区块": "“红色区块”指地图上标出的一块区域，表示此处人很多，与句意相合。", "按钮": "语义：地图上不会用红色按钮来表示人口密度，“按钮”与句中的地图语境不合。", "标题": "语义：标题是文字的题目，不能在地图上表示人多。", "语气": "搭配：“红色”不修饰“语气”这类抽象的说话方式，“地图上的红色语气”不成立。"}, "sentence_index": 6, "correct_answer": "区块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球上的区块一直在缓慢移动。", "explanation": "这里应该用〈板块〉。板块指地壳中的大块岩石，地质上说“板块运动”；“区块”不用于地壳运动。"}, {"text": "这只区块记录了昨天的交易。", "explanation": "这里应该用〈个〉。“只”用于动物或成对的东西，区块是划分出的单位，量词用“个”。"}, {"text": "工厂的流水线上摆着一批区块，工人一个个检查。", "explanation": "这里应该用〈零件〉。零件是机器的组成部分；“区块”指划分出的区域，不用于机器部件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每条区块都记录着一批交易数据。", "corrected_sentence": "每个区块都记录着一批交易数据。", "error_description": "量词错误：“区块”应搭配量词“个”，写成“每条区块”是错误的，“条”用于长条形的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "物业把小区分成了四条区块。", "corrected_sentence": "物业把小区分成了四个区块。", "error_description": "量词错误：“区块”应搭配量词“个”，不能说“四条区块”，“条”不用于计量区块。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c56a0ea9-c8d7-4fa3-ad4e-ab5f94a36891') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
