INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10586, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变物体的位置或方向。", "primary_collocate": null, "pronunciation": "yí dòng", "ipa": "i˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "请把桌子往左边移动一点。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢移动着椅子。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳在天空中慢慢移动。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要移动这些箱子。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把花盆移动到窗边。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云向东边移动了。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把沙发移动一下，好打扫。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小虫一动不动，没有移动过。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的小点正在向右移动。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别移动那张床，太重了。", "target_word": "移动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移动着", "label": "体标"}, {"form": "移动了", "label": "体标"}, {"form": "移动过", "label": "体标"}, {"form": "移動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使物体的位置或方向发生改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac8efc8-1461-4dce-be40-9987f9ef42b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10586, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "移动", "is_correct": true, "explanation": "正确答案：移动（yí dòng），改变物体的位置。"}, {"text": "易懂", "is_correct": false, "explanation": "易懂（yì dǒng）：yì 与 yí 声调不同，dǒng 与 dòng 声调不同，意思是容易理解。"}, {"text": "一共", "is_correct": false, "explanation": "一共（yí gòng）：gòng 与 dòng 只有声母不同（g 与 d），意思是总共。"}, {"text": "异动", "is_correct": false, "explanation": "异动（yì dòng）：yì 与 yí 声调不同，意思是异常的变动。"}, {"text": "移送", "is_correct": false, "explanation": "移送（yí sòng）：sòng 与 dòng 只有声母不同（s 与 d），意思是转交给有关机关。"}], "explanations": {"移动": "正确答案：移动（yí dòng），改变物体的位置。", "易懂": "易懂（yì dǒng）：yì 与 yí 声调不同，dǒng 与 dòng 声调不同，意思是容易理解。", "一共": "一共（yí gòng）：gòng 与 dòng 只有声母不同（g 与 d），意思是总共。", "异动": "异动（yì dòng）：yì 与 yí 声调不同，意思是异常的变动。", "移送": "移送（yí sòng）：sòng 与 dòng 只有声母不同（s 与 d），意思是转交给有关机关。"}, "sentence_index": null, "correct_answer": "移动"}, "level_3": {"options": [{"text": "移动", "is_correct": true, "explanation": "正确：移动，改变桌子的位置，与「往左边一点」相符。"}, {"text": "拆", "is_correct": false, "explanation": "语义：「拆」是拆开、分解，与挪动桌子的位置无关，句意不通。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：「搬运」多指成批搬运货物，不说把桌子往左边搬运一点。"}, {"text": "抬起", "is_correct": false, "explanation": "语义：「抬起」是向上举起，与「往左边」的水平方向矛盾。"}], "explanations": {"移动": "正确：移动，改变桌子的位置，与「往左边一点」相符。", "拆": "语义：「拆」是拆开、分解，与挪动桌子的位置无关，句意不通。", "搬运": "搭配：「搬运」多指成批搬运货物，不说把桌子往左边搬运一点。", "抬起": "语义：「抬起」是向上举起，与「往左边」的水平方向矛盾。"}, "sentence_index": 0, "correct_answer": "移动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的态度移动了，不再反对我们的计划。", "explanation": "这里应该用〈改变〉。移动指具体物体的位置改变，态度这类抽象的东西要说改变或转变。"}, {"text": "我的心脏移动得很快。", "explanation": "这里应该用〈跳动〉。移动指物体位置的改变，心脏的搏动要说跳动。"}, {"text": "政府移动了大批志愿者去救灾。", "explanation": "这里应该用〈调动〉。移动指物体的位置改变，人员的调派要说调动或抽调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移动", "is_correct": true, "explanation": "正确：移动，把沙发挪动位置，便于打扫。"}, {"text": "固定", "is_correct": false, "explanation": "语义：「固定」是使其不动，与「好打扫」需要挪动沙发的目的矛盾。"}, {"text": "放大", "is_correct": false, "explanation": "语义：「放大」是增大尺寸，沙发不能靠放大来便于打扫，句意不通。"}, {"text": "撞击", "is_correct": false, "explanation": "搭配：「撞击」指猛烈碰撞，不用于为打扫而挪动沙发。"}], "explanations": {"移动": "正确：移动，把沙发挪动位置，便于打扫。", "固定": "语义：「固定」是使其不动，与「好打扫」需要挪动沙发的目的矛盾。", "放大": "语义：「放大」是增大尺寸，沙发不能靠放大来便于打扫，句意不通。", "撞击": "搭配：「撞击」指猛烈碰撞，不用于为打扫而挪动沙发。"}, "sentence_index": 6, "correct_answer": "移动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的病移动了一个星期才好。", "explanation": "这里应该用〈拖〉。移动指物体位置的改变，病情持续的时间要说拖，不能说移动。"}, {"text": "这个月我的体重移动了三公斤。", "explanation": "这里应该用〈增加〉或〈减轻〉。移动指物体位置的改变，体重的变化要说增加或减轻。"}, {"text": "她把注意力移动到了窗外。", "explanation": "这里应该用〈转移〉。移动用于具体物体，注意力这类抽象的东西要说转移。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经把书架移动了到墙边。", "corrected_sentence": "我们已经把书架移动到了墙边。", "error_description": "「了」的位置错误：结果补语「到墙边」之后应接「了」，不能放在「到」之前。正确说法是「移动到了墙边」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人把那张大沙发移动。", "corrected_sentence": "他一个人把那张大沙发移动到了门口。", "error_description": "「把」字句不完整：「把」字句中的动词「移动」不能单独结尾，后面要有补语或「了」等成分，如「移动到了门口」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
