INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10587, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把钱给别人，来换东西或服务。", "primary_collocate": null, "pronunciation": "zhī fù", "ipa": "tʂɻ̩⁵⁵ fu⁵¹", "syllable_count": 2, "sentences": [{"text": "我用手机支付了饭钱。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他支付了这个月的房租。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在三天内支付费用。", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司每月支付工资。", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你可以用现金支付吗？", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们已经支付了修车的钱。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用信用卡支付了机票。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人要先支付押金。", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店不能用微信支付。", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她支付了全部医药费。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "支付了", "label": "体标"}, {"form": "支付方式", "label": "复合"}], "register": "中性", "sense_fingerprint": "把钱交给对方以换取物品或服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac8efc8-1461-4dce-be40-9987f9ef42b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支付", "is_correct": true, "explanation": "正确：支付，把钱交给对方，与「用手机付饭钱」相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是房间、地面等，不能说打扫饭钱。"}, {"text": "借", "is_correct": false, "explanation": "语义：「借」是暂时拿别人的东西，不是把钱给出去。"}, {"text": "领取", "is_correct": false, "explanation": "语义：「领取」是收下发给自己的东西，与「我付饭钱」的方向相反。"}], "explanations": {"支付": "正确：支付，把钱交给对方，与「用手机付饭钱」相符。", "打扫": "搭配：「打扫」的对象是房间、地面等，不能说打扫饭钱。", "借": "语义：「借」是暂时拿别人的东西，不是把钱给出去。", "领取": "语义：「领取」是收下发给自己的东西，与「我付饭钱」的方向相反。"}, "sentence_index": 0, "correct_answer": "支付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭店向客人支付服务费。", "explanation": "这里应该用〈收取〉。支付是把钱付给对方，收取是向对方拿钱，方向正好相反。"}, {"text": "他支付了很大的努力，终于完成了任务。", "explanation": "这里应该用〈付出〉。支付只用于钱款，努力这类抽象的东西要说付出。"}, {"text": "他支付了三天的假期，好好休息。", "explanation": "这里应该用〈享受〉。支付只用于付钱，假期要说享受或度过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支付", "is_correct": true, "explanation": "正确：支付，用信用卡付钱，与「买了机票」相符。"}, {"text": "取消", "is_correct": false, "explanation": "语义：「取消」是撤销订单，与「用信用卡付钱」矛盾。"}, {"text": "退订", "is_correct": false, "explanation": "语义：「退订」是退掉已订的票，不是付钱。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：「赠送」是无偿送给他人，与句中用信用卡付钱买票的情境不符。"}], "explanations": {"支付": "正确：支付，用信用卡付钱，与「买了机票」相符。", "取消": "语义：「取消」是撤销订单，与「用信用卡付钱」矛盾。", "退订": "语义：「退订」是退掉已订的票，不是付钱。", "赠送": "语义：「赠送」是无偿送给他人，与句中用信用卡付钱买票的情境不符。"}, "sentence_index": 6, "correct_answer": "支付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他支付了老师的恩情，一直没有忘记。", "explanation": "这里应该用〈报答〉。支付只用于付钱，恩情要说报答。"}, {"text": "他支付了巨大的压力，很辛苦。", "explanation": "这里应该用〈承受〉。支付只用于钱款，压力要说承受。"}, {"text": "我们支付了一次精彩的讨论。", "explanation": "这里应该用〈参加〉。支付只用于付钱，讨论是要参加或进行的，不能说支付。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经把房租全部支付了完。", "corrected_sentence": "他已经把房租全部支付完了。", "error_description": "「了」的位置错误：「支付完」是结果补语，「了」应放在补语之后，不能放在「完」之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天支付着学费。", "corrected_sentence": "他昨天支付了学费。", "error_description": "体标误用：「昨天支付学费」是已经完成的动作，要用「了」，不能用表示持续的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
