INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人们站立或放置物品的平坦高台。", "primary_collocate": null, "pronunciation": "píng tái", "ipa": "pʰiŋ˧˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "房子后面有一个平台，我们常在那里喝茶。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爬上平台，向下面的人挥手。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平台很高，小孩子不要爬上去。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把花盆都放在窗外的平台上。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人站在平台上修理高处的灯。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店有一个大平台，可以看到海。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台前面有一个小平台，歌手站在上面唱歌。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在平台上，一边吃饭一边看风景。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼顶的平台上晒着很多衣服。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶有一个石头平台，大家都在那里拍照。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "展示平台", "label": "复合"}], "register": "中性", "sense_fingerprint": "供人站立或放物的平坦高台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42af6dd8-76df-4128-9f4d-41a929127788') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "平台指平坦的高台，可以放东西、坐或站，符合「房子后面」和「喝茶」的语境。"}, {"text": "烟囱", "is_correct": false, "explanation": "语义：烟囱是排烟的高管子，人不能在那里坐着喝茶。"}, {"text": "深坑", "is_correct": false, "explanation": "体貌：深坑是凹下去的，不是平的，既不能站也不能放茶具。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是用来扔垃圾的，不能在那里喝茶。"}], "explanations": {"平台": "平台指平坦的高台，可以放东西、坐或站，符合「房子后面」和「喝茶」的语境。", "烟囱": "语义：烟囱是排烟的高管子，人不能在那里坐着喝茶。", "深坑": "体貌：深坑是凹下去的，不是平的，既不能站也不能放茶具。", "垃圾桶": "语义：垃圾桶是用来扔垃圾的，不能在那里喝茶。"}, "sentence_index": 0, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在平台上游泳，一直游到对岸。", "explanation": "这里应该用「河」。平台是平坦的台面，不是水域；「游泳」和「游到对岸」都要在水里进行。"}, {"text": "他一口把平台吃了下去。", "explanation": "这里应该用「饼」或「点心」。平台是固定的台面，不能吃；「吃下去」用于食物。"}, {"text": "这个平台很陡，人走上去会滑下来。", "explanation": "这里应该用「斜坡」。平台是平的，不会陡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "平台是平的高台，歌手可以站在上面唱歌，符合句中的语境。"}, {"text": "帘子", "is_correct": false, "explanation": "语义：帘子是挂着的布，歌手不能站在上面唱歌。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是用来坐的，不能站上去唱歌，也不是舞台前的设施。"}, {"text": "水池", "is_correct": false, "explanation": "体貌：水池是凹下去的，里面有水，歌手不可能站在上面。"}], "explanations": {"平台": "平台是平的高台，歌手可以站在上面唱歌，符合句中的语境。", "帘子": "语义：帘子是挂着的布，歌手不能站在上面唱歌。", "沙发": "语义：沙发是用来坐的，不能站上去唱歌，也不是舞台前的设施。", "水池": "体貌：水池是凹下去的，里面有水，歌手不可能站在上面。"}, "sentence_index": 6, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个平台会唱歌，大家都围过来听。", "explanation": "这里应该用「音箱」。平台是平坦的台面，不会唱歌；「唱歌」要用能发声的东西。"}, {"text": "我把平台捏成了一个小团子，给孩子玩。", "explanation": "这里应该用「橡皮泥」。平台是硬的台面，不能捏成团子。"}, {"text": "我们把平台折起来，放进了书包里。", "explanation": "这里应该用「纸」。平台是固定的台面，不能折起来放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她站在一条平台上，给大家拍了一张照片。", "corrected_sentence": "她站在一个平台上，给大家拍了一张照片。", "error_description": "错误：「一条平台」，正确：「一个平台」。平台用量词「个」，「条」用于河、路等细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "舞台旁边搭了一条木头平台，歌手可以站在上面唱歌。", "corrected_sentence": "舞台旁边搭了一个木头平台，歌手可以站在上面唱歌。", "error_description": "错误：「一条木头平台」，正确：「一个木头平台」。平台应用量词「个」，「条」用于河、路等细长的东西，不能用来数平台。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
