INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指天生的资质或才能。", "primary_collocate": null, "pronunciation": "bǐng fù", "ipa": "piŋ²¹⁴ fu⁵¹", "syllable_count": 2, "sentences": [{"text": "老师说他在数学方面很有禀赋。", "target_word": "禀赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子有音乐禀赋。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的绘画禀赋很高。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个人的禀赋不一样。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她有语言方面的禀赋。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好老师能发现学生的禀赋。", "target_word": "禀赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "禀赋加上努力才会成功。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他天生有运动禀赋。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位歌手的禀赋让人羡慕。", "target_word": "禀赋", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她没有学数学的禀赋。", "target_word": "禀赋", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "稟賦", "label": "繁体"}], "register": "书面", "sense_fingerprint": "天生的资质、才能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac8efc8-1461-4dce-be40-9987f9ef42b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "禀赋", "is_correct": true, "explanation": "禀赋：指天生的资质，与“数学方面”搭配，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是人的资质，“很有椅子”句意不通。"}, {"text": "零件", "is_correct": false, "explanation": "语义：零件不指人的才能，“很有零件”句意不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能用来形容人的资质，句意不通。"}], "explanations": {"禀赋": "禀赋：指天生的资质，与“数学方面”搭配，符合句意。", "椅子": "语义：椅子不是人的资质，“很有椅子”句意不通。", "零件": "语义：零件不指人的才能，“很有零件”句意不通。", "河流": "语义：河流不能用来形容人的资质，句意不通。"}, "sentence_index": 0, "correct_answer": "禀赋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他通过多年训练积累了很强的禀赋。", "explanation": "这里应该用〈能力〉。禀赋指天生的资质，靠训练积累的要说能力。"}, {"text": "这次考试他的禀赋只考了二十分。", "explanation": "这里应该用〈成绩〉。禀赋指天生的资质，考试得的分数要说成绩，不能说禀赋。"}, {"text": "他的禀赋是当一名医生。", "explanation": "这里应该用〈志向〉。禀赋指天生的资质，不指想要做的事，想做的事要说志向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禀赋", "is_correct": true, "explanation": "禀赋：指天生的才能，符合“禀赋加上努力才会成功”的句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与“加上努力才会成功”的条件无关，句意不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是能靠努力加上去的成功条件，句意不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是能靠努力加上去的成功条件，句意不通。"}], "explanations": {"禀赋": "禀赋：指天生的才能，符合“禀赋加上努力才会成功”的句意。", "颜色": "语义：颜色与“加上努力才会成功”的条件无关，句意不通。", "椅子": "语义：椅子不是能靠努力加上去的成功条件，句意不通。", "雨伞": "语义：雨伞不是能靠努力加上去的成功条件，句意不通。"}, "sentence_index": 6, "correct_answer": "禀赋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天的禀赋很好，所以考得很顺利。", "explanation": "这里应该用〈状态〉。禀赋是天生的资质，不随一天的好坏而变，说今天的好坏要用状态。"}, {"text": "他的禀赋很英俊，很多女生喜欢他。", "explanation": "这里应该用〈长相〉。禀赋指天生的才能，不指外貌，形容相貌要用长相。"}, {"text": "他的禀赋很开朗，喜欢和大家聊天。", "explanation": "这里应该用〈性格〉。禀赋指才能，不能用来形容开朗的个性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子有一只很好的禀赋。", "corrected_sentence": "这个孩子有一种很好的禀赋。", "error_description": "量词错误：禀赋应搭配量词“种”，“只”多用于动物等，不能用于禀赋。正确说法是“一种很好的禀赋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在写作方面有很好禀赋。", "corrected_sentence": "他在写作方面有很好的禀赋。", "error_description": "漏了“的”：定语“很好”修饰名词“禀赋”时中间要加“的”，应说“很好的禀赋”，不能说“很好禀赋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
