INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10599, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "错误地匹配或配对。", "primary_collocate": null, "pronunciation": "cuò pèi", "ipa": "tsʰuo⁵¹ pʰei⁵¹", "syllable_count": 2, "sentences": [{"text": "店员把两桌客人的餐点错配了。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司把人才和岗位错配了。", "target_word": "错配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人才错配会浪费资源。", "target_word": "错配", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工作和专长错配，他很不开心。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个零件错配了，机器不能用。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "资金错配让小公司借不到钱。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数据表里的名字和电话错配了。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校要避免学生和课程错配。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生发现药和病人错配了。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市场上的供给和需求错配。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "错配了", "label": "体标"}, {"form": "錯配", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人、资源等配对不当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac8efc8-1461-4dce-be40-9987f9ef42b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10599, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "错配", "is_correct": true, "explanation": "错配：动词，指餐点与客人对不上，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发声的动作，“把餐点唱了”句意不通。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步是人的运动，“把餐点跑步了”句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是人的动作，“把餐点睡觉了”句意不通。"}], "explanations": {"错配": "错配：动词，指餐点与客人对不上，符合句意。", "唱": "语义：唱是发声的动作，“把餐点唱了”句意不通。", "跑步": "语义：跑步是人的运动，“把餐点跑步了”句意不通。", "睡觉": "语义：睡觉是人的动作，“把餐点睡觉了”句意不通。"}, "sentence_index": 0, "correct_answer": "错配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两件衣服错配得很好看。", "explanation": "这里应该用〈搭配〉。错配指配错，不能说“错配得很好看”，形容配得好要用搭配。"}, {"text": "两位队员错配得很默契。", "explanation": "这里应该用〈配合〉。错配指配错，与“默契”矛盾，形容协作好要用配合。"}, {"text": "这条领带和西装错配得很有品味，大家都夸他。", "explanation": "这里应该用〈协调〉。错配指配错，与“有品味”矛盾，形容相配好要用协调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错配", "is_correct": true, "explanation": "错配：指名字和电话对应出错，符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌是人的动作，“名字和电话唱歌了”句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求饮食类宾语，名字和电话不能作它的宾语。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步是人的运动，“数据表里的名字和电话跑步了”句意不通。"}], "explanations": {"错配": "错配：指名字和电话对应出错，符合句意。", "唱歌": "语义：唱歌是人的动作，“名字和电话唱歌了”句意不通。", "吃": "配价：“吃”要求饮食类宾语，名字和电话不能作它的宾语。", "跑步": "语义：跑步是人的运动，“数据表里的名字和电话跑步了”句意不通。"}, "sentence_index": 6, "correct_answer": "错配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板把任务合理错配给了每个员工。", "explanation": "这里应该用〈分配〉。错配指配错，不能与“合理”搭配，分配任务要用分配。"}, {"text": "这件衣服错配得很舒服，他穿着很自在。", "explanation": "这里应该用〈合身〉。错配指配错，与“舒服”“很自在”矛盾，形容大小合适要用合身。"}, {"text": "这两位合作伙伴错配得很默契，效率很高。", "explanation": "这里应该用〈合作〉。错配指配错，与“默契”“效率高”矛盾，合作顺利要说合作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅把菜和酒错配。", "corrected_sentence": "这家餐厅把菜和酒错配了。", "error_description": "把字句缺少补充成分：“把”字句中的动词“错配”后面要有“了”等成分表示结果，不能只用光杆动词，应说“错配了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两批货物没有错配了。", "corrected_sentence": "这两批货物没有错配。", "error_description": "否定与体标冲突：“没有”已表示未发生，句末不能再加“了”，应说“这两批货物没有错配。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
