INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "创作或谱写歌曲。", "primary_collocate": null, "pronunciation": "xiě gē", "ipa": "ɕjɛ˨˩ kɤ˥", "syllable_count": 2, "sentences": [{"text": "记谱法帮助作曲家写歌。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "他每天晚上弹吉他写歌。", "target_word": "写歌", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想给妈妈写歌，词和曲都自己来。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位歌手不但会唱歌，还会自己写歌。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写歌需要灵感，也需要很多练习。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在山上住了三个月，为新专辑写歌。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐老师教大家怎么写歌和编曲。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写歌的时候，总是先想好旋律。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了参加原创比赛，他们三个人一起写歌。", "target_word": "写歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学过作曲，现在在家写歌。", "target_word": "写歌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "写了歌", "label": "体标"}, {"form": "写过歌", "label": "体标"}, {"form": "寫歌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "创作歌曲，谱写歌词与旋律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3108ec33-339a-4478-bb81-96f499e82975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写歌", "is_correct": true, "explanation": "写歌：创作歌曲，记谱法帮助的正是创作。"}, {"text": "扫地", "is_correct": false, "explanation": "语义：扫地与作曲无关，记谱法不能帮助作曲家扫地。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与音乐创作无关，“帮助作曲家吃饭”不通。"}, {"text": "写信", "is_correct": false, "explanation": "搭配：“写”的宾语应是信件，作曲家的工作不能用写信来帮助。"}], "explanations": {"写歌": "写歌：创作歌曲，记谱法帮助的正是创作。", "扫地": "语义：扫地与作曲无关，记谱法不能帮助作曲家扫地。", "吃饭": "语义：吃饭与音乐创作无关，“帮助作曲家吃饭”不通。", "写信": "搭配：“写”的宾语应是信件，作曲家的工作不能用写信来帮助。"}, "sentence_index": 0, "correct_answer": "写歌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "观众在台下一边写歌，一边大声鼓掌。", "explanation": "这里应该用〈唱歌〉。写歌是创作歌曲；台下观众跟着唱、鼓掌说的是现场演唱，不是创作。"}, {"text": "她在卡拉OK包厢里写歌，大家听得直拍手。", "explanation": "这里应该用〈唱歌〉。写歌是创作，大家听得直拍手说的是她在现场唱。"}, {"text": "他一边跑步一边写歌，喘得说不出话来。", "explanation": "这里应该用〈唱歌〉。写歌是创作，喘得说不出话说明他是边跑边唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写歌", "is_correct": true, "explanation": "写歌：创作歌曲，与“编曲”并列，是音乐创作的两项内容。"}, {"text": "洗碗", "is_correct": false, "explanation": "语义：洗碗与音乐创作无关，“教大家怎么洗碗和编曲”不通。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：“修车”的宾语是车辆，不能与“编曲”并列作教学内容。"}, {"text": "理发", "is_correct": false, "explanation": "语义：理发与编曲无关，不能作为音乐课的内容。"}], "explanations": {"写歌": "写歌：创作歌曲，与“编曲”并列，是音乐创作的两项内容。", "洗碗": "语义：洗碗与音乐创作无关，“教大家怎么洗碗和编曲”不通。", "修车": "搭配：“修车”的宾语是车辆，不能与“编曲”并列作教学内容。", "理发": "语义：理发与编曲无关，不能作为音乐课的内容。"}, "sentence_index": 6, "correct_answer": "写歌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在录音棚里写歌，录了三遍才过。", "explanation": "这里应该用〈录歌〉。写歌是创作；录了三遍才过说的是录制，要用录歌。"}, {"text": "他站在看台上写歌，为球队大声加油。", "explanation": "这里应该用〈加油〉。写歌是创作，为球队大声喊口号要用加油。"}, {"text": "她站在舞台中央写歌，台下的观众听得热泪盈眶。", "explanation": "这里应该用〈演唱〉。写歌是创作；台下观众听得热泪盈眶，说的是现场演唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天写歌过，很好听。", "corrected_sentence": "他昨天写过歌，很好听。", "error_description": "体标错误：「过」须紧跟动词，应说「写过歌」，不能说「写歌过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很写歌，每首歌都很有感觉。", "corrected_sentence": "她很会写歌，每首歌都很有感觉。", "error_description": "能愿动词错误：“写歌”作谓语前要加能愿动词“会”，“很”修饰的是“会”。错误形式是“她很写歌”，正确形式是“她很会写歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
