INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10628, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了掌握某种技能或知识而反复进行的行为。", "primary_collocate": null, "pronunciation": "liàn xí", "ipa": "ljɛn˥˩ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "学生练习，记住符号的意思。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "我每天晚上练习写汉字。", "target_word": "练习", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们正在练习唱一首新歌。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了考试，同学们反复练习听力。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她练习了一个小时的钢琴。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多练习口语，你的发音会更好。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们两个人一起练习对话。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已经练习过很多次这个动作。", "target_word": "练习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，运动员要认真练习跑步。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在院子里练习着踢球。", "target_word": "练习", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "练习了", "label": "体标"}, {"form": "练习过", "label": "体标"}, {"form": "练习着", "label": "体标"}, {"form": "练习练习", "label": "重叠"}, {"form": "練習", "label": "繁体"}], "register": "中性", "sense_fingerprint": "练习|为掌握技能或知识而反复进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10628, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "练习", "is_correct": true, "explanation": "目标词：练习（liàn xí）。"}, {"text": "联系", "is_correct": false, "explanation": "联系（lián xì）与练习两个音节的声调都不同，意思是联系。"}, {"text": "怜惜", "is_correct": false, "explanation": "怜惜（lián xī）与练习两个音节的声调都不同，意思是怜惜。"}, {"text": "利息", "is_correct": false, "explanation": "利息（lì xī）第一音节韵母不同（lì 无 -ian），第二音节声调也不同，意思是利息。"}], "explanations": {"练习": "目标词：练习（liàn xí）。", "联系": "联系（lián xì）与练习两个音节的声调都不同，意思是联系。", "怜惜": "怜惜（lián xī）与练习两个音节的声调都不同，意思是怜惜。", "利息": "利息（lì xī）第一音节韵母不同（lì 无 -ian），第二音节声调也不同，意思是利息。"}, "sentence_index": null, "correct_answer": "练习"}, "level_3": {"options": [{"text": "练习", "is_correct": true, "explanation": "指为掌握技能而反复做，与“记住符号的意思”的目的相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与“记住符号的意思”无关，句子不通。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与句末的“记住”意思相反，不能填入。"}, {"text": "瞎搞", "is_correct": false, "explanation": "语义：“瞎搞”指胡乱地做，不能达到“记住符号的意思”的目的，且含贬义，句意不通。"}], "explanations": {"练习": "指为掌握技能而反复做，与“记住符号的意思”的目的相符。", "唱歌": "语义：唱歌与“记住符号的意思”无关，句子不通。", "忘记": "语义：“忘记”与句末的“记住”意思相反，不能填入。", "瞎搞": "语义：“瞎搞”指胡乱地做，不能达到“记住符号的意思”的目的，且含贬义，句意不通。"}, "sentence_index": 0, "correct_answer": "练习"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家正在练习这种新药的作用。", "explanation": "这里应该用〈研究〉。“练习”是反复做以掌握，不用于探索未知的作用。"}, {"text": "爱迪生练习了电灯。", "explanation": "这里应该用〈发明〉。“练习”指反复做，不能用于创造新事物。"}, {"text": "医生练习了病人的出院。", "explanation": "这里应该用〈办理〉。“练习”指反复做以熟练，不能用于办理出院手续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "练习", "is_correct": true, "explanation": "指反复做以熟悉对话内容，与“两个人一起”的语境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或物品，不能搭配“对话”。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，后面不能直接带“对话”作宾语。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“让我们一起”的合作语境相反。"}], "explanations": {"练习": "指反复做以熟悉对话内容，与“两个人一起”的语境相符。", "打扫": "搭配：“打扫”的对象是场地或物品，不能搭配“对话”。", "睡觉": "配价：“睡觉”是不及物动词，后面不能直接带“对话”作宾语。", "逃跑": "语义：“逃跑”与“让我们一起”的合作语境相反。"}, "sentence_index": 6, "correct_answer": "练习"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在工地上练习了一座大桥。", "explanation": "这里应该用〈建造〉。“练习”是反复做以熟练，不用于建成实物。"}, {"text": "我周末去医院练习生病的奶奶。", "explanation": "这里应该用〈看望〉。“练习”是反复做事以掌握技能，不能用于探望人，应说“看望生病的奶奶”。"}, {"text": "他昨晚练习了妈妈。", "explanation": "这里应该用〈梦见〉。“练习”的对象是动作或技能，不能是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在练习了钢琴。", "corrected_sentence": "他正在练习钢琴。", "error_description": "“正在”表示动作进行，不能与“了”同用，应为“他正在练习钢琴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天都在练习了口语。", "corrected_sentence": "我每天都在练习口语。", "error_description": "“在”表示动作正在进行或习惯进行，不能与表示完成的“了”同用，应删去“了”，改为“我每天都在练习口语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
