INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10630, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物所包含的思想、道理或想要表达的内容。", "primary_collocate": null, "pronunciation": "yì si", "ipa": "i˥˩ sɨ", "syllable_count": 2, "sentences": [{"text": "学生练习，记住符号的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个词是什么意思？", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师解释了这句话的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不懂他话里的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字有两个意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你查一下词典，看看这个词的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标志的意思是禁止停车。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这句话的意思写在本子上。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词的意思差不多。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译这段话，要先弄清楚每个句子的意思。", "target_word": "意思", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "词语、符号、话语所包含的含义或内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3108ec33-339a-4478-bb81-96f499e82975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意思", "is_correct": true, "explanation": "正确：「意思」指符号所表示的含义，与「记住符号的意思」相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：符号没有价格，「记住符号的价格」说不通。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：「性格」只用于人或动物，不能说符号有性格。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：符号没有年龄，句子意思不通。"}], "explanations": {"意思": "正确：「意思」指符号所表示的含义，与「记住符号的意思」相合。", "价格": "语义：符号没有价格，「记住符号的价格」说不通。", "性格": "搭配：「性格」只用于人或动物，不能说符号有性格。", "年龄": "语义：符号没有年龄，句子意思不通。"}, "sentence_index": 0, "correct_answer": "意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个节日的意思特别热闹。", "explanation": "这里应该用〈气氛〉。「气氛热闹」形容节日场面；「意思」指含义，不能说节日的「意思」热闹。"}, {"text": "读完这本书，我的意思很多。", "explanation": "这里应该用〈感想〉。「感想很多」指读后的心得体会；「意思」指书中的含义，不指个人的心得，所以不说「我的意思很多」。"}, {"text": "这个药的意思很好。", "explanation": "这里应该用〈效果〉。「效果好」说药物或方法的作用；「意思」指想说的内容，不能用于药物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意思", "is_correct": true, "explanation": "正确：「意思」指标志所表达的含义，与「禁止停车」相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：标志的颜色不能是「禁止停车」，句意不通。"}, {"text": "形状", "is_correct": false, "explanation": "语义：标志的形状不能是「禁止停车」这种行为，句意不通。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：标志没有价钱，「价钱是禁止停车」说不通。"}], "explanations": {"意思": "正确：「意思」指标志所表达的含义，与「禁止停车」相合。", "颜色": "语义：标志的颜色不能是「禁止停车」，句意不通。", "形状": "语义：标志的形状不能是「禁止停车」这种行为，句意不通。", "价钱": "语义：标志没有价钱，「价钱是禁止停车」说不通。"}, "sentence_index": 6, "correct_answer": "意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱子的意思很重。", "explanation": "这里应该用〈分量〉。「分量很重」说物体的重量；「意思」指含义，不能说箱子的「意思」很重。"}, {"text": "这扇门的意思很响。", "explanation": "这里应该用〈声音〉。「声音很响」说门发出的声音；「意思」指含义，不能说门的「意思」很响。"}, {"text": "他做事的意思很快，三天就完成了。", "explanation": "这里应该用〈速度〉。「速度很快」说做事的快慢；「意思」指含义或意图，不能用来说快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个符号有一只意思。", "corrected_sentence": "这个符号有一个意思。", "error_description": "量词错误：「意思」应用量词「个」，不能用「只」。「只」多用于动物或成对的东西，不能说「一只意思」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段话意思我已经弄清楚了。", "corrected_sentence": "这段话的意思我已经弄清楚了。", "error_description": "「的」遗漏：定语「这段话」与中心词「意思」之间要加「的」，应说「这段话的意思」，不能说「这段话意思」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
