INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10635, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "演奏琴类乐器，如钢琴、古琴等。", "primary_collocate": null, "pronunciation": "tán qín", "ipa": "tʰan˧˥ tɕʰin˧˥", "syllable_count": 2, "sentences": [{"text": "我每天晚上弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在客厅里弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢弹琴唱歌。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐从五岁开始弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会弹琴吗？", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不爱弹琴，爱踢球。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居晚上弹琴，声音很好听。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边弹琴，一边唱歌。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们安静地听老师弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我怎么弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弹弹琴", "label": "重叠"}, {"form": "彈琴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "演奏钢琴、古琴等琴类乐器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3108ec33-339a-4478-bb81-96f499e82975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弹琴", "is_correct": true, "explanation": "正确：「弹琴」是晚上的日常活动，与「我每天晚上」相合。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：熔化是物质受热变成液体，人不能熔化，句子不通。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：「讨论」需要讨论的对象作宾语，句中没有宾语，说不完整。"}, {"text": "叫醒", "is_correct": false, "explanation": "配价：「叫醒」需要被叫醒的人作宾语，句中缺宾语。"}], "explanations": {"弹琴": "正确：「弹琴」是晚上的日常活动，与「我每天晚上」相合。", "熔化": "语义：熔化是物质受热变成液体，人不能熔化，句子不通。", "讨论": "配价：「讨论」需要讨论的对象作宾语，句中没有宾语，说不完整。", "叫醒": "配价：「叫醒」需要被叫醒的人作宾语，句中缺宾语。"}, "sentence_index": 0, "correct_answer": "弹琴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿起笛子，站在窗前弹琴。", "explanation": "这里应该用〈吹笛子〉。笛子是管乐器，要「吹」；弹琴指演奏钢琴、古琴等琴类乐器。"}, {"text": "她在鼓前坐下，开始弹琴。", "explanation": "这里应该用〈打鼓〉。鼓要「打」或「敲」，不是琴，不能说弹琴。"}, {"text": "他拿起小提琴，用弓子弹琴。", "explanation": "这里应该用〈拉琴〉。小提琴用弓子拉，要说「拉琴」，不说弹琴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弹琴", "is_correct": true, "explanation": "正确：「弹琴」是晚上的活动，且弹出的声音可以好听，与「声音很好听」相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉不发出让人赞美的声音，句子说不通。"}, {"text": "修理", "is_correct": false, "explanation": "配价：「修理」需要修理的对象作宾语，句中没有宾语。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与「声音很好听」没有关系，句意不通。"}], "explanations": {"弹琴": "正确：「弹琴」是晚上的活动，且弹出的声音可以好听，与「声音很好听」相合。", "睡觉": "语义：睡觉不发出让人赞美的声音，句子说不通。", "修理": "配价：「修理」需要修理的对象作宾语，句中没有宾语。", "吃饭": "语义：吃饭与「声音很好听」没有关系，句意不通。"}, "sentence_index": 6, "correct_answer": "弹琴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钢琴的音不准了，妈妈请师傅来家里弹琴。", "explanation": "这里应该用〈调音〉。师傅来是修正音准，要用调音；弹琴是演奏。"}, {"text": "姐姐买了一把二胡，每天在家弹琴。", "explanation": "这里应该用〈拉二胡〉。二胡用弓拉，要说「拉二胡」，不能说弹琴。"}, {"text": "他坐在台下认真地弹琴，听得很入迷。", "explanation": "这里应该用〈听琴〉。台下的人是在听别人演奏，不是自己弹琴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹昨天下午弹琴过，声音很好听。", "corrected_sentence": "妹妹昨天下午弹过琴，声音很好听。", "error_description": "体标错误：「过」须紧跟动词，应说「弹过琴」，不能说「弹琴过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班的同学都弹琴得很好。", "corrected_sentence": "我们班的同学都弹琴弹得很好。", "error_description": "补语结构错误：「弹琴」后接程度补语时需重复动词「弹」，应说「弹琴弹得很好」，不能说「弹琴得很好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
