INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10637, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指由物体振动产生的、通过空气等传播并能被听觉器官感知的波动现象。", "primary_collocate": null, "pronunciation": "yīn", "ipa": "in˥", "syllable_count": 1, "sentences": [{"text": "在五线谱上，线的位置越高，所表示的音就越高。", "target_word": "音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚开始只有两条线，后来变成五条线，能更清楚地表示音的高低。", "target_word": "音", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "有人用数字软件直接调整这个音的高低。", "target_word": "音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套记谱法把每个音的高低都记录了下来，便于后人演奏。", "target_word": "音", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "巴洛克时代的乐谱只标出每个音的高低，和声则要由演奏者根据数字记号自行配置。", "target_word": "音", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这个音太高了，我唱不上去。", "target_word": "音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "琴弦越短，发出的音就越高。", "target_word": "音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钢琴上每个键发出的音都不一样。", "target_word": "音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个音很低，要仔细听才能听到。", "target_word": "音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一弹错一个音，老师就让他重来。", "target_word": "音", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高音", "label": "复合"}, {"form": "低音", "label": "复合"}], "register": "书面", "sense_fingerprint": "音：物体振动产生、耳朵能听到的声波，有高低之分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dab81e9-4fc4-4e85-8310-7a60964d0d47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10637, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "音", "is_correct": true, "explanation": "正确答案：音（yīn），指物体振动产生、耳朵能听到的声波。"}, {"text": "银", "is_correct": false, "explanation": "银（yín）与音（yīn）只有声调不同（第二声与第一声），意思是银子。"}, {"text": "饮", "is_correct": false, "explanation": "饮（yǐn）与音（yīn）只有声调不同，意思是喝。"}, {"text": "印", "is_correct": false, "explanation": "印（yìn）与音（yīn）只有声调不同（第四声与第一声），意思是印刷或盖章。"}, {"text": "衣", "is_correct": false, "explanation": "衣（yī）与音（yīn）韵尾不同，少了 n，意思是衣服。"}], "explanations": {"音": "正确答案：音（yīn），指物体振动产生、耳朵能听到的声波。", "银": "银（yín）与音（yīn）只有声调不同（第二声与第一声），意思是银子。", "饮": "饮（yǐn）与音（yīn）只有声调不同，意思是喝。", "印": "印（yìn）与音（yīn）只有声调不同（第四声与第一声），意思是印刷或盖章。", "衣": "衣（yī）与音（yīn）韵尾不同，少了 n，意思是衣服。"}, "sentence_index": null, "correct_answer": "音"}, "level_3": {"options": [{"text": "音", "is_correct": true, "explanation": "正确：“所表示的音就越高”指音高随线的位置升高，应为“音”。"}, {"text": "字", "is_correct": false, "explanation": "语义：字是文字符号，不能说高低，与五线谱上的位置无关。"}, {"text": "图", "is_correct": false, "explanation": "语义：图是图形，不能说高低，句意不通。"}, {"text": "色", "is_correct": false, "explanation": "语义：色是颜色，不能说高低，句意不通。"}], "explanations": {"音": "正确：“所表示的音就越高”指音高随线的位置升高，应为“音”。", "字": "语义：字是文字符号，不能说高低，与五线谱上的位置无关。", "图": "语义：图是图形，不能说高低，句意不通。", "色": "语义：色是颜色，不能说高低，句意不通。"}, "sentence_index": 0, "correct_answer": "音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口吃掉了一个音。", "explanation": "这里应该用〈饼干〉。音指声波，看不见摸不着，不能吃；能一口吃掉的是饼干。"}, {"text": "这个音很重，他搬不动。", "explanation": "这里应该用〈石头〉。音指声波，没有重量，搬不动的是石头。"}, {"text": "这堵音很厚，挡住了风。", "explanation": "这里应该用〈墙〉。音指声波，不能挡风，也没有厚度；挡风的厚实之物是墙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10637, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "音", "is_correct": true, "explanation": "正确答案：音（yīn），指物体振动产生、耳朵能听到的声波。"}, {"text": "英", "is_correct": false, "explanation": "英（yīng）与音（yīn）韵尾不同（ng 与 n），意思是杰出，也是英国的简称。"}, {"text": "烟", "is_correct": false, "explanation": "烟（yān）与音（yīn）声调相同，只有韵母不同（an 与 in），意思是烟雾。"}, {"text": "隐", "is_correct": false, "explanation": "隐（yǐn）与音（yīn）只有声调不同（第三声与第一声），意思是隐藏。"}, {"text": "银", "is_correct": false, "explanation": "银（yín）与音（yīn）只有声调不同（第二声与第一声），意思是银子。"}], "explanations": {"音": "正确答案：音（yīn），指物体振动产生、耳朵能听到的声波。", "英": "英（yīng）与音（yīn）韵尾不同（ng 与 n），意思是杰出，也是英国的简称。", "烟": "烟（yān）与音（yīn）声调相同，只有韵母不同（an 与 in），意思是烟雾。", "隐": "隐（yǐn）与音（yīn）只有声调不同（第三声与第一声），意思是隐藏。", "银": "银（yín）与音（yīn）只有声调不同（第二声与第一声），意思是银子。"}, "sentence_index": null, "correct_answer": "音"}, "level_3": {"options": [{"text": "音", "is_correct": true, "explanation": "正确：“琴弦越短，发出的音就越高”中，“音”指音高。"}, {"text": "光", "is_correct": false, "explanation": "语义：光没有高低的说法，与琴弦发声的情形不符。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味不能用高低来形容，与琴弦发声无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色越高”不符合颜色的表达习惯，与琴弦发声不搭。"}], "explanations": {"音": "正确：“琴弦越短，发出的音就越高”中，“音”指音高。", "光": "语义：光没有高低的说法，与琴弦发声的情形不符。", "气味": "语义：气味不能用高低来形容，与琴弦发声无关。", "颜色": "搭配：“颜色越高”不符合颜色的表达习惯，与琴弦发声不搭。"}, "sentence_index": 6, "correct_answer": "音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一个音送给了朋友。", "explanation": "这里应该用〈花〉。音指声波，看不见摸不着，不能当礼物送人；送人的是花。"}, {"text": "他跑了三公里，累得满头音。", "explanation": "这里应该用〈汗〉。音指声波，不能长在头上；满头的是汗，即满头大汗。"}, {"text": "我的音有三扇窗户。", "explanation": "这里应该用〈房间〉。音指声波，没有窗户；有窗户的是房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他弹错了一只音。", "corrected_sentence": "他弹错了一个音。", "error_description": "错误：“音”的量词用了“只”，“只”用于动物，音应用“个”。应为“一个音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他弹错了一张音，老师就让他重来。", "corrected_sentence": "他弹错了一个音，老师就让他重来。", "error_description": "错误：“音”的量词用了“张”，“张”多用于纸、桌子等平面的东西，音应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10638, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
