INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10638, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "口中发出乐音，按照一定的旋律和歌词表演歌曲。", "primary_collocate": null, "pronunciation": "chàng", "ipa": "tʂʰɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这些符号告诉人们哪个音要唱。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "她在台上唱了一首中文歌。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明唱得很好，大家都鼓掌。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一边做饭，一边唱着老歌。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌太难了，我唱不好。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想唱哪一首？我来弹吉他。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学校的晚会上唱过两次。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再唱一遍，我想录下来。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站成一排，大声地唱。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起唱生日歌，祝奶奶快乐。", "target_word": "唱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "唱了", "label": "完成体"}, {"form": "唱着", "label": "持续体"}, {"form": "唱过", "label": "经历体"}, {"form": "唱唱", "label": "重叠"}, {"form": "唱歌", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用嗓音按旋律演唱歌曲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b90b6993-4408-4414-a5ca-24fcb8214168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10638, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "唱", "is_correct": true, "explanation": "正确答案：唱（第四声），意思是口中发出乐音、演唱歌曲。"}, {"text": "长", "is_correct": false, "explanation": "cháng（第二声）与 chàng（第四声）声调不同，意思是长。"}, {"text": "上", "is_correct": false, "explanation": "shàng 与 chàng 声母不同（sh 与 ch），意思是上。"}, {"text": "场", "is_correct": false, "explanation": "chǎng（第三声）与 chàng（第四声）声调不同，意思是场地、场合。"}, {"text": "常", "is_correct": false, "explanation": "cháng（第二声）与 chàng（第四声）声调不同，意思是经常。"}], "explanations": {"唱": "正确答案：唱（第四声），意思是口中发出乐音、演唱歌曲。", "长": "cháng（第二声）与 chàng（第四声）声调不同，意思是长。", "上": "shàng 与 chàng 声母不同（sh 与 ch），意思是上。", "场": "chǎng（第三声）与 chàng（第四声）声调不同，意思是场地、场合。", "常": "cháng（第二声）与 chàng（第四声）声调不同，意思是经常。"}, "sentence_index": null, "correct_answer": "唱"}, "level_3": {"options": [{"text": "唱", "is_correct": true, "explanation": "正确：“唱”表示按旋律发出乐音，符合“哪个音要唱”的语境。"}, {"text": "画", "is_correct": false, "explanation": "搭配：“画”不能用来表示按旋律发出乐音，“哪个音要画”句意不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指用笔记录，与发出乐音无关，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能用于乐音，“哪个音要吃”句意不通。"}], "explanations": {"唱": "正确：“唱”表示按旋律发出乐音，符合“哪个音要唱”的语境。", "画": "搭配：“画”不能用来表示按旋律发出乐音，“哪个音要画”句意不通。", "写": "语义：“写”指用笔记录，与发出乐音无关，句意不通。", "吃": "搭配：“吃”不能用于乐音，“哪个音要吃”句意不通。"}, "sentence_index": 0, "correct_answer": "唱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她唱了一杯茶，递给客人。", "explanation": "这里应该用〈倒〉。“唱”指按旋律演唱，不能用来表示倒茶。"}, {"text": "妈妈在厨房唱了一锅汤，香味飘满了屋子。", "explanation": "这里应该用〈煮〉。“唱”只能用于歌曲，不能用来表示烧煮，这里误用了。"}, {"text": "她唱了一个电话，告诉妈妈我到了。", "explanation": "这里应该用〈打〉。“唱”只能用于歌曲，不能和“电话”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": true, "explanation": "正确：“唱过”表示在晚会上演唱过，符合句中的语境。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，与“在晚会上”的活动不相符，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不与“晚会”上的活动搭配，句意不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”不与“晚会”上的表演活动搭配，句意不通。"}], "explanations": {"唱": "正确：“唱过”表示在晚会上演唱过，符合句中的语境。", "修": "语义：“修”指修理，与“在晚会上”的活动不相符，句意不通。", "洗": "搭配：“洗”不与“晚会”上的活动搭配，句意不通。", "擦": "搭配：“擦”不与“晚会”上的表演活动搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "唱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个面包唱得很香。", "explanation": "“唱”指按旋律演唱，只能用于人或动物，不能用来形容食物的香味，这里误用了。"}, {"text": "他用笔在纸上唱了一个字。", "explanation": "这里应该用〈写〉。“唱”只能用于歌唱，不能用来表示写字，这里误用了。"}, {"text": "我们一起唱生日蛋糕，祝奶奶快乐。", "explanation": "这里应该用〈切〉。“唱”的对象只能是歌曲，不能说“唱蛋糕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她唱很动人。", "corrected_sentence": "她唱得很动人。", "error_description": "补语错误：表示程度的补语前要用“得”，应说“唱得很动人”，不能说“唱很动人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在家里唱了着一首老歌，声音很温柔。", "corrected_sentence": "他在家里唱着一首老歌，声音很温柔。", "error_description": "体标错误：持续态“着”直接接在“唱”后，不能再加“了”。应说“唱着”，不能说“唱了着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
