INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10640, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "表示数目的符号，如阿拉伯数字1、2、3；也泛指用数表示的记号。", "primary_collocate": null, "pronunciation": "shù zì", "ipa": "ʂu˥˩ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "有些人用字母，有些人用数字。", "target_word": "数字", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "请在表格里写你的电话号码，只能写数字。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个银行卡密码是六个数字。", "target_word": "数字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手机号码一共有十一个数字。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时钟上的数字太小，我看不清楚。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里的数字不对，要再检查一下。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个大数字。", "target_word": "数字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的销售数字比上个月高。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的门牌上只有数字，没有字母。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先输入数字，再按这个键。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "阿拉伯数字", "label": "复合词"}, {"form": "数字化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "阿拉伯数字等表示数目的符号，也指用数表示的记号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71661477-2f15-4858-bb22-282f8f8aa695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10640, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数字", "is_correct": true, "explanation": "数字：表示数目的符号，如阿拉伯数字。"}, {"text": "数次", "is_correct": false, "explanation": "cì 与 zì 声母不同（c/z），意思是「几次」。"}, {"text": "数日", "is_correct": false, "explanation": "rì 与 zì 声母不同（r/z），意思是「几天」。"}, {"text": "数制", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh/z），意思是「进位制」。"}], "explanations": {"数字": "数字：表示数目的符号，如阿拉伯数字。", "数次": "cì 与 zì 声母不同（c/z），意思是「几次」。", "数日": "rì 与 zì 声母不同（r/z），意思是「几天」。", "数制": "zhì 与 zì 声母不同（zh/z），意思是「进位制」。"}, "sentence_index": null, "correct_answer": "数字"}, "level_3": {"options": [{"text": "数字", "is_correct": true, "explanation": "正确：与“字母”并列，指书写用的符号，可以填入空格。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是符号，不能用来表示信息，「有些人用天气」说不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不用来书写或表示信息。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是用来表示信息的符号，句意不通。"}], "explanations": {"数字": "正确：与“字母”并列，指书写用的符号，可以填入空格。", "天气": "语义：天气不是符号，不能用来表示信息，「有些人用天气」说不通。", "水果": "语义：水果是食物，不用来书写或表示信息。", "汽油": "语义：汽油是燃料，不是用来表示信息的符号，句意不通。"}, "sentence_index": 0, "correct_answer": "数字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班一共有三十个数字。", "explanation": "这里应该用〈数目〉。数字指表示数目的符号，说一群人的多少要用“数目”或“人数”。"}, {"text": "我口渴了，想喝一杯数字。", "explanation": "这里应该用〈水〉。数字指表示数目的符号，不能喝；口渴要喝“水”。"}, {"text": "这箱苹果的数字是二十个。", "explanation": "这里应该用〈数量〉。数字指表示数目的符号，说一箱东西有多少要用“数量”，“数字”不指物品的数目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字", "is_correct": true, "explanation": "正确：黑板上写的大号符号，可以填入空格。"}, {"text": "图画", "is_correct": false, "explanation": "搭配：“写”不搭配“图画”，应说“画”。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不能写在黑板上，句子说不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以写的东西，“写了一个大天空”不合理。"}], "explanations": {"数字": "正确：黑板上写的大号符号，可以填入空格。", "图画": "搭配：“写”不搭配“图画”，应说“画”。", "饭菜": "语义：饭菜不能写在黑板上，句子说不通。", "天空": "语义：天空不是可以写的东西，“写了一个大天空”不合理。"}, "sentence_index": 6, "correct_answer": "数字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗一共有八个数字。", "explanation": "这里应该用〈字〉。数字指表示数目的符号，不指诗里的文字；说诗的字数要用“字”。"}, {"text": "外面很冷，你多穿一件数字吧。", "explanation": "这里应该用〈衣服〉。数字指表示数目的符号，不能穿；天冷要多穿“衣服”。"}, {"text": "动物园里有三个数字。", "explanation": "这里应该用〈猴子〉。数字指表示数目的符号，不指动物；说动物园里的动物要用“猴子”等名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在纸上写下了一本数字。", "corrected_sentence": "他在纸上写下了一个数字。", "error_description": "量词错误：“数字”的量词应为“个”，说「一本数字」是错的，“本”用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师让我们抄写这只数字。", "corrected_sentence": "老师让我们抄写这个数字。", "error_description": "量词错误：“数字”的量词应为“个”，“只”用于动物，说「这只数字」是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10642, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "记住", "is_correct": true, "explanation": "正确：“记住”与“忘记”构成反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "旅行", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}], "correct_answer": "记住", "explanations": {"记住": "正确：“记住”与“忘记”构成反义关系。", "思考": "与“忘记”无反义关系，二者语义无对立。", "旅行": "与“忘记”无反义关系，二者语义无对立。", "唱歌": "与“忘记”无反义关系，二者语义无对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10642, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "记住", "is_correct": true, "explanation": "正确：“记住”与“忘记”构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "写字", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}], "correct_answer": "记住", "explanations": {"记住": "正确：“记住”与“忘记”构成反义关系。", "游泳": "与“忘记”无反义关系，二者语义无对立。", "写字": "与“忘记”无反义关系，二者语义无对立。", "吃饭": "与“忘记”无反义关系，二者语义无对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10642, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指原先记住的事物从脑海中消失，无法回想起来。", "primary_collocate": null, "pronunciation": "wàng jì", "ipa": "wɑŋ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "没有记谱法，音乐很容易忘记。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "时间太久，我已经忘记他的名字了。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单词很难，我总是忘记。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年纪大了，常常忘记事情。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你记下来吧，不然明天会忘记。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们小时候的事，我一点也没忘记。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘记了他的电话号码。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试以后，我很快就忘记了那些单词。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年没用汉语，我把很多字都忘记了。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首老歌的歌词，他到现在也没忘记。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忘记了", "label": "体标"}, {"form": "忘记过", "label": "体标"}], "register": "中性", "sense_fingerprint": "记住的内容从脑海中消失，想不起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71661477-2f15-4858-bb22-282f8f8aa695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忘记", "is_correct": true, "explanation": "正确：原先记住的内容消失，可以填入空格。"}, {"text": "生病", "is_correct": false, "explanation": "语义：音乐不会生病，“音乐很容易生病”说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：音乐不能结婚，句子语义不通。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”多用于器物，“音乐很容易打碎”不自然。"}], "explanations": {"忘记": "正确：原先记住的内容消失，可以填入空格。", "生病": "语义：音乐不会生病，“音乐很容易生病”说不通。", "结婚": "语义：音乐不能结婚，句子语义不通。", "打碎": "搭配：“打碎”多用于器物，“音乐很容易打碎”不自然。"}, "sentence_index": 0, "correct_answer": "忘记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他忘记了一口饭，咽了下去。", "explanation": "这里应该用〈吃〉。“忘记”指记忆消失，不能用于吞咽食物。"}, {"text": "他忘记了眼泪，没有哭出来。", "explanation": "这里应该用〈忍住〉。“忘记”指原先记住的内容从脑海中消失，不能用于控制眼泪。"}, {"text": "她忘记了一只手，用它去拿杯子。", "explanation": "这里应该用〈伸〉。“忘记”指记忆消失，不能用于身体的动作，应说“伸出手去拿杯子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": true, "explanation": "正确：原先记住的电话号码消失，可以填入空格。"}, {"text": "吃", "is_correct": false, "explanation": "语义：电话号码不能被吃，句子语义不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：电话号码不能被煮，句子语义不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象应是可洗的东西，电话号码不能被洗。"}], "explanations": {"忘记": "正确：原先记住的电话号码消失，可以填入空格。", "吃": "语义：电话号码不能被吃，句子语义不通。", "煮": "语义：电话号码不能被煮，句子语义不通。", "洗": "搭配：“洗”的对象应是可洗的东西，电话号码不能被洗。"}, "sentence_index": 6, "correct_answer": "忘记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请忘记距离，不要靠近。", "explanation": "这里应该用〈保持〉。“忘记”指记忆消失，不能用来表示保持某种状态。"}, {"text": "这台电脑忘记了，只能送去修理。", "explanation": "这里应该用〈损坏〉。“忘记”指记不住，不能用于机器坏掉。"}, {"text": "他深深地忘记了一口气，慢慢放松下来。", "explanation": "这里应该用〈吸〉。“忘记”指记忆消失，不能用于呼吸的动作，应说「吸了一口气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我忘记着那个单词。", "corrected_sentence": "我忘记了那个单词。", "error_description": "体标错误：表示忘掉的结果要用“了”，不能用“着”，应说「忘记了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我忘记了过这件事。", "corrected_sentence": "我忘记过这件事。", "error_description": "体标错误：表示曾经忘记的经历用“过”，“忘记了过”重复了体标，应说「忘记过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
