INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "音符是乐谱中用来记录音高和时值的符号，是音乐的基本元素。", "primary_collocate": null, "pronunciation": "yīn fú", "ipa": "in˥ fu˧˥", "syllable_count": 2, "sentences": [{"text": "音符在不同的位置，声音就不一样。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这首歌一共有三十个音符。", "target_word": "音符", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友在纸上画了几个音符。", "target_word": "音符", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钢琴老师说，这个音符要弹得慢一点。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐谱上的音符是黑色的小圆点。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认识乐谱上的每一个音符。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不懂这个音符，请你教教我。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个音符的时值很长，要唱两拍。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些音符按顺序弹出来。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个音符的时值是一拍。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "乐谱中记录音高和时值的符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71661477-2f15-4858-bb22-282f8f8aa695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10645, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音符", "is_correct": true, "explanation": "正确。音符是乐谱上标示音高和时值的符号，位置不同，音高和声音就不同。"}, {"text": "信封", "is_correct": false, "explanation": "语义：信封不发声，“位置”不会改变它的声音，句意不通。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词是文字，不会因位置不同而改变声音，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色是外观特征，与声音的高低、强弱无关，句意不通。"}], "explanations": {"音符": "正确。音符是乐谱上标示音高和时值的符号，位置不同，音高和声音就不同。", "信封": "语义：信封不发声，“位置”不会改变它的声音，句意不通。", "歌词": "语义：歌词是文字，不会因位置不同而改变声音，句意不通。", "颜色": "体貌：颜色是外观特征，与声音的高低、强弱无关，句意不通。"}, "sentence_index": 0, "correct_answer": "音符"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个单词的音符要记住。", "explanation": "这里应该用〈音标〉。音符指乐谱上的符号，记单词的读音要用音标。"}, {"text": "这个词有两个音符。", "explanation": "这里应该用〈音节〉。音符指乐谱上的符号，说词的音数要用音节。"}, {"text": "汉语有四个音符。", "explanation": "这里应该用〈声调〉。音符是乐谱上的符号，汉语的音高变化要用声调表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音符", "is_correct": true, "explanation": "正确。音符是乐谱上的符号，看不懂的正是这种符号，句意相合。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是穿戴用品，不是需要读懂的符号，与“看不懂”不合。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看不懂”的对象应是文字或符号，不能说“看不懂味道”。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，没有需要读懂的内容，句意不通。"}], "explanations": {"音符": "正确。音符是乐谱上的符号，看不懂的正是这种符号，句意相合。", "手套": "语义：手套是穿戴用品，不是需要读懂的符号，与“看不懂”不合。", "味道": "搭配：“看不懂”的对象应是文字或符号，不能说“看不懂味道”。", "花瓶": "语义：花瓶是器物，没有需要读懂的内容，句意不通。"}, "sentence_index": 6, "correct_answer": "音符"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个字的音符是第三声。", "explanation": "这里应该用〈声调〉。音符是乐谱上的符号，汉字的第几声要用“声调”。"}, {"text": "句子写完了，后面要加一个音符。", "explanation": "这里应该用〈标点符号〉。音符是乐谱上的符号，句子后面加的是“标点符号”，如句号。"}, {"text": "这道数学题的答案是一个音符。", "explanation": "这里应该用〈数字〉。音符是乐谱上的符号，数学题的答案要用“数字”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌里有一首很难的音符。", "corrected_sentence": "这首歌里有一个很难的音符。", "error_description": "量词错误：“音符”应用量词“个”。“首”用于歌曲、诗词，不能用于音符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在纸上写了一张音符。", "corrected_sentence": "他在纸上写了一个音符。", "error_description": "量词错误：“音符”应用量词“个”。“张”多用于纸张、平面物，不能用于音符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10654, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可变", "is_correct": true, "explanation": "反义：“固定”指不改变，“可变”指能够改变，两者意义相对。"}, {"text": "复杂", "is_correct": false, "explanation": "与“固定”无反义关系。“复杂”形容事情繁多、头绪多，不指变动与否。"}, {"text": "明亮", "is_correct": false, "explanation": "与“固定”无反义关系。“明亮”形容光线或颜色。"}, {"text": "高大", "is_correct": false, "explanation": "与“固定”无反义关系。“高大”形容体形。"}], "correct_answer": "可变", "explanations": {"可变": "反义：“固定”指不改变，“可变”指能够改变，两者意义相对。", "复杂": "与“固定”无反义关系。“复杂”形容事情繁多、头绪多，不指变动与否。", "明亮": "与“固定”无反义关系。“明亮”形容光线或颜色。", "高大": "与“固定”无反义关系。“高大”形容体形。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10654, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可变", "is_correct": true, "explanation": "反义：“固定”指不改变，“可变”指能够改变，两者意义相对。"}, {"text": "寒冷", "is_correct": false, "explanation": "与“固定”无反义关系。“寒冷”形容温度低。"}, {"text": "清楚", "is_correct": false, "explanation": "与“固定”无反义关系。“清楚”形容明白、不模糊。"}, {"text": "轻巧", "is_correct": false, "explanation": "与“固定”无反义关系。“轻巧”形容轻便灵活。"}], "correct_answer": "可变", "explanations": {"可变": "反义：“固定”指不改变，“可变”指能够改变，两者意义相对。", "寒冷": "与“固定”无反义关系。“寒冷”形容温度低。", "清楚": "与“固定”无反义关系。“清楚”形容明白、不模糊。", "轻巧": "与“固定”无反义关系。“轻巧”形容轻便灵活。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10654, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事物保持在一定的位置、状态或程度上，不变动。", "primary_collocate": null, "pronunciation": "gù dìng", "ipa": "ku˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "最早的音乐没有固定的记法，人们靠耳朵学习。", "target_word": "固定", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我在公司有固定的座位。", "target_word": "固定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的工作时间很固定。", "target_word": "固定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的价格是固定的，不能讲价。", "target_word": "固定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们每周三有固定的练习时间。", "target_word": "固定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有固定的住处，常常搬家。", "target_word": "固定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公交车按固定的路线行驶。", "target_word": "固定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每个月有固定的收入，生活不用担心。", "target_word": "固定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的上课时间是固定的，不会改变。", "target_word": "固定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的门禁密码是固定的，很少更换。", "target_word": "固定", "complexity_tier": "T3", "furigana": "zhè gè xiǎo qū de mén jìn mì mǎ shì gù dìng de hěn shǎo gēng huàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "固定资产", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：事物不变动的，如固定的时间、地点、做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c37cae-b219-4aee-bb4e-93cb237f46fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "固定", "is_correct": true, "explanation": "正确。固定读作 gù dìng，意思是不变动。"}, {"text": "注定", "is_correct": false, "explanation": "zhù 与 gù 的声母不同（zh 与 g），声调相同，意思是注定。"}, {"text": "估定", "is_correct": false, "explanation": "gū（第一声）与 gù（第四声）声调不同，意思是估计并确定。"}, {"text": "不定", "is_correct": false, "explanation": "bù 与 gù 的声母不同（b 与 g），声调相同，意思是不确定。"}], "explanations": {"固定": "正确。固定读作 gù dìng，意思是不变动。", "注定": "zhù 与 gù 的声母不同（zh 与 g），声调相同，意思是注定。", "估定": "gū（第一声）与 gù（第四声）声调不同，意思是估计并确定。", "不定": "bù 与 gù 的声母不同（b 与 g），声调相同，意思是不确定。"}, "sentence_index": null, "correct_answer": "固定"}, "level_3": {"options": [{"text": "鲜艳", "is_correct": false, "explanation": "语义：“鲜艳”形容颜色明亮，与记法无关，不能用来修饰“记法”。"}, {"text": "固定", "is_correct": true, "explanation": "正确。“没有固定的记法”指记法没有统一的标准，即不变动。"}, {"text": "友好", "is_correct": false, "explanation": "语义：“友好”形容人际态度，不能用来修饰“记法”。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体形，不能与“记法”搭配。"}], "explanations": {"鲜艳": "语义：“鲜艳”形容颜色明亮，与记法无关，不能用来修饰“记法”。", "固定": "正确。“没有固定的记法”指记法没有统一的标准，即不变动。", "友好": "语义：“友好”形容人际态度，不能用来修饰“记法”。", "高大": "搭配：“高大”形容体形，不能与“记法”搭配。"}, "sentence_index": 0, "correct_answer": "固定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水在零度以下会变成固定。", "explanation": "这里应该用〈固体〉。固定形容事物不变动，说物质的形态要用固体，固定不能指物质的状态类别。"}, {"text": "他很固定，不肯改变想法。", "explanation": "这里应该用〈固执〉。固定说的是事物不变动，形容人坚持己见要用固执。"}, {"text": "这个班的成绩很固定。", "explanation": "这里应该用〈稳定〉。固定指不变动，成绩起伏要用稳定来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来修饰“路线”。"}, {"text": "固定", "is_correct": true, "explanation": "正确。“按固定的路线行驶”指公交车沿着不变的路线走。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，与公交车的路线无关。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”不能修饰“路线”，不能说“沉重的路线”。"}], "explanations": {"清脆": "语义：“清脆”形容声音，不能用来修饰“路线”。", "固定": "正确。“按固定的路线行驶”指公交车沿着不变的路线走。", "温柔": "语义：“温柔”形容性情，与公交车的路线无关。", "沉重": "搭配：“沉重”不能修饰“路线”，不能说“沉重的路线”。"}, "sentence_index": 6, "correct_answer": "固定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的信念很固定，任何困难都不动摇。", "explanation": "这里应该用〈坚定〉。固定只说事物不变动，形容人的信念要用坚定。"}, {"text": "那位老人身体很固定。", "explanation": "这里应该用〈硬朗〉。固定说的是事物不变动，形容老人身体健康要用硬朗。"}, {"text": "这个西瓜很固定。", "explanation": "这里应该用〈甜〉。固定说的是事物不变动，形容水果的味道要用甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的上班时间比固定。", "corrected_sentence": "她的上班时间很固定。", "error_description": "“比”后须接比较对象，不能直接接“固定”；表达性质时应在“固定”前加程度副词“很”，说“很固定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的收入是固定地。", "corrected_sentence": "他的收入是固定的。", "error_description": "“的”与“地”混用：“固定”作谓语说明“收入”时要用“的”，不能用“地”，应说“是固定的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
