INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10655, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "帮助记忆的方法或技巧。", "primary_collocate": null, "pronunciation": "jì fǎ", "ipa": "tɕi˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "我找到了一个好记法，很快就记住了生词。", "target_word": "记法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教了我们一种记单词的新记法。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个记法很有用，我一下就记住了电话号码。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的记法不一样，你可以找适合自己的。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用图画帮助记忆是一种好记法。", "target_word": "记法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用自己的记法背汉字，效果很好。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听歌记单词是他最喜欢的记法。", "target_word": "记法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种记法能让你很快记住长长的数字。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友告诉我一个背课文的好记法。", "target_word": "记法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试前，同学们互相分享各自的记法。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "記法", "label": "繁体"}], "register": "中性", "sense_fingerprint": "帮助记忆的方法、技巧，如记单词的记法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c37cae-b219-4aee-bb4e-93cb237f46fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10655, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记法", "is_correct": true, "explanation": "正确。记法读作 jì fǎ，意思是帮助记忆的方法。"}, {"text": "戏法", "is_correct": false, "explanation": "xì 与 jì 的声母不同（x 与 j），声调相同，意思是戏法（变魔术）。"}, {"text": "寄发", "is_correct": false, "explanation": "fā（第一声）与 fǎ（第三声）声调不同，意思是寄出。"}, {"text": "继发", "is_correct": false, "explanation": "fā（第一声）与 fǎ（第三声）声调不同，意思是由其他情况引起而发生（如继发感染）。"}], "explanations": {"记法": "正确。记法读作 jì fǎ，意思是帮助记忆的方法。", "戏法": "xì 与 jì 的声母不同（x 与 j），声调相同，意思是戏法（变魔术）。", "寄发": "fā（第一声）与 fǎ（第三声）声调不同，意思是寄出。", "继发": "fā（第一声）与 fǎ（第三声）声调不同，意思是由其他情况引起而发生（如继发感染）。"}, "sentence_index": null, "correct_answer": "记法"}, "level_3": {"options": [{"text": "书桌", "is_correct": false, "explanation": "语义：“书桌”是家具，找到书桌不能让人“很快就记住了生词”。"}, {"text": "记法", "is_correct": true, "explanation": "正确。找到好的记法（记忆方法），所以很快记住了生词。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是电器，与记住生词没有关系。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“花朵”是植物，不能帮助人记住生词。"}], "explanations": {"书桌": "语义：“书桌”是家具，找到书桌不能让人“很快就记住了生词”。", "记法": "正确。找到好的记法（记忆方法），所以很快记住了生词。", "冰箱": "语义：“冰箱”是电器，与记住生词没有关系。", "花朵": "语义：“花朵”是植物，不能帮助人记住生词。"}, "sentence_index": 0, "correct_answer": "记法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我学会了一只记法，很快就记住了单词。", "explanation": "这里应该用〈种〉。“只”用于动物等，记法要用“种”来计量。"}, {"text": "今天的记法很晴朗。", "explanation": "这里应该用〈天气〉。记法指帮助记忆的方法，“很晴朗”形容天气，不能用来修饰记法。"}, {"text": "我把记法装进了箱子。", "explanation": "这里把〈记法〉当作可以装进箱子的实物，记法指帮助记忆的方法，是抽象的，不能装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“听歌记单词”没有关系，不能说“听歌记单词是他最喜欢的颜色”。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“听歌记单词”是一种方法，不能说成“最喜欢的手机”。"}, {"text": "记法", "is_correct": true, "explanation": "正确。“听歌记单词是他最喜欢的记法”指他喜欢的记忆方法。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是穿着用品，与记忆单词的方式无关。"}], "explanations": {"颜色": "语义：“颜色”与“听歌记单词”没有关系，不能说“听歌记单词是他最喜欢的颜色”。", "手机": "搭配：“听歌记单词”是一种方法，不能说成“最喜欢的手机”。", "记法": "正确。“听歌记单词是他最喜欢的记法”指他喜欢的记忆方法。", "鞋子": "语义：“鞋子”是穿着用品，与记忆单词的方式无关。"}, "sentence_index": 6, "correct_answer": "记法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师教我们一颗记法。", "explanation": "这里应该用〈种〉。“颗”用于颗粒状的东西，不能用于记法。"}, {"text": "这碗汤的记法很鲜美。", "explanation": "这里应该用〈味道〉。记法指帮助记忆的方法，“很鲜美”形容味道，不能用来修饰记法。"}, {"text": "这个房间的记法很宽敞。", "explanation": "这里应该用〈空间〉。记法指帮助记忆的方法，“很宽敞”形容空间，不能用来修饰记法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想出了一首新的记法。", "corrected_sentence": "我想出了一种新的记法。", "error_description": "量词错误：“记法”应用“种”计量，“首”只用于诗、歌等，不能用于记法，应说“一种新的记法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我用自己记法记电话号码，很方便。", "corrected_sentence": "我用自己的记法记电话号码，很方便。", "error_description": "漏掉“的”：“自己”修饰“记法”时要用“的”，应说“自己的记法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
