INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和动物的听觉器官。", "primary_collocate": null, "pronunciation": "ěr duo", "ipa": "ɚ˨˩˦ tuo", "syllable_count": 2, "sentences": [{"text": "最早的音乐没有固定的记法，人们靠耳朵学习。", "target_word": "耳朵", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "兔子的耳朵很长。", "target_word": "耳朵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的耳朵有点儿疼。", "target_word": "耳朵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大象用大耳朵扇风，让身体凉快一点。", "target_word": "耳朵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗的耳朵能听到很远的声音。", "target_word": "耳朵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手捂住耳朵，因为声音太大了。", "target_word": "耳朵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子总说耳朵里有声音，妈妈带他去看医生。", "target_word": "耳朵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的耳朵很灵，远处的小声音也听得到。", "target_word": "耳朵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的帽子很小，盖不住两只耳朵。", "target_word": "耳朵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，听音乐的时候，要用耳朵认真听。", "target_word": "耳朵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只耳朵", "label": "量词"}, {"form": "一对耳朵", "label": "量词"}, {"form": "耳朵眼", "label": "复合"}], "register": "中性", "sense_fingerprint": "耳朵：人和动物用来听声音的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8f5f600-ca28-4321-b5a3-d94418e5ffb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耳朵", "is_correct": true, "explanation": "正确：靠耳朵听来学习，与前文“没有固定的记法”相符。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：鼻子用来闻气味，不是学习音乐的器官，“靠鼻子学习”说不通。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：前文说音乐没有固定的记法，不存在可以依靠的乐谱。"}, {"text": "脚", "is_correct": false, "explanation": "搭配：“靠脚学习音乐”不成立，学习音乐靠的是耳朵听。"}], "explanations": {"耳朵": "正确：靠耳朵听来学习，与前文“没有固定的记法”相符。", "鼻子": "语义：鼻子用来闻气味，不是学习音乐的器官，“靠鼻子学习”说不通。", "乐谱": "语义：前文说音乐没有固定的记法，不存在可以依靠的乐谱。", "脚": "搭配：“靠脚学习音乐”不成立，学习音乐靠的是耳朵听。"}, "sentence_index": 0, "correct_answer": "耳朵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我戴上耳朵听歌。", "explanation": "这里应该用〈耳机〉。戴在身上听歌的是耳机，耳朵是人身上的器官，不能被戴上。"}, {"text": "他用耳朵闻花。", "explanation": "这里应该用〈鼻子〉。闻气味要用鼻子，耳朵只负责听声音。"}, {"text": "他用耳朵看书。", "explanation": "这里应该用〈眼睛〉。看书要用眼睛，耳朵只用来听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耳朵", "is_correct": true, "explanation": "正确：耳朵里有声音，妈妈带孩子去看医生，符合孩子耳朵不舒服的语境。"}, {"text": "嘴唇", "is_correct": false, "explanation": "搭配：“嘴唇里有声音”不成立，“有声音”一般说在耳朵、肚子等部位，嘴唇不说这样搭配。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是人的身体部位，后文去看医生，与“电脑里有声音”对不上。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是身体部位，“去看医生”与“书包里有声音”没有关系。"}], "explanations": {"耳朵": "正确：耳朵里有声音，妈妈带孩子去看医生，符合孩子耳朵不舒服的语境。", "嘴唇": "搭配：“嘴唇里有声音”不成立，“有声音”一般说在耳朵、肚子等部位，嘴唇不说这样搭配。", "电脑": "语义：电脑不是人的身体部位，后文去看医生，与“电脑里有声音”对不上。", "书包": "语义：书包不是身体部位，“去看医生”与“书包里有声音”没有关系。"}, "sentence_index": 6, "correct_answer": "耳朵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用耳朵尝了尝汤，觉得有点儿咸。", "explanation": "这里应该用〈舌头〉。尝味道要用舌头，耳朵只用来听声音。"}, {"text": "我用耳朵摸了摸小猫的头。", "explanation": "这里应该用〈手〉。摸东西要用手，耳朵是听声音的器官。"}, {"text": "她用耳朵走了很远的路。", "explanation": "这里应该用〈脚〉。走路要用脚，耳朵只负责听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小狗有两根耳朵，竖得很高。", "corrected_sentence": "这只小狗有两只耳朵，竖得很高。", "error_description": "量词错误：错误形式为“两根耳朵”，正确形式为“两只耳朵”。耳朵的量词是“只”，“根”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫竖上两只耳朵，听着远处的动静。", "corrected_sentence": "小猫竖起两只耳朵，听着远处的动静。", "error_description": "补语错误：错误形式为“竖上两只耳朵”，正确形式为“竖起两只耳朵”。表示耳朵由下向上直立，要用结果补语“起”，“竖上”不这样说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
