INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10657, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用乐器表演音乐，或指表演音乐的过程。", "primary_collocate": null, "pronunciation": "yǎn zòu", "ipa": "jɛn˨˩˦ tsou̯˥˩", "syllable_count": 2, "sentences": [{"text": "后来，作曲家需要把自己的音乐写下来，让更多人可以演奏。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "从简单符号到复杂系统，它帮助音乐跨越时间与空间，被更多人理解和演奏。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "她从五岁开始学习演奏钢琴。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会上，乐队演奏了三首老歌。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他演奏小提琴的样子非常专注。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时会演奏二胡。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上的钢琴家正在演奏一首新曲子。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏结束后，观众们一起站起来鼓掌。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子很难演奏，需要多年的练习。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演奏了", "label": "体标"}, {"form": "演奏过", "label": "体标"}, {"form": "演奏着", "label": "体标"}, {"form": "演奏家", "label": "复合"}, {"form": "演奏会", "label": "复合"}], "register": "中性", "sense_fingerprint": "用乐器表演音乐或表演音乐的过程：演奏钢琴、演奏乐曲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4722aed3-9c6c-4f5b-9332-20e838c26bdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演奏", "is_correct": true, "explanation": "“演奏”指用乐器表演，“让更多人可以演奏”说的是乐谱能让别人表演这首曲子，正好吻合。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能用于音乐。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：前文说要把音乐写下来，是为了保存；“让更多人可以忘记”与写下来的目的相反。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁”是毁掉，与“写下来，让更多人可以……”的目的相悖。"}], "explanations": {"演奏": "“演奏”指用乐器表演，“让更多人可以演奏”说的是乐谱能让别人表演这首曲子，正好吻合。", "翻译": "搭配：“翻译”的对象是语言或文字，不能用于音乐。", "忘记": "语义：前文说要把音乐写下来，是为了保存；“让更多人可以忘记”与写下来的目的相反。", "销毁": "语义：“销毁”是毁掉，与“写下来，让更多人可以……”的目的相悖。"}, "sentence_index": 0, "correct_answer": "演奏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个魔术师在街头演奏了一套新魔术。", "explanation": "这里应该用〈表演〉。演奏指用乐器表演音乐，表演魔术要用“表演”。"}, {"text": "他在会议上演奏了一篇发言。", "explanation": "这里应该用〈发表〉。演奏只用于音乐，发言和讲话要说“发表”。"}, {"text": "她在晚会上演奏了一首诗。", "explanation": "这里应该用〈朗诵〉。演奏指用乐器表演，念诗要说“朗诵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演奏", "is_correct": true, "explanation": "“演奏”指用乐器表演音乐，宾语“二胡”是乐器，符合“会”的语境；其余三项都不能与乐器搭配。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”的对象是人或做法，不能用于乐器。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”用于书刊、乐谱等作品，不能与乐器搭配。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”针对纸张和书册，不能用于乐器。"}], "explanations": {"演奏": "“演奏”指用乐器表演音乐，宾语“二胡”是乐器，符合“会”的语境；其余三项都不能与乐器搭配。", "批评": "语义：“批评”的对象是人或做法，不能用于乐器。", "出版": "搭配：“出版”用于书刊、乐谱等作品，不能与乐器搭配。", "装订": "搭配：“装订”针对纸张和书册，不能用于乐器。"}, "sentence_index": 6, "correct_answer": "演奏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在厨房里演奏了一锅好汤。", "explanation": "这里应该用〈做〉。演奏指用乐器表演，做汤要用“做”。"}, {"text": "她在舞台上演奏了一段舞蹈。", "explanation": "这里应该用〈跳〉。演奏的对象是乐曲，跳舞要用“跳”。"}, {"text": "他用画笔演奏了一幅画。", "explanation": "这里应该用〈画〉。演奏指用乐器发出音乐，作画要用“画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟演奏的很好。", "corrected_sentence": "我弟弟演奏得很好。", "error_description": "补语标记错误：“演奏”后引出程度补语要用“得”，不能用“的”，应说“演奏得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时演奏了过钢琴。", "corrected_sentence": "他年轻时演奏过钢琴。", "error_description": "体标重复：“了”和“过”不能同时用在动词后面，表示曾经做过某事只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
