INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指声音的高低程度，由发声体振动的频率决定。", "primary_collocate": null, "pronunciation": "yīn gāo", "ipa": "in˥ kɑu̯˥", "syllable_count": 2, "sentences": [{"text": "在古代，有些地方用字母表示音高，有些用符号。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "音高", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "此一系统通过线与间的明确对应关系实现了音高的空间化表征，为音乐理论的系统化提供了必要条件。", "target_word": "音高", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "勋伯格的十二音体系迫使理论家重构音高组织逻辑，序列主义将节奏、时值、力度等参数均纳入控制，催生出高度数学化的记谱语言。", "target_word": "音高", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个歌手的音高很准。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小提琴的音高可以用手指来调整。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩说话的音高比男孩高。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴每个键的音高都不一样。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听出了两个声音的音高不同。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先练习唱准音高。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绝对音高", "label": "复合"}, {"form": "相对音高", "label": "复合"}], "register": "中性", "sense_fingerprint": "声音的高低程度，由振动频率决定：音高准、标记音高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4722aed3-9c6c-4f5b-9332-20e838c26bdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音高", "is_correct": true, "explanation": "“音高”指声音的高低，用字母或符号标记的正是这种声音属性，符合语境。"}, {"text": "观众", "is_correct": false, "explanation": "语义：“观众”是人，不能用字母或符号来表示。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是实物，与声音的标记无关。"}, {"text": "歌手", "is_correct": false, "explanation": "搭配：“表示”的对象应是抽象的属性，“歌手”是人，不能作为被标记的对象。"}], "explanations": {"音高": "“音高”指声音的高低，用字母或符号标记的正是这种声音属性，符合语境。", "观众": "语义：“观众”是人，不能用字母或符号来表示。", "桌子": "语义：“桌子”是实物，与声音的标记无关。", "歌手": "搭配：“表示”的对象应是抽象的属性，“歌手”是人，不能作为被标记的对象。"}, "sentence_index": 0, "correct_answer": "音高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把音响的音高调大了。", "explanation": "这里应该用〈音量〉。音高指声音的高低，音响的大小要用“音量”。"}, {"text": "这首曲子的音高很快。", "explanation": "这里应该用〈节奏〉。音高指高低，快慢要用“节奏”。"}, {"text": "这台音箱的音高很贵。", "explanation": "这里应该用〈价格〉。音高指声音的高低，价钱要用“价格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音高", "is_correct": true, "explanation": "“音高”指声音的高低，“女孩说话的音高比男孩高”符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人体的高矮，不能用来形容说话的声音。"}, {"text": "肤色", "is_correct": false, "explanation": "语义：“肤色”与声音的高低无关，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能修饰“说话”，句子不通。"}], "explanations": {"音高": "“音高”指声音的高低，“女孩说话的音高比男孩高”符合语境。", "身高": "语义：“身高”指人体的高矮，不能用来形容说话的声音。", "肤色": "语义：“肤色”与声音的高低无关，句子不通。", "年龄": "搭配：“年龄”不能修饰“说话”，句子不通。"}, "sentence_index": 6, "correct_answer": "音高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大楼的音高有两百米。", "explanation": "这里应该用〈高度〉。音高指声音的高低，建筑的高矮要用“高度”。"}, {"text": "今天的音高是三十度。", "explanation": "这里应该用〈温度〉。音高指声音的高低，气温要用“温度”。"}, {"text": "她的音高有一米六。", "explanation": "这里应该用〈身高〉。音高指声音的高低，人的高矮要用“身高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他能分辨出两只不同的音高。", "corrected_sentence": "他能分辨出两种不同的音高。", "error_description": "量词错误：“音高”是抽象的声音属性，量词应用“种”，“只”不能用于音高。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师很满意学生音高。", "corrected_sentence": "老师很满意学生的音高。", "error_description": "结构助词错误：表示所属要用“的”，“学生音高”应说“学生的音高”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10663, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": true, "explanation": "粗糙：与“精细”构成反义，指做工不细致，与“雕刻得很精细”相反。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：形容质地软，与“精细”的做工义没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线或颜色，与“精细”不构成反义。"}, {"text": "寒冷", "is_correct": false, "explanation": "寒冷：形容温度，与“精细”不构成反义。"}], "correct_answer": "粗糙", "explanations": {"粗糙": "粗糙：与“精细”构成反义，指做工不细致，与“雕刻得很精细”相反。", "柔软": "柔软：形容质地软，与“精细”的做工义没有反义关系。", "明亮": "明亮：形容光线或颜色，与“精细”不构成反义。", "寒冷": "寒冷：形容温度，与“精细”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10663, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": true, "explanation": "粗糙：与“精细”构成反义，指做工不细致，与“做得很精细”相反。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖：形容温度或感觉，与“精细”不构成反义。"}, {"text": "古老", "is_correct": false, "explanation": "古老：形容年代久远，与“精细”不构成反义。"}, {"text": "圆润", "is_correct": false, "explanation": "圆润：形容形状或声音饱满，与“精细”不构成反义。"}], "correct_answer": "粗糙", "explanations": {"粗糙": "粗糙：与“精细”构成反义，指做工不细致，与“做得很精细”相反。", "温暖": "温暖：形容温度或感觉，与“精细”不构成反义。", "古老": "古老：形容年代久远，与“精细”不构成反义。", "圆润": "圆润：形容形状或声音饱满，与“精细”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10663, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容物品制作或做事非常细致、精确。", "primary_collocate": null, "pronunciation": "jīng xì", "ipa": "tɕiŋ⁵⁵ ɕi⁵¹", "syllable_count": 2, "sentences": [{"text": "为了实现高效巡航，航空工程师必须在气动构型上进行精细权衡，以最大化升阻比——即单位阻力下所能产生的升力，这是衡量飞行效率的关键指标。", "target_word": "精细", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "随着音乐理论的进步，记谱法变得更精细。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这件玉器的做工非常精细。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅雕刻得很精细，连小花瓣都清楚。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用精细的针脚绣了一朵花。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图画得很精细，小路都标出来了。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表里的零件做得特别精细。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种工作需要精细的计算，不能马虎。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的点心做得很精细，样子也好看。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把模型的每个部分都做得很精细。", "target_word": "精细", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精細", "label": "繁体"}, {"form": "精细化", "label": "复合"}], "register": "书面", "sense_fingerprint": "制作或做事细致精确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65ed119e-0d7b-4fd6-9dc2-f9c5d6a85cda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10663, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精细", "is_correct": true, "explanation": "精细：形容权衡细致、精确，与以最大化升阻比为目标的工程语境相符。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色明亮，不能修饰“权衡”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来修饰“权衡”。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容环境安静，与权衡的精确程度无关。"}], "explanations": {"精细": "精细：形容权衡细致、精确，与以最大化升阻比为目标的工程语境相符。", "鲜艳": "搭配：“鲜艳”形容颜色明亮，不能修饰“权衡”。", "清脆": "搭配：“清脆”形容声音，不能用来修饰“权衡”。", "寂静": "语义：“寂静”形容环境安静，与权衡的精确程度无关。"}, "sentence_index": 0, "correct_answer": "精细"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛很精细。", "explanation": "这里应该用〈精彩〉。精细形容做事或制作细致，比赛的好看要用“精彩”。"}, {"text": "老人家今天看起来很精细。", "explanation": "这里应该用〈精神〉。精细形容做事细致，人的气色和精神状态要用“精神”。"}, {"text": "这次台风的力量很精细。", "explanation": "这里应该用〈强〉。精细形容制作或做事的细致程度，形容力量要用“强”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精细", "is_correct": true, "explanation": "精细：手表里的零件很小，要求做得精密细致，符合语境。"}, {"text": "宽大", "is_correct": false, "explanation": "语义：手表里的零件很小，“宽大”与零件的尺寸相矛盾。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能修饰“零件做得”的做工。"}, {"text": "柔和", "is_correct": false, "explanation": "语义：“柔和”形容光线或声音，与零件的做工无关。"}], "explanations": {"精细": "精细：手表里的零件很小，要求做得精密细致，符合语境。", "宽大": "语义：手表里的零件很小，“宽大”与零件的尺寸相矛盾。", "响亮": "搭配：“响亮”形容声音，不能修饰“零件做得”的做工。", "柔和": "语义：“柔和”形容光线或声音，与零件的做工无关。"}, "sentence_index": 6, "correct_answer": "精细"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的雨下得很精细。", "explanation": "这里应该用〈细〉。精细形容做工细致，形容雨点细密要用“细”。"}, {"text": "他长得很精细。", "explanation": "这里应该用〈清秀〉。精细形容做事或制作的细致，形容人的长相要用“清秀”。"}, {"text": "她的皮肤很精细。", "explanation": "这里应该用〈细腻〉。精细形容做工或做事的精确，形容皮肤质地要用“细腻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器的零件做得很精细化。", "corrected_sentence": "这台机器的零件做得很精细。", "error_description": "“精细化”是动词，指使事物变得更精细；形容零件做工细致要用形容词“精细”，不能说“很精细化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的蛋糕做很精细。", "corrected_sentence": "这家店的蛋糕做得很精细。", "error_description": "漏掉补语标记“得”：“做”后接程度补语“很精细”，应说“做得很精细”，不能说“做很精细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10665, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10665, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10665, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "线谱，即五线谱，是一种用五条平行线来记录音符的记谱法。", "primary_collocate": null, "pronunciation": "xiàn pǔ", "ipa": "ɕjɛn˥˩ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "欧洲中世纪出现了线谱的早期形式。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "虽然各地有不同习惯，但是线谱慢慢成为国际通用的方法。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然今天学习西方线谱的人很多，但这些古老方法仍有价值。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早期的乐谱只能粗略地记下旋律，直到线谱出现，人们才能准确地记下音高。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "至文艺复兴时期，线谱逐渐确立为标准，配合小节线、调号与拍号的引入，记谱法日趋精密。", "target_word": "线谱", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "电子音乐的兴起更带来全新维度：频谱分析、波形图、算法生成乐谱等技术手段，使记谱超越线谱的视觉范式，进入数据化表达领域。", "target_word": "线谱", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "传统线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "线谱", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "老师在黑板上画了一张线谱。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学音乐的人要先学会看线谱。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着线谱，慢慢弹起了钢琴。", "target_word": "线谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "五线谱", "label": "复合"}, {"form": "张", "label": "量词"}], "register": "中性", "sense_fingerprint": "用平行线记录音符的记谱法，即五线谱：看线谱、一张线谱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4722aed3-9c6c-4f5b-9332-20e838c26bdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线谱", "is_correct": true, "explanation": "正确。线谱即五线谱，它的早期形式在欧洲中世纪出现。"}, {"text": "手机", "is_correct": false, "explanation": "语义：中世纪欧洲没有手机，与“欧洲中世纪”的时代背景冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是近代才发明的家用电器，中世纪不可能出现它的早期形式。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”不是记谱法，与“出现了……的早期形式”的记谱语境不符。"}], "explanations": {"线谱": "正确。线谱即五线谱，它的早期形式在欧洲中世纪出现。", "手机": "语义：中世纪欧洲没有手机，与“欧洲中世纪”的时代背景冲突。", "冰箱": "语义：冰箱是近代才发明的家用电器，中世纪不可能出现它的早期形式。", "饭菜": "语义：“饭菜”不是记谱法，与“出现了……的早期形式”的记谱语境不符。"}, "sentence_index": 0, "correct_answer": "线谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的线谱是用数字写的，初学者很容易看懂。", "explanation": "这里应该用〈简谱〉。线谱指五线谱，靠线和音符表示音高；用数字记音的是简谱，两者不能互换。"}, {"text": "医生看了我的线谱，说我的心脏没问题。", "explanation": "这里应该用〈心电图〉。线谱是记录音符的五线谱，检查心脏要看心电图。"}, {"text": "妈妈照着线谱做了一桌菜。", "explanation": "这里应该用〈食谱〉。线谱是音乐的记谱法，不能用来做菜；做菜要照食谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线谱", "is_correct": true, "explanation": "正确。线谱即五线谱，句中“仍是全球通行的技术语言”指的就是它。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱记录烹饪方法，不是音乐记谱语言，与“交响乐团、歌剧制作”的语境不符。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是发声的器具，不是记谱语言，无法“支撑……作曲教学”。"}, {"text": "顺口溜", "is_correct": false, "explanation": "语域：“顺口溜”是口头俗语，与“技术语言”和学院派教学的书面语境不协调。"}], "explanations": {"线谱": "正确。线谱即五线谱，句中“仍是全球通行的技术语言”指的就是它。", "菜谱": "语义：菜谱记录烹饪方法，不是音乐记谱语言，与“交响乐团、歌剧制作”的语境不符。", "乐器": "语义：乐器是发声的器具，不是记谱语言，无法“支撑……作曲教学”。", "顺口溜": "语域：“顺口溜”是口头俗语，与“技术语言”和学院派教学的书面语境不协调。"}, "sentence_index": 6, "correct_answer": "线谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的线谱写着怎么安装。", "explanation": "这里应该用〈说明书〉。线谱是记音符的五线谱，不记录安装步骤；说明安装要用说明书。"}, {"text": "游客拿着线谱，很快找到了博物馆。", "explanation": "这里应该用〈地图〉。线谱是乐谱记法，不标示路线；找路要用地图。"}, {"text": "饭店的线谱上写着今天的菜。", "explanation": "这里应该用〈菜单〉。线谱是音乐记谱，不能用来列出菜品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把线谱是老师送给我的。", "corrected_sentence": "这张线谱是老师送给我的。", "error_description": "错误：量词“把”用错。线谱是纸质乐谱，应与量词“张”搭配，说“这张线谱”；“把”用于椅子、刀等，不能修饰线谱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学钢琴的人要先读懂线谱们。", "corrected_sentence": "学钢琴的人要先读懂线谱。", "error_description": "错误：多加了复数后缀“们”。“们”只用于指人，不能加在“线谱”后面；应说“读懂线谱”，表示多份时可说“很多线谱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10666, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内容", "is_correct": true, "explanation": "内容：与形式相对，指事物所包含的实质。"}, {"text": "花园", "is_correct": false, "explanation": "花园与形式没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户与形式没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流与形式没有反义关系。"}], "correct_answer": "内容", "explanations": {"内容": "内容：与形式相对，指事物所包含的实质。", "花园": "花园与形式没有反义关系。", "窗户": "窗户与形式没有反义关系。", "河流": "河流与形式没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10666, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内容", "is_correct": true, "explanation": "内容：与形式相对，指信息或作品所包含的实质。"}, {"text": "大海", "is_correct": false, "explanation": "大海与形式没有反义关系。"}, {"text": "草地", "is_correct": false, "explanation": "草地与形式没有反义关系。"}, {"text": "课桌", "is_correct": false, "explanation": "课桌与形式没有反义关系。"}], "correct_answer": "内容", "explanations": {"内容": "内容：与形式相对，指信息或作品所包含的实质。", "大海": "大海与形式没有反义关系。", "草地": "草地与形式没有反义关系。", "课桌": "课桌与形式没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物显现出来的样子、状态或结构。", "primary_collocate": null, "pronunciation": "xíng shì", "ipa": "ɕiŋ˧˥ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "欧洲中世纪出现了线谱的早期形式。", "target_word": "形式", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "这次演出的形式很新，有歌有舞。", "target_word": "形式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐是一种用声音表达感情的艺术形式。", "target_word": "形式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内容很重要，形式也很重要。", "target_word": "形式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这首歌的形式很简单，只有两段。", "target_word": "形式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "诗有很多形式，比如五言诗和七言诗。", "target_word": "形式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信息可以用文字的形式保存下来。", "target_word": "形式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新学校的建筑形式很特别，一半像船，一半像山。", "target_word": "形式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用唱歌的形式把故事讲给孩子们听。", "target_word": "形式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告要写成书面形式，不能只口头说。", "target_word": "形式", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种形式", "label": "量词"}, {"form": "形式主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "形式：事物表现出来的状态或结构，与内容相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8f5f600-ca28-4321-b5a3-d94418e5ffb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "形式", "is_correct": true, "explanation": "正确：形式读 xíng shì，指事物显现出来的样子、结构。"}, {"text": "情势", "is_correct": false, "explanation": "声母不同：情势读 qíng shì，q 与 x 不同，意思是情况和局势。"}, {"text": "行驶", "is_correct": false, "explanation": "声调不同：行驶读 xíng shǐ，第二个音节是第三声，意思是车船等移动。"}, {"text": "姓氏", "is_correct": false, "explanation": "声调不同：姓氏读 xìng shì，第一个音节是第四声，意思是姓。"}], "explanations": {"形式": "正确：形式读 xíng shì，指事物显现出来的样子、结构。", "情势": "声母不同：情势读 qíng shì，q 与 x 不同，意思是情况和局势。", "行驶": "声调不同：行驶读 xíng shǐ，第二个音节是第三声，意思是车船等移动。", "姓氏": "声调不同：姓氏读 xìng shì，第一个音节是第四声，意思是姓。"}, "sentence_index": null, "correct_answer": "形式"}, "level_3": {"options": [{"text": "形式", "is_correct": true, "explanation": "正确：线谱的早期形式指记谱的早期样式，与前文的线谱相符。"}, {"text": "颜值", "is_correct": false, "explanation": "语域：“颜值”是网络口语，与这段书面的历史叙述不合，也不指线谱。"}, {"text": "价格", "is_correct": false, "explanation": "语义：线谱是记谱的方法，不说它有价格，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”一般指食物或气息，线谱的早期不说味道。"}], "explanations": {"形式": "正确：线谱的早期形式指记谱的早期样式，与前文的线谱相符。", "颜值": "语域：“颜值”是网络口语，与这段书面的历史叙述不合，也不指线谱。", "价格": "语义：线谱是记谱的方法，不说它有价格，句意不通。", "味道": "搭配：“味道”一般指食物或气息，线谱的早期不说味道。"}, "sentence_index": 0, "correct_answer": "形式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的形式很深刻。", "explanation": "这里应该用〈意义〉。“深刻”说的是内容，形式指外在的结构，不能用来形容形式。"}, {"text": "目前的形式很严峻。", "explanation": "这里应该用〈形势〉。“严峻”形容局势，形式指事物外在的样子或结构，二者读音相同，容易混淆。"}, {"text": "这道菜的形式很咸。", "explanation": "这里应该用〈味道〉。“咸”形容味道，形式指事物外在的样子或结构，不能用来描述咸淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10666, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "形式", "is_correct": true, "explanation": "正确：形式读 xíng shì，指事物显现出来的样子、结构。"}, {"text": "幸事", "is_correct": false, "explanation": "声调不同：幸事读 xìng shì，第一个音节是第四声，意思是令人高兴的事。"}, {"text": "行使", "is_correct": false, "explanation": "声调不同：行使读 xíng shǐ，第二个音节是第三声，意思是运用权力。"}, {"text": "形似", "is_correct": false, "explanation": "声母不同：形似读 xíng sì，第二个音节是 s 声母，不是 sh，意思是形状相像。"}], "explanations": {"形式": "正确：形式读 xíng shì，指事物显现出来的样子、结构。", "幸事": "声调不同：幸事读 xìng shì，第一个音节是第四声，意思是令人高兴的事。", "行使": "声调不同：行使读 xíng shǐ，第二个音节是第三声，意思是运用权力。", "形似": "声母不同：形似读 xíng sì，第二个音节是 s 声母，不是 sh，意思是形状相像。"}, "sentence_index": null, "correct_answer": "形式"}, "level_3": {"options": [{"text": "形式", "is_correct": true, "explanation": "正确：用文字的形式保存信息，“形式”指表达信息的方式，与前文相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：文字不是颜色，不能用颜色来保存信息。"}, {"text": "口音", "is_correct": false, "explanation": "搭配：“口音”指说话的声音特点，不能修饰文字，“文字的口音”不成立。"}, {"text": "声音", "is_correct": false, "explanation": "语义：用文字保存信息不能说“文字的声音”，声音要靠录音来保存。"}], "explanations": {"形式": "正确：用文字的形式保存信息，“形式”指表达信息的方式，与前文相符。", "颜色": "语义：文字不是颜色，不能用颜色来保存信息。", "口音": "搭配：“口音”指说话的声音特点，不能修饰文字，“文字的口音”不成立。", "声音": "语义：用文字保存信息不能说“文字的声音”，声音要靠录音来保存。"}, "sentence_index": 6, "correct_answer": "形式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的形式对我们很有利。", "explanation": "这里应该用〈形势〉。“有利”说的是局势的发展，形式指事物外在的样子或结构，二者读音相同，容易混淆。"}, {"text": "他的说话形式很温和，大家都愿意听。", "explanation": "这里应该用〈方式〉。说话用“方式”，指做事说话的方法；形式指事物外在的结构。"}, {"text": "他每天跑步，身体形式很好。", "explanation": "这里应该用〈状况〉。身体好不好说“身体状况”，形式不用来描述健康。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书法是一条很美的艺术形式。", "corrected_sentence": "书法是一种很美的艺术形式。", "error_description": "量词错误：错误形式为“一条”，正确形式为“一种”。“形式”的量词是“种”，“条”用于长条形的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校用两个形式通知了家长。", "corrected_sentence": "学校用两种形式通知了家长。", "error_description": "量词错误：错误形式为“两个形式”，正确形式为“两种形式”。形式的量词是“种”，“个”用于个体的人或物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
