INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "五线谱是一种音乐记谱法，通过在五条平行横线上标记音符来表示音高和节奏。", "primary_collocate": null, "pronunciation": "wǔ xiàn pǔ", "ipa": "u˨˩˦ ɕjɛn˥˩ pʰu˨˩˦", "syllable_count": 3, "sentences": [{"text": "虽然各地有不同习惯，但是五线谱慢慢成为国际通用的方法。", "target_word": "五线谱", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "虽然今天学习西方五线谱的人很多，但这些古老方法仍有价值。", "target_word": "五线谱", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "至文艺复兴时期，五线谱逐渐确立为标准，配合小节线、调号与拍号的引入，记谱法日趋精密。", "target_word": "五线谱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电子音乐的兴起更带来全新维度：频谱分析、波形图、算法生成乐谱等技术手段，使记谱超越五线谱的视觉范式，进入数据化表达领域。", "target_word": "五线谱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "传统五线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "五线谱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他正在看五线谱，准备明天的音乐课。", "target_word": "五线谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "五线谱上有高音谱号，也有低音谱号。", "target_word": "五线谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用五线谱写了一首很短的钢琴曲。", "target_word": "五线谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在欧洲，很多学校都教学生看五线谱。", "target_word": "五线谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书里有很多歌，每首都有五线谱。", "target_word": "五线谱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "五線譜", "label": "繁体"}, {"form": "张", "label": "量词"}, {"form": "本", "label": "量词"}], "register": "中性", "sense_fingerprint": "用五条平行横线记录音高与节奏的西方记谱法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4722aed3-9c6c-4f5b-9332-20e838c26bdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "五线谱", "is_correct": true, "explanation": "正确。五线谱是国际通用的记谱方法，句中“慢慢成为国际通用的方法”指的就是它。"}, {"text": "普通话", "is_correct": false, "explanation": "语义：普通话是汉语的标准语言，不是记谱方法，与“国际通用的方法”不符。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言只在某地使用，与句中“国际通用”的转折相矛盾。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“成为……的方法”要求指做事的办法，“乐器”是实物，不能这样搭配。"}], "explanations": {"五线谱": "正确。五线谱是国际通用的记谱方法，句中“慢慢成为国际通用的方法”指的就是它。", "普通话": "语义：普通话是汉语的标准语言，不是记谱方法，与“国际通用的方法”不符。", "方言": "语义：方言只在某地使用，与句中“国际通用”的转折相矛盾。", "乐器": "搭配：“成为……的方法”要求指做事的办法，“乐器”是实物，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "五线谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的五线谱是用数字写的，初学者很容易看懂。", "explanation": "这里应该用〈简谱〉。五线谱用五条线和音符记音高；用数字记音的是简谱。"}, {"text": "医生看了我的五线谱，说我的心脏没问题。", "explanation": "这里应该用〈心电图〉。五线谱只记音高和节奏，检查心脏要看心电图。"}, {"text": "五线谱说明天会下雨。", "explanation": "这里应该用〈天气预报〉。五线谱只记音高和节奏，不报天气；报天气要用天气预报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "五线谱", "is_correct": true, "explanation": "正确。五线谱上画着高音谱号和低音谱号，句中“上有高音谱号”指的就是它。"}, {"text": "手表", "is_correct": false, "explanation": "语义：手表上没有谱号，谱号是乐谱中标示音高基准的符号。"}, {"text": "信封", "is_correct": false, "explanation": "语义：信封上不会标示谱号，谱号只出现在乐谱上。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱记录食材和做法，不会标示谱号，与“高音谱号”“低音谱号”的语境不符。"}], "explanations": {"五线谱": "正确。五线谱上画着高音谱号和低音谱号，句中“上有高音谱号”指的就是它。", "手表": "语义：手表上没有谱号，谱号是乐谱中标示音高基准的符号。", "信封": "语义：信封上不会标示谱号，谱号只出现在乐谱上。", "菜谱": "语义：菜谱记录食材和做法，不会标示谱号，与“高音谱号”“低音谱号”的语境不符。"}, "sentence_index": 6, "correct_answer": "五线谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天照着五线谱做菜。", "explanation": "这里应该用〈菜谱〉。五线谱是音乐记谱法，不能用来做菜。"}, {"text": "我们沿着五线谱找到了博物馆。", "explanation": "这里应该用〈地图〉。五线谱只记音高和节奏，不标路线。"}, {"text": "我们用五线谱查到了这个字的意思。", "explanation": "这里应该用〈字典〉。五线谱只记音高和节奏，查字义要用字典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师发给我们一只五线谱。", "corrected_sentence": "老师发给我们一张五线谱。", "error_description": "错误：量词“只”用错。“只”用于动物等，五线谱是纸质乐谱，应说“一张五线谱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于看懂了五线谱们。", "corrected_sentence": "她终于看懂了五线谱。", "error_description": "错误：多加了复数后缀“们”。“们”只用于指人，不能加在“五线谱”后面；应说“看懂了五线谱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10674, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专用", "is_correct": true, "explanation": "反义：通用指普遍适用，专用指只用于特定对象，两者意义相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：漂亮形容外貌，与用途范围无关。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：迅速形容速度，与用途范围无关。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：复杂形容结构或难度，与用途范围无关。"}], "correct_answer": "专用", "explanations": {"专用": "反义：通用指普遍适用，专用指只用于特定对象，两者意义相对。", "漂亮": "无关：漂亮形容外貌，与用途范围无关。", "迅速": "无关：迅速形容速度，与用途范围无关。", "复杂": "无关：复杂形容结构或难度，与用途范围无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10674, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专用", "is_correct": true, "explanation": "反义：通用指普遍适用，专用指只用于特定对象，两者意义相对。"}, {"text": "危险", "is_correct": false, "explanation": "无关：危险形容有害的状况，与用途范围无关。"}, {"text": "缓慢", "is_correct": false, "explanation": "无关：缓慢形容速度，与用途范围无关。"}, {"text": "安静", "is_correct": false, "explanation": "无关：安静形容声音或环境，与用途范围无关。"}], "correct_answer": "专用", "explanations": {"专用": "反义：通用指普遍适用，专用指只用于特定对象，两者意义相对。", "危险": "无关：危险形容有害的状况，与用途范围无关。", "缓慢": "无关：缓慢形容速度，与用途范围无关。", "安静": "无关：安静形容声音或环境，与用途范围无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10674, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指普遍适用或共同使用的。", "primary_collocate": null, "pronunciation": "tōng yòng", "ipa": "tʰʊŋ˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "虽然各地有不同习惯，但是五线谱慢慢成为国际通用的方法。", "target_word": "通用", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "英语是国际通用的语言。", "target_word": "通用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种货币在很多国家都通用。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个标志全世界通用。", "target_word": "通用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "全国通用的急救电话是一二零。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "普通话是全国通用的语言。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种尺寸的表格在各地都通用。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点头表示同意，在许多地方是通用的。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套标准已经在行业里通用了很多年。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上的通用符号，大家都看得懂。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通用语", "label": "复合"}, {"form": "通用性", "label": "复合"}], "register": "中性", "sense_fingerprint": "通用·在多个地区、国家或行业中普遍适用、共同使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c932acf-f05f-4d8d-ad7f-aaeceee4f32a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：指在国际上普遍使用，与“成为国际……的方法”相符。"}, {"text": "专用", "is_correct": false, "explanation": "语义：专用指只为特定对象使用，与“国际”及“慢慢成为……”相矛盾。"}, {"text": "手工", "is_correct": false, "explanation": "搭配：“国际”多修饰标准、语言等，不能说“国际手工的方法”。"}, {"text": "冷门", "is_correct": false, "explanation": "语义：冷门指不被多数人采用，与“慢慢成为……”相矛盾。"}], "explanations": {"通用": "通用：指在国际上普遍使用，与“成为国际……的方法”相符。", "专用": "语义：专用指只为特定对象使用，与“国际”及“慢慢成为……”相矛盾。", "手工": "搭配：“国际”多修饰标准、语言等，不能说“国际手工的方法”。", "冷门": "语义：冷门指不被多数人采用，与“慢慢成为……”相矛盾。"}, "sentence_index": 0, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把钥匙只能开我家的门，在别处也通用。", "explanation": "这里与“只能开我家的门”矛盾。只能在特定处使用的要说专用，不能说在别处也通用。"}, {"text": "这份合同只限本公司使用，对外也通用。", "explanation": "这里与“只限本公司使用”矛盾。只限本公司使用的要说限用，不能说对外也通用。"}, {"text": "这种鞋子只适合在室内穿，在室外也通用。", "explanation": "这里与“只适合在室内穿”矛盾。只限室内使用的要说限于室内，不能说在室外也通用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：指在各地都能使用，与“在各地都”相符。"}, {"text": "独有", "is_correct": false, "explanation": "语义：独有指只属于某一处，与“在各地都”相矛盾。"}, {"text": "花哨", "is_correct": false, "explanation": "搭配：花哨形容外观，不用来说明表格在各地的使用范围。"}, {"text": "卡顿", "is_correct": false, "explanation": "语义：卡顿形容运行不流畅，不能用来说明表格的使用范围，句意不通。"}], "explanations": {"通用": "通用：指在各地都能使用，与“在各地都”相符。", "独有": "语义：独有指只属于某一处，与“在各地都”相矛盾。", "花哨": "搭配：花哨形容外观，不用来说明表格在各地的使用范围。", "卡顿": "语义：卡顿形容运行不流畅，不能用来说明表格的使用范围，句意不通。"}, "sentence_index": 6, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种纸杯只能用一次，却很通用。", "explanation": "这里与“只能用一次”矛盾。通用指普遍适用，只能用一次的纸杯要说一次性。"}, {"text": "这个词只有少数专家认识，很通用。", "explanation": "这里应该用〈罕见〉。通用指普遍使用，只有少数人认识的要说罕见。"}, {"text": "这项技术很通用，只有他们公司能用。", "explanation": "这里应该用〈专用〉。通用指普遍使用，只有一家公司能用的要说专用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种卡在很多国家都被通用。", "corrected_sentence": "这种卡在很多国家都能通用。", "error_description": "“通用”是形容词，不能用“被”字句；正确：都能通用；错误：都被通用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种充电器在国外没通用。", "corrected_sentence": "这种充电器在国外不通用。", "error_description": "“通用”是形容词，表示一般的状态，否定时用“不”，不用“没”。正确：在国外不通用；错误：在国外没通用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
