INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10675, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中国传统记谱法中表示音高的字符，如“工”“尺”；也用来代称工尺谱。", "primary_collocate": null, "pronunciation": "gōng chě", "ipa": "kʊŋ˥ ʈʂʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "古人用工尺把乐曲的音高记下来。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些老曲子都是用工尺记下来的，今天的人还能照着唱。", "target_word": "工尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人常用工尺来记音乐。", "target_word": "工尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工尺是中国古代的一种记音符号。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，“工”和“尺”都是工尺里的字。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在博物馆看到了一本用工尺写的老书。", "target_word": "工尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱戏的老先生会读工尺。", "target_word": "工尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学会工尺以后，他能看懂古代的曲子。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和五线谱不同，工尺用汉字表示音高。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首老歌是用工尺写下来的。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "工尺谱", "label": "复合"}], "register": "书面", "sense_fingerprint": "中国传统记谱法里表示音高的字符，也指工尺谱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4722aed3-9c6c-4f5b-9332-20e838c26bdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工尺", "is_correct": true, "explanation": "正确：工尺是古代记录音高的字符，可以用来把乐曲的音高记下来。"}, {"text": "筷子", "is_correct": false, "explanation": "语义：筷子是吃饭的用具，不能用来记录音高。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是挡雨的用具，不能用来记录乐曲。"}, {"text": "枕头", "is_correct": false, "explanation": "语义：枕头是睡觉用的，不能用来记录音高。"}], "explanations": {"工尺": "正确：工尺是古代记录音高的字符，可以用来把乐曲的音高记下来。", "筷子": "语义：筷子是吃饭的用具，不能用来记录音高。", "雨伞": "语义：雨伞是挡雨的用具，不能用来记录乐曲。", "枕头": "语义：枕头是睡觉用的，不能用来记录音高。"}, "sentence_index": 0, "correct_answer": "工尺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用工尺量了一下桌子的长度。", "explanation": "语义：这里把“工尺”当成了〈尺〉（量长度的器具），但工尺指古代记音的字符，不能用来量东西。"}, {"text": "我买了一只工尺。", "explanation": "量词：“只”用于动物或成对的东西，工尺是记音的字符，不能用“只”来数。"}, {"text": "这个工尺很能干，每天都按时上班。", "explanation": "语义：这里把“工尺”当成了〈人〉（如同事）来写，但工尺是记音的符号，不指人，不能说它能干或上班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工尺", "is_correct": true, "explanation": "正确：“读”的对象是工尺这类记音符号，与“唱戏的老先生”相合。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“读”的对象是文字或乐谱，不能说“读乐器”。"}, {"text": "扑克", "is_correct": false, "explanation": "搭配：扑克牌不是可以读的文字或乐谱，“读扑克”不成立。"}, {"text": "胡琴", "is_correct": false, "explanation": "搭配：胡琴是乐器，不能用“读”来搭配。"}], "explanations": {"工尺": "正确：“读”的对象是工尺这类记音符号，与“唱戏的老先生”相合。", "乐器": "搭配：“读”的对象是文字或乐谱，不能说“读乐器”。", "扑克": "搭配：扑克牌不是可以读的文字或乐谱，“读扑克”不成立。", "胡琴": "搭配：胡琴是乐器，不能用“读”来搭配。"}, "sentence_index": 6, "correct_answer": "工尺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的工尺是两米。", "explanation": "语义：这里把“工尺”当成了〈尺寸〉（机器的规格），但工尺指古代记音的字符，不能表示长度。"}, {"text": "工尺旁边正在盖一栋新楼。", "explanation": "语义：工尺不指工地或施工场所。"}, {"text": "他喜欢吃工尺。", "explanation": "语义：这里把“工尺”当成了〈食物〉来吃，但工尺是古代记音的字符，不是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被工尺记下了这首曲子。", "corrected_sentence": "他用工尺记下了这首曲子。", "error_description": "错误：“被工尺”；正确：“用工尺”。工尺是记曲子的工具，要用介词“用”引出，不能用表示被动的“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她小时候学了过工尺。", "corrected_sentence": "她小时候学过工尺。", "error_description": "错误：“学了过”；正确：“学过”。表示以前的经历只用体标“过”，不能和“了”连在一起用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
