INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10677, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "减字谱是中国古琴的一种记谱法，用汉字的偏旁、部首和简化字组合成符号，指示弹奏的弦位、指法和音高，不直接记录旋律。", "primary_collocate": null, "pronunciation": "jiǎn zì pǔ", "ipa": "tɕjɛn˨˩˦ tsz̩˥˩ pʰu˨˩˦", "syllable_count": 3, "sentences": [{"text": "在中国，古代也有自己的记谱方式，比如工尺谱和减字谱。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "古琴谱不用五线谱，而是用减字谱。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我看减字谱上的符号。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减字谱把汉字的一部分拼成一个符号。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本古琴书里全是减字谱，我看不懂。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减字谱只告诉你手指按哪根弦，不直接写旋律。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学古琴的人要先认识减字谱。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一页很老的减字谱。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用减字谱抄下了这首古曲。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和五线谱比，减字谱更像汉字。", "target_word": "减字谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套减字谱", "label": "量词"}, {"form": "減字譜", "label": "繁体"}], "register": "书面", "sense_fingerprint": "古琴专用记谱法，用汉字部件组合成符号，指示弦位和指法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8f5f600-ca28-4321-b5a3-d94418e5ffb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10677, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减字谱", "is_correct": true, "explanation": "减字谱是古琴记谱法，与工尺谱并列，同为古代记谱方式，句意通顺。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是记谱方式，放在“工尺谱和”后面句意不通。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指不是记谱方式，与“工尺谱”并列说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“记谱方式”的并列项须是记谱法，“歌曲”是被记录的内容，不能与记谱法并列。"}], "explanations": {"减字谱": "减字谱是古琴记谱法，与工尺谱并列，同为古代记谱方式，句意通顺。", "钢琴": "语义：钢琴是乐器，不是记谱方式，放在“工尺谱和”后面句意不通。", "手指": "语义：手指不是记谱方式，与“工尺谱”并列说不通。", "歌曲": "搭配：“记谱方式”的并列项须是记谱法，“歌曲”是被记录的内容，不能与记谱法并列。"}, "sentence_index": 0, "correct_answer": "减字谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "减字谱用五条线和音符记录音高，学生照着唱就行。", "explanation": "这里应该用〈五线谱〉。五线谱用五条线和音符记录音高；减字谱不用线，而是用汉字部件组合成的符号指示弦位和指法。"}, {"text": "减字谱用工、尺、上等字记录音高，便于歌唱。", "explanation": "这里应该用〈工尺谱〉。工尺谱用工、尺、上等字记音高；减字谱用汉字部件组成的符号指示弦位、指法和音高，不用这些字。"}, {"text": "减字谱是一种乐器，弹的时候要用手指拨弦。", "explanation": "这里应该用〈古琴〉。古琴靠手指拨弦发声；减字谱是古琴的记谱符号，本身不发声，也不能拨弦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减字谱", "is_correct": true, "explanation": "减字谱是古琴自己的记谱方式，学古琴的人先认识它，句意通顺。"}, {"text": "吉他", "is_correct": false, "explanation": "搭配：“学古琴”后要认识的是古琴自己的记谱，“吉他”属于另一种乐器，与“古琴”不配搭。"}, {"text": "烤鸭", "is_correct": false, "explanation": "语义：烤鸭是食物，与学习古琴无关，句意不通。"}, {"text": "高铁", "is_correct": false, "explanation": "语义：高铁是交通工具，学古琴的人不需要先认识它，句意不通。"}], "explanations": {"减字谱": "减字谱是古琴自己的记谱方式，学古琴的人先认识它，句意通顺。", "吉他": "搭配：“学古琴”后要认识的是古琴自己的记谱，“吉他”属于另一种乐器，与“古琴”不配搭。", "烤鸭": "语义：烤鸭是食物，与学习古琴无关，句意不通。", "高铁": "语义：高铁是交通工具，学古琴的人不需要先认识它，句意不通。"}, "sentence_index": 6, "correct_answer": "减字谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "减字谱用数字1到7记录音高，初学者很容易看懂。", "explanation": "这里应该用〈简谱〉。简谱用数字1到7记音高；减字谱用汉字部件组成的符号指示弦位、指法和音高，不用数字。"}, {"text": "减字谱上标着每个音的音高和节奏，照着就能弹。", "explanation": "这里应该用〈乐谱〉。乐谱泛指标明音高和节奏的谱子；减字谱用符号指示弦位、指法和音高，不直接记录旋律。"}, {"text": "我把这张减字谱放进唱机，听它的旋律。", "explanation": "这里应该用〈唱片〉。唱片可以放进唱机播放；减字谱是记谱符号，本身不发声，不能播放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只减字谱。", "corrected_sentence": "我买了一套减字谱。", "error_description": "量词错误：谱子可用“本”或“套”来数（一本/一套减字谱），“只”不用于数谱子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套减字谱我的抽屉里。", "corrected_sentence": "这套减字谱在我的抽屉里。", "error_description": "缺少动词：错误形式为“这套减字谱我的抽屉里”，正确形式为“这套减字谱在我的抽屉里”。表示东西所在的地方，要用动词“在”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
