INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10681, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指可以演奏出音乐的器具，如钢琴、小提琴、笛子等。", "primary_collocate": null, "pronunciation": "yuè qì", "ipa": "ɥɛ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "有些乐谱用汉字或符号记录指法和弦位，适合传统乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴和小提琴都是常见的乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学一种乐器，比如笛子。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件乐器能发出很好听的声音。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古琴是中国很老的乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会弹三种乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里卖各种乐器，有鼓也有吉他。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子对乐器很有兴趣。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把乐器放进盒子里。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐课上，大家都带着乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件乐器", "label": "量词"}, {"form": "一种乐器", "label": "量词"}, {"form": "樂器", "label": "繁体"}, {"form": "民族乐器", "label": "复合"}], "register": "中性", "sense_fingerprint": "能演奏音乐的器具，如钢琴、小提琴、笛子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8f5f600-ca28-4321-b5a3-d94418e5ffb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10681, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乐器", "is_correct": true, "explanation": "乐器：可以演奏出音乐的器具，如钢琴、小提琴、笛子等。"}, {"text": "玉器", "is_correct": false, "explanation": "yù（第四声）与 yuè（第四声）韵母不同，意思是玉石制成的器物。"}, {"text": "跃起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是猛然跳起。"}, {"text": "血气", "is_correct": false, "explanation": "xuè 与 yuè 声母不同，意思是精力、朝气，是较书面的词。"}], "explanations": {"乐器": "乐器：可以演奏出音乐的器具，如钢琴、小提琴、笛子等。", "玉器": "yù（第四声）与 yuè（第四声）韵母不同，意思是玉石制成的器物。", "跃起": "qǐ（第三声）与 qì（第四声）声调不同，意思是猛然跳起。", "血气": "xuè 与 yuè 声母不同，意思是精力、朝气，是较书面的词。"}, "sentence_index": null, "correct_answer": "乐器"}, "level_3": {"options": [{"text": "乐器", "is_correct": true, "explanation": "乐器：能演奏音乐的器具，与“传统”和“指法、弦位”的语境相合。"}, {"text": "厨具", "is_correct": false, "explanation": "语义：指法和弦位是演奏乐器才有的概念，厨具不需要记录这些，句子不成立。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“指法和弦位”指演奏技法，玩具与之无关，句子读起来不通。"}, {"text": "器皿", "is_correct": false, "explanation": "语义：器皿是盛放物品的容器，不能用来记录指法和弦位，句意不通。"}], "explanations": {"乐器": "乐器：能演奏音乐的器具，与“传统”和“指法、弦位”的语境相合。", "厨具": "语义：指法和弦位是演奏乐器才有的概念，厨具不需要记录这些，句子不成立。", "玩具": "语义：“指法和弦位”指演奏技法，玩具与之无关，句子读起来不通。", "器皿": "语义：器皿是盛放物品的容器，不能用来记录指法和弦位，句意不通。"}, "sentence_index": 0, "correct_answer": "乐器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一本乐器。", "explanation": "这里应该用〈件〉或〈种〉。乐器用“件”或“种”计量，“本”用于书籍等。"}, {"text": "这件乐器很好吃。", "explanation": "这里应该用〈点心〉。乐器是演奏音乐的器具，不能吃，“好吃”只能形容食物。"}, {"text": "这首乐器能发出很好听的声音。", "explanation": "这里应该用〈件〉或〈种〉。“首”用于诗歌、歌曲，乐器不用“首”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10681, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乐器", "is_correct": true, "explanation": "乐器：可以演奏出音乐的器具，如钢琴、小提琴、笛子等。"}, {"text": "月季", "is_correct": false, "explanation": "jì（第四声）与 qì（第四声）声母不同，意思是一种花。"}, {"text": "阅历", "is_correct": false, "explanation": "lì 与 qì 声母不同，意思是人生经历、见识。"}, {"text": "夜气", "is_correct": false, "explanation": "yè（第四声）与 yuè 韵母不同（少一个 ü 介音），意思是夜间的清新之气，多用于文言。"}], "explanations": {"乐器": "乐器：可以演奏出音乐的器具，如钢琴、小提琴、笛子等。", "月季": "jì（第四声）与 qì（第四声）声母不同，意思是一种花。", "阅历": "lì 与 qì 声母不同，意思是人生经历、见识。", "夜气": "yè（第四声）与 yuè 韵母不同（少一个 ü 介音），意思是夜间的清新之气，多用于文言。"}, "sentence_index": null, "correct_answer": "乐器"}, "level_3": {"options": [{"text": "乐器", "is_correct": true, "explanation": "乐器：商店里可以售卖的一类物品，与“鼓”“吉他”相合。"}, {"text": "文具", "is_correct": false, "explanation": "语义：文具是书写用品，与“鼓”“吉他”不属于同一类，句子不通。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品是可以吃的东西，“鼓”和“吉他”不是食品，句子不通。"}, {"text": "乐手", "is_correct": false, "explanation": "搭配：“卖”的对象是物品，不能说卖人，“乐手”是人，搭配不当。"}], "explanations": {"乐器": "乐器：商店里可以售卖的一类物品，与“鼓”“吉他”相合。", "文具": "语义：文具是书写用品，与“鼓”“吉他”不属于同一类，句子不通。", "食品": "语义：食品是可以吃的东西，“鼓”和“吉他”不是食品，句子不通。", "乐手": "搭配：“卖”的对象是物品，不能说卖人，“乐手”是人，搭配不当。"}, "sentence_index": 6, "correct_answer": "乐器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件乐器很难读。", "explanation": "这里应该用〈乐谱〉。“读”的对象是乐谱，乐器不能说读。"}, {"text": "我买了一块乐器，回家练习。", "explanation": "这里应该用〈件〉或〈种〉。“块”用于成块的东西，乐器不用“块”。"}, {"text": "这座乐器很大，房间放不下。", "explanation": "这里应该用〈件〉或〈种〉。“座”用于山、楼等大型固定物，乐器不用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天练习一只乐器。", "corrected_sentence": "他每天练习一种乐器。", "error_description": "量词错误：“乐器”应使用“种”或“件”，不能用“只”。“只”一般用于动物或成对物品中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的乐器们都放在房间里。", "corrected_sentence": "我的乐器都放在房间里。", "error_description": "多加了“们”：“乐器”是无生名词，后面不能加“们”表示复数，应说“乐器都……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
