INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体通过光线在镜子、屏幕或纸上呈现出的视觉形状。", "primary_collocate": null, "pronunciation": "tú xiàng", "ipa": "tʰu˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "水面上的图像晃来晃去，看不清楚。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜子里的图像是反的，左右和真的相反。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的图像突然变模糊了。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线太暗，纸上的图像看不清楚。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投影仪把图像投到大屏幕上。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视图像很清楚，声音却很小。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线穿过小孔，在纸上出现一个倒着的图像。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的图像一动不动，电脑好像坏了。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面镜子很旧，照出来的图像有点黄。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把投影的图像调大一点，后面看不见。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张图像", "label": "量词"}, {"form": "一幅图像", "label": "量词"}, {"form": "圖像", "label": "繁体"}, {"form": "图像处理", "label": "复合"}], "register": "中性", "sense_fingerprint": "光线在镜子、屏幕、纸上形成的视觉形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf1fc5f1-3de3-49b7-bd2c-bca5dafc47e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图像", "is_correct": true, "explanation": "正确：光线在水面上反射形成看得见的形状，就是图像，可以“看不清楚”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听觉的，不能用“看不清楚”来说。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味是闻到的，看不见，不能“看不清楚”。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量没有形状，不会在水面上晃来晃去，也不能用眼睛看。"}], "explanations": {"图像": "正确：光线在水面上反射形成看得见的形状，就是图像，可以“看不清楚”。", "声音": "语义：声音是听觉的，不能用“看不清楚”来说。", "香味": "语义：香味是闻到的，看不见，不能“看不清楚”。", "重量": "语义：重量没有形状，不会在水面上晃来晃去，也不能用眼睛看。"}, "sentence_index": 0, "correct_answer": "图像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同的图像写得很清楚。", "explanation": "这里应该用〈条款〉。合同的内容要说条款，图像指光线形成的影像，不能用来形容文字内容。"}, {"text": "她在我心里是一个勇敢的图像。", "explanation": "这里应该用〈形象〉。别人对人的印象和品格要说形象，图像不用来形容人。"}, {"text": "墙上挂着一条图像。", "explanation": "这里量词用错。图像要用〈张〉或〈幅〉计量，〈条〉用于细长的东西，不能用来数图像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图像", "is_correct": true, "explanation": "正确：小孔成像在纸上形成的是倒立的影像，就是图像。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：“倒着”说的是形体的朝向，颜色没有上下之分，不能倒着出现。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道看不见，不能通过小孔在纸上出现。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“倒着”修饰有形体的东西，不说“倒着的温度”。"}], "explanations": {"图像": "正确：小孔成像在纸上形成的是倒立的影像，就是图像。", "颜色": "体貌：“倒着”说的是形体的朝向，颜色没有上下之分，不能倒着出现。", "味道": "语义：味道看不见，不能通过小孔在纸上出现。", "温度": "搭配：“倒着”修饰有形体的东西，不说“倒着的温度”。"}, "sentence_index": 6, "correct_answer": "图像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首曲子的图像很好听。", "explanation": "这里应该用〈旋律〉。曲子好听说的是旋律，图像是光线形成的影像，不能用来形容声音。"}, {"text": "这道菜的图像很香，大家都想吃。", "explanation": "这里应该用〈味道〉。香形容气味，图像是视觉影像，不能用来形容闻到的味道。"}, {"text": "这个图像写得很长，我看不懂。", "explanation": "这里应该用〈文章〉。文章是用文字写出来的，图像是光线形成的影像，不能用“写”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕上有一本图像，非常清楚。", "corrected_sentence": "屏幕上有一张图像，非常清楚。", "error_description": "量词错误：“图像”应该用“张”或“幅”计量，“本”用于书册，不能数图像。应说“一张图像”，不说“一本图像”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把图像调很清楚。", "corrected_sentence": "我把图像调得很清楚。", "error_description": "补语错误：动词“调”后带补语“很清楚”时要用“得”连接，应说“调得很清楚”，漏掉“得”就不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
