INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10691, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10691, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对资料、文字或内容进行整理、修改或加工，使其符合要求或更完善。", "primary_collocate": null, "pronunciation": "biān jí", "ipa": "pjɛn˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "也有人用数字软件直接编辑声音。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他正在编辑一篇新文章。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这段文字再编辑一下。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以编辑视频。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用手机编辑了一份旅行资料。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我编辑完了，你再检查一遍吧。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们编辑班级的新闻稿。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告还要编辑，错字太多了。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先编辑内容，最后才能发给大家。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天晚上编辑视频，常常很晚才睡。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编辑了", "label": "体标"}, {"form": "编辑过", "label": "体标"}, {"form": "編輯", "label": "繁体"}, {"form": "编辑器", "label": "复合"}, {"form": "编辑部", "label": "复合"}], "register": "中性", "sense_fingerprint": "整理、修改内容使其符合要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf1fc5f1-3de3-49b7-bd2c-bca5dafc47e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10691, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "编辑", "is_correct": true, "explanation": "正确：数字软件可以直接对声音进行修改加工，“编辑声音”说得通。"}, {"text": "种植", "is_correct": false, "explanation": "语义：声音不能种植，“直接种植声音”说不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食材，不说烹饪声音。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”的对象是衣物、布料，不能缝补声音。"}], "explanations": {"编辑": "正确：数字软件可以直接对声音进行修改加工，“编辑声音”说得通。", "种植": "语义：声音不能种植，“直接种植声音”说不通。", "烹饪": "搭配：“烹饪”的对象是食材，不说烹饪声音。", "缝补": "搭配：“缝补”的对象是衣物、布料，不能缝补声音。"}, "sentence_index": 0, "correct_answer": "编辑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用相机编辑了一段视频。", "explanation": "这里应该用〈拍摄〉。编辑是对已有内容加工，用相机录下视频要说拍摄。"}, {"text": "他把这篇中文文章编辑成了英文。", "explanation": "这里应该用〈翻译〉。把文章换成另一种语言要说翻译，编辑只是修改加工原文，不改变语言。"}, {"text": "我从网上编辑了一个视频。", "explanation": "这里应该用〈下载〉。从网上获得现成的视频要说下载，编辑指修改加工已有内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10691, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编辑", "is_correct": true, "explanation": "正确：老师让学生修改加工班级新闻稿，符合“编辑”的意思。"}, {"text": "烧烤", "is_correct": false, "explanation": "搭配：“烧烤”的对象是食物，不说烧烤新闻稿。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：喂养的对象是动物或植物，新闻稿不能被喂养。"}, {"text": "冰冻", "is_correct": false, "explanation": "语义：新闻稿是文字材料，不能被冰冻，句子不成立。"}], "explanations": {"编辑": "正确：老师让学生修改加工班级新闻稿，符合“编辑”的意思。", "烧烤": "搭配：“烧烤”的对象是食物，不说烧烤新闻稿。", "喂养": "语义：喂养的对象是动物或植物，新闻稿不能被喂养。", "冰冻": "语义：新闻稿是文字材料，不能被冰冻，句子不成立。"}, "sentence_index": 6, "correct_answer": "编辑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "园丁每天编辑树枝，很辛苦。", "explanation": "这里应该用〈修剪〉。剪掉多余枝叶要说修剪，编辑只用于文字、图片、音视频等内容。"}, {"text": "妈妈每天编辑衣服，很辛苦。", "explanation": "这里应该用〈熨烫〉。把衣服烫平要说熨烫，编辑不能用于衣物。"}, {"text": "爸爸每天编辑自行车，很辛苦。", "explanation": "这里应该用〈修理〉。坏了的自行车要修理，编辑的对象是文字和媒体内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10691, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把这段视频编辑很漂亮。", "corrected_sentence": "她把这段视频编辑得很漂亮。", "error_description": "补语错误：动词“编辑”后带补语“很漂亮”时要用“得”连接，应说“编辑得很漂亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10691, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他编辑了过这篇文章。", "corrected_sentence": "他编辑过这篇文章。", "error_description": "体标错误：“编辑”后用“过”表示经历，不能再加“了”，应说“编辑过这篇文章”，不说“编辑了过这篇文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
