INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10693, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "音乐创作是指通过构思、作曲、编曲等方式，创作出新的音乐作品的过程。", "primary_collocate": null, "pronunciation": "yīn yuè chuàng zuò", "ipa": "in˥ ɥe˥˩ ʈʂʰuɑŋ˥˩ tsuo˥˩", "syllable_count": 4, "sentences": [{"text": "这些新方法让音乐创作更自由。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "值得注意的是，人工智能介入音乐创作后，机器生成的乐谱常融合符号逻辑与概率模型，引发关于“可读性”与“可演性”的新讨论。", "target_word": "音乐创作", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他从小就喜欢音乐创作。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐创作需要很多时间和耐心。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学学的是音乐创作。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教我们音乐创作的方法。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑让音乐创作变得更容易。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐创作中，好的想法最重要。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天花三个小时进行音乐创作。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对音乐创作来说，生活经验很重要。", "target_word": "音乐创作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "音樂創作", "label": "繁体"}, {"form": "音乐创作人", "label": "复合"}], "register": "中性", "sense_fingerprint": "构思、作曲、编曲而产生新音乐作品的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f4a8b1-54f9-4af0-bf82-5bf023832828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐创作", "is_correct": true, "explanation": "“音乐创作”指创作音乐的过程，可以作为“让……更自由”的对象，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能被新方法“变得更自由”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的物质，“更自由”不能用来描述它。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“更自由”说的是人的活动，不修饰房间这类空间。"}], "explanations": {"音乐创作": "“音乐创作”指创作音乐的过程，可以作为“让……更自由”的对象，与句意相符。", "天气": "语义：天气是自然现象，不能被新方法“变得更自由”。", "空气": "语义：空气是无形的物质，“更自由”不能用来描述它。", "房间": "搭配：“更自由”说的是人的活动，不修饰房间这类空间。"}, "sentence_index": 0, "correct_answer": "音乐创作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位医生每天在诊室里音乐创作十个病人。", "explanation": "这里应该用〈看诊〉。音乐创作指写作乐曲，给病人诊治要用“看诊”，不能用来指医疗工作。"}, {"text": "他是一位优秀的音乐创作。", "explanation": "这里应该用〈音乐创作人〉。音乐创作指活动本身，指从事这项工作的人要用“音乐创作人”。"}, {"text": "她每天在画布上进行音乐创作。", "explanation": "这里应该用〈绘画创作〉。在画布上完成的是绘画，音乐创作只限于音乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐创作", "is_correct": true, "explanation": "“音乐创作”作为“变得更容易”的主语，指创作音乐这件事，与“电脑”的帮助语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以被电脑“变得更容易”的活动，句意不通。"}, {"text": "河水", "is_correct": false, "explanation": "搭配：“变得更容易”不用来描述河水的状态。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是需要做的事，不能“变得更容易”。"}], "explanations": {"音乐创作": "“音乐创作”作为“变得更容易”的主语，指创作音乐这件事，与“电脑”的帮助语境相符。", "天气": "语义：天气不是可以被电脑“变得更容易”的活动，句意不通。", "河水": "搭配：“变得更容易”不用来描述河水的状态。", "窗户": "语义：窗户不是需要做的事，不能“变得更容易”。"}, "sentence_index": 6, "correct_answer": "音乐创作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每周在地里音乐创作三亩小麦。", "explanation": "这里应该用〈收割〉。音乐创作指写作乐曲，在地里收割小麦要用“收割”，不能用于农事。"}, {"text": "这位老师每周在大学里音乐创作三节课。", "explanation": "这里应该用〈讲课〉。音乐创作指写作音乐，不是授课，给学生讲课要用“讲课”。"}, {"text": "他在厨房里音乐创作晚餐，很快就做好了。", "explanation": "这里应该用〈烹饪〉。音乐创作的对象是音乐，不能用于做饭菜，做饭要用“烹饪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向音乐创作中获得了很多乐趣。", "corrected_sentence": "他从音乐创作中获得了很多乐趣。", "error_description": "介词错误：“获得……”的来源要用“从”，不能用“向”，“向”表示朝向或对象。写作：他从音乐创作中获得了很多乐趣。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在音乐创作很有兴趣。", "corrected_sentence": "她对音乐创作很有兴趣。", "error_description": "介词错误：“对……有兴趣”要用介词“对”，不能用“在”，说“在音乐创作有兴趣”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
