INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10701, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "历史发展的过程和趋势。", "primary_collocate": null, "pronunciation": "lì shǐ jìn chéng", "ipa": "li˥˩ ʂɨ˨˩˦ tɕin˥˩ ʈʂʰəŋ˧˥", "syllable_count": 4, "sentences": [{"text": "记谱法体系的演变深刻反映了人类对声音秩序之理解的历史进程。", "target_word": "历史进程", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "科学让历史进程走得更快。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场战争改变了历史进程。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读这本书，你能了解中国的历史进程。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个国家都有自己的历史进程。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的发明推动了历史进程。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了世界的历史进程。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河流的变化也影响着历史进程。", "target_word": "历史进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能停下历史进程。", "target_word": "历史进程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座古城见证了一段历史进程。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷史進程", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "历史发展的过程与趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db84973e-d904-419a-b58d-917694db0a8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10701, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“理解”没有重量，“体重”与“理解”无关。"}, {"text": "历史进程", "is_correct": true, "explanation": "正确：“历史进程”指历史发展的过程，与“反映……的历史进程”相符。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：“外貌”指人的外表长相，“对……理解的外貌”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“理解”没有味道，“味道”与“理解”无关。"}], "explanations": {"体重": "语义：“理解”没有重量，“体重”与“理解”无关。", "历史进程": "正确：“历史进程”指历史发展的过程，与“反映……的历史进程”相符。", "外貌": "语义：“外貌”指人的外表长相，“对……理解的外貌”说不通。", "味道": "语义：“理解”没有味道，“味道”与“理解”无关。"}, "sentence_index": 0, "correct_answer": "历史进程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个实验的历史进程很顺利。", "explanation": "这里应该用〈过程〉。历史进程指历史发展的趋势，不指一次实验的步骤，说实验步骤要用「过程」。"}, {"text": "这次出差的历史进程很长。", "explanation": "这里应该用〈路程〉。历史进程指历史发展的过程和趋势，不指一段路的距离，说路程长要用「路程」。"}, {"text": "这项历史进程已经完工了。", "explanation": "这里应该用〈工程〉。历史进程指历史发展的过程和趋势，不指具体的建设项目，说项目完工要用「工程」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血型", "is_correct": false, "explanation": "语义：“世界”没有血型，“血型”是人的特征。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体貌，不能用于“世界”。"}, {"text": "历史进程", "is_correct": true, "explanation": "正确：“历史进程”指历史发展的过程，与“讲了世界的”相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是人的疾病，不能用于“世界”。"}], "explanations": {"血型": "语义：“世界”没有血型，“血型”是人的特征。", "身高": "体貌：“身高”是人的体貌，不能用于“世界”。", "历史进程": "正确：“历史进程”指历史发展的过程，与“讲了世界的”相符。", "感冒": "语义：“感冒”是人的疾病，不能用于“世界”。"}, "sentence_index": 6, "correct_answer": "历史进程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的创业历史进程很艰辛。", "explanation": "这里应该用〈历程〉。历史进程指历史发展的趋势，不指个人的经历，说个人的经历要用「历程」。"}, {"text": "这首歌的历史进程很好听。", "explanation": "这里应该用〈旋律〉。历史进程指历史发展的过程和趋势，不指乐曲的音调，说旋律好听要用「旋律」。"}, {"text": "我们沿着历史进程一直走到山顶。", "explanation": "这里“沿着……走到山顶”说的是实际路线，而历史进程只指历史发展的过程和趋势，不能当作路径来走，所以句子不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块历史进程很有意义。", "corrected_sentence": "这个历史进程很有意义。", "error_description": "错误形式为“这块历史进程”，正确形式为“这个历史进程”。“历史进程”是抽象名词，量词应用「个」；「块」用于成块的物体，不用于此。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座历史进程持续了很久。", "corrected_sentence": "这个历史进程持续了很久。", "error_description": "错误形式为“这座历史进程”，正确形式为“这个历史进程”。“历史进程”是抽象名词，量词应用「个」；「座」用于山、楼等大型固定物，不用于此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
