INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遥远的古代；指距离现在非常久远的时代。", "primary_collocate": null, "pronunciation": "yuǎn gǔ", "ipa": "ɥæn˨˩˦ ku˨˩˦", "syllable_count": 2, "sentences": [{"text": "自远古以来，干旱地区的农业社群便发展出一系列复杂的资源管理体系，这些体系不仅是对自然制约的回应，更深刻体现了本土知识与生态伦理的融合。", "target_word": "远古", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "自远古时期起，不同文明便尝试以视觉符号捕捉稍纵即逝的音响，然而早期的记谱方式多具提示性而非精确性。", "target_word": "远古", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "远古时代，人们住在山洞里。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些石器来自远古时期。", "target_word": "远古", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给我们讲了远古人类的生活。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里有很多远古的动物骨头。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远古的人用石头打猎。", "target_word": "远古", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河边发现了远古留下的脚印。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远古的森林比现在大得多。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，远古时有很多大动物。", "target_word": "远古", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠古", "label": "繁体"}, {"form": "远古时代", "label": "复合"}, {"form": "远古时期", "label": "复合"}], "register": "书面", "sense_fingerprint": "距今非常久远的古代时期，多指史前或文明早期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77085c74-6cb5-4c24-9776-6ad1cbffcff0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远古", "is_correct": true, "explanation": "与“自……以来”搭配，指距今极其久远的时代，与一系列复杂资源管理体系所需的漫长发展时间相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”只指一天，与“自……以来”所需的漫长时间跨度矛盾。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指一年之内，与“发展出一系列复杂的资源管理体系”所需的漫长时间矛盾。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，不能与“自……以来”连用，也与已经发展出的体系矛盾。"}], "explanations": {"远古": "与“自……以来”搭配，指距今极其久远的时代，与一系列复杂资源管理体系所需的漫长发展时间相符。", "昨天": "语义：“昨天”只指一天，与“自……以来”所需的漫长时间跨度矛盾。", "去年": "语义：“去年”指一年之内，与“发展出一系列复杂的资源管理体系”所需的漫长时间矛盾。", "明天": "语义：“明天”指将来，不能与“自……以来”连用，也与已经发展出的体系矛盾。"}, "sentence_index": 0, "correct_answer": "远古"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明朝是远古的一个朝代。", "explanation": "这里应该用〈古代〉。远古指距今极其久远的史前或文明早期，明朝距今数百年，应说〈古代〉。"}, {"text": "我的远古很快乐。", "explanation": "这里应该用〈童年〉。远古指遥远的古代，不能用来指个人的一段时期。"}, {"text": "远古，中国开始了工业化。", "explanation": "这里应该用〈近代〉。工业化是近代的事，远古指极其久远的时代，时间不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远古", "is_correct": true, "explanation": "作定语修饰“人”，指很久以前的时代，与“用石头打猎”的情境相符。"}, {"text": "太空", "is_correct": false, "explanation": "语义：“太空”指宇宙空间，与“用石头打猎”的古代情境矛盾。"}, {"text": "电子", "is_correct": false, "explanation": "搭配：“电子”不指时代，不能修饰“人”来表示所处的时期。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”指将来的时代，与“用石头打猎”的古代情境矛盾。"}], "explanations": {"远古": "作定语修饰“人”，指很久以前的时代，与“用石头打猎”的情境相符。", "太空": "语义：“太空”指宇宙空间，与“用石头打猎”的古代情境矛盾。", "电子": "搭配：“电子”不指时代，不能修饰“人”来表示所处的时期。", "未来": "语义：“未来”指将来的时代，与“用石头打猎”的古代情境矛盾。"}, "sentence_index": 6, "correct_answer": "远古"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我远古在超市买了一本书。", "explanation": "这里应该用〈昨天〉。远古指极其久远的古代，表示昨天这样的近期应说〈昨天〉。"}, {"text": "我们班远古搬了新教室。", "explanation": "这里应该用〈上个月〉。远古指很久以前，不能用来指上个月这样的近期时间。"}, {"text": "远古我们班有三十个学生。", "explanation": "这里应该用〈今年〉。远古指遥远的古代，描述今年班级人数应说〈今年〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远古时期的石器很远古。", "corrected_sentence": "远古时期的石器很精美。", "error_description": "错误：“远古”是名词，不能作“很”的谓语；应把谓语改为形容词“精美”，写作“远古时期的石器很精美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很远古时期的生活很简单。", "corrected_sentence": "远古时期的生活很简单。", "error_description": "错误：“远古”是名词，前面不能加“很”修饰；应去掉“很”，写作“远古时期的生活很简单”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
