INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某一段时间，常指有特定特征或事件的一段时间。", "primary_collocate": null, "pronunciation": "shí qī", "ipa": "ʂɨ³⁵ tɕʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "战争时期，很多人过着苦日子。", "target_word": "时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青春期是人成长的重要时期。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个时期，我们家很穷。", "target_word": "时期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "唐朝是中国历史上很繁荣的时期。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生时期，我最喜欢上历史课。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在困难时期帮助过我。", "target_word": "时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个时期的衣服和现在很不一样。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济快速发展的时期已经过去了。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈常说起她少年时期的故事。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在特殊时期，大家都要戴口罩。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "有特定特征或事件的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10703, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时期", "is_correct": true, "explanation": "正确答案，指一段有特定特征的时间，与听到的音相符。"}, {"text": "石器", "is_correct": false, "explanation": "声调不同：qì（第四声）与 qī（第一声），意思是石制的工具。"}, {"text": "时机", "is_correct": false, "explanation": "第二音节声母不同：jī 与 qī，意思是合适的机会。"}, {"text": "时区", "is_correct": false, "explanation": "第二音节韵母不同：qū（ü）与 qī（i），意思是地球上按经度划分的时区。"}], "explanations": {"时期": "正确答案，指一段有特定特征的时间，与听到的音相符。", "石器": "声调不同：qì（第四声）与 qī（第一声），意思是石制的工具。", "时机": "第二音节声母不同：jī 与 qī，意思是合适的机会。", "时区": "第二音节韵母不同：qū（ü）与 qī（i），意思是地球上按经度划分的时区。"}, "sentence_index": null, "correct_answer": "时期"}, "level_3": {"options": [{"text": "时期", "is_correct": true, "explanation": "语义与搭配都正确：“战争时期”指战争发生的一段时间，与后文“苦日子”相符。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”指地方，不指一段时间，“战争地点”与句意不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“战争”不能修饰“年龄”，不成词组，句子不通。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“战争工作”不指一段时间，与“很多人过着苦日子”的时间语境不符。"}], "explanations": {"时期": "语义与搭配都正确：“战争时期”指战争发生的一段时间，与后文“苦日子”相符。", "地点": "语义：“地点”指地方，不指一段时间，“战争地点”与句意不符。", "年龄": "搭配：“战争”不能修饰“年龄”，不成词组，句子不通。", "工作": "语义：“战争工作”不指一段时间，与“很多人过着苦日子”的时间语境不符。"}, "sentence_index": 0, "correct_answer": "时期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "修这座桥只用了三个小时的时期。", "explanation": "这里应该用〈时间〉。时期指有特定特征的一段时间，表示事情耗费的时长要用“时间”。"}, {"text": "我们吃饭的时期很少说话。", "explanation": "这里应该用〈时候〉。时期指较长的一段时间，表示某个具体时点要用“时候”。"}, {"text": "出发的时期到了，大家快上车。", "explanation": "这里应该用〈时刻〉。时期指一段时间，“出发的时刻到了”指具体的一个时间点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10703, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时期", "is_correct": true, "explanation": "正确答案，指一段有特定特征的时间，与听到的音相符。"}, {"text": "失期", "is_correct": false, "explanation": "声调不同：shī（第一声）与 shí（第二声），意思是错过规定的期限。"}, {"text": "拾起", "is_correct": false, "explanation": "第二音节声调不同：qǐ（第三声）与 qī（第一声），意思是捡起来。"}, {"text": "食器", "is_correct": false, "explanation": "第二音节声调不同：qì（第四声）与 qī（第一声），意思是吃饭用的器具。"}], "explanations": {"时期": "正确答案，指一段有特定特征的时间，与听到的音相符。", "失期": "声调不同：shī（第一声）与 shí（第二声），意思是错过规定的期限。", "拾起": "第二音节声调不同：qǐ（第三声）与 qī（第一声），意思是捡起来。", "食器": "第二音节声调不同：qì（第四声）与 qī（第一声），意思是吃饭用的器具。"}, "sentence_index": null, "correct_answer": "时期"}, "level_3": {"options": [{"text": "时期", "is_correct": true, "explanation": "语义与搭配都正确：“这个时期”指某一段时间，修饰“衣服”后与“现在”形成对比。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”不能修饰“衣服”，“这个性格的衣服”不成词组。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”指交流工具，与衣服的样式无关，句子不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能修饰“衣服”，“这个心情的衣服”不成立。"}], "explanations": {"时期": "语义与搭配都正确：“这个时期”指某一段时间，修饰“衣服”后与“现在”形成对比。", "性格": "搭配：“性格”不能修饰“衣服”，“这个性格的衣服”不成词组。", "语言": "语义：“语言”指交流工具，与衣服的样式无关，句子不通。", "心情": "搭配：“心情”不能修饰“衣服”，“这个心情的衣服”不成立。"}, "sentence_index": 6, "correct_answer": "时期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约好的时期是下周三。", "explanation": "这里应该用〈日期〉。“约好的日期”指具体的某一天，时期指一段较长的时间，不能用来指某一天。"}, {"text": "他的时期已经超过六十岁了。", "explanation": "这里应该用〈年龄〉。说人的岁数要用“年龄”，时期指一段时间，不能表示人的岁数。"}, {"text": "作业的时期是星期五。", "explanation": "这里应该用〈期限〉。“作业的期限”指截止的时限，时期指一段时间，不能表示截止的日子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那段时期了，我们家一直很穷。", "corrected_sentence": "那段时期，我们家一直很穷。", "error_description": "“了”的误用：“那段时期”作时间状语时后面不能直接加“了”，“时期了”不通，应去掉“了”，写作“那段时期，我们家一直很穷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条时期我们的工作很忙。", "corrected_sentence": "这段时期我们的工作很忙。", "error_description": "量词错误：“条”用于长条形的东西，时期应搭配“段”或“个”，应改为“这段时期”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
