INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10706, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "试验，试着做某事以了解效果或判断是否可行。", "primary_collocate": null, "pronunciation": "cháng shì", "ipa": "ʈʂʰaŋ³⁵ ʂɨ⁵¹", "syllable_count": 2, "sentences": [{"text": "自远古时期起，不同文明便尝试以视觉符号捕捉稍纵即逝的音响，然而早期的记谱方式多具提示性而非精确性。", "target_word": "尝试", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我想尝试一种新的学习方法。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次尝试做中国菜。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她尝试着和新同事聊天。", "target_word": "尝试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以尝试用另一种办法。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我尝试过很多次，都没成功。", "target_word": "尝试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕失败，愿意尝试新工作。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生建议你尝试每天早点睡觉。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们尝试自己系鞋带。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们尝试了三种方案，最后选了第二种。", "target_word": "尝试", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尝试了", "label": "体标"}, {"form": "尝试过", "label": "体标"}, {"form": "尝试着", "label": "体标"}], "register": "中性", "sense_fingerprint": "试着做以了解效果或可行性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10706, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尝试", "is_correct": true, "explanation": "正确答案，指试着做某事以了解效果，与听到的音相符。"}, {"text": "常识", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声），意思是常识。"}, {"text": "长史", "is_correct": false, "explanation": "声调不同：shǐ（第三声）与 shì（第四声），意思是古代官职名。"}, {"text": "长诗", "is_correct": false, "explanation": "声调不同：shī（第一声）与 shì（第四声），意思是长篇诗歌。"}], "explanations": {"尝试": "正确答案，指试着做某事以了解效果，与听到的音相符。", "常识": "声调不同：shí（第二声）与 shì（第四声），意思是常识。", "长史": "声调不同：shǐ（第三声）与 shì（第四声），意思是古代官职名。", "长诗": "声调不同：shī（第一声）与 shì（第四声），意思是长篇诗歌。"}, "sentence_index": null, "correct_answer": "尝试"}, "level_3": {"options": [{"text": "尝试", "is_correct": true, "explanation": "语义与搭配都正确：“便尝试以视觉符号捕捉音响”表示试着做，与后句“然而”的转折相符。"}, {"text": "享受", "is_correct": false, "explanation": "配价：“享受”的宾语应是生活或感受，不能接“以视觉符号”这种表示方式的成分。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指记不住，与“捕捉音响”的努力意义相反，句意不通。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”表示扔掉，与后文说明的努力意义相反，句意不通。"}], "explanations": {"尝试": "语义与搭配都正确：“便尝试以视觉符号捕捉音响”表示试着做，与后句“然而”的转折相符。", "享受": "配价：“享受”的宾语应是生活或感受，不能接“以视觉符号”这种表示方式的成分。", "忘记": "语义：“忘记”指记不住，与“捕捉音响”的努力意义相反，句意不通。", "丢弃": "语义：“丢弃”表示扔掉，与后文说明的努力意义相反，句意不通。"}, "sentence_index": 0, "correct_answer": "尝试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天尝试弹钢琴，已经弹了十年。", "explanation": "这里应该用〈练习〉。“尝试”指试着做以了解效果，不用于长期、经常性的练习。"}, {"text": "我尝试了一下天气，觉得很冷。", "explanation": "这里应该用〈感受〉。“尝试”的对象是做法或行为，天气是环境，感受天气要用“感受”。"}, {"text": "我在晚会上尝试了两个新朋友。", "explanation": "这里应该用〈认识〉。“尝试”的对象是做法或行为，不能以人作宾语；结交新朋友要用“认识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尝试", "is_correct": true, "explanation": "语义与搭配正确：“愿意尝试新工作”表示愿意试着做，与“不怕失败”相符。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”表示躲开，与“不怕失败”的态度相反，句意矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“愿意”和“不怕失败”的语气矛盾，句子不通。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”的宾语应是申请、计划等，不能直接接“新工作”。"}], "explanations": {"尝试": "语义与搭配正确：“愿意尝试新工作”表示愿意试着做，与“不怕失败”相符。", "逃避": "语义：“逃避”表示躲开，与“不怕失败”的态度相反，句意矛盾。", "放弃": "语义：“放弃”与“愿意”和“不怕失败”的语气矛盾，句子不通。", "批准": "搭配：“批准”的宾语应是申请、计划等，不能直接接“新工作”。"}, "sentence_index": 6, "correct_answer": "尝试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生尝试了病人的心脏，然后开了药。", "explanation": "这里应该用〈检查〉。“尝试”指试着做以了解效果，检查器官要说“检查”。"}, {"text": "他尝试了那个房间，现在房间很干净。", "explanation": "这里应该用〈打扫〉。让房间变干净要用“打扫”，“尝试”不能直接以房间为宾语。"}, {"text": "妈妈尝试了那个孩子，然后很放心。", "explanation": "这里应该用〈照顾〉。照顾孩子用“照顾”，“尝试”不能接人作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他尝试着三种方法，都不太好。", "corrected_sentence": "他尝试过三种方法，都不太好。", "error_description": "体标错误：表示经历过的动作应用“过”，写成“尝试过三种方法”；“尝试着”表示动作进行，不能直接接数量宾语“三种方法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你可以尝试一下子这个方法。", "corrected_sentence": "你可以尝试一下这个方法。", "error_description": "“一下子”与“一下”混用：“一下子”是副词，表示短时间或突然，不能作动量补语。动量补语应用“一下”，应写作“尝试一下这个方法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10708, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10708, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10708, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来看得见的标记来表示声音或音乐的方法", "primary_collocate": null, "pronunciation": "fú hào", "ipa": "fu˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "自远古时期起，不同文明便尝试以视觉符号捕捉稍纵即逝的音响，然而早期的记谱方式多具提示性而非精确性。", "target_word": "符号", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "符号", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "记谱法的发展，本质上是人类试图以有限符号系统捕捉无限音响可能性的永恒努力，其演变轨迹，正是音乐理论与实践互动共生的深层见证。", "target_word": "符号", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "乐谱上有很多小小的符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我看乐谱上的符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐谱里这个符号表示休息一下。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴谱上的符号，我还不太懂。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个符号告诉你要唱得小声一点。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学音乐的人要先认识谱上的符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在歌谱上画了一个符号，提醒自己换气。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "乐谱上用来记录音高、节奏、力度的标记", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3242d957-0d44-43bf-84d5-365f64ae4fa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号", "is_correct": true, "explanation": "符号：用视觉标记记录音响的方法，“以视觉符号”符合记谱的语境。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是视觉的，也不能用来捕捉音响。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用来记录稍纵即逝的音响，句子无法成立。"}, {"text": "口号", "is_correct": false, "explanation": "搭配：“视觉”不能修饰“口号”，口号也不是记录音响的方法。"}], "explanations": {"符号": "符号：用视觉标记记录音响的方法，“以视觉符号”符合记谱的语境。", "味道": "语义：味道不是视觉的，也不能用来捕捉音响。", "颜色": "语义：颜色不能用来记录稍纵即逝的音响，句子无法成立。", "口号": "搭配：“视觉”不能修饰“口号”，口号也不是记录音响的方法。"}, "sentence_index": 0, "correct_answer": "符号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在乐队里吹了一个符号。", "explanation": "这里应该用〈乐器〉。“吹”的对象是乐器，符号是记录音乐的标记，不能被吹。"}, {"text": "他的符号是三十五。", "explanation": "这里应该用〈号码〉。符号是记录音乐或表示意义的标记，不能用来表示编号。"}, {"text": "他在歌唱时露出了温柔的符号。", "explanation": "这里应该用〈表情〉。表情指脸上的神情，符号不能指面部的神情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号", "is_correct": true, "explanation": "符号：乐谱上表示音乐要素的标记，“钢琴谱上的符号”指的就是这个。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”与乐谱无关，“钢琴谱上的石头”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户与乐谱无关，不能出现在钢琴谱上。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“钢琴谱上的脚印”的说法不成立，脚印不属于乐谱。"}], "explanations": {"符号": "符号：乐谱上表示音乐要素的标记，“钢琴谱上的符号”指的就是这个。", "石头": "语义：“石头”与乐谱无关，“钢琴谱上的石头”说不通。", "窗户": "语义：窗户与乐谱无关，不能出现在钢琴谱上。", "脚印": "搭配：“钢琴谱上的脚印”的说法不成立，脚印不属于乐谱。"}, "sentence_index": 6, "correct_answer": "符号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一开口，符号就很响亮。", "explanation": "这里应该用〈声音〉。符号是记录音乐的记号，不能用来形容声音的响亮。"}, {"text": "这次行动的符号只有我们几个人知道。", "explanation": "这里应该用〈代号〉。符号是记录音乐的记号，不能用来给行动起代号。"}, {"text": "这首歌的符号是三分钟长。", "explanation": "这里应该用〈时长〉。符号是记录音乐的记号，不能用来说明歌曲有多长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "乐谱上有很多张小小的符号。", "corrected_sentence": "乐谱上有很多个小小的符号。", "error_description": "量词错误：“符号”应该用量词“个”，不能用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在谱子上画了一只符号。", "corrected_sentence": "他在谱子上画了一个符号。", "error_description": "量词错误：“符号”应该用量词“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
