INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10710, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容时间或机会极易失去，稍微一放松就过去了。", "primary_collocate": null, "pronunciation": "shāo zòng jí shì", "ipa": "ʂaʊ⁵⁵ tsʊŋ⁵¹ tɕi³⁵ ʂɨ⁵¹", "syllable_count": 4, "sentences": [{"text": "自远古时期起，不同文明便尝试以视觉符号捕捉稍纵即逝的音响，然而早期的记谱方式多具提示性而非精确性。", "target_word": "稍纵即逝", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好机会稍纵即逝，要快做决定。", "target_word": "稍纵即逝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的美景稍纵即逝，快拍照吧。", "target_word": "稍纵即逝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青春稍纵即逝，我们要珍惜。", "target_word": "稍纵即逝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机会稍纵即逝，他马上报了名。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "彩虹稍纵即逝，孩子们赶紧跑出去看。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中的机会稍纵即逝，球员必须马上射门。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的灵感稍纵即逝，所以随身带着笔记本。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流星稍纵即逝，我还没许愿就不见了。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好价格稍纵即逝，明天就涨了。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "时间或机会极易失去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稍纵即逝", "is_correct": true, "explanation": "正确：“稍纵即逝”修饰“音响”，说声音转瞬即逝，与“捕捉”搭配。"}, {"text": "无声", "is_correct": false, "explanation": "语义：“无声”与“音响”矛盾，音响本身是声音，不能捕捉无声的音响。"}, {"text": "斑斓", "is_correct": false, "explanation": "体貌：“斑斓”形容色彩外观，不能修饰声音。"}, {"text": "静止", "is_correct": false, "explanation": "语义：“静止”指不动，与声音的流动、转瞬即逝相矛盾，不能捕捉静止的音响。"}], "explanations": {"稍纵即逝": "正确：“稍纵即逝”修饰“音响”，说声音转瞬即逝，与“捕捉”搭配。", "无声": "语义：“无声”与“音响”矛盾，音响本身是声音，不能捕捉无声的音响。", "斑斓": "体貌：“斑斓”形容色彩外观，不能修饰声音。", "静止": "语义：“静止”指不动，与声音的流动、转瞬即逝相矛盾，不能捕捉静止的音响。"}, "sentence_index": 0, "correct_answer": "稍纵即逝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天局势稍纵即逝，大家都很紧张。", "explanation": "这里应该用〈瞬息万变〉。稍纵即逝只说机会或时光一闪而过，局势多变要用瞬息万变。"}, {"text": "这座古城稍纵即逝。", "explanation": "这里应该用〈古老〉。稍纵即逝说时机或时光一闪而过，古城存在多年，表示久远要用古老。"}, {"text": "他的身高稍纵即逝。", "explanation": "这里应该用〈稳定〉。稍纵即逝说时机或时光转瞬即逝，身高是长期保持的特征，表示持续不变要用稳定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稍纵即逝", "is_correct": true, "explanation": "正确：“稍纵即逝”说机会转瞬即逝，与“必须马上射门”的紧迫语气相合。"}, {"text": "永恒", "is_correct": false, "explanation": "语义：“永恒”指永远存在，与“必须马上射门”矛盾，机会永恒就不必马上行动。"}, {"text": "充裕", "is_correct": false, "explanation": "语义：“充裕”说机会很多，与“必须马上射门”矛盾。"}, {"text": "稳定", "is_correct": false, "explanation": "语义：“稳定”指长期不变，与“必须马上射门”的紧迫感相矛盾，机会稳定就无需立刻行动。"}], "explanations": {"稍纵即逝": "正确：“稍纵即逝”说机会转瞬即逝，与“必须马上射门”的紧迫语气相合。", "永恒": "语义：“永恒”指永远存在，与“必须马上射门”矛盾，机会永恒就不必马上行动。", "充裕": "语义：“充裕”说机会很多，与“必须马上射门”矛盾。", "稳定": "语义：“稳定”指长期不变，与“必须马上射门”的紧迫感相矛盾，机会稳定就无需立刻行动。"}, "sentence_index": 6, "correct_answer": "稍纵即逝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书法功力稍纵即逝。", "explanation": "这里应该用〈深厚〉。稍纵即逝说时机一闪而过，书法功力是长期积累的能力，表示功底的程度要用深厚。"}, {"text": "这条大河稍纵即逝。", "explanation": "这里应该用〈奔流不息〉。稍纵即逝说转瞬消失，大河长期存在、持续流动，应该表达这种持续的状态。"}, {"text": "她的性格稍纵即逝。", "explanation": "这里应该用〈稳定〉。稍纵即逝说时机或时光转瞬即逝，性格是长期稳定的特征，不能用它来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "时机很稍纵即逝，我们得赶紧行动。", "corrected_sentence": "时机稍纵即逝，我们得赶紧行动。", "error_description": "错误：“很稍纵即逝”；正确：“稍纵即逝”。“稍纵即逝”是四字成语，直接作谓语，前面一般不加程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份稍纵即逝美景值得好好珍惜。", "corrected_sentence": "这份稍纵即逝的美景值得好好珍惜。", "error_description": "错误：“稍纵即逝美景”；正确：“稍纵即逝的美景”。“稍纵即逝”修饰名词时，中间需要加结构助词“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
