INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10711, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "音响指能放大声音、播放音乐的电子设备，通常包括音箱和功放。", "primary_collocate": null, "pronunciation": "yīn xiǎng", "ipa": "in⁵⁵ ɕjɑŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "深夜十一点，邻居敲门说他家的音响太吵了。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音响的发展，让普通人在家也能听到接近现场的声音，其演变过程正体现了科技与音乐互动共生的深层关系。", "target_word": "音响", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "客厅里的音响声音很大。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家新买了一套音响。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台音响可以连接手机播放音乐。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，他先检查了音响有没有声音。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把音响的声音调小一点。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套音响的音箱很大，声音很好听。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒吧里的音响整晚放着音乐。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用音响放大了歌手的声音。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套音响", "label": "量词"}, {"form": "一台音响", "label": "量词"}, {"form": "音響", "label": "繁体"}], "register": "中性", "sense_fingerprint": "放大声音、播放音乐的电子设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10711, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "音响", "is_correct": true, "explanation": "正确：音响指放大声音、播放音乐的电子设备，与释义一致。"}, {"text": "印象", "is_correct": false, "explanation": "yìnxiàng 与 yīnxiǎng 两个音节的声调都不同，意思是“印象”。"}, {"text": "影响", "is_correct": false, "explanation": "yǐngxiǎng 与 yīnxiǎng 第一音节韵母（ing/in）和声调不同，意思是对别人起作用。"}, {"text": "音像", "is_correct": false, "explanation": "yīnxiàng 只有第二个音节的声调与 yīnxiǎng 不同，意思是“音像”。"}], "explanations": {"音响": "正确：音响指放大声音、播放音乐的电子设备，与释义一致。", "印象": "yìnxiàng 与 yīnxiǎng 两个音节的声调都不同，意思是“印象”。", "影响": "yǐngxiǎng 与 yīnxiǎng 第一音节韵母（ing/in）和声调不同，意思是对别人起作用。", "音像": "yīnxiàng 只有第二个音节的声调与 yīnxiǎng 不同，意思是“音像”。"}, "sentence_index": null, "correct_answer": "音响"}, "level_3": {"options": [{"text": "音响", "is_correct": true, "explanation": "正确：“家里的音响太吵了”指播放设备发出噪声，与深夜敲门投诉的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉特征，不会发出声音，不能说“太吵了”。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味属于嗅觉，不能用“太吵了”来形容。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：花朵不会发出声音，“花朵太吵了”不成立。"}], "explanations": {"音响": "正确：“家里的音响太吵了”指播放设备发出噪声，与深夜敲门投诉的语境相符。", "颜色": "语义：颜色是视觉特征，不会发出声音，不能说“太吵了”。", "香味": "语义：香味属于嗅觉，不能用“太吵了”来形容。", "花朵": "搭配：花朵不会发出声音，“花朵太吵了”不成立。"}, "sentence_index": 0, "correct_answer": "音响"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用音响擦干净了桌子。", "explanation": "这里应该用〈抹布〉。音响只用来放大和播放声音，擦桌子要用抹布。"}, {"text": "他每天在音响里学习汉字。", "explanation": "这里应该用〈教室〉。音响指放大声音的电子设备，不是可以学习的场所，表示地点时要换成〈教室〉之类的地方。"}, {"text": "我戴上音响听音乐。", "explanation": "这里应该用〈耳机〉。耳机戴在耳朵上，音响是放在房间或桌上的大型设备，不能戴在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音响", "is_correct": true, "explanation": "正确：“请把音响的声音调小一点”说的是能发声的设备，与“调小”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子本身不发声，没有声音可以调小。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：花朵不能发出声音，“花朵的声音”搭配不当。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“调小”的对象必须是能发声的设备，窗户不能作其受事。"}], "explanations": {"音响": "正确：“请把音响的声音调小一点”说的是能发声的设备，与“调小”搭配。", "桌子": "语义：桌子本身不发声，没有声音可以调小。", "花朵": "搭配：花朵不能发出声音，“花朵的声音”搭配不当。", "窗户": "配价：“调小”的对象必须是能发声的设备，窗户不能作其受事。"}, "sentence_index": 6, "correct_answer": "音响"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正在种音响，希望秋天能收获。", "explanation": "这里应该用〈庄稼〉。音响是电子设备，不是植物，不能播种或收获，种植的对象应换成〈庄稼〉之类。"}, {"text": "妈妈用音响炒了一盘青菜。", "explanation": "这里应该用〈锅〉。音响只用来放大和播放声音，炒菜要用锅，不能当作炊具。"}, {"text": "这台音响每天在花园里晒太阳。", "explanation": "这里应该用〈植物〉。晒太阳只用于有生命的植物或人，音响是没有生命的设备，不能晒太阳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家买了一张新音响，声音很好。", "corrected_sentence": "我家买了一套新音响，声音很好。", "error_description": "错误：“一张新音响”；正确：“一套新音响”。音响是电器，量词应用“套”或“台”；“张”用于平面的物品，不能用来数音响。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们家买了一辆音响，放在客厅里。", "corrected_sentence": "他们家买了一台音响，放在客厅里。", "error_description": "错误：“一辆音响”；正确：“一台音响”。“辆”用于车，音响这类电器应该用“台”或“套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
