INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10712, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "用来提醒或指出重要信息的性质。", "primary_collocate": null, "pronunciation": "tí shì xìng", "ipa": "tʰi³⁵ ʂɻ̩⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "这份乐谱只具有提示性，不能照着它精确地还原原曲。", "target_word": "提示性", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这个标志的提示性很强。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话只是提示性的，不是要求。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的黄色线条有提示性。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条短信的提示性不够明确。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的箭头具有提示性。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的建议更多是提示性的，不是命令。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的广告词要有提示性。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的目录提示性很好，容易找到内容。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯的提示性比文字更直接。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "提醒或指出重要信息的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提示性", "is_correct": true, "explanation": "正确。“只具有提示性”说明乐谱只起提醒作用，所以“不能照着它精确地还原原曲”。"}, {"text": "准确性", "is_correct": false, "explanation": "语义：“只具有准确性”与“不能照着它精确地还原”相矛盾，准确与精确意思相近，句意自相抵触。"}, {"text": "持久性", "is_correct": false, "explanation": "语义：“持久性”指长久留存，与“不能精确地还原原曲”没有逻辑联系，句意不通。"}, {"text": "娱乐性", "is_correct": false, "explanation": "语义：“娱乐性”指使人愉悦，与“不能精确地还原原曲”没有逻辑联系，句意不通。"}], "explanations": {"提示性": "正确。“只具有提示性”说明乐谱只起提醒作用，所以“不能照着它精确地还原原曲”。", "准确性": "语义：“只具有准确性”与“不能照着它精确地还原”相矛盾，准确与精确意思相近，句意自相抵触。", "持久性": "语义：“持久性”指长久留存，与“不能精确地还原原曲”没有逻辑联系，句意不通。", "娱乐性": "语义：“娱乐性”指使人愉悦，与“不能精确地还原原曲”没有逻辑联系，句意不通。"}, "sentence_index": 0, "correct_answer": "提示性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把尺子的提示性很高。", "explanation": "这里应该用〈精确性〉。提示性指提醒或指出信息的性质，测量工具的准确程度要用精确性。"}, {"text": "这条法律的提示性很强，人们都不敢违反。", "explanation": "这里应该用〈威慑性〉。提示性只是提醒，令人不敢违反的作用要用威慑性。"}, {"text": "这部电影的提示性很强，观众笑个不停。", "explanation": "这里应该用〈趣味性〉。提示性指提醒信息，电影让观众发笑要用趣味性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提示性", "is_correct": true, "explanation": "正确。“提示性的”与后句“不是命令”形成对照，说明医生的建议只起提醒作用。"}, {"text": "强制性", "is_correct": false, "explanation": "语义：“强制性的”意思接近命令，与后句“不是命令”相矛盾，句意自相抵触。"}, {"text": "指令性", "is_correct": false, "explanation": "语域：“指令性”是政策、计划等书面用语，不用于口头建议，且与“不是命令”意思相反。"}, {"text": "完整性", "is_correct": false, "explanation": "语义：“完整性”指齐全、无缺，与“不是命令”的对比无关，句意不通。"}], "explanations": {"提示性": "正确。“提示性的”与后句“不是命令”形成对照，说明医生的建议只起提醒作用。", "强制性": "语义：“强制性的”意思接近命令，与后句“不是命令”相矛盾，句意自相抵触。", "指令性": "语域：“指令性”是政策、计划等书面用语，不用于口头建议，且与“不是命令”意思相反。", "完整性": "语义：“完整性”指齐全、无缺，与“不是命令”的对比无关，句意不通。"}, "sentence_index": 6, "correct_answer": "提示性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的提示性很好，挂在客厅里很漂亮。", "explanation": "这里应该用〈装饰性〉。提示性指提醒信息，画作的装饰美化作用要用装饰性。"}, {"text": "这篇文章的提示性很强，能说服很多读者。", "explanation": "这里应该用〈说服力〉。提示性只是提醒，使读者信服要说“说服力很强”。"}, {"text": "这座建筑的提示性很高，看起来很美。", "explanation": "这里应该用〈美观性〉。提示性指提醒，建筑外形的美感要用美观性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个路牌的提示性的很好。", "corrected_sentence": "这个路牌的提示性很好。", "error_description": "多出一个“的”。“的”已接在“路牌”后面，“提示性”后应直接接谓语“很好”，不能再加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个按钮的提示性了很好。", "corrected_sentence": "这个按钮的提示性很好。", "error_description": "“了”误加在名词“提示性”后面。“提示性”后直接接“很好”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10713, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊性", "is_correct": true, "explanation": "正确。“模糊性”指不清楚、不准确，与“精确性”构成反义。"}, {"text": "速度", "is_correct": false, "explanation": "“速度”指快慢，与“精确性”没有反义关系。"}, {"text": "复杂度", "is_correct": false, "explanation": "“复杂度”指繁复的程度，与“精确性”没有反义关系。"}, {"text": "灵活度", "is_correct": false, "explanation": "“灵活度”指变通的程度，与“精确性”没有反义关系。"}], "correct_answer": "模糊性", "explanations": {"模糊性": "正确。“模糊性”指不清楚、不准确，与“精确性”构成反义。", "速度": "“速度”指快慢，与“精确性”没有反义关系。", "复杂度": "“复杂度”指繁复的程度，与“精确性”没有反义关系。", "灵活度": "“灵活度”指变通的程度，与“精确性”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10713, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊性", "is_correct": true, "explanation": "正确。“模糊性”指不清楚、不准确，与“精确性”构成反义。"}, {"text": "温度", "is_correct": false, "explanation": "“温度”指冷热的程度，与“精确性”没有反义关系。"}, {"text": "重量", "is_correct": false, "explanation": "“重量”指物体的轻重，与“精确性”没有反义关系。"}, {"text": "体积", "is_correct": false, "explanation": "“体积”指物体所占空间的大小，与“精确性”没有反义关系。"}], "correct_answer": "模糊性", "explanations": {"模糊性": "正确。“模糊性”指不清楚、不准确，与“精确性”构成反义。", "温度": "“温度”指冷热的程度，与“精确性”没有反义关系。", "重量": "“重量”指物体的轻重，与“精确性”没有反义关系。", "体积": "“体积”指物体所占空间的大小，与“精确性”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物或行为非常准确、没有偏差或错误的性质。", "primary_collocate": null, "pronunciation": "jīng què xìng", "ipa": "tɕiŋ⁵⁵ tɕʰɥe⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "手术器械要求极高，医生必须保证操作的精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的精确性很高。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生做手术时要保证精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学实验最重视数据的精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译要注意意思的精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的计算有很高的精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块手表的精确性让人放心。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图的精确性影响我们找路。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了提高精确性，他测量了三次。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写报告时，数字的精确性很重要。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精確性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "非常准确、没有偏差的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精确性", "is_correct": true, "explanation": "正确。“保证操作的精确性”指手术动作必须准确无误，与“要求极高”相符。"}, {"text": "提示性", "is_correct": false, "explanation": "语义：“保证操作的提示性”不通，手术操作要求的是准确无误，不是提醒作用。"}, {"text": "复杂性", "is_correct": false, "explanation": "语义：手术要求的是操作准确无误，“保证操作的复杂性”与“要求极高”的用意不符。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：“随机性”指无规律，与“保证”和“要求极高”的意思相反。"}], "explanations": {"精确性": "正确。“保证操作的精确性”指手术动作必须准确无误，与“要求极高”相符。", "提示性": "语义：“保证操作的提示性”不通，手术操作要求的是准确无误，不是提醒作用。", "复杂性": "语义：手术要求的是操作准确无误，“保证操作的复杂性”与“要求极高”的用意不符。", "随机性": "语义：“随机性”指无规律，与“保证”和“要求极高”的意思相反。"}, "sentence_index": 0, "correct_answer": "精确性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的精确性很快，半小时就到了。", "explanation": "这里应该用〈速度〉。精确性指准确无误，不用来形容快慢，车快要说速度。"}, {"text": "他的精确性很强，能举起一百公斤。", "explanation": "这里应该用〈力量〉。精确性指准确无误，不指体力，举起重物的能力要用力量。"}, {"text": "这首歌的精确性很高，大家都爱唱。", "explanation": "这里应该用〈流行程度〉。精确性指准确无误，歌曲受欢迎的程度要用流行程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精确性", "is_correct": true, "explanation": "正确。“精确性让人放心”指手表计时准确可靠，与句意相符。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：“随意性”指随便、没有定准，与“让人放心”相反。"}, {"text": "学术性", "is_correct": false, "explanation": "语域：“学术性”是专业研究用语，不用来形容手表，与口语语境不合。"}, {"text": "艺术性", "is_correct": false, "explanation": "语义：“艺术性”指美感与设计，与“让人放心”所指的性能可靠不符。"}], "explanations": {"精确性": "正确。“精确性让人放心”指手表计时准确可靠，与句意相符。", "随意性": "语义：“随意性”指随便、没有定准，与“让人放心”相反。", "学术性": "语域：“学术性”是专业研究用语，不用来形容手表，与口语语境不合。", "艺术性": "语义：“艺术性”指美感与设计，与“让人放心”所指的性能可靠不符。"}, "sentence_index": 6, "correct_answer": "精确性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个段子的精确性很强，大家都笑了。", "explanation": "这里应该用〈幽默性〉。精确性指准确无误，段子引人发笑要用幽默性。"}, {"text": "这份文件的精确性很强，只有领导能看。", "explanation": "这里应该用〈保密性〉。精确性指准确无误，限制他人查看要用保密性。"}, {"text": "这种材料的精确性很好，能承受很大压力。", "explanation": "这里应该用〈抗压性〉。精确性指准确无误，材料承受压力的能力要用抗压性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台秤的精确性的很好。", "corrected_sentence": "这台秤的精确性很好。", "error_description": "多出一个“的”。“的”已接在“秤”后面，“精确性”后应直接接谓语“很好”，不能再加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把尺子的精确性了很高。", "corrected_sentence": "这把尺子的精确性很高。", "error_description": "“了”误加在名词“精确性”后面。“精确性”后直接接“很高”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
