INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10715, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "concrete", "definition": "指为了识别、记录或提示而做的记号或符号；也指做记号的动作。", "primary_collocate": null, "pronunciation": "biāo jì", "ipa": "pjɑʊ˥˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "标记", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "请在地图上标记你家的位置。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个标记是什么意思？", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用红笔标记了重要的句子。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "箱子上有一个小小的标记。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在书上做了一个标记。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的名字标记在杯子上。", "target_word": "标记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的黄色标记是给司机看的。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要在墙上留下任何标记。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用小星星标记已经看完的书。", "target_word": "标记", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "标记了", "label": "体标"}, {"form": "标记着", "label": "体标"}, {"form": "标记过", "label": "体标"}, {"form": "標記", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为识别、记录或提示而做的记号；做记号的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2f31c21-2c55-48e3-af67-23fb038a16e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10715, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "标记", "is_correct": true, "explanation": "正确：标记（biāo jì），指记号、符号。"}, {"text": "标价", "is_correct": false, "explanation": "jià（第四声）与 jì（第四声）韵母不同，意思是价格，不是记号。"}, {"text": "边际", "is_correct": false, "explanation": "边际（biān jì）与标记（biāo jì）：biān 与 biāo 声母相同，韵母不同（-an / -ao），意思是边缘、界限。"}, {"text": "标界", "is_correct": false, "explanation": "jiè（第四声）与 jì（第四声）韵母不同，意思是划定界限。"}], "explanations": {"标记": "正确：标记（biāo jì），指记号、符号。", "标价": "jià（第四声）与 jì（第四声）韵母不同，意思是价格，不是记号。", "边际": "边际（biān jì）与标记（biāo jì）：biān 与 biāo 声母相同，韵母不同（-an / -ao），意思是边缘、界限。", "标界": "jiè（第四声）与 jì（第四声）韵母不同，意思是划定界限。"}, "sentence_index": null, "correct_answer": "标记"}, "level_3": {"options": [{"text": "标记", "is_correct": true, "explanation": "正确：此处指用字母做记号，以标明音高。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：「演奏」的对象是乐曲，不能与「字母」「音高」搭配。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：「朗读」指出声读出文字，与标注音高的语境不符。"}, {"text": "弹奏", "is_correct": false, "explanation": "搭配：「弹奏」需要乐器，「字母」不能被弹奏。"}], "explanations": {"标记": "正确：此处指用字母做记号，以标明音高。", "演奏": "搭配：「演奏」的对象是乐曲，不能与「字母」「音高」搭配。", "朗读": "语义：「朗读」指出声读出文字，与标注音高的语境不符。", "弹奏": "搭配：「弹奏」需要乐器，「字母」不能被弹奏。"}, "sentence_index": 0, "correct_answer": "标记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的标记很吸引人。", "explanation": "这里应该用〈标题〉。标记指记号、符号，不能指文章的名称。"}, {"text": "这件衣服的标记是三百元。", "explanation": "这里应该用〈标价〉。标记指记号、符号，不表示商品上标注的价格。"}, {"text": "墙上写着一个响亮的标记。", "explanation": "这里应该用〈标语〉。标记是记号，不能像标语那样写出响亮的口号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标记", "is_correct": true, "explanation": "正确：此处指在杯子上做记号，写上自己的名字。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发出歌声，不能把名字「唱」在杯子上。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指进食，与在杯子上留名字无关。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是饮品，「名字」不能被「喝」。"}], "explanations": {"标记": "正确：此处指在杯子上做记号，写上自己的名字。", "唱": "语义：「唱」指发出歌声，不能把名字「唱」在杯子上。", "吃": "语义：「吃」指进食，与在杯子上留名字无关。", "喝": "搭配：「喝」的对象是饮品，「名字」不能被「喝」。"}, "sentence_index": 6, "correct_answer": "标记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的荣誉标记是全国劳模。", "explanation": "这里应该用〈称号〉。标记指记号，不能用来指荣誉的名称。"}, {"text": "这是我去北京带回来的标记。", "explanation": "这里应该用〈纪念品〉。标记是记号，不是可以带回来送人的物件。"}, {"text": "他把这首诗标记成了英文。", "explanation": "这里应该用〈翻译〉。标记是做记号，不表示把诗句转换成另一种语言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我见过这只标记。", "corrected_sentence": "我见过这个标记。", "error_description": "量词错误：「标记」是记号，量词应用「个」，「只」多用于动物，不能说「这只标记」，应说「这个标记」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路边有一只黄色的标记。", "corrected_sentence": "路边有一个黄色的标记。", "error_description": "量词错误：「标记」是记号，量词应用「个」，「只」多用于动物，不能说「一只黄色的标记」，应说「一个黄色的标记」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
