INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旋律是指一系列有组织、有节奏的音符，构成音乐中可被辨认和记忆的主要线条。", "primary_collocate": null, "pronunciation": "xuán lǜ", "ipa": "ɕɥɛn˧˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "旋律", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首歌的旋律很简单，我一听就会哼。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只听了一遍，就记住了这首歌的旋律。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴弹出了美丽的旋律。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边走路，一边哼着那首歌的旋律。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段旋律很慢，听着让人想睡觉。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小提琴拉出的旋律让大家都安静下来。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里的旋律很有名，很多人都会唱。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，先学会旋律，再学歌词。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己写的旋律弹给我听。", "target_word": "旋律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主旋律", "label": "复合"}], "register": "中性", "sense_fingerprint": "音乐中由音符按节奏连成的、可辨认可记忆的主线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2f31c21-2c55-48e3-af67-23fb038a16e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旋律", "is_correct": true, "explanation": "正确：旋律指音符连成的主线，此处指音高的走向。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：「色彩」指颜色，与音高走向的语境不符。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：「香味」不能有「走向」，与音高无关。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：「颜料」不能用「指示…走向」来描述。"}], "explanations": {"旋律": "正确：旋律指音符连成的主线，此处指音高的走向。", "色彩": "语义：「色彩」指颜色，与音高走向的语境不符。", "香味": "搭配：「香味」不能有「走向」，与音高无关。", "颜料": "搭配：「颜料」不能用「指示…走向」来描述。"}, "sentence_index": 0, "correct_answer": "旋律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "钢琴发出了很大的旋律。", "explanation": "这里应该用〈音量〉。旋律指音符连成的主线，不表示声音的大小。"}, {"text": "这把椅子的旋律很好。", "explanation": "这里应该用〈质量〉。旋律是音乐中的线条，不指家具的质量。"}, {"text": "风车的旋律很快。", "explanation": "这里应该用〈旋转〉。旋律是音乐线条，不用来形容风车的转动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旋律", "is_correct": true, "explanation": "正确：小提琴拉出的音乐主线，让大家安静下来。"}, {"text": "灰尘", "is_correct": false, "explanation": "语义：「灰尘」不是音乐，不会让人安静下来。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「拉出」的对象是乐声，不能拉出「颜色」。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「拉出」不能搭配「味道」，乐器拉出的是声音。"}], "explanations": {"旋律": "正确：小提琴拉出的音乐主线，让大家安静下来。", "灰尘": "语义：「灰尘」不是音乐，不会让人安静下来。", "颜色": "搭配：「拉出」的对象是乐声，不能拉出「颜色」。", "味道": "搭配：「拉出」不能搭配「味道」，乐器拉出的是声音。"}, "sentence_index": 6, "correct_answer": "旋律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的旋律很鲜。", "explanation": "这里应该用〈味道〉。旋律是音乐概念，不指食物的味道。"}, {"text": "这些数字有一定的旋律。", "explanation": "这里应该用〈规律〉。旋律指音乐中的主线，不指事物的规则。"}, {"text": "这幅画的旋律很鲜艳。", "explanation": "这里应该用〈颜色〉。旋律不用来形容画面的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段很慢旋律让人想睡觉。", "corrected_sentence": "这段很慢的旋律让人想睡觉。", "error_description": "定语缺「的」：形容词带「很」作定语时要加「的」，应说「很慢的旋律」，不能说「很慢旋律」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说，要先记住一只旋律。", "corrected_sentence": "老师说，要先记住一段旋律。", "error_description": "量词错误：「旋律」应用量词「段」计量，不能用「只」，应说「一段旋律」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
