INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10719, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人或事物向某个方向移动或发展的趋势。", "primary_collocate": null, "pronunciation": "zǒu xiàng", "ipa": "tsou˨˩˦ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "走向", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河的走向是从西到东。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了前面的内容，我猜不到故事的走向。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在地图上指出了山的走向。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的走向已经很清楚了，红队会赢。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，公司明年的走向还不清楚。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子的走向很特别，先高后低。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看着图说，病情的走向还要观察。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的走向是南北的，我们往北走。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的走向让人想不到，大家都很吃惊。", "target_word": "走向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发展走向", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物移动或发展所呈现的方向与趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2f31c21-2c55-48e3-af67-23fb038a16e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10719, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "走向", "is_correct": true, "explanation": "正确答案。走向 zǒu xiàng，指事物移动或发展的趋势。"}, {"text": "奏响", "is_correct": false, "explanation": "zòu xiǎng（第四声、第三声）与 zǒu xiàng（第三声、第四声）声调不同，意思是演奏出响亮的声音。"}, {"text": "走样", "is_correct": false, "explanation": "yàng 与 xiàng 声母不同，走样意思是失去原来的样子。"}, {"text": "走线", "is_correct": false, "explanation": "xiàn 与 xiàng 韵尾不同（n 与 ng），走线意思是布设线路。"}], "explanations": {"走向": "正确答案。走向 zǒu xiàng，指事物移动或发展的趋势。", "奏响": "zòu xiǎng（第四声、第三声）与 zǒu xiàng（第三声、第四声）声调不同，意思是演奏出响亮的声音。", "走样": "yàng 与 xiàng 声母不同，走样意思是失去原来的样子。", "走线": "xiàn 与 xiàng 韵尾不同（n 与 ng），走线意思是布设线路。"}, "sentence_index": null, "correct_answer": "走向"}, "level_3": {"options": [{"text": "走向", "is_correct": true, "explanation": "正确答案。“旋律走向”指旋律音高起伏的趋势，符合“符号指示”的语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“旋律”没有“价格”，符号也不会指示旋律的价格。"}, {"text": "音色", "is_correct": false, "explanation": "语义：前半句说符号标记的是音高，音色不是这类符号所指示的内容。"}, {"text": "歌词", "is_correct": false, "explanation": "搭配：“旋律”不与“歌词”搭配，旋律本身不含歌词。"}], "explanations": {"走向": "正确答案。“旋律走向”指旋律音高起伏的趋势，符合“符号指示”的语境。", "价格": "语义：“旋律”没有“价格”，符号也不会指示旋律的价格。", "音色": "语义：前半句说符号标记的是音高，音色不是这类符号所指示的内容。", "歌词": "搭配：“旋律”不与“歌词”搭配，旋律本身不含歌词。"}, "sentence_index": 0, "correct_answer": "走向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子的走向很好，每天都能晒到太阳。", "explanation": "这里应该用〈朝向〉。房屋面对哪个方向用朝向，走向指事物移动或发展的趋势。"}, {"text": "这个路标的走向很清楚，大家都看懂了。", "explanation": "这里应该用〈指向〉。路标指示方向用指向，走向说的是移动或发展的趋势。"}, {"text": "指南针的走向总是朝南。", "explanation": "这里应该用〈指向〉。指南针指示方向用指向，走向表示移动或发展的趋势，不用来说指针的方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走向", "is_correct": true, "explanation": "正确答案。“走向”指曲子音高起伏的趋势，符合“先高后低”。"}, {"text": "包装", "is_correct": false, "explanation": "语义：后半句“先高后低”描述音高走势，包装没有高低起伏。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“这首曲子”不搭配“气味”，曲子没有气味。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“先高后低”描述音高，颜色没有这样的走势。"}], "explanations": {"走向": "正确答案。“走向”指曲子音高起伏的趋势，符合“先高后低”。", "包装": "语义：后半句“先高后低”描述音高走势，包装没有高低起伏。", "气味": "搭配：“这首曲子”不搭配“气味”，曲子没有气味。", "颜色": "语义：“先高后低”描述音高，颜色没有这样的走势。"}, "sentence_index": 6, "correct_answer": "走向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这扇窗户的走向朝南，屋里很亮。", "explanation": "这里应该用〈朝向〉。窗户面对哪个方向用朝向，走向指事物移动或发展的趋势。"}, {"text": "她唱歌的走向很好听。", "explanation": "这里应该用〈声音〉。好不好听说的是声音，走向指事物移动或发展的趋势。"}, {"text": "这本书的走向是按时间排的。", "explanation": "这里应该用〈编排〉。书的内容安排用编排，走向指事物移动或发展的趋势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影有一只新的走向。", "corrected_sentence": "这部电影有一个新的走向。", "error_description": "量词错误：“走向”是抽象名词，应用“个”。“只”用于动物等，不能用于走向，应为“一个新的走向”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段音乐的走向了很特别。", "corrected_sentence": "这段音乐的走向很特别。", "error_description": "体标错误：名词“走向”后不能加“了”，应为“走向很特别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
