INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "暂时使用别人的物品或金钱，以后归还。", "primary_collocate": null, "pronunciation": "jiè", "ipa": "tɕje˥˩", "syllable_count": 1, "sentences": [{"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "借", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我想向你借一支笔。", "target_word": "借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向图书馆借了三本书。", "target_word": "借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了带钱，想跟朋友借五十块。", "target_word": "借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是我从同学那里借来的。", "target_word": "借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，我可以借你的手机打电话吗？", "target_word": "借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借了钱，下个月一定要还。", "target_word": "借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟他借了一把伞，所以我没有淋雨。", "target_word": "借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟借过我的自行车，还没还。", "target_word": "借", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书可以借两个星期。", "target_word": "借", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "借了", "label": "体标"}, {"form": "借过", "label": "体标"}, {"form": "借出", "label": "复合"}, {"form": "借用", "label": "复合"}], "register": "中性", "sense_fingerprint": "暂时使用别人的东西或钱，日后归还", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2f31c21-2c55-48e3-af67-23fb038a16e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "借", "is_correct": true, "explanation": "正确答案。借 jiè，指暂时使用别人的东西或钱，以后归还。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）声调不同，意思是接收、接住。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是节日或段落。"}, {"text": "解", "is_correct": false, "explanation": "jiě（第三声）与 jiè（第四声）声调不同，意思是解开或理解。"}], "explanations": {"借": "正确答案。借 jiè，指暂时使用别人的东西或钱，以后归还。", "接": "jiē（第一声）与 jiè（第四声）声调不同，意思是接收、接住。", "节": "jié（第二声）与 jiè（第四声）声调不同，意思是节日或段落。", "解": "jiě（第三声）与 jiè（第四声）声调不同，意思是解开或理解。"}, "sentence_index": null, "correct_answer": "借"}, "level_3": {"options": [{"text": "借", "is_correct": true, "explanation": "正确答案。“借你的手机”指暂时使用对方的手机打电话。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送你的手机”是把手机给对方，与想用对方手机的意思相反。"}, {"text": "还", "is_correct": false, "explanation": "语义：“还”表示归还，“还你的手机打电话”不通，应先借用再归还。"}, {"text": "收", "is_correct": false, "explanation": "搭配：“收”不与“你的手机打电话”搭配，收取的是东西，不是用来打电话。"}], "explanations": {"借": "正确答案。“借你的手机”指暂时使用对方的手机打电话。", "送": "语义：“送你的手机”是把手机给对方，与想用对方手机的意思相反。", "还": "语义：“还”表示归还，“还你的手机打电话”不通，应先借用再归还。", "收": "搭配：“收”不与“你的手机打电话”搭配，收取的是东西，不是用来打电话。"}, "sentence_index": 0, "correct_answer": "借"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在街上借了一间小屋，每个月付一千块钱。", "explanation": "这里应该用〈租〉。借是无偿地暂时使用，按月付钱使用要说租。"}, {"text": "我借了朋友一个电话，告诉他我到了。", "explanation": "这里应该用〈打了〉。给人打电话说“打电话”，借是暂时使用别人的东西后归还。"}, {"text": "我在超市借了一袋米，月底再付钱。", "explanation": "这里应该用〈赊〉。先拿货、以后付钱要说赊，借是暂时使用后归还。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10720, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "借", "is_correct": true, "explanation": "正确答案。借 jiè，指暂时使用别人的东西或钱，以后归还。"}, {"text": "街", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）声调不同，意思是街道。"}, {"text": "结", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是结束或打结。"}, {"text": "姐", "is_correct": false, "explanation": "jiě（第三声）与 jiè（第四声）声调不同，意思是姐姐。"}, {"text": "价", "is_correct": false, "explanation": "jià 与 jiè 韵母不同（a 与 e），声调相同，意思是价格。"}], "explanations": {"借": "正确答案。借 jiè，指暂时使用别人的东西或钱，以后归还。", "街": "jiē（第一声）与 jiè（第四声）声调不同，意思是街道。", "结": "jié（第二声）与 jiè（第四声）声调不同，意思是结束或打结。", "姐": "jiě（第三声）与 jiè（第四声）声调不同，意思是姐姐。", "价": "jià 与 jiè 韵母不同（a 与 e），声调相同，意思是价格。"}, "sentence_index": null, "correct_answer": "借"}, "level_3": {"options": [{"text": "借", "is_correct": true, "explanation": "正确答案。借了钱，之后需要归还，符合后半句。"}, {"text": "存", "is_correct": false, "explanation": "语义：「存钱」是把钱存入，不需要归还，与后半句矛盾。"}, {"text": "赚", "is_correct": false, "explanation": "语义：赚来的钱不需要归还，与后半句矛盾。"}, {"text": "花", "is_correct": false, "explanation": "语义：「花钱」是支出，不需要归还，与后半句矛盾。"}], "explanations": {"借": "正确答案。借了钱，之后需要归还，符合后半句。", "存": "语义：「存钱」是把钱存入，不需要归还，与后半句矛盾。", "赚": "语义：赚来的钱不需要归还，与后半句矛盾。", "花": "语义：「花钱」是支出，不需要归还，与后半句矛盾。"}, "sentence_index": 6, "correct_answer": "借"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在网上借了一台电脑，付了五千块。", "explanation": "这里应该用〈买〉。借是暂时使用后归还，付钱拥有要说买。"}, {"text": "我借了一个工人来修房子，每天付他工资。", "explanation": "这里应该用〈雇〉。借的是东西，请人做事要说雇。"}, {"text": "我在书店借了一本词典，付了五十块。", "explanation": "这里应该用〈买〉。借是暂时使用后归还，付钱拥有要说买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向邻居借给了一把伞。", "corrected_sentence": "他向邻居借了一把伞。", "error_description": "补语错误：“向邻居借”是向别人拿来用，“借给”表示把东西给别人，方向相反，应为“借了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹借了过我的伞。", "corrected_sentence": "妹妹借过我的伞。", "error_description": "体标错误：“了”和“过”不能同时用在动词后，应为“借过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e83a676a-8873-48f4-ad4d-547ac7b0b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
