INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10721, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指文字和符号的基本书写单位。", "primary_collocate": null, "pronunciation": "zì fú", "ipa": "tsɨ˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "字符", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "屏幕上出现了很多奇怪的字符。", "target_word": "字符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复制网页时，部分字符会变成问号。", "target_word": "字符", "complexity_tier": "T3", "furigana": "fù zhì wǎng yè shí, bù fen zì fú huì biàn chéng wèn hào.", "sentence_source": "generated"}, {"text": "文件里的字符全都变成了乱码。", "target_word": "字符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在输入框里输入至少六个字符。", "target_word": "字符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者比较了两种古文字的字符形态。", "target_word": "字符", "complexity_tier": "T3", "furigana": "yán jiū zhě bǐ jiào le liǎng zhǒng gǔ wén zì de zì fú xíng tài.", "sentence_source": "generated"}, {"text": "这本书讲述了计算机如何处理中文字符。", "target_word": "字符", "complexity_tier": "T3", "furigana": "zhè běn shū jiǎng shù le jì suàn jī rú hé chǔ lǐ zhōng wén zì fú.", "sentence_source": "generated"}, {"text": "老式电报机只能发送有限的字符。", "target_word": "字符", "complexity_tier": "T3", "furigana": "lǎo shì diàn bào jī zhǐ néng fā sòng yǒu xiàn de zì fú.", "sentence_source": "generated"}, {"text": "他用电脑键盘打出了一行字符。", "target_word": "字符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个字符在文本里都有对应的编码。", "target_word": "字符", "complexity_tier": "T3", "furigana": "měi gè zì fú zài wén běn lǐ dōu yǒu duì yìng de biān mǎ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "字符串", "label": "复合"}, {"form": "字符集", "label": "复合"}], "register": "中性", "sense_fingerprint": "文字和符号的基本书写单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5516fdd-9a58-4c2f-a23e-f5845a48af52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10721, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "字符", "is_correct": true, "explanation": "正确答案。字符指文字和符号的基本书写单位，读作 zì fú。"}, {"text": "制服", "is_correct": false, "explanation": "zhì（zh）与 zì（z）声母不同，制服意思是制服、降伏，不是字符。"}, {"text": "自负", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，自负意思是自以为了不起。"}, {"text": "赐福", "is_correct": false, "explanation": "cì（c）与 zì（z）声母不同，fú 相同；赐福意思是给予福气，不是字符。"}], "explanations": {"字符": "正确答案。字符指文字和符号的基本书写单位，读作 zì fú。", "制服": "zhì（zh）与 zì（z）声母不同，制服意思是制服、降伏，不是字符。", "自负": "fù（第四声）与 fú（第二声）声调不同，自负意思是自以为了不起。", "赐福": "cì（c）与 zì（z）声母不同，fú 相同；赐福意思是给予福气，不是字符。"}, "sentence_index": null, "correct_answer": "字符"}, "level_3": {"options": [{"text": "字符", "is_correct": true, "explanation": "正确答案。工尺谱借字符记录相对音位，“字符”指书写的符号。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不能用来记录音高和音位，与句中“记录相对音位”不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气候状况，与记录音位无关。"}, {"text": "图画", "is_correct": false, "explanation": "搭配：“记录音位”的媒介应是字符或音符，“图画”不能这样用于记录相对音位。"}], "explanations": {"字符": "正确答案。工尺谱借字符记录相对音位，“字符”指书写的符号。", "颜色": "语义：颜色是视觉属性，不能用来记录音高和音位，与句中“记录相对音位”不合。", "天气": "语义：天气指气候状况，与记录音位无关。", "图画": "搭配：“记录音位”的媒介应是字符或音符，“图画”不能这样用于记录相对音位。"}, "sentence_index": 0, "correct_answer": "字符"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的字符很好，大家都喜欢他。", "explanation": "这里应该用〈性格〉。字符指文字和符号的书写单位，不能指人的性格。"}, {"text": "这部电视剧的字符很有个性。", "explanation": "这里应该用〈角色〉。字符指文字和符号的书写单位，不能指剧中的人物。"}, {"text": "这家饭店的字符很好吃。", "explanation": "这里应该用〈菜〉。字符指文字和符号，不能用来形容饭菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10721, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "字符", "is_correct": true, "explanation": "正确答案。字符指文字和符号的基本书写单位，读作 zì fú。"}, {"text": "祝福", "is_correct": false, "explanation": "zhù 与 zì 声母、韵母不同，fú 相同；祝福意思是表达美好的祝愿。"}, {"text": "致富", "is_correct": false, "explanation": "zhì（zh）与 zì（z）声母不同，fù（第四声）与 fú（第二声）声调不同，致富意思是变得富有。"}, {"text": "自付", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，自付意思是由自己承担费用。"}], "explanations": {"字符": "正确答案。字符指文字和符号的基本书写单位，读作 zì fú。", "祝福": "zhù 与 zì 声母、韵母不同，fú 相同；祝福意思是表达美好的祝愿。", "致富": "zhì（zh）与 zì（z）声母不同，fù（第四声）与 fú（第二声）声调不同，致富意思是变得富有。", "自付": "fù（第四声）与 fú（第二声）声调不同，自付意思是由自己承担费用。"}, "sentence_index": null, "correct_answer": "字符"}, "level_3": {"options": [{"text": "字符", "is_correct": true, "explanation": "正确答案。句中讲的是计算机处理中文的书写单位，应用“字符”。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵是天上的水汽凝结物，不是计算机处理的对象。"}, {"text": "灯火", "is_correct": false, "explanation": "语义：灯火指灯光，与计算机处理中文的内容无关。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“处理”的对象是文字、数据、问题，不能用于“脚步”。"}], "explanations": {"字符": "正确答案。句中讲的是计算机处理中文的书写单位，应用“字符”。", "云朵": "语义：云朵是天上的水汽凝结物，不是计算机处理的对象。", "灯火": "语义：灯火指灯光，与计算机处理中文的内容无关。", "脚步": "搭配：“处理”的对象是文字、数据、问题，不能用于“脚步”。"}, "sentence_index": 6, "correct_answer": "字符"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说的字符很有个性。", "explanation": "这里应该用〈人物〉。字符指文字和符号的书写单位，不能指小说中的人物。"}, {"text": "这首歌的字符很好听。", "explanation": "这里应该用〈旋律〉。字符是书写单位，不能用来形容歌曲的旋律。"}, {"text": "老师的字符很温柔。", "explanation": "这里应该用〈声音〉。字符是书写单位，不能用来形容声音温柔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10721, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕上出现了几条奇怪的字符。", "corrected_sentence": "屏幕上出现了几个奇怪的字符。", "error_description": "量词错误：“字符”应该用“个”，不能用“条”。“条”多用于线、消息等，“字符”是可数的单位，应说“几个字符”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10721, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个程序只统计了两个字符们。", "corrected_sentence": "这个程序只统计了两个字符。", "error_description": "复数错误：“字符”是事物单位，不能加“们”。“们”只用于指人，应说“两个字符”，不说“两个字符们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
