INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10724, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物中较小的组成部分或环节。", "primary_collocate": null, "pronunciation": "xì jié", "ipa": "ɕi˥˩ tɕje˧˥", "syllable_count": 2, "sentences": [{"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "细节", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个计划的细节还没有决定。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把事情的细节告诉我。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家很注意画里的每一个细节。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他记得那天发生的所有细节。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同的细节要仔细看清楚。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的细节拍得很真实。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要只看大方向，也要注意细节。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的设计细节让客人很满意。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问了他案子的很多细节。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "細節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物中较小的组成部分或环节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5516fdd-9a58-4c2f-a23e-f5845a48af52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10724, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "细节", "is_correct": true, "explanation": "正确答案。细节指事物中较小的组成部分，读作 xì jié。"}, {"text": "季节", "is_correct": false, "explanation": "jì（第四声）与 xì（第四声）声母不同，季节意思是一年中的春夏秋冬。"}, {"text": "洗劫", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，洗劫意思是抢劫财物。"}, {"text": "礼节", "is_correct": false, "explanation": "lǐ（第三声）与 xì（第四声）声母和声调都不同，礼节意思是礼仪规矩。"}], "explanations": {"细节": "正确答案。细节指事物中较小的组成部分，读作 xì jié。", "季节": "jì（第四声）与 xì（第四声）声母不同，季节意思是一年中的春夏秋冬。", "洗劫": "xǐ（第三声）与 xì（第四声）声调不同，洗劫意思是抢劫财物。", "礼节": "lǐ（第三声）与 xì（第四声）声母和声调都不同，礼节意思是礼仪规矩。"}, "sentence_index": null, "correct_answer": "细节"}, "level_3": {"options": [{"text": "细节", "is_correct": true, "explanation": "正确答案。句中说“规定节奏细节”，指节奏中的小组成部分。"}, {"text": "音色", "is_correct": false, "explanation": "语义：音色是乐音的品质，节奏的规定不包括音色。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与节奏的规定无关。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“节奏”后面不能接处所名词，“厨房”不能被“规定”。"}], "explanations": {"细节": "正确答案。句中说“规定节奏细节”，指节奏中的小组成部分。", "音色": "语义：音色是乐音的品质，节奏的规定不包括音色。", "温度": "语义：温度与节奏的规定无关。", "厨房": "搭配：“节奏”后面不能接处所名词，“厨房”不能被“规定”。"}, "sentence_index": 0, "correct_answer": "细节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的细节很开朗。", "explanation": "这里应该用〈性格〉。细节指事物的组成部分，不能用来形容人的性格。"}, {"text": "她的细节很苗条。", "explanation": "这里应该用〈身材〉。细节指事物的组成部分，不能用来形容人的身材。"}, {"text": "他的细节增加了五公斤。", "explanation": "这里应该用〈体重〉。细节指组成部分，不能用“增加了几公斤”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10724, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "细节", "is_correct": true, "explanation": "正确答案。细节指事物中较小的组成部分，读作 xì jié。"}, {"text": "气节", "is_correct": false, "explanation": "qì（第四声）与 xì（第四声）声母不同，气节意思是坚守的节操。"}, {"text": "系列", "is_correct": false, "explanation": "liè 与 jié 声母不同、声调也不同，系列意思是一组相关的事物。"}, {"text": "气结", "is_correct": false, "explanation": "qì 与 xì 声母不同，jié 相同；气结意思是因气愤而说不出话。"}], "explanations": {"细节": "正确答案。细节指事物中较小的组成部分，读作 xì jié。", "气节": "qì（第四声）与 xì（第四声）声母不同，气节意思是坚守的节操。", "系列": "liè 与 jié 声母不同、声调也不同，系列意思是一组相关的事物。", "气结": "qì 与 xì 声母不同，jié 相同；气结意思是因气愤而说不出话。"}, "sentence_index": null, "correct_answer": "细节"}, "level_3": {"options": [{"text": "细节", "is_correct": true, "explanation": "正确答案。句中说电影拍得真实，指影片中的细小部分。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“拍”的对象是画面、场景、镜头，“价格”不能被拍。"}, {"text": "味道", "is_correct": false, "explanation": "语义：影片是视听作品，味道无法拍摄。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的形体特征，不能说“电影的身高拍得很真实”。"}], "explanations": {"细节": "正确答案。句中说电影拍得真实，指影片中的细小部分。", "价格": "搭配：“拍”的对象是画面、场景、镜头，“价格”不能被拍。", "味道": "语义：影片是视听作品，味道无法拍摄。", "身高": "语义：身高是人的形体特征，不能说“电影的身高拍得很真实”。"}, "sentence_index": 6, "correct_answer": "细节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月的细节很高。", "explanation": "这里应该用〈收入〉。细节指事物的组成部分，不能用来说收入多少。"}, {"text": "他的细节一米八。", "explanation": "这里应该用〈身高〉。细节指组成部分，不能用来说人的身高。"}, {"text": "病人的细节很低。", "explanation": "这里应该用〈血压〉。细节指事物的组成部分，不能用来说血压的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案的每颗细节都要仔细检查。", "corrected_sentence": "这个方案的每个细节都要仔细检查。", "error_description": "量词错误：“细节”应该用“个”，“颗”多用于粒状或圆形的东西，不能用来数“细节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察只问了几个细节们。", "corrected_sentence": "警察只问了几个细节。", "error_description": "复数错误：“细节”是事物的组成部分，不能加“们”。“们”只用于指人，应说“几个细节”，不说“几个细节们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
