INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10725, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指师徒间口头传授和内心领会，后泛指通过言语和示范来传授技艺或学问。", "primary_collocate": null, "pronunciation": "kǒu chuán xīn shòu", "ipa": "kʰoʊ˨˩˦ ʈʂʰwan˧˥ ɕin˥ ʂoʊ˥˩", "syllable_count": 4, "sentences": [{"text": "古希腊使用字母标记音高，拜占庭以符号指示旋律走向，而中国工尺谱则借字符记录相对音位——这些系统皆未规定节奏细节，其演奏依赖口传心授的传统。", "target_word": "口传心授", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这门手艺靠口传心授一代代传下来。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅用口传心授的方法教徒弟。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的很多技艺都是口传心授的。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首民歌没有谱子，只靠口传心授。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统戏曲主要依靠口传心授。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶艺大师以口传心授的方式带学生。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口传心授是古老的学习方式。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的做菜秘方是口传心授的。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有书本时，人们靠口传心授保存知识。", "target_word": "口传心授", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "口傳心授", "label": "繁体"}], "register": "书面", "sense_fingerprint": "师徒间口头传授、内心领会的传承方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5516fdd-9a58-4c2f-a23e-f5845a48af52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口传心授", "is_correct": true, "explanation": "正确。与“传统”搭配，指口头传授与心领神会的传承方式，符合前句“未规定节奏细节”的语境。"}, {"text": "文字记载", "is_correct": false, "explanation": "语义：若演奏依赖文字记载，节奏就会被规定，与前句“未规定节奏细节”矛盾。"}, {"text": "五线谱", "is_correct": false, "explanation": "语义：五线谱会具体标示节奏，与“未规定节奏细节”相悖，无法说明演奏依赖它。"}, {"text": "数码录音", "is_correct": false, "explanation": "语义：古代工尺谱时代没有数码录音，与句中的历史语境矛盾。"}], "explanations": {"口传心授": "正确。与“传统”搭配，指口头传授与心领神会的传承方式，符合前句“未规定节奏细节”的语境。", "文字记载": "语义：若演奏依赖文字记载，节奏就会被规定，与前句“未规定节奏细节”矛盾。", "五线谱": "语义：五线谱会具体标示节奏，与“未规定节奏细节”相悖，无法说明演奏依赖它。", "数码录音": "语义：古代工尺谱时代没有数码录音，与句中的历史语境矛盾。"}, "sentence_index": 0, "correct_answer": "口传心授"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父亲把老房子口传心授给了我。", "explanation": "这里应该用〈留〉。口传心授指师徒间的技艺或学问传授，不能用于财产的转移。"}, {"text": "这些年他在书房里口传心授，一本书接一本书地读。", "explanation": "这里应该用〈埋头苦读〉。口传心授是师徒间的口头传授，不能用来形容自己埋头读书。"}, {"text": "我是从一句口传心授里听说这件事的。", "explanation": "这里应该用〈传闻〉。口传心授指有意的师徒传授，传闻是无意间流传的消息，两者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口传心授", "is_correct": true, "explanation": "正确。指师徒间口头与心领的传授方式，符合“带学生”的语境。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法是一门技艺，不是教学方式，“以书法的方式带学生”不成立。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是检验手段，不是传授方式，无法说明“带学生”的做法。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“带学生”需要有人施教，“机器”不能与“带学生”构成合适的搭配。"}], "explanations": {"口传心授": "正确。指师徒间口头与心领的传授方式，符合“带学生”的语境。", "书法": "语义：书法是一门技艺，不是教学方式，“以书法的方式带学生”不成立。", "考试": "语义：考试是检验手段，不是传授方式，无法说明“带学生”的做法。", "机器": "搭配：“带学生”需要有人施教，“机器”不能与“带学生”构成合适的搭配。"}, "sentence_index": 6, "correct_answer": "口传心授"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座古桥是从古代口传心授下来的。", "explanation": "这里应该用〈流传〉。口传心授指师徒间的技艺或学问传授，不能用来说建筑的留存。"}, {"text": "他没有老师，却靠口传心授学会了编程。", "explanation": "这里应该用〈自学〉。没有老师施教却说“口传心授”，前后矛盾。"}, {"text": "我们在酒桌上口传心授了很久。", "explanation": "这里应该用〈闲聊〉。口传心授指有意的师徒传授，不能用来形容随意的闲谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项技艺是一种口传心授传统。", "corrected_sentence": "这项技艺是一种口传心授的传统。", "error_description": "“的”漏用：“口传心授”修饰“传统”时，中间需加“的”，正确说法是“口传心授的传统”，不能省去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些技艺一直被口传心授延续下来。", "corrected_sentence": "这些技艺一直靠口传心授延续下来。", "error_description": "介词错误：“口传心授”表示传承的方式，不能放在“被”后面当施事，应用“靠”引出方式，即“靠口传心授延续下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
