INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物发展过程中方向或性质的关键改变。", "primary_collocate": null, "pronunciation": "zhuǎn zhé", "ipa": "ʈʂwan˨˩˦ ʈʂɤ˧˥", "syllable_count": 2, "sentences": [{"text": "真正革命性的转折始自中世纪末期西欧的纽姆谱发展，修士们在经文上方添加符号以指示音的升降，最终演化为四线谱，由圭多·达莱佐在11世纪奠定基础。", "target_word": "转折", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部电影的转折很突然，观众都没想到。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试成了他人生的一个转折。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事的转折出现在第三章。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场大病是她生活中的一个转折。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济形势在去年下半年出现了转折。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说没有转折，读起来很平淡。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个决定让公司的发展出现了转折。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一年的政策调整是行业发展的重要转折。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛到了后半场才出现转折。", "target_word": "转折", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "转折点", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词：事物发展中方向或性质改变的关键处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5516fdd-9a58-4c2f-a23e-f5845a48af52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转折", "is_correct": true, "explanation": "正确。指记谱方式上的关键变化，与“革命性”及“始自…发展”的语境相符。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”与“革命性”相悖，革命性的停滞无法推动记谱发展。"}, {"text": "倒退", "is_correct": false, "explanation": "语义：“倒退”与“革命性”和“发展”的语境矛盾。"}, {"text": "惯例", "is_correct": false, "explanation": "搭配：“革命性”一般修饰变化或突破，不能修饰“惯例”。"}], "explanations": {"转折": "正确。指记谱方式上的关键变化，与“革命性”及“始自…发展”的语境相符。", "停滞": "语义：“停滞”与“革命性”相悖，革命性的停滞无法推动记谱发展。", "倒退": "语义：“倒退”与“革命性”和“发展”的语境矛盾。", "惯例": "搭配：“革命性”一般修饰变化或突破，不能修饰“惯例”。"}, "sentence_index": 0, "correct_answer": "转折"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "齿轮开始缓缓转折。", "explanation": "这里应该用〈转动〉。转折多指事情或话题的关键改变，机械的旋转要用转动。"}, {"text": "他在山脚突然转折，朝村子跑去。", "explanation": "这里应该用〈拐弯〉。转折指事情或情况的关键变化，不能用来形容人走路时的拐弯。"}, {"text": "他忽然转折离开了，没有回头。", "explanation": "这里应该用〈转身〉。转折指事情或话题的关键改变，人背过身离开要用转身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转折", "is_correct": true, "explanation": "正确。与“读起来很平淡”相呼应，说明小说缺少关键的变化。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“没有字数”与“读起来平淡”之间没有合理的搭配关系。"}, {"text": "封面", "is_correct": false, "explanation": "语义：封面与“读起来很平淡”的阅读感受无关，语义不通。"}, {"text": "作者", "is_correct": false, "explanation": "语义：“没有作者”与“读起来很平淡”逻辑不通，无法构成因果。"}], "explanations": {"转折": "正确。与“读起来很平淡”相呼应，说明小说缺少关键的变化。", "字数": "搭配：“没有字数”与“读起来平淡”之间没有合理的搭配关系。", "封面": "语义：封面与“读起来很平淡”的阅读感受无关，语义不通。", "作者": "语义：“没有作者”与“读起来很平淡”逻辑不通，无法构成因果。"}, "sentence_index": 6, "correct_answer": "转折"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河是两省的转折。", "explanation": "这里应该用〈界限〉。转折指事情或话题的变化节点，不能指地理上的分界，两省之间的分界要用界限。"}, {"text": "村民每天都要走过这座转折。", "explanation": "这里应该用〈桥〉。转折指事情或情况的关键变化，不能指具体的建筑物。"}, {"text": "他是班里的转折，经常惹麻烦。", "explanation": "这里应该用〈捣蛋鬼〉。转折指事情或情况的变化节点，不能指人；形容班里经常惹麻烦的学生要用捣蛋鬼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次搬家是他生活的一本大转折。", "corrected_sentence": "这次搬家是他生活的一个大转折。", "error_description": "量词错误：“转折”应用量词“个”，“本”用于书册，应为“一个大转折”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部剧在结尾有一条转折。", "corrected_sentence": "这部剧在结尾有一次转折。", "error_description": "量词错误：“转折”应用量词“次”或“个”，“条”用于细长的东西，应为“一次转折”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
