INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10727, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示从某个时间或地点开始", "primary_collocate": null, "pronunciation": "shǐ zì", "ipa": "ʂɻ̩˨˩ tsɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "真正革命性的转折始自中世纪末期西欧的纽姆谱发展，修士们在经文上方添加符号以指示音的升降，最终演化为四线谱，由圭多·达莱佐在11世纪奠定基础。", "target_word": "始自", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个节日始自一千多年前的唐朝。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的茶文化始自两千多年前。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种比赛始自一九〇〇年。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的友谊始自小学。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路始自老城，一直通到海边。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的历史始自一个小渔村。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个习惯始自去年冬天。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河始自高山上的一个小湖。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的音乐梦想始自一把旧吉他。", "target_word": "始自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "动词：事物从某个时间或地点开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5516fdd-9a58-4c2f-a23e-f5845a48af52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10727, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "始自", "is_correct": true, "explanation": "正确答案。始自表示从某个时间或地点开始。"}, {"text": "十字", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，十字意思是十字形、交叉。"}, {"text": "柿子", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，后一音节轻声，意思是柿子。"}, {"text": "狮子", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，意思是狮子。"}, {"text": "石子", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，后一音节轻声，意思是小石头。"}], "explanations": {"始自": "正确答案。始自表示从某个时间或地点开始。", "十字": "shí（第二声）与 shǐ（第三声）声调不同，十字意思是十字形、交叉。", "柿子": "shì（第四声）与 shǐ（第三声）声调不同，后一音节轻声，意思是柿子。", "狮子": "shī（第一声）与 shǐ（第三声）声调不同，意思是狮子。", "石子": "shí（第二声）与 shǐ（第三声）声调不同，后一音节轻声，意思是小石头。"}, "sentence_index": null, "correct_answer": "始自"}, "level_3": {"options": [{"text": "始自", "is_correct": true, "explanation": "正确。“始自”说明转折从中世纪末期开始，与句中的起点义相符。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”表示中止，与后文“最终演化为四线谱”所说的持续发展相矛盾。"}, {"text": "保存", "is_correct": false, "explanation": "搭配：“保存”接的是文物、资料等，不能接“发展”作宾语。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”接的是房屋、道路等工程，不能接“发展”作宾语。"}], "explanations": {"始自": "正确。“始自”说明转折从中世纪末期开始，与句中的起点义相符。", "停止": "语义：“停止”表示中止，与后文“最终演化为四线谱”所说的持续发展相矛盾。", "保存": "搭配：“保存”接的是文物、资料等，不能接“发展”作宾语。", "修建": "搭配：“修建”接的是房屋、道路等工程，不能接“发展”作宾语。"}, "sentence_index": 0, "correct_answer": "始自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个朋友始自北京。", "explanation": "这里应该用〈来自〉。始自多指事物的起点，人的来处、籍贯要用来自。"}, {"text": "我们今天始自一起去看电影。", "explanation": "这里应该用〈开始〉。始自表示起点（时间、地点或事物），不能直接接“一起去看电影”这样的动作。"}, {"text": "我们明天始自学习汉语。", "explanation": "这里应该用〈开始〉。始自后面要接时间、地点等起点，不能直接接“学习汉语”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10727, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "始自", "is_correct": true, "explanation": "正确答案。始自表示从某个时间或地点开始。"}, {"text": "识字", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，识字意思是认识文字。"}, {"text": "实字", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，实字是语法术语，指有实在意义的字。"}, {"text": "虱子", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，后一音节轻声，意思是虱子。"}], "explanations": {"始自": "正确答案。始自表示从某个时间或地点开始。", "识字": "shí（第二声）与 shǐ（第三声）声调不同，识字意思是认识文字。", "实字": "shí（第二声）与 shǐ（第三声）声调不同，实字是语法术语，指有实在意义的字。", "虱子": "shī（第一声）与 shǐ（第三声）声调不同，后一音节轻声，意思是虱子。"}, "sentence_index": null, "correct_answer": "始自"}, "level_3": {"options": [{"text": "始自", "is_correct": true, "explanation": "正确。“始自”表示历史从一个小渔村开始，与句中的起点义相符。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，后面不能直接带“一个小渔村”这样的宾语。"}, {"text": "建成", "is_correct": false, "explanation": "搭配：“建成”接的是房屋、工程，不能说历史“建成”一个村子。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”接的是建筑、设施，“历史”不能被拆除，也拆不出一个村子。"}], "explanations": {"始自": "正确。“始自”表示历史从一个小渔村开始，与句中的起点义相符。", "消失": "配价：“消失”是不及物动词，后面不能直接带“一个小渔村”这样的宾语。", "建成": "搭配：“建成”接的是房屋、工程，不能说历史“建成”一个村子。", "拆除": "搭配：“拆除”接的是建筑、设施，“历史”不能被拆除，也拆不出一个村子。"}, "sentence_index": 6, "correct_answer": "始自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她始自一个音乐家庭。", "explanation": "这里应该用〈出身〉。说人的家庭背景要用出身，始自只用于事物的起点。"}, {"text": "我们一早始自去山上。", "explanation": "这里应该用〈出发〉。人动身前往某地要说出发，始自不用来表示人的行程。"}, {"text": "他始自一九九〇年。", "explanation": "这里应该用〈出生〉。说人的出生时间要用出生，始自用于事物的起点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行始自了三月初，一直持续到夏天。", "corrected_sentence": "这次旅行始自三月初，一直持续到夏天。", "error_description": "“始自”后面不能直接加“了”。正确写法是“这次旅行始自三月初”，“始自”本身已表示起点，不带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目从始自七点，一直播到深夜。", "corrected_sentence": "这个节目始自七点，一直播到深夜。", "error_description": "“始自”本身已表示起点，前面不能再加“从”。正确写法是“这个节目始自七点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
