INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10729, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "修士是基督教等宗教中，为专注于灵修与神学而献身、通常居住于修道院的男性。", "primary_collocate": null, "pronunciation": "xiū shì", "ipa": "ɕjoʊ˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "中世纪西欧的修士们在经文上方添加符号，以指示音的升降。", "target_word": "修士", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这位修士住在山上的修道院里。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修士每天早上都要先祈祷。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年轻时成了一名修士。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修士们在院子里安静地读书。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位修士把经书带给了村民。", "target_word": "修士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修道院里有二十多位修士。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位修士一生都在研究神学。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修士们过着简单的生活。", "target_word": "修士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他决定去做修士，离开家乡。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "修士们", "label": "复数"}], "register": "书面", "sense_fingerprint": "基督教修道院中专心灵修与神学的男性修道者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e54962f-2c27-426e-ada9-9ddfb59d8bac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修士", "is_correct": true, "explanation": "正确。「修士们」指修道院里的男修道者，能够在经文上方添加符号，符合中世纪西欧的语境。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：添加符号以指示音的升降是抄写乐谱的工作，与厨师的职业无关。"}, {"text": "水手", "is_correct": false, "explanation": "语义：水手在船上工作，与句中经文和乐谱的抄写环境不符。"}, {"text": "矿工", "is_correct": false, "explanation": "搭配：「在经文上方添加符号」的主体是抄写文字的人，矿工不与之搭配。"}], "explanations": {"修士": "正确。「修士们」指修道院里的男修道者，能够在经文上方添加符号，符合中世纪西欧的语境。", "厨师": "语义：添加符号以指示音的升降是抄写乐谱的工作，与厨师的职业无关。", "水手": "语义：水手在船上工作，与句中经文和乐谱的抄写环境不符。", "矿工": "搭配：「在经文上方添加符号」的主体是抄写文字的人，矿工不与之搭配。"}, "sentence_index": 0, "correct_answer": "修士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她年轻时进了修道院，成了一名修士。", "explanation": "这里应该用〈修女〉。修士指男性修道者，女性修道者称〈修女〉，〈修士〉不能指女性。"}, {"text": "他结了婚，仍然是一名修士，和妻子住在一起。", "explanation": "这里应该用〈牧师〉。修士要立誓独身，不能结婚；可以结婚的基督教教职人员称〈牧师〉。"}, {"text": "他在寺庙里出家，剃了头，成了一名修士。", "explanation": "这里应该用〈和尚〉。修士指基督教等宗教修道院中的男性修道者，在佛教寺庙出家的男子称〈和尚〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修士", "is_correct": true, "explanation": "正确。修道院里的成员用「位」计数，「修士」符合句意。"}, {"text": "律师", "is_correct": false, "explanation": "语义：律师的工作场所不是修道院，与句中的修道院语境不符。"}, {"text": "演员", "is_correct": false, "explanation": "语义：修道院不是演员聚集的地方，句中的语境排除了演员。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：「有二十多位司机」一般指单位的职工，修道院语境下不这样搭配。"}], "explanations": {"修士": "正确。修道院里的成员用「位」计数，「修士」符合句意。", "律师": "语义：律师的工作场所不是修道院，与句中的修道院语境不符。", "演员": "语义：修道院不是演员聚集的地方，句中的语境排除了演员。", "司机": "搭配：「有二十多位司机」一般指单位的职工，修道院语境下不这样搭配。"}, "sentence_index": 6, "correct_answer": "修士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司当修士，负责管理财务。", "explanation": "这里应该用〈会计〉。修士指立誓献身宗教的男人，不是公司的职务；负责管理财务的人称〈会计〉。"}, {"text": "他在图书馆当修士，负责整理书籍。", "explanation": "这里应该用〈管理员〉。修士是宗教称谓，不是图书馆的职位；整理书籍的工作人员称〈管理员〉。"}, {"text": "他是我们游泳队的修士，负责训练队员。", "explanation": "这里应该用〈教练〉。修士不是体育队的职务；负责训练队员的人称〈教练〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两位修士们每天都在山上祈祷。", "corrected_sentence": "这两位修士每天都在山上祈祷。", "error_description": "「这两位」已经表示数量，「修士」后面不能再加「们」，属于重复表示复数。应改为「这两位修士」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只修士每天早上都在院子里读经。", "corrected_sentence": "那位修士每天早上都在院子里读经。", "error_description": "「修士」指人，量词应用「位」，不能用「只」（「只」多用于动物）。应改为「那位修士」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
