INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10730, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指宗教或古代经典中的文字。", "primary_collocate": null, "pronunciation": "jīng wén", "ipa": "tɕiŋ˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "中世纪西欧的修士们在经文上方添加符号，以指示音的升降。", "target_word": "经文", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "修士每天都在教堂里念经文。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段经文是几百年前写的。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们解释了这段经文的意思。", "target_word": "经文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寺庙的墙上刻着很多经文。", "target_word": "经文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他能背出整段经文。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书里收录了不少古代经文的原文。", "target_word": "经文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把经文抄在了纸上。", "target_word": "经文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟着老师读经文。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些经文对信徒来说很重要。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "經文", "label": "繁体"}], "register": "书面", "sense_fingerprint": "宗教或古代经典中的文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e54962f-2c27-426e-ada9-9ddfb59d8bac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经文", "is_correct": true, "explanation": "正确。「经文上方」指写在文字上方的符号，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：添加符号以指示音的升降要写在乐谱或经文上，不能写在天空上。"}, {"text": "田野", "is_correct": false, "explanation": "语义：田野与抄写乐谱无关，句中是在文字上方加符号。"}, {"text": "海面", "is_correct": false, "explanation": "搭配：「在……上方添加符号」的对象一般是书写材料，「海面」不与之搭配。"}], "explanations": {"经文": "正确。「经文上方」指写在文字上方的符号，符合句意。", "天空": "语义：添加符号以指示音的升降要写在乐谱或经文上，不能写在天空上。", "田野": "语义：田野与抄写乐谱无关，句中是在文字上方加符号。", "海面": "搭配：「在……上方添加符号」的对象一般是书写材料，「海面」不与之搭配。"}, "sentence_index": 0, "correct_answer": "经文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "莎士比亚的戏剧是英国文学的经文。", "explanation": "这里应该用〈经典〉。经文指宗教或古代经典中的文字，文学名著应说〈经典〉。"}, {"text": "这首歌的经文写得很感人。", "explanation": "这里应该用〈歌词〉。经文指宗教或古代经典中的文字，歌曲的词要说〈歌词〉。"}, {"text": "这篇经文报道了地震的情况。", "explanation": "这里应该用〈新闻〉。经文是宗教文字，报道时事的文章应说〈新闻〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经文", "is_correct": true, "explanation": "正确。「收录」与「古代经文的原文」相符，「原文」指文字内容。"}, {"text": "陶器", "is_correct": false, "explanation": "语义：「陶器的原文」不成立，「原文」只指文字，陶器不是文字。"}, {"text": "家具", "is_correct": false, "explanation": "语义：「家具的原文」不成立，「原文」只指文字，家具不是文字。"}, {"text": "船只", "is_correct": false, "explanation": "语义：「船只的原文」不成立，「原文」只指文字，船只不是文字。"}], "explanations": {"经文": "正确。「收录」与「古代经文的原文」相符，「原文」指文字内容。", "陶器": "语义：「陶器的原文」不成立，「原文」只指文字，陶器不是文字。", "家具": "语义：「家具的原文」不成立，「原文」只指文字，家具不是文字。", "船只": "语义：「船只的原文」不成立，「原文」只指文字，船只不是文字。"}, "sentence_index": 6, "correct_answer": "经文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份经文记录了他去年的生活。", "explanation": "这里应该用〈日记〉。经文指宗教或古代经典中的文字，记录个人生活的文字应说〈日记〉。"}, {"text": "这份经文上列着每个月的花费。", "explanation": "这里应该用〈账单〉。经文指宗教或古代经典中的文字，列明花费的文字应说〈账单〉。"}, {"text": "这份经文讲解了手机的使用方法。", "explanation": "这里应该用〈说明书〉。经文指宗教或古代经典中的文字，讲解产品用法的文字应说〈说明书〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些经文们是修士们抄写的。", "corrected_sentence": "这些经文是修士们抄写的。", "error_description": "「这些」已经表示复数，「经文」后面不能再加「们」。应改为「这些经文」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "信徒在家里读这只经文。", "corrected_sentence": "信徒在家里读这段经文。", "error_description": "「经文」是文字，量词应用「段」，不能用「只」。应改为「这段经文」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10731, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "删除", "is_correct": true, "explanation": "删除与添加相对，指把原有的东西去掉，意思相反。"}, {"text": "完成", "is_correct": false, "explanation": "完成指做好某件事，与添加不是反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究指深入探讨，与添加没有相对的意思。"}, {"text": "保持", "is_correct": false, "explanation": "保持指维持原样，与添加不构成反义。"}], "correct_answer": "删除", "explanations": {"删除": "删除与添加相对，指把原有的东西去掉，意思相反。", "完成": "完成指做好某件事，与添加不是反义关系。", "研究": "研究指深入探讨，与添加没有相对的意思。", "保持": "保持指维持原样，与添加不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
