INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10731, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在原有基础上增加或加入。", "primary_collocate": null, "pronunciation": "tiān jiā", "ipa": "tʰjɛn˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "做汤时可以再添加一点盐。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在名单上添加我的名字。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件新添加了一个功能。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在面粉里添加了一些牛奶。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想在文件里添加别的内容吗？", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在文章最后添加了一段话。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种饮料没有添加糖。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在表格里添加了两行。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机里可以添加新的联系人。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要给菜单添加几个新菜。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "添加了", "label": "体标"}, {"form": "添加过", "label": "体标"}, {"form": "添加剂", "label": "复合"}], "register": "通用", "sense_fingerprint": "在原有基础上增加或加入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e54962f-2c27-426e-ada9-9ddfb59d8bac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10731, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "添加", "is_correct": true, "explanation": "正确答案，意思是在原有基础上增加或加入。"}, {"text": "天价", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，天价指极高的价格。"}, {"text": "田家", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，田家指农家，是书面词。"}, {"text": "天津", "is_correct": false, "explanation": "jīn 与 jiā 只差韵母（in 与 ia），声调相同，天津是城市名。"}, {"text": "天骄", "is_correct": false, "explanation": "jiāo 与 jiā 韵母不同（iao 与 ia），声调相同，天骄指杰出的人，是书面词。"}], "explanations": {"添加": "正确答案，意思是在原有基础上增加或加入。", "天价": "jià（第四声）与 jiā（第一声）声调不同，天价指极高的价格。", "田家": "tián（第二声）与 tiān（第一声）声调不同，田家指农家，是书面词。", "天津": "jīn 与 jiā 只差韵母（in 与 ia），声调相同，天津是城市名。", "天骄": "jiāo 与 jiā 韵母不同（iao 与 ia），声调相同，天骄指杰出的人，是书面词。"}, "sentence_index": null, "correct_answer": "添加"}, "level_3": {"options": [{"text": "添加", "is_correct": true, "explanation": "正确：「添加」表示把盐加进汤里，与「再……一点盐」相符。"}, {"text": "切", "is_correct": false, "explanation": "搭配：「切」用于块状食物，盐不能说「切」。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指食用，与「做汤时」的烹饪动作不符，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」不用于盐，「洗一点盐」不通。"}], "explanations": {"添加": "正确：「添加」表示把盐加进汤里，与「再……一点盐」相符。", "切": "搭配：「切」用于块状食物，盐不能说「切」。", "吃": "语义：「吃」指食用，与「做汤时」的烹饪动作不符，句意不通。", "洗": "搭配：「洗」不用于盐，「洗一点盐」不通。"}, "sentence_index": 0, "correct_answer": "添加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重添加了三公斤。", "explanation": "这里应该用〈增加〉。添加指把东西加进原有事物里，体重这类数量的增减要用增加。"}, {"text": "这一年城市的人口添加了很多。", "explanation": "这里应该用〈增长〉。添加强调加入新的东西，人口自然增多要用增长。"}, {"text": "锻炼可以添加体质。", "explanation": "这里应该用〈增强〉。添加指加入东西，体质的提升要用增强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10731, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "添加", "is_correct": true, "explanation": "正确答案，意思是在原有基础上增加或加入。"}, {"text": "天街", "is_correct": false, "explanation": "jiē 与 jiā 只差韵母（e 与 a），声调相同；天街指天上的街道，多见于诗文。"}, {"text": "天将", "is_correct": false, "explanation": "jiàng（第四声）与 jiā（第一声）声调不同，韵母也略有差别（iang 与 ia）；天将指神话中的天兵将领。"}, {"text": "田间", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）声调不同，jiān 与 jiā 只差韵尾 n；田间指田地里。"}], "explanations": {"添加": "正确答案，意思是在原有基础上增加或加入。", "天街": "jiē 与 jiā 只差韵母（e 与 a），声调相同；天街指天上的街道，多见于诗文。", "天将": "jiàng（第四声）与 jiā（第一声）声调不同，韵母也略有差别（iang 与 ia）；天将指神话中的天兵将领。", "田间": "tián（第二声）与 tiān（第一声）声调不同，jiān 与 jiā 只差韵尾 n；田间指田地里。"}, "sentence_index": null, "correct_answer": "添加"}, "level_3": {"options": [{"text": "添加", "is_correct": true, "explanation": "正确：「添加」表示把糖加进饮料里，与「没有……糖」相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是液体，糖不能说「喝」。"}, {"text": "发明", "is_correct": false, "explanation": "语义：「发明」指创造新事物，与饮料里的糖无关，句意不通。"}, {"text": "读", "is_correct": false, "explanation": "搭配：「读」的对象是文字，不能说「读糖」。"}], "explanations": {"添加": "正确：「添加」表示把糖加进饮料里，与「没有……糖」相符。", "喝": "搭配：「喝」的对象是液体，糖不能说「喝」。", "发明": "语义：「发明」指创造新事物，与饮料里的糖无关，句意不通。", "读": "搭配：「读」的对象是文字，不能说「读糖」。"}, "sentence_index": 6, "correct_answer": "添加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他添加了篮球队。", "explanation": "这里应该用〈加入〉。添加指把东西加到已有的东西里，人参加组织要用加入。"}, {"text": "这学期我的成绩添加了很多。", "explanation": "这里应该用〈提高〉。添加用于加入东西，成绩的上升要用提高。"}, {"text": "我们要添加生产规模。", "explanation": "这里应该用〈扩大〉。添加是加入东西，规模的扩展要用扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把盐添加汤里了。", "corrected_sentence": "我们把盐添加到汤里了。", "error_description": "错误：「添加汤里」缺少介词「到」。正确应为「添加到汤里」，表示把东西加入某处，缺了「到」句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司新添加了一只服务。", "corrected_sentence": "公司新添加了一项服务。", "error_description": "错误：「服务」作宾语时应用量词「项」，不能用「只」（「只」用于动物等）。正确应为「新添加了一项服务」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
