INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10732, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指物体在垂直方向上的移动，或气温、股价等数值的上升与下降。", "primary_collocate": null, "pronunciation": "shēng jiàng", "ipa": "ʂɤŋ˥ tɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这座平台的升降由液压系统控制，运行时几乎感觉不到晃动，适合搬运重型设备。", "target_word": "升降", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "电梯的升降很平稳。", "target_word": "升降", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "舞台的升降由工作人员控制。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气温的升降会影响人们的穿衣。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个平台可以升降，高度能调整。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗帘的升降全靠一个小开关。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台货梯的升降要平稳，不能突然停下。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子的升降很方便，一按按钮就行。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货车的车斗可以升降，方便装货。", "target_word": "升降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股价的升降每天都不一样。", "target_word": "升降", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升降机", "label": "复合"}, {"form": "升降台", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体或数值在垂直方向上的上升与下降变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e54962f-2c27-426e-ada9-9ddfb59d8bac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "升降", "is_correct": true, "explanation": "正确：「平台的升降」指平台上下移动，由液压系统控制，符合句意。"}, {"text": "面积", "is_correct": false, "explanation": "语义：「面积」指平面大小，不能由液压系统控制，句意不通。"}, {"text": "酸甜", "is_correct": false, "explanation": "语义：「酸甜」指味道，平台没有酸甜，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不能由液压系统控制，句意不通。"}], "explanations": {"升降": "正确：「平台的升降」指平台上下移动，由液压系统控制，符合句意。", "面积": "语义：「面积」指平面大小，不能由液压系统控制，句意不通。", "酸甜": "语义：「酸甜」指味道，平台没有酸甜，句意不通。", "颜色": "语义：「颜色」不能由液压系统控制，句意不通。"}, "sentence_index": 0, "correct_answer": "升降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把自行车升降到了门口。", "explanation": "这里应该用〈推〉。升降只指垂直方向的上下移动，把自行车沿地面推到门口是水平移动，要用推。"}, {"text": "陀螺在地上升降。", "explanation": "这里应该用〈旋转〉。升降指上下移动，陀螺绕轴转动要用旋转。"}, {"text": "汽车在马路上升降。", "explanation": "这里应该用〈前进〉。升降指垂直方向的上下移动，汽车在地面向前行驶要用前进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "升降", "is_correct": true, "explanation": "正确：「货梯的升降」指货梯上下移动，「要平稳」与之相符。"}, {"text": "形状", "is_correct": false, "explanation": "语义：「形状」不能「平稳」，「货梯的形状要平稳」句意不通。"}, {"text": "高矮", "is_correct": false, "explanation": "搭配：「高矮」描述高低，不能用「平稳」修饰，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：货梯没有体重要「平稳」的说法，句意不通。"}], "explanations": {"升降": "正确：「货梯的升降」指货梯上下移动，「要平稳」与之相符。", "形状": "语义：「形状」不能「平稳」，「货梯的形状要平稳」句意不通。", "高矮": "搭配：「高矮」描述高低，不能用「平稳」修饰，句意不通。", "体重": "语义：货梯没有体重要「平稳」的说法，句意不通。"}, "sentence_index": 6, "correct_answer": "升降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钟摆在左右升降。", "explanation": "这里应该用〈摆动〉。升降只指上下方向，钟摆左右来回要用摆动。"}, {"text": "孩子们在操场上升降。", "explanation": "这里应该用〈奔跑〉。升降指垂直上下移动，人在地面快速跑动要用奔跑。"}, {"text": "他慢慢升降着走出了房间。", "explanation": "这里应该用〈倒退〉。升降指上下移动，人向后退着慢慢离开要用倒退，不能用升降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电梯完成了一个升降。", "corrected_sentence": "电梯完成了一次升降。", "error_description": "错误：「升降」作名词计量时用量词「次」，不能用「个」。正确应为「完成了一次升降」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "舞台缓慢的升降着。", "corrected_sentence": "舞台缓慢地升降着。", "error_description": "错误：「缓慢」修饰动词「升降」应用「地」；用「的」会把「升降」变成名词，后面不能再接动态助词「着」。正确应为「缓慢地升降着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10737, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10737, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10737, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打下基础，使事物稳固地建立起来。", "primary_collocate": null, "pronunciation": "diàn dìng", "ipa": "tjɛn˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他每天练琴，为以后学音乐奠定基础。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次会议为合作奠定了基础。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "良好的习惯能为未来奠定基础。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候读的书，为他奠定了文化基础。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科学家为现代医学奠定了基础。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好语法，才能为写作奠定基础。", "target_word": "奠定", "complexity_tier": "T3", "furigana": "xué hǎo yǔ fǎ, cái néng wèi xiě zuò diàn dìng jī chǔ", "sentence_source": "generated"}, {"text": "这场胜利奠定了他在队里的地位。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用三年时间奠定了自己在行业里的地位。", "target_word": "奠定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条法律为国家发展奠定了制度基础。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国签了条约，为和平奠定基础。", "target_word": "奠定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "奠定了", "label": "体标"}, {"form": "奠定过", "label": "体标"}], "register": "书面", "sense_fingerprint": "为事业或事物打下稳固的基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e54962f-2c27-426e-ada9-9ddfb59d8bac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10737, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奠定", "is_correct": true, "explanation": "正确：奠定（diàn dìng）指打下基础，使事物稳固地建立起来。"}, {"text": "淡定", "is_correct": false, "explanation": "dàn（第四声）与 diàn 的第一音节只差介音 i（ian 与 an），淡定指镇定、从容，与打下基础无关。"}, {"text": "电动", "is_correct": false, "explanation": "第二音节韵母 ong 与 ing 不同（dòng 与 dìng），电动指靠电力驱动，与打下基础无关。"}, {"text": "电灯", "is_correct": false, "explanation": "第二音节 dēng 与 dìng 韵母、声调都不同，电灯指用电发光的灯，与打下基础无关。"}], "explanations": {"奠定": "正确：奠定（diàn dìng）指打下基础，使事物稳固地建立起来。", "淡定": "dàn（第四声）与 diàn 的第一音节只差介音 i（ian 与 an），淡定指镇定、从容，与打下基础无关。", "电动": "第二音节韵母 ong 与 ing 不同（dòng 与 dìng），电动指靠电力驱动，与打下基础无关。", "电灯": "第二音节 dēng 与 dìng 韵母、声调都不同，电灯指用电发光的灯，与打下基础无关。"}, "sentence_index": null, "correct_answer": "奠定"}, "level_3": {"options": [{"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”多接火焰、热情，不能接“基础”。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于影片、音乐，不能接“基础”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」多接食物，或「亏、苦」等，不能接「基础」。"}, {"text": "奠定", "is_correct": true, "explanation": "正确：“奠定基础”指打下稳固的基础，符合句意。"}], "explanations": {"点燃": "搭配：“点燃”多接火焰、热情，不能接“基础”。", "播放": "搭配：“播放”用于影片、音乐，不能接“基础”。", "吃": "搭配：「吃」多接食物，或「亏、苦」等，不能接「基础」。", "奠定": "正确：“奠定基础”指打下稳固的基础，符合句意。"}, "sentence_index": 0, "correct_answer": "奠定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议奠定了新的午餐菜单。", "explanation": "这里应该用〈制定〉。奠定指打下基础，宾语多为基础、地位；菜单这类具体安排要用制定。"}, {"text": "经理奠定了下周的会议时间。", "explanation": "这里应该用〈确定〉。奠定指打下基础，不用于会议时间这类具体安排，应说确定。"}, {"text": "他在班里奠定了榜样。", "explanation": "这里应该用〈树立〉。奠定指打下基础，不说“奠定榜样”；榜样、形象、威信要用树立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10737, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奠定", "is_correct": true, "explanation": "正确：奠定（diàn dìng）指打下基础，使事物稳固地建立起来。"}, {"text": "限定", "is_correct": false, "explanation": "第一音节声母 x 与 d 不同（xiàn 与 diàn），限定指规定在一定范围内，与打下基础无关。"}, {"text": "电镜", "is_correct": false, "explanation": "第二音节声母 j 与 d 不同（jìng 与 dìng），电镜指电子显微镜。"}, {"text": "殿顶", "is_correct": false, "explanation": "第二音节 dǐng（第三声）与 dìng（第四声）只差声调，殿顶指宫殿的屋顶。"}], "explanations": {"奠定": "正确：奠定（diàn dìng）指打下基础，使事物稳固地建立起来。", "限定": "第一音节声母 x 与 d 不同（xiàn 与 diàn），限定指规定在一定范围内，与打下基础无关。", "电镜": "第二音节声母 j 与 d 不同（jìng 与 dìng），电镜指电子显微镜。", "殿顶": "第二音节 dǐng（第三声）与 dìng（第四声）只差声调，殿顶指宫殿的屋顶。"}, "sentence_index": null, "correct_answer": "奠定"}, "level_3": {"options": [{"text": "失去", "is_correct": false, "explanation": "语义：胜利会使人得到地位，不会让人失去地位，句意相反。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是主动舍弃，与“胜利”带来的结果相冲突。"}, {"text": "抹去", "is_correct": false, "explanation": "语义：胜利应当提升地位，不会抹去地位，句意相反。"}, {"text": "奠定", "is_correct": true, "explanation": "正确：“奠定地位”指使地位稳固地建立起来，符合句意。"}], "explanations": {"失去": "语义：胜利会使人得到地位，不会让人失去地位，句意相反。", "放弃": "语义：“放弃”是主动舍弃，与“胜利”带来的结果相冲突。", "抹去": "语义：胜利应当提升地位，不会抹去地位，句意相反。", "奠定": "正确：“奠定地位”指使地位稳固地建立起来，符合句意。"}, "sentence_index": 6, "correct_answer": "奠定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "双方奠定了和平条约。", "explanation": "这里应该用〈缔结〉。奠定指打下基础，宾语多为基础、地位；条约要说缔结或签订。"}, {"text": "市政府奠定了新的办事处。", "explanation": "这里应该用〈设立〉。奠定指打下基础，不用于办事处这类机构；设立机构要用设立。"}, {"text": "这位探险家奠定了新的航线。", "explanation": "这里应该用〈开辟〉。奠定指打下基础，不用于航线、道路等具体路线；开辟航线要用开辟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一步把根基奠定很牢。", "corrected_sentence": "这一步把根基奠定得很牢。", "error_description": "错误：“奠定”后面的程度补语前漏掉了“得”，写成了“奠定很牢”。应写作“奠定得很牢”，“得”用来连接动词和补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次合作把基础奠定了好。", "corrected_sentence": "这次合作把基础奠定好了。", "error_description": "错误：结果补语“好”应紧接动词，“了”应放在补语之后。“奠定了好”是错的，应写作“奠定好了”，即“奠定”后接补语“好”，再接“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10739, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
