INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10739, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指两个事物在某方面相符合、相当或互相配合。", "primary_collocate": null, "pronunciation": "duì yìng", "ipa": "twei˥˩ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "每个数字都对应一个字母。", "target_word": "对应", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "表格里的每一行都对应一个名字。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左边的词和右边的意思要一一对应。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个按钮对应屏幕上的哪个功能？", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上的每种颜色都对应一种高度。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的座位号对应票上的数字。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每把钥匙都对应一扇门。", "target_word": "对应", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些图片分别对应课文里的一句话。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个词在意思上不完全对应。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个汉字的读音都对应一个声调。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "对应了", "label": "体标"}, {"form": "对应着", "label": "体标"}, {"form": "對應", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个事物一一相配、相符", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b63a2c7-7b4b-4b6e-a491-5467c19626e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10739, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对应", "is_correct": true, "explanation": "正确。“对应”指两个事物一一相配，这里说每个数字和一个字母一一配合。"}, {"text": "喝", "is_correct": false, "explanation": "语义：数字不能“喝”字母，“喝”的对象须是饮品。"}, {"text": "吃", "is_correct": false, "explanation": "语义：数字不能“吃”字母，“吃”的对象须是食物。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”通常带歌曲作宾语，不说唱字母。"}], "explanations": {"对应": "正确。“对应”指两个事物一一相配，这里说每个数字和一个字母一一配合。", "喝": "语义：数字不能“喝”字母，“喝”的对象须是饮品。", "吃": "语义：数字不能“吃”字母，“吃”的对象须是食物。", "唱": "搭配：“唱”通常带歌曲作宾语，不说唱字母。"}, "sentence_index": 0, "correct_answer": "对应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对应朋友很真诚。", "explanation": "这里应该用〈对待〉。对应表示两者相符，对待朋友的态度要用“对待”。"}, {"text": "妈妈对应了我的请求。", "explanation": "这里应该用〈答应〉。对应表示两者相符，不表示同意；同意请求要说“答应”。"}, {"text": "他对应我一个微笑。", "explanation": "这里应该用〈回以〉。对应表示两者相符，回应别人的笑容要说“回以微笑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对应", "is_correct": true, "explanation": "正确。“对应”指两个事物一一相配，这里说每把钥匙和一扇门一一配合。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”的宾语是帽子、眼镜等，不说戴门。"}, {"text": "吻", "is_correct": false, "explanation": "语义：钥匙不能“吻”门，“吻”需要有生命的施事。"}, {"text": "咬", "is_correct": false, "explanation": "语义：钥匙不能“咬”门，与“一把对一扇”的配合无关。"}], "explanations": {"对应": "正确。“对应”指两个事物一一相配，这里说每把钥匙和一扇门一一配合。", "戴": "搭配：“戴”的宾语是帽子、眼镜等，不说戴门。", "吻": "语义：钥匙不能“吻”门，“吻”需要有生命的施事。", "咬": "语义：钥匙不能“咬”门，与“一把对一扇”的配合无关。"}, "sentence_index": 6, "correct_answer": "对应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府积极对应群众的呼声。", "explanation": "这里应该用〈响应〉。对应指两者一一相符，回应群众的呼声要用“响应”。"}, {"text": "他对应坏人很有办法。", "explanation": "这里应该用〈对付〉。对应表示相符，应付、处理坏人要用“对付”。"}, {"text": "他对应了我的道歉。", "explanation": "这里应该用〈接受〉。对应表示相符，接受别人的道歉要用“接受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个号码都对应的一位同学。", "corrected_sentence": "每个号码都对应一位同学。", "error_description": "“对应”后直接接宾语，中间不能加“的”。原句“对应的一位同学”多了“的”，正确说法是“每个号码都对应一位同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个灯泡都把对应一个开关。", "corrected_sentence": "每个灯泡都对应一个开关。", "error_description": "“把”字句要求“把”后接宾语再接动词；这里“把”后直接是动词“对应”，缺少宾语，“把”多余。正确说法是“每个灯泡都对应一个开关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
