INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10741, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物质存在的广延性，由长、宽、高表现出来；也指可以容纳事物的地方或范围。", "primary_collocate": null, "pronunciation": "kōng jiān", "ipa": "kʰʊŋ˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "这个房间的空间很大。", "target_word": "空间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞船里的空间非常小。", "target_word": "空间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "时间和空间都是物理学的概念。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车后面的空间足够放三个箱子。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的公共空间不多。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们需要一个玩的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙发放在这儿会占很多空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个书架很好地利用了墙上的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校里有很大的活动空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机上的座位空间太小了。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "空間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长宽高构成的范围；容纳事物的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b63a2c7-7b4b-4b6e-a491-5467c19626e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10741, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空间", "is_correct": true, "explanation": "正确。“空间”指物体所占的范围，这里说房间的大小。"}, {"text": "性格", "is_correct": false, "explanation": "语义：房间没有“性格”，“房间的性格很大”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：房间不说“体重”，与房间的大小无关。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气很大”只用于人或动物，不用于房间。"}], "explanations": {"空间": "正确。“空间”指物体所占的范围，这里说房间的大小。", "性格": "语义：房间没有“性格”，“房间的性格很大”说不通。", "体重": "语义：房间不说“体重”，与房间的大小无关。", "脾气": "搭配：“脾气很大”只用于人或动物，不用于房间。"}, "sentence_index": 0, "correct_answer": "空间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的空间很重。", "explanation": "这里应该用〈重量〉。空间指物体所占的范围，不表示轻重；说石头的轻重要用“重量”。"}, {"text": "他的空间已经五十岁了。", "explanation": "这里应该用〈年龄〉。空间指物体所占的范围，不能用来说人的岁数；说人多大了要用“年龄”。"}, {"text": "这段空间过得很快。", "explanation": "这里应该用〈时间〉。“过得很快”说的是时间流逝，空间不能表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空间", "is_correct": true, "explanation": "正确。“空间”指物体所占的范围，这里说沙发占用的地方。"}, {"text": "温度", "is_correct": false, "explanation": "语义：沙发不能“占”温度，“占很多温度”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：沙发不能“占”年龄，与放置位置无关。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“占”一般接位置、空间或时间，不接“笑声”。"}], "explanations": {"空间": "正确。“空间”指物体所占的范围，这里说沙发占用的地方。", "温度": "语义：沙发不能“占”温度，“占很多温度”说不通。", "年龄": "语义：沙发不能“占”年龄，与放置位置无关。", "笑声": "搭配：“占”一般接位置、空间或时间，不接“笑声”。"}, "sentence_index": 6, "correct_answer": "空间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的空间有一米八。", "explanation": "这里应该用〈身高〉。空间指物体所占的范围，不表示人的高矮；说人有多高要用“身高”。"}, {"text": "这架飞机的空间很快。", "explanation": "这里应该用〈速度〉。空间表示物体所占的范围，不表示快慢，形容飞机快要说“速度”。"}, {"text": "这杯咖啡的空间很高。", "explanation": "这里应该用〈温度〉。空间不能表示冷热，形容咖啡的热度要用“温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子有一只很大的空间。", "corrected_sentence": "这间屋子有一个很大的空间。", "error_description": "“空间”的量词应用“个”，不用“只”。正确说法是“一个很大的空间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套房子有一套宽敞的空间。", "corrected_sentence": "这套房子有一个宽敞的空间。", "error_description": "“空间”的量词应用“个”，“一套”不用于空间。正确说法是“一个宽敞的空间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
