INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10743, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物显露出来的性质、特征或迹象。", "primary_collocate": null, "pronunciation": "biǎo zhēng", "ipa": "pjɑʊ˨˩˦ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这一系列异常的卫星云图，既是台风逼近的先兆，也是大气环流剧变的表征。", "target_word": "表征", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "天空变黑是要下雨的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花开得这么早，是春天来了的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格一直上涨，是经济过热的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变浑，是上游下过大雨的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶变黄是秋天到来的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民说，这种颜色是果子成熟的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地面出现裂缝，是地震的一种表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们常把动物不安当作地震的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小草变绿，是天气变暖的明显表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表徵", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物显露出来、可据以判断的特征或迹象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c5811c7-5286-4a58-bed4-0f21f210b18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10743, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表征", "is_correct": true, "explanation": "表征：指显露出来的特征或迹象，此处指异常云图所显示的大气环流剧变的迹象。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情指人的心理状态，不能作为云图所显示的天气迹象。"}, {"text": "人物", "is_correct": false, "explanation": "语义：人物指人，与云图所显示的台风先兆和气流变化无关。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”为口语，与这段书面语的语域不合，且不指表示特征的事物。"}], "explanations": {"表征": "表征：指显露出来的特征或迹象，此处指异常云图所显示的大气环流剧变的迹象。", "感情": "语义：感情指人的心理状态，不能作为云图所显示的天气迹象。", "人物": "语义：人物指人，与云图所显示的台风先兆和气流变化无关。", "玩意儿": "语域：“玩意儿”为口语，与这段书面语的语域不合，且不指表示特征的事物。"}, "sentence_index": 0, "correct_answer": "表征"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中的表征很出色。", "explanation": "这里应该用〈表现〉。表征指事物显露出的特征或迹象，多用于抽象情况；人在比赛中的行为与结果要用表现。"}, {"text": "她脸上的表征很温柔。", "explanation": "这里应该用〈表情〉。表征不指人脸上的神情；“脸上的神情”要用表情。"}, {"text": "他对这件事的表征很认真。", "explanation": "这里应该用〈态度〉。表征指事物显露出的特征或迹象，不指人对事情的看法；“对事情的态度”要用态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表征", "is_correct": true, "explanation": "表征：指事物显露出的特征或迹象，此处指这种颜色显示出果子已经成熟。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指买卖中的货币数额，与颜色和果子成熟无关。"}, {"text": "嗓门", "is_correct": false, "explanation": "语域：“嗓门”为口语，与这段书面表述的语域不合，且不指表示状态的事物。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“成熟”用于果实或事物的发展阶段，工资不能说成熟。"}], "explanations": {"表征": "表征：指事物显露出的特征或迹象，此处指这种颜色显示出果子已经成熟。", "价格": "语义：价格指买卖中的货币数额，与颜色和果子成熟无关。", "嗓门": "语域：“嗓门”为口语，与这段书面表述的语域不合，且不指表示状态的事物。", "工资": "搭配：“成熟”用于果实或事物的发展阶段，工资不能说成熟。"}, "sentence_index": 6, "correct_answer": "表征"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试的表征很好。", "explanation": "这里应该用〈成绩〉。表征指显露出的特征或迹象，考试的分数与结果要用成绩。"}, {"text": "我在国外有很多有意思的表征。", "explanation": "这里应该用〈经历〉。表征指事物显露出的特征或迹象，不指亲身遭遇的事情；“有很多有意思的经历”要用经历。"}, {"text": "他听完消息后的表征很平静。", "explanation": "这里应该用〈神情〉。表征不指人脸上或心里的神态；“神情很平静”要用神情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10743, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片黄色是叶子老化的表征着。", "corrected_sentence": "这片黄色是叶子老化的表征。", "error_description": "“表征”是名词，后面不能加动态助词“着”；去掉“着”，说“叶子老化的表征”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10743, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋顶漏水，是房子老化的一只表征。", "corrected_sentence": "屋顶漏水，是房子老化的一种表征。", "error_description": "“表征”前的量词用错。“只”多用于动物或个体物件，不搭配这类抽象事物；应说“一种表征”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
