INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使事物按照一定条理和顺序组成有机整体。", "primary_collocate": null, "pronunciation": "xì tǒng huà", "ipa": "ɕi˥˩ tʰʊŋ˨˩˦ xu̯a˥˩", "syllable_count": 3, "sentences": [{"text": "此一系统通过线与间的明确对应关系实现了音高的空间化表征，为音乐理论的系统化提供了必要条件。", "target_word": "系统化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师帮我们把知识系统化。", "target_word": "系统化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把这些笔记系统化。", "target_word": "系统化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些零散的想法需要系统化。", "target_word": "系统化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司正在让管理工作系统化。", "target_word": "系统化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "系统化的复习比临时背书更有效。", "target_word": "系统化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旧资料整理并系统化了。", "target_word": "系统化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套课本让汉字学习更加系统化。", "target_word": "系统化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要让数据管理系统化。", "target_word": "系统化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经验只有系统化以后才容易教给别人。", "target_word": "系统化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "系统化了", "label": "体标"}, {"form": "系统化过", "label": "体标"}, {"form": "系統化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把零散内容整理成有条理的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b63a2c7-7b4b-4b6e-a491-5467c19626e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "系统化", "is_correct": true, "explanation": "正确：“音乐理论的系统化”指使理论有条理，与“提供了必要条件”的语境相符。"}, {"text": "美化", "is_correct": false, "explanation": "语义：“美化”指使事物更美观，与“为理论提供必要条件”的意思不相关。"}, {"text": "绿化", "is_correct": false, "explanation": "语义：“绿化”指种植花草树木，与音乐理论无关。"}, {"text": "老化", "is_correct": false, "explanation": "搭配：“老化”多用于物体或机体的衰退，不说“理论的老化”。"}], "explanations": {"系统化": "正确：“音乐理论的系统化”指使理论有条理，与“提供了必要条件”的语境相符。", "美化": "语义：“美化”指使事物更美观，与“为理论提供必要条件”的意思不相关。", "绿化": "语义：“绿化”指种植花草树木，与音乐理论无关。", "老化": "搭配：“老化”多用于物体或机体的衰退，不说“理论的老化”。"}, "sentence_index": 0, "correct_answer": "系统化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他系统化了一次晚会。", "explanation": "这里应该用〈组织〉。系统化用于知识、理论、资料等内容，不用于活动或事件。"}, {"text": "他把木头系统化成小块。", "explanation": "这里应该用〈切〉。系统化指使内容有条理地组成整体，不能用于把实物切开；“切成小块”要用〈切〉。"}, {"text": "他把那条小河系统化了。", "explanation": "这里应该用〈治理〉。系统化用于知识、资料等内容，不用于河流等自然事物；治理河道要用〈治理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "系统化", "is_correct": true, "explanation": "正确：“整理并系统化了”指把旧资料整理得有条理，与句意相符。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”是降温保存，与“整理”旧资料的意思不符。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：“嚼”是用牙咀嚼，资料不能嚼，与整理的意思无关。"}, {"text": "绣", "is_correct": false, "explanation": "搭配：“绣”用于布料或图案，不说“整理并绣了资料”。"}], "explanations": {"系统化": "正确：“整理并系统化了”指把旧资料整理得有条理，与句意相符。", "冷冻": "语义：“冷冻”是降温保存，与“整理”旧资料的意思不符。", "嚼": "语义：“嚼”是用牙咀嚼，资料不能嚼，与整理的意思无关。", "绣": "搭配：“绣”用于布料或图案，不说“整理并绣了资料”。"}, "sentence_index": 6, "correct_answer": "系统化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把客厅系统化了一遍。", "explanation": "这里应该用〈打扫〉。系统化用于零散的内容，不用于清洁房间。"}, {"text": "妈妈系统化了我的头发。", "explanation": "这里应该用〈梳〉。系统化用于知识、资料等内容，不能用于头发等身体部位；梳头要用〈梳〉。"}, {"text": "这个孩子系统化了一万米。", "explanation": "这里应该用〈跑〉。系统化用于知识、计划等内容，不能用来计量距离；“跑了一万米”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这些数据很系统化了。", "corrected_sentence": "我们把这些数据系统化了。", "error_description": "“系统化”在这里是动词，“把这些数据系统化了”表示完成的动作，不能用程度副词“很”修饰。应去掉“很”，说“我们把这些数据系统化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很快就把这套笔记把系统化了。", "corrected_sentence": "他很快就把这套笔记系统化了。", "error_description": "“把”字句只需一个“把”，“把”后的宾语“这套笔记”之后直接接“系统化”。原句多加了一个“把”，正确说法是“他很快就把这套笔记系统化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
