INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10746, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某一事物成立或发生所必须具备的前提条件，不可或缺。", "primary_collocate": null, "pronunciation": "bì yào tiáo jiàn", "ipa": "pi˥˩ jaʊ˥˩ tʰjaʊ˧˥ tɕjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "此一系统通过线与间的明确对应关系实现了音高的空间化表征，为音乐理论的系统化提供了必要条件。", "target_word": "必要条件", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "健康是幸福生活的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "努力是成功的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气是生命存在的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和阳光是植物生长的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信任是合作的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良好的睡眠是学习的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和平是国家发展的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，练习是学好语言的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氧气是火燃烧的必要条件。", "target_word": "必要条件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "充分必要条件", "label": "复合"}, {"form": "必要條件", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物成立或发生必须具备的前提", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b63a2c7-7b4b-4b6e-a491-5467c19626e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必要条件", "is_correct": true, "explanation": "正确：“必要条件”指成立所不可缺少的前提，与“为理论的系统化提供了”相符。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化外表，与为理论提供前提的意思不符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是买卖的价值，与理论的系统化无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“提供颜色”不成立，且与理论的系统化无关。"}], "explanations": {"必要条件": "正确：“必要条件”指成立所不可缺少的前提，与“为理论的系统化提供了”相符。", "装饰": "语义：“装饰”指美化外表，与为理论提供前提的意思不符。", "价格": "语义：“价格”是买卖的价值，与理论的系统化无关。", "颜色": "搭配：“提供颜色”不成立，且与理论的系统化无关。"}, "sentence_index": 0, "correct_answer": "必要条件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的必要条件很辣。", "explanation": "这里应该用〈味道〉。必要条件指事物成立不可缺少的前提，不用来形容菜的辣度；说菜的味道要用“味道”。"}, {"text": "这种药的必要条件是止痛。", "explanation": "这里应该用〈作用〉。必要条件指事物成立不可缺少的前提，不用来说药物的功效。"}, {"text": "他的必要条件很幽默。", "explanation": "这里应该用〈性格〉。必要条件指事物成立不可缺少的前提，不能用来形容人的品性；形容人的品性要说“性格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必要条件", "is_correct": true, "explanation": "正确：“良好的睡眠是学习的必要条件”指学习成立的前提，句意相符。"}, {"text": "娱乐", "is_correct": false, "explanation": "语义：“娱乐”指让人高兴的活动，与学习的前提关系不符。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：“宠物”是饲养的动物，睡眠不能是宠物，与句意无关。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“学习的温度”不成立，“温度”不用于说学习。"}], "explanations": {"必要条件": "正确：“良好的睡眠是学习的必要条件”指学习成立的前提，句意相符。", "娱乐": "语义：“娱乐”指让人高兴的活动，与学习的前提关系不符。", "宠物": "语义：“宠物”是饲养的动物，睡眠不能是宠物，与句意无关。", "温度": "搭配：“学习的温度”不成立，“温度”不用于说学习。"}, "sentence_index": 6, "correct_answer": "必要条件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的必要条件很鲜艳。", "explanation": "这里应该用〈颜色〉。必要条件指事物成立不可缺少的前提，不用来描述事物的外观。"}, {"text": "这本书的必要条件很有趣。", "explanation": "这里应该用〈内容〉。必要条件指事物成立不可缺少的前提，不用来形容书有没有趣；说书的内容要用“内容”。"}, {"text": "他找了一个必要条件来解释迟到。", "explanation": "这里应该用〈借口〉。必要条件是事物成立的前提，不是用来推托的理由。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水分是植物生长的很必要条件。", "corrected_sentence": "水分是植物生长的必要条件。", "error_description": "“很”不能修饰名词“必要条件”；“必要”是这个名词的一部分，前面不能加“很”。正确说法是“植物生长的必要条件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是考试成功的一张必要条件。", "corrected_sentence": "这是考试成功的一个必要条件。", "error_description": "量词错误：“张”用于纸、桌子等平面的东西，不能用于“条件”。“必要条件”应该用“个”或“条”，正确说法是“这是考试成功的一个必要条件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
