INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10748, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "牢固地建立或制定，使事物稳定、明确地存在。", "primary_collocate": null, "pronunciation": "què lì", "ipa": "tɕʰɥe˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "至文艺复兴时期，五线谱逐渐确立为标准，配合小节线、调号与拍号的引入，记谱法日趋精密。", "target_word": "确立", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他很早就确立了自己的目标。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司确立了新的规矩。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要确立学习的方向。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在比赛中确立了领先的位置。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议确立了明年的发展方向。", "target_word": "确立", "complexity_tier": "T3", "furigana": "zhè cì huìyì quèlì le míngnián de fāzhǎn fāngxiàng.", "sentence_source": "generated"}, {"text": "中国确立了新的教育制度。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人应该尽早确立人生目标。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国确立了友好的关系。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我确立了论文的主题。", "target_word": "确立", "complexity_tier": "T3", "furigana": "lǎoshī bāng wǒ quèlì le lùnwén de zhǔtí.", "sentence_source": "generated"}], "morphological_forms": [{"form": "确立了", "label": "体标（了）"}, {"form": "确立过", "label": "体标（过）"}, {"form": "確立", "label": "繁体"}], "register": "书面", "sense_fingerprint": "牢固地建立或制定，使其稳定明确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b63a2c7-7b4b-4b6e-a491-5467c19626e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "确立", "is_correct": true, "explanation": "正确。“确立”指牢固地建立，与“逐渐……为标准”相合。"}, {"text": "摇晃", "is_correct": false, "explanation": "语义：“摇晃”指来回晃动，与“成为标准”不相合，句子读不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：“拒绝”需要带宾语，“拒绝为标准”不能成立。"}, {"text": "搞定", "is_correct": false, "explanation": "语域：“搞定”是口语，与这段书面语体不协调，且“搞定为标准”不通。"}], "explanations": {"确立": "正确。“确立”指牢固地建立，与“逐渐……为标准”相合。", "摇晃": "语义：“摇晃”指来回晃动，与“成为标准”不相合，句子读不通。", "拒绝": "配价：“拒绝”需要带宾语，“拒绝为标准”不能成立。", "搞定": "语域：“搞定”是口语，与这段书面语体不协调，且“搞定为标准”不通。"}, "sentence_index": 0, "correct_answer": "确立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们已经确立了下午的开会时间。", "explanation": "这里应该用〈确定〉。“确立”用于制度、目标、地位等，具体的时间应用“确定”。"}, {"text": "学校确立了一座新的图书馆。", "explanation": "这里应该用〈建立〉。“确立”指使抽象事物固定下来，建造建筑、设立机构应用“建立”。"}, {"text": "我已经确立了收件人的地址。", "explanation": "这里应该用〈确认〉。“确认”指核实后认定，核实具体信息应用“确认”，不能用“确立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "确立", "is_correct": true, "explanation": "正确。“确立”指使制度牢固地建立起来，与“中国……新的教育制度”相合。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”针对食物，不能用于“教育制度”，句子读不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应为食物，不能说吃制度。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“制度”作宾语。"}], "explanations": {"确立": "正确。“确立”指使制度牢固地建立起来，与“中国……新的教育制度”相合。", "咀嚼": "语义：“咀嚼”针对食物，不能用于“教育制度”，句子读不通。", "吃": "搭配：“吃”的宾语应为食物，不能说吃制度。", "游泳": "配价：“游泳”是不及物动词，不能带“制度”作宾语。"}, "sentence_index": 6, "correct_answer": "确立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们确立了明天去北京旅游。", "explanation": "这里应该用〈决定〉。“确立”用于制度、目标、地位，安排具体行动应用“决定”。"}, {"text": "他确立了桌上的钥匙。", "explanation": "这里应该用〈发现〉。“确立”指使抽象事物固定下来，找到具体的东西应用“发现”。"}, {"text": "他确立了老师的批评。", "explanation": "这里应该用〈接受〉。“确立”不用于对他人意见的认可，接受批评应用“接受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把以学生为本的办学宗旨确立。", "corrected_sentence": "学校把以学生为本的办学宗旨确立下来了。", "error_description": "错误：“把”字句缺少补语。应为“确立下来了”。“把……确立”后面要带补语或“了”等成分，句末不能只留动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "双方很快确立着合作的关系。", "corrected_sentence": "双方很快确立了合作的关系。", "error_description": "错误：“很快”指短时间内完成的动作，与表示持续状态的“着”相矛盾。应为“确立了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10750, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大节", "is_correct": true, "explanation": "“大节”指关乎原则的大事，与“小节”相对。"}, {"text": "环境", "is_correct": false, "explanation": "“环境”指周围的情况和条件，与“小节”不构成反义关系。"}, {"text": "方针", "is_correct": false, "explanation": "“方针”指指导工作的大方向，与“小节”不构成反义关系。"}, {"text": "习惯", "is_correct": false, "explanation": "“习惯”指长期形成的行为模式，与“小节”不构成反义关系。"}], "correct_answer": "大节", "explanations": {"大节": "“大节”指关乎原则的大事，与“小节”相对。", "环境": "“环境”指周围的情况和条件，与“小节”不构成反义关系。", "方针": "“方针”指指导工作的大方向，与“小节”不构成反义关系。", "习惯": "“习惯”指长期形成的行为模式，与“小节”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10750, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大节", "is_correct": true, "explanation": "“大节”指关乎原则的大事，与“小节”相对。"}, {"text": "信念", "is_correct": false, "explanation": "“信念”指坚定的信仰或想法，与“小节”不构成反义关系。"}, {"text": "风度", "is_correct": false, "explanation": "“风度”指举止和气质，与“小节”不构成反义关系。"}, {"text": "品德", "is_correct": false, "explanation": "“品德”指个人的道德品质，与“小节”不构成反义关系。"}], "correct_answer": "大节", "explanations": {"大节": "“大节”指关乎原则的大事，与“小节”相对。", "信念": "“信念”指坚定的信仰或想法，与“小节”不构成反义关系。", "风度": "“风度”指举止和气质，与“小节”不构成反义关系。", "品德": "“品德”指个人的道德品质，与“小节”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指细小的、非原则性的行为或事情，常与‘大节’相对。", "primary_collocate": null, "pronunciation": "xiǎo jié", "ipa": "ɕjɑʊ̯˨˩ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "他常在小节上让步，但对原则从不退让。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不拘小节，常常忘记整理房间。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大事要认真，小节可以不计较。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做大事的人，不会在小节上花太多时间。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间不必计较小节。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，大节要守住，小节可以放松。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大节很好，只是小节上有些马虎。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不在乎这些小节，只看你做人怎么样。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了一点小节，你们就吵架，不值得。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们：做人要守住原则，也要注意小节。", "target_word": "小节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小節", "label": "繁体"}], "register": "书面", "sense_fingerprint": "细小而不关原则的行为或事情，与大节相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c71fde6-0539-4dbc-ab5a-4c8d08a9070a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10750, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小节", "is_correct": true, "explanation": "正确答案：小节（xiǎo jié），指细小的、非原则性的行为或事情。"}, {"text": "小姐", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，“小姐”指年轻女子，意思不同。"}, {"text": "小鞋", "is_correct": false, "explanation": "xié 与 jié 声母不同（x 与 j），“小鞋”指（穿）小鞋，意思不同。"}, {"text": "小街", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，“小街”指小的街道。"}], "explanations": {"小节": "正确答案：小节（xiǎo jié），指细小的、非原则性的行为或事情。", "小姐": "jiě（第三声）与 jié（第二声）声调不同，“小姐”指年轻女子，意思不同。", "小鞋": "xié 与 jié 声母不同（x 与 j），“小鞋”指（穿）小鞋，意思不同。", "小街": "jiē（第一声）与 jié（第二声）声调不同，“小街”指小的街道。"}, "sentence_index": null, "correct_answer": "小节"}, "level_3": {"options": [{"text": "小节", "is_correct": true, "explanation": "正确：“在小节上让步”指在细枝末节上不较真，与后句“对原则从不退让”形成对比。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以让步的事情，与句意不符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是具体物品，不能在它上面让步。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“在……上让步”要接抽象事项，不接“桌子”。"}], "explanations": {"小节": "正确：“在小节上让步”指在细枝末节上不较真，与后句“对原则从不退让”形成对比。", "天气": "语义：“天气”不是可以让步的事情，与句意不符。", "书包": "语义：“书包”是具体物品，不能在它上面让步。", "桌子": "搭配：“在……上让步”要接抽象事项，不接“桌子”。"}, "sentence_index": 0, "correct_answer": "小节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张画的小节很精致。", "explanation": "这里应该用〈细节〉。小节指不关原则的行为或事情，不指画面上具体的局部；局部的精致要说“细节”。"}, {"text": "会议结束前，主持人做了一个小节。", "explanation": "这里应该用〈小结〉。“小结”指对会议内容的简短总结；“小节”指不关原则的小事，不能用来说做一个总结。"}, {"text": "我们一家人一起过小节。", "explanation": "这里应该用〈节日〉。“过”搭配节日，“小节”指不关原则的小事，不指节日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小节", "is_correct": true, "explanation": "正确：“小节上有些马虎”指细节上不够认真，与前句“大节很好”形成对比。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“马虎”说做事或细节，不说“脾气上马虎”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“马虎”，句中说的是人的做事态度。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”是外形特征，不能用“马虎”来形容。"}], "explanations": {"小节": "正确：“小节上有些马虎”指细节上不够认真，与前句“大节很好”形成对比。", "脾气": "搭配：“马虎”说做事或细节，不说“脾气上马虎”。", "天气": "语义：天气不能被“马虎”，句中说的是人的做事态度。", "身材": "体貌：“身材”是外形特征，不能用“马虎”来形容。"}, "sentence_index": 6, "correct_answer": "小节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次犯了小节，我们原谅了他。", "explanation": "这里应该用〈小错误〉。“犯”搭配“错误”，小节指不关原则的行为或事情，不能说“犯小节”。"}, {"text": "这块玉有一点小节，影响了价值。", "explanation": "这里应该用〈瑕疵〉。小节指人的行为或事情，不指物品上的缺陷。"}, {"text": "他在比赛中出现了一次小节。", "explanation": "这里应该用〈失误〉。小节不指比赛中做错的事，失误才指这类错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了一张小节，他们吵了半天。", "corrected_sentence": "为了一点小节，他们吵了半天。", "error_description": "量词错误：“小节”指不关原则的小事，是抽象名词，不能用“张”这种表示平面物品的量词；应该说“一点小节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们不必为小节们争执，要抓住大事。", "corrected_sentence": "我们不必为小节争执，要抓住大事。", "error_description": "词缀错误：“小节”是抽象的事情，不能加表示人的复数词尾“们”。正确说法是“为小节争执”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
