INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10751, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "调号是乐谱开头标明乐曲调性的升降号记号。", "primary_collocate": null, "pronunciation": "diào hào", "ipa": "tjɑʊ̯˥˩ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "至文艺复兴时期，五线谱逐渐确立为标准，配合小节线、调号与拍号的引入，记谱法日趋精密。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "乐谱开头有两个升号，这是调号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看谱时，先看调号，再看拍号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的调号是一个降号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么认五线谱上的调号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了看调号，所以弹错了几个音。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调号写在谱子的最前面。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有调号的曲子，常常是C大调。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "转调的时候，谱上会换一个新的调号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学钢琴要先学会读调号。", "target_word": "调号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "調號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "乐谱开头标明调性的升降号记号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c71fde6-0539-4dbc-ab5a-4c8d08a9070a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10751, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调号", "is_correct": true, "explanation": "正确答案：调号（diào hào），乐谱开头标明调性的升降号记号。"}, {"text": "调好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，“调好”意为调整好，不是调号。"}, {"text": "跳号", "is_correct": false, "explanation": "d 与 t 声母不同，“跳号”指跳过编号，意思不同。"}, {"text": "叫号", "is_correct": false, "explanation": "d 与 j 声母不同，“叫号”指按号码叫人，意思不同。"}], "explanations": {"调号": "正确答案：调号（diào hào），乐谱开头标明调性的升降号记号。", "调好": "hǎo（第三声）与 hào（第四声）声调不同，“调好”意为调整好，不是调号。", "跳号": "d 与 t 声母不同，“跳号”指跳过编号，意思不同。", "叫号": "d 与 j 声母不同，“叫号”指按号码叫人，意思不同。"}, "sentence_index": null, "correct_answer": "调号"}, "level_3": {"options": [{"text": "调号", "is_correct": true, "explanation": "正确：“调号”标明调性，与小节线、拍号同属记谱符号。"}, {"text": "号码", "is_correct": false, "explanation": "语义：“号码”不是乐谱记号，与记谱语境不符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”不属于乐谱记号，与五线谱无关。"}, {"text": "俗语", "is_correct": false, "explanation": "语义：“俗语”是流传已久的固定说法，不是记谱符号，与小节线、拍号并列不通。"}], "explanations": {"调号": "正确：“调号”标明调性，与小节线、拍号同属记谱符号。", "号码": "语义：“号码”不是乐谱记号，与记谱语境不符。", "温度": "语义：“温度”不属于乐谱记号，与五线谱无关。", "俗语": "语义：“俗语”是流传已久的固定说法，不是记谱符号，与小节线、拍号并列不通。"}, "sentence_index": 0, "correct_answer": "调号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的调号是四四拍。", "explanation": "这里应该用〈拍号〉。调号标明调性的升降，四四拍是拍号，记录每小节的拍数。"}, {"text": "谱子开头画了一个高音调号。", "explanation": "这里应该用〈谱号〉。高音谱号标明音高位置，调号标明调性，二者不能互换。"}, {"text": "这首歌的调号很悦耳。", "explanation": "这里应该用〈调子〉。调号是乐谱开头标明调性的记号，不能用来形容曲子好听；说“悦耳”要用调子、旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调号", "is_correct": true, "explanation": "正确：“调号”写在谱子开头，标明调性。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”不能写在乐谱上，与句中语境无关。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不属于乐谱内容，不会写在谱子最前面。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形特征，不能写在谱子上。"}], "explanations": {"调号": "正确：“调号”写在谱子开头，标明调性。", "饭菜": "语义：“饭菜”不能写在乐谱上，与句中语境无关。", "天气": "语义：“天气”不属于乐谱内容，不会写在谱子最前面。", "身高": "体貌：“身高”是人的外形特征，不能写在谱子上。"}, "sentence_index": 6, "correct_answer": "调号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学钢琴要先学会弹调号。", "explanation": "这里应该用〈音阶〉。“弹”搭配音阶、曲子，调号是乐谱记号，不能被“弹”。"}, {"text": "学钢琴要先学会按调号。", "explanation": "这里应该用〈和弦〉。“按”搭配和弦、琴键，调号不能被“按”。"}, {"text": "学钢琴要先学会打调号。", "explanation": "这里应该用〈节奏〉。“打”搭配节奏、拍子，调号不能被“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弹琴前，要先看懂一条调号。", "corrected_sentence": "弹琴前，要先看懂调号。", "error_description": "量词错误：“调号”前不能加量词“条”（“条”多用于长条状的东西）。正确说法是“看懂调号”，不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两首曲子的调号们不一样。", "corrected_sentence": "这两首曲子的调号不一样。", "error_description": "词缀错误：“调号”是乐谱记号，不能加表示人的复数词尾“们”。正确说法是“调号不一样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87783e0e-3f38-415b-9b92-0235739128ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
