INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "音乐术语，用来表示每小节包含多少拍以及以什么音符为一拍的记号。", "primary_collocate": null, "pronunciation": "pāi hào", "ipa": "pʰai̯˥ xau̯˥˩", "syllable_count": 2, "sentences": [{"text": "至文艺复兴时期，五线谱逐渐确立为标准，配合小节线、调号与拍号的引入，记谱法日趋精密。", "target_word": "拍号", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首歌的拍号是四四拍。", "target_word": "拍号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先看谱子开头的拍号。", "target_word": "拍号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三四拍的拍号怎么写？", "target_word": "拍号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个拍号。", "target_word": "拍号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首圆舞曲的拍号表示每小节有三拍。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍号一改变，节奏感就不一样了。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没看清楚拍号，所以拍子打错了。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学钢琴要先认识谱号和拍号。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴谱的开头有谱号、调号和拍号。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "拍號", "label": "繁体"}], "register": "专业", "sense_fingerprint": "音乐术语：标明每小节拍数与以何种音符为一拍的记号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ea6cd0-2927-4045-bed6-9cd5a0064201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拍号", "is_correct": true, "explanation": "正确：拍号，表示每小节拍数的音乐记号。"}, {"text": "排号", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，意思是排号（排队取号），与乐谱无关。"}, {"text": "牌号", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，意思是牌号（产品或车辆的编号）。"}, {"text": "拍好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是拍好（拍得好、拍完成）。"}], "explanations": {"拍号": "正确：拍号，表示每小节拍数的音乐记号。", "排号": "pái（第二声）与 pāi（第一声）声调不同，意思是排号（排队取号），与乐谱无关。", "牌号": "pái（第二声）与 pāi（第一声）声调不同，意思是牌号（产品或车辆的编号）。", "拍好": "hǎo（第三声）与 hào（第四声）声调不同，意思是拍好（拍得好、拍完成）。"}, "sentence_index": null, "correct_answer": "拍号"}, "level_3": {"options": [{"text": "拍号", "is_correct": true, "explanation": "正确：拍号与小节线、调号并列，是记谱法的记号，符合句意。"}, {"text": "乐队", "is_correct": false, "explanation": "语义：乐队是演奏的群体，不是记谱符号，不能与小节线、调号并列引入记谱法。"}, {"text": "舞步", "is_correct": false, "explanation": "语义：舞步是舞蹈动作，与记谱法的记号无关。"}, {"text": "琴弦", "is_correct": false, "explanation": "语义：琴弦是乐器的部件，不是记谱符号，不能与小节线、调号并列引入记谱法。"}], "explanations": {"拍号": "正确：拍号与小节线、调号并列，是记谱法的记号，符合句意。", "乐队": "语义：乐队是演奏的群体，不是记谱符号，不能与小节线、调号并列引入记谱法。", "舞步": "语义：舞步是舞蹈动作，与记谱法的记号无关。", "琴弦": "语义：琴弦是乐器的部件，不是记谱符号，不能与小节线、调号并列引入记谱法。"}, "sentence_index": 0, "correct_answer": "拍号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跟着拍号打手掌。", "explanation": "这里应该用〈节拍〉。拍号是乐谱上的记号，表示每小节的拍数，不是实际敲出的节奏点，不能跟着它打拍子。"}, {"text": "这首曲子里有一只拍号。", "explanation": "这里应该用〈个〉。拍号的量词是“个”；“只”用于动物或成对物品中的一件，不能修饰拍号。"}, {"text": "这首曲子的拍号是C大调。", "explanation": "这里应该用〈调号〉。调号标明曲子的调性（如C大调），拍号标明每小节的拍数，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拍号", "is_correct": true, "explanation": "正确：拍号一改变，节奏感随之改变，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色的改变不会影响节奏感，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与曲子的节奏感无关，不能这样说。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“节奏感”与“尺寸”不搭配，尺寸改变不会谈到节奏感。"}], "explanations": {"拍号": "正确：拍号一改变，节奏感随之改变，符合句意。", "颜色": "语义：颜色的改变不会影响节奏感，句意不通。", "价格": "语义：价格与曲子的节奏感无关，不能这样说。", "尺寸": "搭配：“节奏感”与“尺寸”不搭配，尺寸改变不会谈到节奏感。"}, "sentence_index": 6, "correct_answer": "拍号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的拍号很快。", "explanation": "这里应该用〈节奏〉。拍号是记号，只标明每小节的拍数，不能说快慢；形容快慢要用“节奏”或“速度”。"}, {"text": "这段音乐的拍号很大。", "explanation": "这里应该用〈音量〉。拍号不表示声音的大小，不能说“很大”。"}, {"text": "这段拍号很优美。", "explanation": "这里应该用〈旋律〉。拍号是记谱的记号，不能用“优美”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在谱子上看到了一张拍号。", "corrected_sentence": "我在谱子上看到了一个拍号。", "error_description": "量词错误：“拍号”应用量词“个”，说“一张拍号”是错误的。“张”多用于纸张、桌子等成片的物件，拍号是一个记号，应说“一个拍号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "曲子中间标了两个的拍号。", "corrected_sentence": "曲子中间标了两个拍号。", "error_description": "多余的“的”：数量短语“两个”直接修饰名词时不加“的”，应说“两个拍号”，不能说“两个的拍号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
