INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10754, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事物随着时间的推移而逐渐发展或变化。", "primary_collocate": null, "pronunciation": "rì qū", "ipa": "ʐɨ˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "至文艺复兴时期，五线谱逐渐确立为标准，配合小节线、调号与拍号的引入，记谱法日趋精密。", "target_word": "日趋", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座城市的交通问题日趋严重。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过几年的学习，他的想法日趋成熟。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上购物的竞争日趋激烈。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷，市场上的水果日趋减少。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过几年努力，公司的制度日趋完善。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国之间的关系日趋紧张。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环境问题已经日趋明显。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，他的病情日趋稳定。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代社会的生活节奏日趋加快。", "target_word": "日趋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日趨", "label": "繁体"}], "register": "书面", "sense_fingerprint": "副词：随时间推移逐渐朝某方向变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ea6cd0-2927-4045-bed6-9cd5a0064201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日趋", "is_correct": true, "explanation": "正确：“日趋”表示逐渐发展，与“逐渐确立”呼应，符合句意。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指突然发生，与句中逐渐发展的过程不符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示一下子发生，与“逐渐确立”的渐进过程相矛盾。"}, {"text": "随即", "is_correct": false, "explanation": "搭配：“随即”多接动作，不接“精密”这类状态形容词。"}], "explanations": {"日趋": "正确：“日趋”表示逐渐发展，与“逐渐确立”呼应，符合句意。", "忽然": "语义：“忽然”指突然发生，与句中逐渐发展的过程不符。", "突然": "语义：“突然”表示一下子发生，与“逐渐确立”的渐进过程相矛盾。", "随即": "搭配：“随即”多接动作，不接“精密”这类状态形容词。"}, "sentence_index": 0, "correct_answer": "日趋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他日趋摔倒了。", "explanation": "这里应该用〈忽然〉。日趋表示逐渐发展，摔倒是一瞬间发生的事，不能用日趋。"}, {"text": "他日趋喊了一声。", "explanation": "这里应该用〈突然〉。“喊了一声”是一瞬间完成的动作，日趋表示逐渐变化，不能用于此。"}, {"text": "他接到电话，日趋出发了。", "explanation": "这里应该用〈马上〉。出发是一次性的动作，日趋只用于逐渐变化的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日趋", "is_correct": true, "explanation": "正确：“日趋”表示逐渐发展，符合句意。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”需接一个行为选择，不能修饰“紧张”这类状态。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”修饰行动，不能修饰“紧张”这类状态，句意不通。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”修饰人的行为，不能修饰“关系紧张”这类状态，句意不通。"}], "explanations": {"日趋": "正确：“日趋”表示逐渐发展，符合句意。", "只好": "搭配：“只好”需接一个行为选择，不能修饰“紧张”这类状态。", "赶紧": "搭配：“赶紧”修饰行动，不能修饰“紧张”这类状态，句意不通。", "亲自": "搭配：“亲自”修饰人的行为，不能修饰“关系紧张”这类状态，句意不通。"}, "sentence_index": 6, "correct_answer": "日趋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的名字日趋是北京。", "explanation": "这里应该用〈一直〉。日趋表示逐渐变化，城市的名字不会改变，表示始终不变应用“一直”。"}, {"text": "他日趋会来开会。", "explanation": "这里应该用〈有时〉。“有时”指不定期发生，与日趋的持续变化不能互换。"}, {"text": "我们日趋住在朋友家。", "explanation": "这里应该用〈暂时〉。暂时指时间较短，日趋指长时间的逐渐变化，不能替换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的交通日趋很便利。", "corrected_sentence": "这座城市的交通日趋便利。", "error_description": "程度副词错误：“日趋”本身已表示逐渐变化，后面不能再接程度副词“很”，应说“日趋便利”，不能说“日趋很便利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近年来，人们的生活节奏日趋的加快。", "corrected_sentence": "近年来，人们的生活节奏日趋加快。", "error_description": "多余的“的”：“日趋”后直接接动词或形容词，不加“的”，应说“日趋加快”，不能说“日趋的加快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
