INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10757, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用某种工具或方法来做某事", "primary_collocate": null, "pronunciation": "shǐ", "ipa": "ʂɨ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个老木匠手艺好，各种老工具他都会使，干起活来又快又准。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会使筷子吗？", "target_word": "使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个工人很会使电钻，干活又快又好。", "target_word": "使", "complexity_tier": "T3", "furigana": "Zhè gè gōngrén hěn huì shǐ diànzuàn, gànhuó yòu kuài yòu hǎo.", "sentence_source": "generated"}, {"text": "这把剪刀太旧，我使不惯。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷以前使过毛笔写信。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会使这台机器，请你教教我。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他使着一把老刀，慢慢削苹果。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木匠使锯子很熟练，一会儿就锯完了。", "target_word": "使", "complexity_tier": "T3", "furigana": "Mùjiang shǐ jùzi hěn shúliàn, yíhuìr jiù jù wán le.", "sentence_source": "generated"}, {"text": "我不太会使这把水果刀。", "target_word": "使", "complexity_tier": "T3", "furigana": "Wǒ bú tài huì shǐ zhè bǎ shuǐguǒ dāo.", "sentence_source": "generated"}, {"text": "修自行车时他很会使扳手，几下就修好了。", "target_word": "使", "complexity_tier": "T3", "furigana": "Xiū zìxíngchē shí tā hěn huì shǐ bānshou, jǐ xià jiù xiū hǎo le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "使了", "label": "体标"}, {"form": "使过", "label": "体标"}, {"form": "使着", "label": "体标"}, {"form": "使用", "label": "复合"}], "register": "口语", "sense_fingerprint": "动词：拿某种工具或方法来用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 4 words above tier T1 (max 2): 木匠 (Zipf 3.43), 锯 (Zipf 3.52), 熟练 (Zipf 3.98), 锯 (Zipf 3.52)','sentence 9 above tier T1: 3 words above tier T1 (max 2): 扳 (Zipf 3.22), 几下 (Zipf 3.53), 修好 (Zipf 3.47)']::text[], '01ea6cd0-2927-4045-bed6-9cd5a0064201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10757, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "使", "is_correct": true, "explanation": "正确答案：使（shǐ）是动词，意思是用某种工具或方法来做事"}, {"text": "施", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，意思是施行、施加"}, {"text": "时", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是时间"}, {"text": "是", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是是、对"}], "explanations": {"使": "正确答案：使（shǐ）是动词，意思是用某种工具或方法来做事", "施": "shī（第一声）与 shǐ（第三声）声调不同，意思是施行、施加", "时": "shí（第二声）与 shǐ（第三声）声调不同，意思是时间", "是": "shì（第四声）与 shǐ（第三声）声调不同，意思是是、对"}, "sentence_index": null, "correct_answer": "使"}, "level_3": {"options": [{"text": "使", "is_correct": true, "explanation": "正确：“会使”即会用某种工具，与“都会”呼应，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“都会”后表示会用工具的意思不符，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象不能是工具，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象不能是工具，句意不通。"}], "explanations": {"使": "正确：“会使”即会用某种工具，与“都会”呼应，符合句意。", "扔": "语义：“扔”是丢弃，与“都会”后表示会用工具的意思不符，句意不通。", "吃": "语义：“吃”的对象不能是工具，句意不通。", "唱": "语义：“唱”的对象不能是工具，句意不通。"}, "sentence_index": 0, "correct_answer": "使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他使着一碗面条，走进了厨房。", "explanation": "这里应该用〈端〉。端碗要说“端”，“使”只用于工具或方法，不用于这类托着东西的动作"}, {"text": "他使着眼镜看书，看得很清楚。", "explanation": "这里应该用〈戴〉。“使”用于工具或方法，眼镜是戴在脸上的，不能说“使眼镜”"}, {"text": "他使着一件红衣服，站在门口。", "explanation": "这里应该用〈穿〉。衣服要说“穿”，不能说“使”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10757, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "使", "is_correct": true, "explanation": "正确答案：使（shǐ）是动词，意思是用某种工具或方法来做事"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是十"}, {"text": "诗", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，意思是诗"}, {"text": "世", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是世界、世代"}, {"text": "市", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是市场、城市。"}], "explanations": {"使": "正确答案：使（shǐ）是动词，意思是用某种工具或方法来做事", "十": "shí（第二声）与 shǐ（第三声）声调不同，意思是十", "诗": "shī（第一声）与 shǐ（第三声）声调不同，意思是诗", "世": "shì（第四声）与 shǐ（第三声）声调不同，意思是世界、世代", "市": "shì（第四声）与 shǐ（第三声）声调不同，意思是市场、城市。"}, "sentence_index": null, "correct_answer": "使"}, "level_3": {"options": [{"text": "使", "is_correct": true, "explanation": "正确答案。“使着”表示手里拿着并使用一把刀，与后面的“慢慢削苹果”相合"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢掉，与后面的“慢慢削苹果”矛盾"}, {"text": "推", "is_correct": false, "explanation": "搭配：“推”后接能被推动的东西，不能说“推着一把刀”来削苹果"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”表示出售，与后面的“慢慢削苹果”矛盾"}], "explanations": {"使": "正确答案。“使着”表示手里拿着并使用一把刀，与后面的“慢慢削苹果”相合", "扔": "语义：“扔”表示丢掉，与后面的“慢慢削苹果”矛盾", "推": "搭配：“推”后接能被推动的东西，不能说“推着一把刀”来削苹果", "卖": "语义：“卖”表示出售，与后面的“慢慢削苹果”矛盾"}, "sentence_index": 6, "correct_answer": "使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈使着围裙在厨房做饭。", "explanation": "这里应该用〈系〉。围裙是系在身上的，不能说“使围裙”"}, {"text": "孩子使着足球在操场上跑。", "explanation": "这里应该用〈踢〉。足球要用“踢”，“使”不用于踢球这类动作"}, {"text": "他使着一个西瓜回家。", "explanation": "这里应该用〈抱〉。西瓜要说抱着或提着，不能说“使”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我使了过这台机器，很方便。", "corrected_sentence": "我使过这台机器，很方便。", "error_description": "错误：“使了过”，“了”和“过”不能同时用在动词后；正确：“使过”，只用“过”表示有过使用的经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很使刨子，木板刨得很平。", "corrected_sentence": "他很会使刨子，木板刨得很平。", "error_description": "错误：“很使”，漏掉了表示能力的“会”；正确：“很会使”，“使”表示会用某种工具时前面要加“会”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
