INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "复调音乐是指由两个或两个以上独立旋律同时进行、相互配合而成的音乐形式。", "primary_collocate": null, "pronunciation": "fù diào yīn yuè", "ipa": "fu˥˩ tjau̯˥˩ in˥ ɥɛ˥˩", "syllable_count": 4, "sentences": [{"text": "这一技术演进不仅使复调音乐的复杂织体得以准确传达，更深刻影响了作曲家的思维方式。", "target_word": "复调音乐", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "复调音乐有两条旋律同时进行。", "target_word": "复调音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "巴赫擅长写复调音乐，很多作品都是这种形式。", "target_word": "复调音乐", "complexity_tier": "T3", "furigana": "Bā hè shàncháng xiě fùdiào yīnyuè, hěn duō zuòpǐn dōu shì zhè zhǒng xíngshì.", "sentence_source": "generated"}, {"text": "这首复调音乐里，高音和低音各唱各的旋律。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听复调音乐时，我常常想跟着每条旋律走。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们放了一段复调音乐。", "target_word": "复调音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "复调音乐不像单旋律歌曲那么简单。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在音乐课上学过复调音乐。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合唱团正在排练一首复调音乐。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文艺复兴时期，教堂里常唱复调音乐。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复调音乐作品", "label": "复合"}], "register": "专业", "sense_fingerprint": "由多条独立旋律同时进行的音乐形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ea6cd0-2927-4045-bed6-9cd5a0064201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复调音乐", "is_correct": true, "explanation": "正确答案：复调音乐指由几条独立旋律同时进行的音乐，此句中指有“织体”的音乐形式"}, {"text": "单旋律歌曲", "is_correct": false, "explanation": "语义：单旋律只有一条旋律，没有“复杂织体”可以被传达"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“织体”是音乐术语，不能说“天气的复杂织体”"}, {"text": "交通", "is_correct": false, "explanation": "搭配：“织体”是音乐术语，不能说“交通的复杂织体”"}], "explanations": {"复调音乐": "正确答案：复调音乐指由几条独立旋律同时进行的音乐，此句中指有“织体”的音乐形式", "单旋律歌曲": "语义：单旋律只有一条旋律，没有“复杂织体”可以被传达", "天气": "搭配：“织体”是音乐术语，不能说“天气的复杂织体”", "交通": "搭配：“织体”是音乐术语，不能说“交通的复杂织体”"}, "sentence_index": 0, "correct_answer": "复调音乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首复调音乐是两人轮流唱的，你一句我一句。", "explanation": "这里应该用〈对唱〉。两人轮流唱是对唱，复调音乐要求几条独立旋律同时进行，不是轮流"}, {"text": "这首复调音乐是他一个人唱的，声音很好听。", "explanation": "这里应该用〈独唱〉。独唱只有一个人唱，复调音乐要求几条独立旋律同时进行"}, {"text": "这首复调音乐，大家都齐声唱同一条旋律。", "explanation": "这里应该用〈齐唱〉。齐唱是所有人唱同一条旋律，与复调音乐的独立多旋律相反"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复调音乐", "is_correct": true, "explanation": "正确答案：复调音乐由几条独立旋律构成，比单旋律歌曲复杂，句中用于比较"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是音乐，不能拿它与“单旋律歌曲”比较是否简单"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”与“单旋律歌曲”不能作“简单”与否的比较，这种比较句不通"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果与音乐不属于同一类，不能用“不像……那么简单”来比较"}], "explanations": {"复调音乐": "正确答案：复调音乐由几条独立旋律构成，比单旋律歌曲复杂，句中用于比较", "石头": "语义：石头不是音乐，不能拿它与“单旋律歌曲”比较是否简单", "天气": "搭配：“天气”与“单旋律歌曲”不能作“简单”与否的比较，这种比较句不通", "水果": "语义：水果与音乐不属于同一类，不能用“不像……那么简单”来比较"}, "sentence_index": 6, "correct_answer": "复调音乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首复调音乐只用鼓点敲打，没有旋律。", "explanation": "这里应该用〈打击乐〉。只有鼓点、没有旋律的是打击乐，复调音乐要求几条独立旋律"}, {"text": "这首复调音乐只有一条旋律，很好记。", "explanation": "这里应该用〈单旋律歌曲〉。它只有一条旋律，复调音乐由两条以上独立旋律构成"}, {"text": "这首复调音乐里，主旋律很突出，其他声部只是和音陪衬。", "explanation": "这里应该用〈主调音乐〉。主旋律突出、其他声部只做和音陪衬是主调音乐，复调音乐各声部旋律独立"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爸爸每天听一个复调音乐。", "corrected_sentence": "我爸爸每天听一首复调音乐。", "error_description": "错误：“一个复调音乐”；正确：“一首复调音乐”。具体的乐曲用量词“首”，“个”不能用于这里", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位作曲家的作品很复调音乐。", "corrected_sentence": "这位作曲家的作品属于复调音乐。", "error_description": "错误：名词“复调音乐”前不能加程度副词“很”；正确：“属于复调音乐”，用动词短语说明作品的归属。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
