INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10759, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "音乐作品中声部的组合方式，包括旋律、节奏、和声等要素的纵向与横向关系。", "primary_collocate": null, "pronunciation": "zhī tǐ", "ipa": "ʈʂʅ˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这一技术演进不仅使复调音乐的复杂织体得以准确传达，更深刻影响了作曲家的思维方式。", "target_word": "织体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首曲子的织体很简单，只有一条旋律。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴曲的织体常常比独唱更丰富。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作曲家改变了织体，让音乐听起来更厚。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复调织体由几条独立的旋律组成。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上分析了这首曲子的织体。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段伴奏的织体很薄，突出了小提琴。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巴赫的作品织体非常复杂。", "target_word": "织体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "织体不同，同一首旋律的效果也不同。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学会怎样设计合唱的织体。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复调织体", "label": "复合"}, {"form": "音乐织体", "label": "复合"}], "register": "专业", "sense_fingerprint": "音乐中声部与各要素的组合方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ea6cd0-2927-4045-bed6-9cd5a0064201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10759, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "织体", "is_correct": true, "explanation": "正确：织体（zhī tǐ）指音乐中声部的组合方式。"}, {"text": "尸体", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh/zh），声调相同，意思是尸体。"}, {"text": "机体", "is_correct": false, "explanation": "jī 与 zhī 声母不同（j/zh），声调相同，意思是有机的身体。"}, {"text": "知底", "is_correct": false, "explanation": "dǐ 与 tǐ 声母不同（d/t），第一个音节相同，意思是知道底细。"}], "explanations": {"织体": "正确：织体（zhī tǐ）指音乐中声部的组合方式。", "尸体": "shī 与 zhī 声母不同（sh/zh），声调相同，意思是尸体。", "机体": "jī 与 zhī 声母不同（j/zh），声调相同，意思是有机的身体。", "知底": "dǐ 与 tǐ 声母不同（d/t），第一个音节相同，意思是知道底细。"}, "sentence_index": null, "correct_answer": "织体"}, "level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是人或物的高度，不能用“复杂”来形容，也不能被“准确传达”。"}, {"text": "织体", "is_correct": true, "explanation": "正确：〈织体〉指声部的组合，可以是复杂的，也可以被准确传达，符合句意。"}, {"text": "门锁", "is_correct": false, "explanation": "语义：门锁是器物，句子说的是音乐，门锁不能被“传达”。"}, {"text": "调料", "is_correct": false, "explanation": "语义：调料与音乐无关，句子中被传达的应是复调音乐的组合方式。"}], "explanations": {"身高": "搭配：“身高”是人或物的高度，不能用“复杂”来形容，也不能被“准确传达”。", "织体": "正确：〈织体〉指声部的组合，可以是复杂的，也可以被准确传达，符合句意。", "门锁": "语义：门锁是器物，句子说的是音乐，门锁不能被“传达”。", "调料": "语义：调料与音乐无关，句子中被传达的应是复调音乐的组合方式。"}, "sentence_index": 0, "correct_answer": "织体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥的织体很坚固。", "explanation": "这里应该用〈结构〉。织体只指音乐中声部的组合方式，桥梁的构造要用结构。"}, {"text": "这把小提琴的织体很温暖。", "explanation": "这里应该用〈音色〉。织体说的是声部的组合，音的色彩要用音色。"}, {"text": "这首歌的织体很快。", "explanation": "这里应该用〈节奏〉。织体指声部的组合方式，不指拍子的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墙壁", "is_correct": false, "explanation": "语义：伴奏没有墙壁，“墙壁很薄”与句子的音乐语境无关。"}, {"text": "织体", "is_correct": true, "explanation": "正确：〈织体〉可以说“薄”或“厚”，指伴奏中声部的组合很少，符合句意。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”说高低，不说厚薄，“很薄”与“体温”不搭配。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：字迹与伴奏无关，句子中要描述的是音乐的组合方式。"}], "explanations": {"墙壁": "语义：伴奏没有墙壁，“墙壁很薄”与句子的音乐语境无关。", "织体": "正确：〈织体〉可以说“薄”或“厚”，指伴奏中声部的组合很少，符合句意。", "体温": "搭配：“体温”说高低，不说厚薄，“很薄”与“体温”不搭配。", "字迹": "语义：字迹与伴奏无关，句子中要描述的是音乐的组合方式。"}, "sentence_index": 6, "correct_answer": "织体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的织体很柔软。", "explanation": "这里应该用〈质地〉。织体只指音乐中声部的组合方式，布料的手感要用质地。"}, {"text": "这首歌的织体很高，我唱不上去。", "explanation": "这里应该用〈音调〉。织体指声部的组合方式，不指声音的高低。"}, {"text": "这首曲子的织体太大了，邻居都听见了。", "explanation": "这里应该用〈音量〉。织体指声部的组合方式，不指声音的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首乐曲有一条织体，听起来很厚。", "corrected_sentence": "这首乐曲有一种织体，听起来很厚。", "error_description": "量词错了：“织体”前面应该用“种”。“条”用于细长的东西，不能用来数织体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段赋格有一把织体，层次很清楚。", "corrected_sentence": "这段赋格有一种织体，层次很清楚。", "error_description": "量词错了：“织体”前面应该用“种”。“把”用于有柄的东西，不能用来数织体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
