INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10760, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10760, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把信息、消息或意思告诉别人，让别人知道。", "primary_collocate": null, "pronunciation": "chuán dá", "ipa": "tʂʰwan˧˥ ta˧˥", "syllable_count": 2, "sentences": [{"text": "其次，算法透明度并非要求公开源代码或核心商业机密，而是通过“可解释性报告”“影响评估文档”等形式，向监管机构与公众传达系统的关键决策逻辑、偏差缓解措施及风险控制机制。", "target_word": "传达", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这一技术演进不仅使复调音乐的复杂织体得以准确传达，更深刻影响了作曲家的思维方式。", "target_word": "传达", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首歌传达了作者对家乡的思念。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用简单的话传达了老板的意思。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画传达出一种安静的感觉。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告想向顾客传达产品的好处。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼神传达了她的紧张。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用表情传达自己的想法。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信没有传达清楚我的意思。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的标志要能传达公司的精神。", "target_word": "传达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传达了", "label": "完成体"}, {"form": "传达过", "label": "经历体"}, {"form": "傳達", "label": "繁体"}], "register": "中性", "sense_fingerprint": "传达：把信息、感情或意思告诉别人，让对方理解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82ebd84-cad9-43e3-91eb-87aa720f70fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传达", "is_correct": true, "explanation": "传达：把决策逻辑等内容告诉监管机构与公众，符合句中透明度的语境。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”是不让人知道，与句中的“透明度”和“可解释性报告”相反。"}, {"text": "追问", "is_correct": false, "explanation": "语义：“追问”是向对方提出问题、要求对方回答，句中是企业向监管机构与公众提供决策逻辑，方向不符，句意不通。"}, {"text": "抄袭", "is_correct": false, "explanation": "搭配：“抄袭”的对象是别人的作品或成果，不能用来指公司的决策逻辑。"}], "explanations": {"传达": "传达：把决策逻辑等内容告诉监管机构与公众，符合句中透明度的语境。", "隐瞒": "语义：“隐瞒”是不让人知道，与句中的“透明度”和“可解释性报告”相反。", "追问": "语义：“追问”是向对方提出问题、要求对方回答，句中是企业向监管机构与公众提供决策逻辑，方向不符，句意不通。", "抄袭": "搭配：“抄袭”的对象是别人的作品或成果，不能用来指公司的决策逻辑。"}, "sentence_index": 0, "correct_answer": "传达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司在官网上传达了新手机。", "explanation": "这里应该用〈发布〉。传达的对象是信息、意思，公开推出产品要用发布。"}, {"text": "这辆卡车把货物传达到了仓库。", "explanation": "这里应该用〈运送〉。传达只用于把信息、意思告诉别人，运送货物要用运送。"}, {"text": "农民在田里传达了小麦。", "explanation": "这里应该用〈种植〉。传达表示把信息告诉别人，种小麦要用种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传达", "is_correct": true, "explanation": "传达：眼神把内心的紧张表现出来，让人感受到，符合句意。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是可以量化的事物，不能说眼神测量紧张。"}, {"text": "追求", "is_correct": false, "explanation": "语义：“追求”指争取某个目标，紧张是一种状态，不能被追求。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”需要商品作宾语，紧张不能被购买。"}], "explanations": {"传达": "传达：眼神把内心的紧张表现出来，让人感受到，符合句意。", "测量": "搭配：“测量”的对象是可以量化的事物，不能说眼神测量紧张。", "追求": "语义：“追求”指争取某个目标，紧张是一种状态，不能被追求。", "购买": "搭配：“购买”需要商品作宾语，紧张不能被购买。"}, "sentence_index": 6, "correct_answer": "传达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把数据传达到了电脑里。", "explanation": "这里应该用〈输入〉。传达是把信息、意思告诉人，数据存入电脑要用输入。"}, {"text": "蚊子会把疟疾传达给人。", "explanation": "这里应该用〈传播〉。传达指把信息告诉别人，疾病的扩散要用传播。"}, {"text": "这座桥传达了两岸。", "explanation": "这里应该用〈连接〉。传达不表示物理上的连通，桥梁连接两岸要用连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把放假的消息传达了给同学。", "corrected_sentence": "老师把放假的消息传达给了同学。", "error_description": "错误：“传达了给同学”；正确：“传达给了同学”。“传达”后要用“给”引出接收者，完成体“了”应放在“给”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想把这个通知传达的给同学。", "corrected_sentence": "我想把这个通知传达给同学。", "error_description": "多用了“的”。“传达”后直接接“给”引出接收者，二者之间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
