INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10762, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人类在认识、分析、解决问题时进行的心理活动过程。", "primary_collocate": null, "pronunciation": "sī wéi", "ipa": "sɿ˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这一技术演进不仅使复调音乐的复杂织体得以准确传达，更深刻影响了作曲家的思维方式。", "target_word": "思维", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "孩子的思维很活跃。", "target_word": "思维", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学数学可以锻炼我们的思维。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的思维方式跟我不一样。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "解决问题需要清晰的思维。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们用清晰的思维分析问题。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人的思维比较灵活。", "target_word": "思维", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个游戏能帮助孩子发展思维。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他思维很快，马上就找到了答案。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到困难时，要换一种思维想一想。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "思维方式", "label": "复合"}, {"form": "思维能力", "label": "复合"}, {"form": "一种思维", "label": "量词"}, {"form": "思維", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人在认识、分析、解决问题时的心理活动过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d3d665-f01a-4085-b9af-4eb3bf63dee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐谱", "is_correct": false, "explanation": "语义：“乐谱”是记录音乐的符号，不是做事的方式，不能填入“作曲家的___方式”。"}, {"text": "思维", "is_correct": true, "explanation": "思维：指思考问题的心理活动过程，“思维方式”指作曲家思考音乐的方式，句意通顺。"}, {"text": "音色", "is_correct": false, "explanation": "搭配：“音色”指声音的特点，不能与“方式”搭配成“作曲家的音色方式”。"}, {"text": "脑瓜", "is_correct": false, "explanation": "语域：“脑瓜”是口语说法，与这句书面语的语体不合，也不能说“脑瓜方式”。"}], "explanations": {"乐谱": "语义：“乐谱”是记录音乐的符号，不是做事的方式，不能填入“作曲家的___方式”。", "思维": "思维：指思考问题的心理活动过程，“思维方式”指作曲家思考音乐的方式，句意通顺。", "音色": "搭配：“音色”指声音的特点，不能与“方式”搭配成“作曲家的音色方式”。", "脑瓜": "语域：“脑瓜”是口语说法，与这句书面语的语体不合，也不能说“脑瓜方式”。"}, "sentence_index": 0, "correct_answer": "思维"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的思维是明天去北京。", "explanation": "这里应该用〈想法〉。“思维”指思考问题的过程或方式，不能直接表示具体的打算。"}, {"text": "他的思维很甜。", "explanation": "这里应该用〈声音〉。“甜”用于形容声音、味道等，不能用来形容“思维”。"}, {"text": "他把思维放进了书包里。", "explanation": "这里应该用〈书〉。“思维”是抽象的心理活动，不是具体的东西，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体力", "is_correct": false, "explanation": "语义：“灵活”形容思维或动作，“体力”是身体的能力，不能说“体力比较灵活”。"}, {"text": "思维", "is_correct": true, "explanation": "思维：指思考的心理活动，“思维比较灵活”符合句意。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体的外形，不能用“灵活”来形容。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“视力”可以说好、差或强、弱，不能说“视力比较灵活”。"}], "explanations": {"体力": "语义：“灵活”形容思维或动作，“体力”是身体的能力，不能说“体力比较灵活”。", "思维": "思维：指思考的心理活动，“思维比较灵活”符合句意。", "身材": "体貌：“身材”指身体的外形，不能用“灵活”来形容。", "视力": "搭配：“视力”可以说好、差或强、弱，不能说“视力比较灵活”。"}, "sentence_index": 6, "correct_answer": "思维"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究人员得出了思维。", "explanation": "这里应该用〈结论〉。“得出”后接结论、答案等结果，“思维”是思考的过程，不能作“得出”的宾语。"}, {"text": "校长听取了思维。", "explanation": "这里应该用〈意见〉。“听取”接意见、建议等内容，不接“思维”。"}, {"text": "她擦掉了黑板上的思维。", "explanation": "这里应该用〈字〉。“擦掉”接字迹、污渍等具体的东西，“思维”是抽象的心理活动，不能擦掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位学者有一条独特的思维。", "corrected_sentence": "这位学者有一种独特的思维。", "error_description": "量词错误：“思维”应使用量词“种”（一种思维）；“条”用于细长的东西，不能修饰“思维”，应改为“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要学会独立地思维方式。", "corrected_sentence": "我们要学会独立的思维方式。", "error_description": "结构助词错误：修饰“思维方式”的成分应用“的”，“地”多用于修饰动词，应改为“独立的思维方式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
