INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10764, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指产生新的思想、作品或成果，如写文章、画画、做音乐等。", "primary_collocate": null, "pronunciation": "chuàng zuò", "ipa": "ʈʂʰuɑŋ˥˩ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他每天晚上都在家创作音乐。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家一年创作了三本小说。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢自己创作歌曲。", "target_word": "创作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "画家在山里创作了很多画。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最近没有时间创作。", "target_word": "创作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这首歌是他去年创作的。", "target_word": "创作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "年轻的诗人正在创作新诗。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "创作需要安静的环境。", "target_word": "创作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他创作过很多有名的电影音乐。", "target_word": "创作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们自己创作一个小故事。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "创作了", "label": "体标"}, {"form": "创作过", "label": "体标"}, {"form": "创作者", "label": "复合"}, {"form": "創作", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写作、绘画、作曲等产生新作品的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d3d665-f01a-4085-b9af-4eb3bf63dee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭菜，不能用于音乐，“在家烹饪音乐”不通。"}, {"text": "缝制", "is_correct": false, "explanation": "搭配：“缝制”多用于衣物，不能说“缝制音乐”。"}, {"text": "创作", "is_correct": true, "explanation": "创作：产生新作品，句中指在家写曲子，“创作音乐”搭配自然。"}, {"text": "腌制", "is_correct": false, "explanation": "语义：“腌制”指用盐等处理食物，与音乐无关，句意不通。"}], "explanations": {"烹饪": "语义：“烹饪”指做饭菜，不能用于音乐，“在家烹饪音乐”不通。", "缝制": "搭配：“缝制”多用于衣物，不能说“缝制音乐”。", "创作": "创作：产生新作品，句中指在家写曲子，“创作音乐”搭配自然。", "腌制": "语义：“腌制”指用盐等处理食物，与音乐无关，句意不通。"}, "sentence_index": 0, "correct_answer": "创作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天创作房间。", "explanation": "这里应该用〈整理〉。“整理”指把杂乱的东西收拾好，房间不是新作品，“创作”指产生新的思想、作品或成果。"}, {"text": "爱迪生创作了电灯。", "explanation": "这里应该用〈发明〉。“创作”用于文艺作品，电灯这类新器物要用“发明”。"}, {"text": "他创作了一锅汤。", "explanation": "这里应该用〈煮〉。“煮”用于烹调食物，“创作”指产生新的作品，不能用于汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "语义：“种植”是栽种植物，不能用于诗，“正在种植新诗”句意不通。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”是收获庄稼，与写诗无关，句意不通。"}, {"text": "创作", "is_correct": true, "explanation": "创作：写作新作品，“正在创作新诗”符合句意。"}, {"text": "烘焙", "is_correct": false, "explanation": "搭配：“烘焙”用于面包、糕点等食物，不能用于“新诗”。"}], "explanations": {"种植": "语义：“种植”是栽种植物，不能用于诗，“正在种植新诗”句意不通。", "收割": "语义：“收割”是收获庄稼，与写诗无关，句意不通。", "创作": "创作：写作新作品，“正在创作新诗”符合句意。", "烘焙": "搭配：“烘焙”用于面包、糕点等食物，不能用于“新诗”。"}, "sentence_index": 6, "correct_answer": "创作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家创作了一颗新星。", "explanation": "这里应该用〈发现〉。自然界已存在的天体、规律用“发现”，“创作”指产生新作品。"}, {"text": "工人们创作了一座大桥。", "explanation": "这里应该用〈修建〉。大桥、房屋等工程用“修建”，“创作”不用于工程。"}, {"text": "公司创作了一款新手机。", "explanation": "这里应该用〈研发〉。产品、技术用“研发”，“创作”多用于文艺作品或文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年很创作了一部小说。", "corrected_sentence": "他去年创作了一部小说。", "error_description": "程度副词位置错误：“很”一般修饰形容词或部分心理动词，不能修饰“创作”这类行为动词，应去掉“很”，说“创作了一部小说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在创作了一首新歌。", "corrected_sentence": "她正在创作一首新歌。", "error_description": "体标错误：“正在”表示动作进行中，与“了”不能同用，应去掉“了”，说“正在创作一首新歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
