INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10765, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过动作、声音或舞台把故事、技术或情感呈现给观众。", "primary_collocate": null, "pronunciation": "biǎo yǎn", "ipa": "piɑʊ˨˩˦ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "学生们在台上表演舞蹈。", "target_word": "表演", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们明天晚上在剧院表演。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她表演得非常好，观众都鼓掌了。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位演员表演过很多角色。", "target_word": "表演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看魔术师表演。", "target_word": "表演", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们给大家表演了一个小节目。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用声音表演故事，大家听得很开心。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "马戏团正在表演骑自行车。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她站在舞台中间表演唱歌。", "target_word": "表演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请他上台表演一下。", "target_word": "表演", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "表演了", "label": "体标"}, {"form": "表演过", "label": "体标"}, {"form": "表演者", "label": "复合"}], "register": "中性", "sense_fingerprint": "在舞台上向观众展示故事、技艺或情感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d3d665-f01a-4085-b9af-4eb3bf63dee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表演", "is_correct": true, "explanation": "表演：在台上把舞蹈呈现给观众，与句意一致。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”要接歌曲，不能说“在台上唱舞蹈”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除脏物，不能用于舞蹈，“在台上打扫舞蹈”句意不通。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”接的是乐曲或乐器，不能说“演奏舞蹈”。"}], "explanations": {"表演": "表演：在台上把舞蹈呈现给观众，与句意一致。", "唱": "搭配：“唱”要接歌曲，不能说“在台上唱舞蹈”。", "打扫": "语义：“打扫”指清除脏物，不能用于舞蹈，“在台上打扫舞蹈”句意不通。", "演奏": "搭配：“演奏”接的是乐曲或乐器，不能说“演奏舞蹈”。"}, "sentence_index": 0, "correct_answer": "表演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想表演对老师的感谢。", "explanation": "这里应该用〈表达〉。表演是把节目或技艺呈现给观众，表达感谢、心意要用表达。"}, {"text": "他在会议上表演了一篇论文。", "explanation": "这里应该用〈发表〉。表演指向观众呈现节目或技艺，论文要用发表。"}, {"text": "博物馆在大厅里表演了一批古代陶器。", "explanation": "这里应该用〈展示〉。表演是把节目或技艺呈现给观众，陈列陶器要用展示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表演", "is_correct": true, "explanation": "表演：用声音把故事呈现给听众，与“大家听得很开心”相符。"}, {"text": "扮演", "is_correct": false, "explanation": "搭配：“扮演”接的是角色，不能说“扮演故事”。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”是用眼睛，与句中的“用声音”和“听”相矛盾。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指写下文字，与“用声音”不符，句中没有书写的意思。"}], "explanations": {"表演": "表演：用声音把故事呈现给听众，与“大家听得很开心”相符。", "扮演": "搭配：“扮演”接的是角色，不能说“扮演故事”。", "看": "语义：“看”是用眼睛，与句中的“用声音”和“听”相矛盾。", "写": "语义：“写”指写下文字，与“用声音”不符，句中没有书写的意思。"}, "sentence_index": 6, "correct_answer": "表演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在危险面前表演出了勇气。", "explanation": "这里应该用〈表现〉。表演指在台上把节目呈现给观众，表现勇气、态度要用表现。"}, {"text": "这位选手今天表演了报名表。", "explanation": "这里应该用〈填写〉。“填写”接表格、表单，“表演”接节目或技艺，不能用于报名表。"}, {"text": "工厂表演了一批海报。", "explanation": "这里应该用〈印刷〉。表演是把节目或技艺呈现给观众，印制海报要用印刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他表演很精彩，大家都鼓掌了。", "corrected_sentence": "他表演得很精彩，大家都鼓掌了。", "error_description": "错误在于漏掉了补语前的“得”。动词后接表示程度的补语时要用“动词+得+形容词”，应说“表演得很精彩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来不表演过舞台剧。", "corrected_sentence": "他从来没表演过舞台剧。", "error_description": "错误在于否定词用了“不”。表示“从来没有过某种经历”要用“没”，应说“从来没表演过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10767, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10767, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10767, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反复琢磨、仔细考虑，多指对文字或问题进行斟酌。", "primary_collocate": null, "pronunciation": "tuī qiāo", "ipa": "tuei˥ tɕʰiɑu˥", "syllable_count": 2, "sentences": [{"text": "当声音可被完整记录，创作便不再局限于即兴表演的范畴，而是成为可在纸上推敲、修改的智力活动。", "target_word": "推敲", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这篇文章的题目，我推敲了很久。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每一句话都仔细推敲了一遍。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写诗时，诗人常常为一个字反复推敲。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划还要再推敲推敲。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同的条款经不起推敲。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们推敲演讲稿里的用词。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过反复推敲，他终于定下了标题。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信的措辞需要好好推敲。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家为了一个词，推敲了整整一夜。", "target_word": "推敲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推敲了", "label": "完成体"}, {"form": "推敲过", "label": "经历体"}, {"form": "推敲推敲", "label": "重叠"}], "register": "书面", "sense_fingerprint": "反复琢磨、斟酌文字或问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d3d665-f01a-4085-b9af-4eb3bf63dee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推敲", "is_correct": true, "explanation": "推敲：反复琢磨、斟酌文字，与“修改”的对象相符。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”接乐曲或乐器，不能用于纸上的文字。"}, {"text": "投影", "is_correct": false, "explanation": "语义：“投影”是把影像投到表面上，与“在纸上修改”无关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”要接歌曲，不能说“可在纸上唱”。"}], "explanations": {"推敲": "推敲：反复琢磨、斟酌文字，与“修改”的对象相符。", "演奏": "搭配：“演奏”接乐曲或乐器，不能用于纸上的文字。", "投影": "语义：“投影”是把影像投到表面上，与“在纸上修改”无关。", "唱": "搭配：“唱”要接歌曲，不能说“可在纸上唱”。"}, "sentence_index": 0, "correct_answer": "推敲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把这家餐厅推敲给朋友。", "explanation": "这里应该用〈推荐〉。推敲指反复琢磨文字或问题，不能用来把餐厅介绍给别人。"}, {"text": "他轻轻推敲了门。", "explanation": "这里应该用〈推开〉。推敲指反复琢磨文字或问题，开门的动作要用推开。"}, {"text": "他用力推敲了箱子。", "explanation": "这里应该用〈推动〉。推敲不能用于移动物体，推箱子使其移动要用推动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推敲", "is_correct": true, "explanation": "推敲：反复斟酌文字用词，与“演讲稿里的用词”相符。"}, {"text": "播放", "is_correct": false, "explanation": "语义：“播放”指放送声音或影像，与“用词”不符。"}, {"text": "朗诵", "is_correct": false, "explanation": "搭配：“朗诵”的对象是诗文等成篇的作品，不能说“朗诵用词”。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”用于切开实物，不能用于文字用词。"}], "explanations": {"推敲": "推敲：反复斟酌文字用词，与“演讲稿里的用词”相符。", "播放": "语义：“播放”指放送声音或影像，与“用词”不符。", "朗诵": "搭配：“朗诵”的对象是诗文等成篇的作品，不能说“朗诵用词”。", "切割": "搭配：“切割”用于切开实物，不能用于文字用词。"}, "sentence_index": 6, "correct_answer": "推敲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大风把那棵树推敲了。", "explanation": "这里应该用〈推倒〉。推敲只用于文字或问题，把树弄倒要用推倒。"}, {"text": "妈妈推敲着婴儿车去公园。", "explanation": "这里应该用〈推〉。推敲不能表示推动物体，推婴儿车要用推。"}, {"text": "人群推敲着向前走。", "explanation": "这里应该用〈推搡〉。推敲指反复琢磨文字或问题，挤着向前走要用推搡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他推敲很仔细，每个字都不放过。", "corrected_sentence": "他推敲得很仔细，每个字都不放过。", "error_description": "错误在于漏掉了“得”。“推敲”后接表示程度的补语时要用“得”，应说“推敲得很仔细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种文字我从来不推敲过。", "corrected_sentence": "这种文字我从来没推敲过。", "error_description": "错误在于否定词用了“不”。表示“从来没有过某种经历”要用“没”，应说“从来没推敲过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
