INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10769, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "运用思考能力进行推理、分析、判断等脑力活动。", "primary_collocate": null, "pronunciation": "zhì lì huó dòng", "ipa": "ʈʂɻ̩˥˩ li˥˩ xuɔ˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "当声音可被完整记录，创作便不再局限于即兴表演的范畴，而是成为可在纸上推敲、修改的智力活动。", "target_word": "智力活动", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "下棋是一种很好的智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做数学题是一项复杂的智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老年人多参加智力活动，可以让大脑更灵活。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写论文需要大量的智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类智力活动对孩子的成长很重要。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "推理和分析都是智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间的智力活动让他很累。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议爷爷每天进行一些智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学研究是一种需要创造力的智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "书面", "sense_fingerprint": "运用思考能力进行推理、分析、判断的脑力活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d3d665-f01a-4085-b9af-4eb3bf63dee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "智力活动", "is_correct": true, "explanation": "正确。“成为……的智力活动”指需要动脑推敲、修改的脑力活动，与“可在纸上推敲、修改”相合。"}, {"text": "体育运动", "is_correct": false, "explanation": "语义：体育运动是身体活动，不能在纸上推敲、修改。"}, {"text": "社交活动", "is_correct": false, "explanation": "语义：社交活动指人与人的交往，不是可以在纸上修改的对象。"}, {"text": "家务劳动", "is_correct": false, "explanation": "搭配：“推敲、修改”的对象是文字作品，不能与“家务劳动”搭配。"}], "explanations": {"智力活动": "正确。“成为……的智力活动”指需要动脑推敲、修改的脑力活动，与“可在纸上推敲、修改”相合。", "体育运动": "语义：体育运动是身体活动，不能在纸上推敲、修改。", "社交活动": "语义：社交活动指人与人的交往，不是可以在纸上修改的对象。", "家务劳动": "搭配：“推敲、修改”的对象是文字作品，不能与“家务劳动”搭配。"}, "sentence_index": 0, "correct_answer": "智力活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个周末我们去爬山、游泳，做了很多智力活动。", "explanation": "这里应该用〈体力活动〉。智力活动指动脑思考的活动，爬山、游泳属于身体活动。"}, {"text": "周末我们去唱歌、看电影，参加了很多智力活动。", "explanation": "这里应该用〈娱乐活动〉。智力活动强调用脑思考，唱歌、看电影属于娱乐，不能这样说。"}, {"text": "我们班周末举办了一次智力活动，大家一起去郊外野餐。", "explanation": "这里应该用〈郊游〉。智力活动指运用思考能力的脑力活动，野餐、郊游是放松的户外活动，不属于这一类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "智力活动", "is_correct": true, "explanation": "正确。“推理和分析”属于思维过程，正是智力活动的内容。"}, {"text": "手工艺", "is_correct": false, "explanation": "语义：手工艺是动手制作的技艺，与推理、分析无关。"}, {"text": "园艺", "is_correct": false, "explanation": "语义：园艺指照料植物的劳作，不是推理或分析。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“推理和分析”是思维过程，“烹饪”是做饭的技艺，两者不搭配。"}], "explanations": {"智力活动": "正确。“推理和分析”属于思维过程，正是智力活动的内容。", "手工艺": "语义：手工艺是动手制作的技艺，与推理、分析无关。", "园艺": "语义：园艺指照料植物的劳作，不是推理或分析。", "烹饪": "搭配：“推理和分析”是思维过程，“烹饪”是做饭的技艺，两者不搭配。"}, "sentence_index": 6, "correct_answer": "智力活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人每天在工地上进行繁重的智力活动。", "explanation": "这里应该用〈体力劳动〉。搬运、施工属于体力劳动，智力活动指用脑思考的活动。"}, {"text": "他的智力活动很高，做题很快。", "explanation": "这里应该用〈智力水平〉。“高”形容水平，智力活动指思考的过程，不能用“高”来衡量。"}, {"text": "我们周末去公园散步，这些都是智力活动。", "explanation": "这里应该用〈休闲活动〉。散步是身体上的放松，不属于用脑思考的智力活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都做一只智力活动，锻炼大脑。", "corrected_sentence": "他每天都做一项智力活动，锻炼大脑。", "error_description": "量词错误：“智力活动”应用量词“项”，不能用“只”。正确形式为“一项智力活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只智力活动对老人的记忆力很有帮助。", "corrected_sentence": "这项智力活动对老人的记忆力很有帮助。", "error_description": "量词错误：“智力活动”应用量词“项”，“只”不能用于活动。正确形式为“这项智力活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
