INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10770, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "巴洛克是欧洲17世纪至18世纪流行的一种艺术风格，特点是华丽、动感和丰富的装饰。", "primary_collocate": null, "pronunciation": "bā luò kè", "ipa": "pa˥ luɔ˥˩ kʰɤ˥˩", "syllable_count": 3, "sentences": [{"text": "巴洛克时代，通奏低音记谱法的流行进一步体现了功能和声观念的成熟；而从古典到浪漫主义时期，记谱日益趋向全面控制，力度、速度、表情记号密集出现，反映出个体情感表达在音乐中的中心地位。", "target_word": "巴洛克", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "巴洛克是十七世纪流行的艺术风格。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巴洛克建筑的特点是华丽和丰富的装饰。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座教堂很有巴洛克的味道，墙上到处是装饰。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巴洛克音乐常常有很强的动感。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢巴洛克时期的画，颜色很丰富。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧洲有很多巴洛克教堂，里面又华丽又漂亮。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的大厅是巴洛克式的，到处是金色装饰。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巴洛克和现代简约风格很不一样。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在欧洲参观了一座巴洛克宫殿。", "target_word": "巴洛克", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巴洛克式", "label": "复合"}, {"form": "巴洛克风格", "label": "复合"}], "register": "书面", "sense_fingerprint": "欧洲十七至十八世纪流行的华丽、有动感的艺术风格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d3d665-f01a-4085-b9af-4eb3bf63dee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巴洛克", "is_correct": true, "explanation": "正确。通奏低音记谱法是巴洛克时代音乐的特征，句中“时代”指的就是巴洛克。"}, {"text": "印象派", "is_correct": false, "explanation": "语义：印象派不是通奏低音记谱法流行的时代，与句中音乐史内容不符。"}, {"text": "立体主义", "is_correct": false, "explanation": "语义：立体主义是二十世纪的绘画流派，与十七至十八世纪的音乐记谱无关。"}, {"text": "装饰艺术", "is_correct": false, "explanation": "搭配：“时代”前应是音乐时期，“装饰艺术”主要指工艺设计，不能与通奏低音记谱法搭配。"}], "explanations": {"巴洛克": "正确。通奏低音记谱法是巴洛克时代音乐的特征，句中“时代”指的就是巴洛克。", "印象派": "语义：印象派不是通奏低音记谱法流行的时代，与句中音乐史内容不符。", "立体主义": "语义：立体主义是二十世纪的绘画流派，与十七至十八世纪的音乐记谱无关。", "装饰艺术": "搭配：“时代”前应是音乐时期，“装饰艺术”主要指工艺设计，不能与通奏低音记谱法搭配。"}, "sentence_index": 0, "correct_answer": "巴洛克"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的设计是巴洛克的，几乎没有任何装饰。", "explanation": "这里应该用〈简约风格〉。巴洛克以繁复装饰为特点，与“几乎没有任何装饰”矛盾。"}, {"text": "这座神庙采用巴洛克风格，柱子整齐对称，外墙平直朴素。", "explanation": "这里应该用〈古典主义〉。古典主义讲究对称、朴素克制；巴洛克以华丽、动感和丰富的装饰为特点，不能用来形容“外墙平直朴素”。"}, {"text": "这间客厅采用巴洛克风格，淡粉浅金的墙面线条轻盈，充满童趣。", "explanation": "这里应该用〈洛可可〉。洛可可风格轻盈、柔和、充满童趣；巴洛克以厚重、动感和华丽的装饰为特点，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巴洛克", "is_correct": true, "explanation": "正确。巴洛克教堂以华丽、漂亮著称，与句末描述相合。"}, {"text": "乡村风格", "is_correct": false, "explanation": "语义：乡村风格朴素自然，与“又华丽又漂亮”的描述相反。"}, {"text": "工业风", "is_correct": false, "explanation": "语义：工业风以粗犷、简约为主，与“华丽”不符。"}, {"text": "北欧风", "is_correct": false, "explanation": "搭配：“北欧风教堂”通常指简洁的风格，与“华丽又漂亮”不协调。"}], "explanations": {"巴洛克": "正确。巴洛克教堂以华丽、漂亮著称，与句末描述相合。", "乡村风格": "语义：乡村风格朴素自然，与“又华丽又漂亮”的描述相反。", "工业风": "语义：工业风以粗犷、简约为主，与“华丽”不符。", "北欧风": "搭配：“北欧风教堂”通常指简洁的风格，与“华丽又漂亮”不协调。"}, "sentence_index": 6, "correct_answer": "巴洛克"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在欧洲参观了一座巴洛克建筑，线条很简洁。", "explanation": "这里应该用〈现代主义〉。现代主义讲究线条简洁，巴洛克以繁复装饰著称。"}, {"text": "这栋大楼采用巴洛克风格，线条流畅，图案几何化。", "explanation": "这里应该用〈装饰艺术〉。装饰艺术讲究几何图案和流线造型，巴洛克以繁复、动感的装饰为特点，不能这样形容。"}, {"text": "这幅巴洛克画线条简练，留白很多。", "explanation": "这里应该用〈水墨画〉。水墨画讲究留白，巴洛克绘画画面饱满、装饰丰富，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在欧洲看了一张巴洛克建筑。", "corrected_sentence": "他们在欧洲看了一座巴洛克建筑。", "error_description": "量词错误：“巴洛克建筑”指房子、教堂这类建筑物，量词要用“座”，不能用“张”。应说“一座巴洛克建筑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一件巴洛克风格的剧院，装饰很华丽。", "corrected_sentence": "这是一座巴洛克风格的剧院，装饰很华丽。", "error_description": "量词错误：“巴洛克风格的剧院”是建筑物，量词要用“座”，不能用“件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
