INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10772, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指频率低、听起来低沉的声音。", "primary_collocate": null, "pronunciation": "dī yīn", "ipa": "ti˥ in˥", "syllable_count": 2, "sentences": [{"text": "这个音箱的低音很好听。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男歌手的低音听起来很稳。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大提琴能拉出很深的低音。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把低音调大一点。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的低音太重了，邻居会听到。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个耳机低音不够，听摇滚不过瘾。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合唱团里需要有人唱低音。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的嗓子好，能唱很低的低音。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机喇叭的低音很弱。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴左手弹的是低音。", "target_word": "低音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低音部", "label": "复合"}, {"form": "低音提琴", "label": "复合"}], "register": "通用", "sense_fingerprint": "频率低而低沉的声音，如音箱、乐器、歌声中的低音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09683557-dab8-41ba-b863-ee314a4fd40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低音", "is_correct": true, "explanation": "指频率低、听起来低沉的声音，与「很好听」的语境相符。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：「好听」形容声音的质感，「音量」只说大小，不说好听。"}, {"text": "按钮", "is_correct": false, "explanation": "语义：「好听」描述声音，按钮是用来按的东西，不能听。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色属于外观，不能用「好听」来形容。"}], "explanations": {"低音": "指频率低、听起来低沉的声音，与「很好听」的语境相符。", "音量": "搭配：「好听」形容声音的质感，「音量」只说大小，不说好听。", "按钮": "语义：「好听」描述声音，按钮是用来按的东西，不能听。", "颜色": "语义：颜色属于外观，不能用「好听」来形容。"}, "sentence_index": 0, "correct_answer": "低音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的低音很好看。", "explanation": "这里应该用〈颜色〉。低音是一种声音，不能用「好看」形容衣服。"}, {"text": "这辆车的低音很快，一下就到了。", "explanation": "这里应该用〈速度〉。低音指低沉的声音，不能表示快慢。"}, {"text": "她说话很低音，别人听不见。", "explanation": "这里应该用〈小声〉。低音是名词，不能受「很」修饰来形容说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低音", "is_correct": true, "explanation": "指合唱中的低音声部，与「唱」搭配，符合句意。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：拖鞋是穿的东西，不能被「唱」。"}, {"text": "节拍", "is_correct": false, "explanation": "语义：「唱」的对象是歌或声部，节拍不能被唱。"}, {"text": "舞步", "is_correct": false, "explanation": "语义：合唱团需要的是声部，舞步与「唱」无关。"}], "explanations": {"低音": "指合唱中的低音声部，与「唱」搭配，符合句意。", "拖鞋": "搭配：拖鞋是穿的东西，不能被「唱」。", "节拍": "语义：「唱」的对象是歌或声部，节拍不能被唱。", "舞步": "语义：合唱团需要的是声部，舞步与「唱」无关。"}, "sentence_index": 6, "correct_answer": "低音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小鸟的叫声又尖又细，是好听的低音。", "explanation": "这里应该用〈高音〉。又尖又细的声音是高音，不是低音。"}, {"text": "这个房间的低音太高了，要开空调。", "explanation": "这里应该用〈温度〉。低音指声音，不能表示冷热。"}, {"text": "他这次考试只拿了个低音。", "explanation": "这里应该用〈低分〉。低音指声音，不能表示分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌的低音又尖又细，很刺耳。", "corrected_sentence": "这首歌的高音又尖又细，很刺耳。", "error_description": "用词错误：又尖又细的声音是「高音」，低音是低沉的声音。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "笛子吹出来的低音很尖，像小鸟在叫。", "corrected_sentence": "笛子吹出来的高音很尖，像小鸟在叫。", "error_description": "用词错误：又尖又像鸟叫的声音是「高音」，「低音」是低沉的声音。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
