INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10775, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物或方法所发挥的有利作用；效能。", "primary_collocate": null, "pronunciation": "gōng néng", "ipa": "kʊŋ˥ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个手机有很多新功能。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药的主要功能是止痛。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校图书馆有学习和休息两种功能。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还不会用这个软件的翻译功能。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肝的功能很重要。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的功能很简单。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电视增加了语音功能。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥除了过河，还有旅游功能。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的功能是开会。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱的冷冻功能坏了。", "target_word": "功能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "多功能", "label": "复合"}, {"form": "功能键", "label": "复合"}], "register": "通用", "sense_fingerprint": "事物、器官或方法所发挥的作用和效能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09683557-dab8-41ba-b863-ee314a4fd40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "功能", "is_correct": true, "explanation": "指事物能发挥的作用，「有很多新功能」符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：手机没有「味道」，「有很多新味道」句意说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是可以「有很多新」的功用，句意说不通。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积是大小，不能说「有很多新体积」。"}], "explanations": {"功能": "指事物能发挥的作用，「有很多新功能」符合句意。", "味道": "语义：手机没有「味道」，「有很多新味道」句意说不通。", "价格": "语义：价格不是可以「有很多新」的功用，句意说不通。", "体积": "语义：体积是大小，不能说「有很多新体积」。"}, "sentence_index": 0, "correct_answer": "功能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的努力起了很大功能。", "explanation": "这里应该用〈作用〉。「起作用」是固定搭配，「功能」指事物能做的事，不能说「起功能」。"}, {"text": "这次训练的功能很好，大家都满意。", "explanation": "这里应该用〈效果〉。训练的好坏是做事后的结果，不用「功能」来衡量。"}, {"text": "这个软件又多了一只功能。", "explanation": "量词错误：「功能」应搭配〈项〉或〈个〉，「只」多用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "功能", "is_correct": true, "explanation": "指新增的语音用途，与「增加了」搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以被「增加」的功用，语音和颜色无关。"}, {"text": "重量", "is_correct": false, "explanation": "语义：「增加了语音重量」说不通，重量不能表示语音的用途。"}, {"text": "外观", "is_correct": false, "explanation": "语义：外观是外形，不能说「增加了语音外观」。"}], "explanations": {"功能": "指新增的语音用途，与「增加了」搭配，符合句意。", "颜色": "语义：颜色不是可以被「增加」的功用，语音和颜色无关。", "重量": "语义：「增加了语音重量」说不通，重量不能表示语音的用途。", "外观": "语义：外观是外形，不能说「增加了语音外观」。"}, "sentence_index": 6, "correct_answer": "功能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改革取得了明显功能。", "explanation": "这里应该用〈成效〉。「取得成效」是固定搭配，「功能」不能被「取得」。"}, {"text": "这台冰箱有两台功能，很实用。", "explanation": "量词错误：「功能」应搭配〈项〉或〈种〉，「台」用于机器，不用于功能。"}, {"text": "这件事对他功能很大。", "explanation": "这里应该用〈影响〉。「功能」指事物的用途，不能表示对人的作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个手机有好几只新功能。", "corrected_sentence": "这个手机有好几项新功能。", "error_description": "量词错误：「功能」应搭配「项」，「只」多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新电视增加了一只语音功能。", "corrected_sentence": "新电视增加了一项语音功能。", "error_description": "量词错误：「功能」应搭配「项」，「只」多用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10779, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代与古典相对，指当代的艺术形式，与“古典舞”相对。"}, {"text": "明亮", "is_correct": false, "explanation": "与古典无反义关系，明亮形容光线或颜色。"}, {"text": "柔软", "is_correct": false, "explanation": "与古典无反义关系，柔软形容质地。"}, {"text": "快速", "is_correct": false, "explanation": "与古典无反义关系，快速形容速度。"}], "correct_answer": "现代", "explanations": {"现代": "现代与古典相对，指当代的艺术形式，与“古典舞”相对。", "明亮": "与古典无反义关系，明亮形容光线或颜色。", "柔软": "与古典无反义关系，柔软形容质地。", "快速": "与古典无反义关系，快速形容速度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10779, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代与古典相对，指当代的文艺形式，与“古典小说”相对。"}, {"text": "湿润", "is_correct": false, "explanation": "与古典无反义关系，湿润形容潮湿的感觉。"}, {"text": "粗糙", "is_correct": false, "explanation": "与古典无反义关系，粗糙形容质地。"}, {"text": "缓慢", "is_correct": false, "explanation": "与古典无反义关系，缓慢形容速度。"}], "correct_answer": "现代", "explanations": {"现代": "现代与古典相对，指当代的文艺形式，与“古典小说”相对。", "湿润": "与古典无反义关系，湿润形容潮湿的感觉。", "粗糙": "与古典无反义关系，粗糙形容质地。", "缓慢": "与古典无反义关系，缓慢形容速度。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10779, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指古代流传下来的，具有经典性质或传统特色的。", "primary_collocate": null, "pronunciation": "gǔ diǎn", "ipa": "ku˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "巴洛克时代，通奏低音记谱法的流行进一步体现了功能和声观念的成熟；而从古典到浪漫主义时期，记谱日益趋向全面控制，力度、速度、表情记号密集出现，反映出个体情感表达在音乐中的中心地位。", "target_word": "古典", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我喜欢听古典音乐。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古典园林很有名。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小学习古典舞。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了很多古典文学作品。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子是古典风格的。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去听了古典音乐会。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古典诗歌的语言很美。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍中国古典建筑。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古典小说《红楼梦》很长。", "target_word": "古典", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "古典主义", "label": "复合"}, {"form": "古典音乐", "label": "复合"}], "register": "中性", "sense_fingerprint": "古代流传下来、具有经典性质或传统特色的（古典音乐、古典文学）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09683557-dab8-41ba-b863-ee314a4fd40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古典", "is_correct": true, "explanation": "正确。“从古典到浪漫主义时期”指音乐史上由古典向浪漫的过渡，此处应填“古典”。"}, {"text": "现代", "is_correct": false, "explanation": "语义：现代晚于浪漫主义，“从现代到浪漫主义时期”时间顺序颠倒。"}, {"text": "民谣", "is_correct": false, "explanation": "搭配：“时期”前接时代或流派名称，民谣是体裁，不能这样接。"}, {"text": "电子", "is_correct": false, "explanation": "语义：电子音乐出现于二十世纪，不能作为早于浪漫主义的时期起点。"}], "explanations": {"古典": "正确。“从古典到浪漫主义时期”指音乐史上由古典向浪漫的过渡，此处应填“古典”。", "现代": "语义：现代晚于浪漫主义，“从现代到浪漫主义时期”时间顺序颠倒。", "民谣": "搭配：“时期”前接时代或流派名称，民谣是体裁，不能这样接。", "电子": "语义：电子音乐出现于二十世纪，不能作为早于浪漫主义的时期起点。"}, "sentence_index": 0, "correct_answer": "古典"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节的古典活动很热闹。", "explanation": "这里应该用〈传统〉。古典多指有经典性质的文学、艺术，春节习俗等应说传统。"}, {"text": "这个村口有一棵古典的大树，已经有几百年了。", "explanation": "这里应该用〈古老〉。古典指有经典性质或传统特色的事物，形容树的年代久远要说古老。"}, {"text": "古典的人们很早就会种田。", "explanation": "这里应该用〈古代〉。古典指有经典性质，不用于指时代久远的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古典", "is_correct": true, "explanation": "正确。“古典音乐会”指演出的曲目风格，此处应填“古典”。"}, {"text": "冷静", "is_correct": false, "explanation": "搭配：“冷静”形容人的态度，不修饰演出活动。"}, {"text": "湿润", "is_correct": false, "explanation": "语义：“湿润”形容潮湿的感觉，与音乐会无关。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：沙发是家具，不能用来修饰「音乐会」。"}], "explanations": {"古典": "正确。“古典音乐会”指演出的曲目风格，此处应填“古典”。", "冷静": "搭配：“冷静”形容人的态度，不修饰演出活动。", "湿润": "语义：“湿润”形容潮湿的感觉，与音乐会无关。", "沙发": "搭配：沙发是家具，不能用来修饰「音乐会」。"}, "sentence_index": 6, "correct_answer": "古典"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天气很古典，适合出去玩。", "explanation": "这里应该用〈晴朗〉。古典用于艺术、文化等有经典性质的事物，不形容天气。"}, {"text": "她跑得很古典。", "explanation": "这里应该用〈快〉。古典不用于形容动作的快慢。"}, {"text": "这部电影是古典，大家都看过。", "explanation": "这里应该用〈经典〉。古典作形容词修饰名词，如“古典音乐”，不能单独作谓语指称作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很喜欢古典地文学。", "corrected_sentence": "他很喜欢古典文学。", "error_description": "错误形式“古典地文学”，正确形式“古典文学”。“地”用于修饰动词、形容词，修饰名词“文学”时不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首曲子很的古典。", "corrected_sentence": "这首曲子很古典。", "error_description": "多加了「的」：程度副词「很」与形容词之间不能插入「的」，删去「的」，应为「很古典」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10780, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实主义", "is_correct": true, "explanation": "现实主义注重客观描写现实，与重视感情和想象的浪漫主义相对。"}, {"text": "咖啡", "is_correct": false, "explanation": "与浪漫主义无反义关系，咖啡是饮品。"}, {"text": "河流", "is_correct": false, "explanation": "与浪漫主义无反义关系，河流是地理事物。"}, {"text": "窗户", "is_correct": false, "explanation": "与浪漫主义无反义关系，窗户是建筑部件。"}], "correct_answer": "现实主义", "explanations": {"现实主义": "现实主义注重客观描写现实，与重视感情和想象的浪漫主义相对。", "咖啡": "与浪漫主义无反义关系，咖啡是饮品。", "河流": "与浪漫主义无反义关系，河流是地理事物。", "窗户": "与浪漫主义无反义关系，窗户是建筑部件。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10780, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实主义", "is_correct": true, "explanation": "现实主义与浪漫主义相对，前者注重客观写实，后者重视感情与想象。"}, {"text": "天空", "is_correct": false, "explanation": "与浪漫主义无反义关系，天空是自然景物。"}, {"text": "桌子", "is_correct": false, "explanation": "与浪漫主义无反义关系，桌子是家具。"}, {"text": "牛奶", "is_correct": false, "explanation": "与浪漫主义无反义关系，牛奶是饮品。"}], "correct_answer": "现实主义", "explanations": {"现实主义": "现实主义与浪漫主义相对，前者注重客观写实，后者重视感情与想象。", "天空": "与浪漫主义无反义关系，天空是自然景物。", "桌子": "与浪漫主义无反义关系，桌子是家具。", "牛奶": "与浪漫主义无反义关系，牛奶是饮品。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "浪漫主义是一种文艺风格，强调感情、想象和自然，反对死板的规则。", "primary_collocate": null, "pronunciation": "làng màn zhǔ yì", "ipa": "lɑŋ˥˩ man˥˩ ʈʂu˨˩˦ i˥˩", "syllable_count": 4, "sentences": [{"text": "巴洛克时代，通奏低音记谱法的流行进一步体现了功能和声观念的成熟；而从古典到浪漫主义时期，记谱日益趋向全面控制，力度、速度、表情记号密集出现，反映出个体情感表达在音乐中的中心地位。", "target_word": "浪漫主义", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "浪漫主义文学强调感情和想象。", "target_word": "浪漫主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家属于浪漫主义。", "target_word": "浪漫主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浪漫主义音乐出现在十九世纪。", "target_word": "浪漫主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上讲了浪漫主义的特点。", "target_word": "浪漫主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浪漫主义反对死板的规则。", "target_word": "浪漫主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师介绍了浪漫主义诗人。", "target_word": "浪漫主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多浪漫主义作品都写到自然。", "target_word": "浪漫主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗是浪漫主义的代表作。", "target_word": "浪漫主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浪漫主义和古典主义很不一样。", "target_word": "浪漫主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪漫主義", "label": "繁体"}, {"form": "浪漫主义者", "label": "复合"}], "register": "书面", "sense_fingerprint": "十九世纪前后强调感情、想象和自然的文艺风格与流派", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09683557-dab8-41ba-b863-ee314a4fd40f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪漫主义", "is_correct": true, "explanation": "正确。“从古典到浪漫主义时期”中，“浪漫主义”指音乐史上的一个时期，此处应填“浪漫主义”。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不是可以用来标定时期的名称。"}, {"text": "民谣", "is_correct": false, "explanation": "搭配：民谣是体裁，“时期”前不接体裁名。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球与音乐风格的历史演进无关，句子语境不通。"}], "explanations": {"浪漫主义": "正确。“从古典到浪漫主义时期”中，“浪漫主义”指音乐史上的一个时期，此处应填“浪漫主义”。", "咖啡": "语义：咖啡是饮品，不是可以用来标定时期的名称。", "民谣": "搭配：民谣是体裁，“时期”前不接体裁名。", "足球": "语义：足球与音乐风格的历史演进无关，句子语境不通。"}, "sentence_index": 0, "correct_answer": "浪漫主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "浪漫主义小说注重写普通人的生活。", "explanation": "这里应该用〈现实主义〉。浪漫主义强调感情和想象，不以描写普通人的日常生活为主。"}, {"text": "这家餐厅的菜很浪漫主义，味道很好。", "explanation": "这里应该用〈好吃〉。浪漫主义是文艺风格的名称，不能形容菜的味道。"}, {"text": "他在讲座上讲了一只浪漫主义。", "explanation": "这里应该用〈种〉。浪漫主义作为流派或思潮，常用“种”计量，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪漫主义", "is_correct": true, "explanation": "正确。“老师介绍了浪漫主义诗人”中，应填表示诗人流派的“浪漫主义”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是诗人的类别，与“诗人”搭配不通。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪是自然现象，不能作为诗人的类别。"}, {"text": "课桌", "is_correct": false, "explanation": "搭配：课桌是物件，不能作为诗人的限定词。"}], "explanations": {"浪漫主义": "正确。“老师介绍了浪漫主义诗人”中，应填表示诗人流派的“浪漫主义”。", "冰箱": "语义：冰箱不是诗人的类别，与“诗人”搭配不通。", "海浪": "语义：海浪是自然现象，不能作为诗人的类别。", "课桌": "搭配：课桌是物件，不能作为诗人的限定词。"}, "sentence_index": 6, "correct_answer": "浪漫主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家书店的服务员是个浪漫主义。", "explanation": "这里应该用〈浪漫主义者〉。浪漫主义是文艺风格，指人要说“浪漫主义者”，不能把人说成一种风格。"}, {"text": "浪漫主义注重客观地描写现实。", "explanation": "这里应该用〈写实主义〉。浪漫主义重视感情和想象，不以客观描写为重点。"}, {"text": "浪漫主义讲究规则和秩序。", "explanation": "这里应该用〈古典主义〉。浪漫主义反对死板的规则，不讲究规则和秩序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很喜欢浪漫主义地文学。", "corrected_sentence": "我很喜欢浪漫主义文学。", "error_description": "错误形式“浪漫主义地文学”，正确形式“浪漫主义文学”。“地”用于修饰动词、形容词，修饰名词“文学”时不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位诗人是一只浪漫主义诗人。", "corrected_sentence": "这位诗人是浪漫主义诗人。", "error_description": "量词错误：「只」多用于动物，不能用来数诗人，删去「一只」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03e7a3fb-53e2-4823-9f3f-4c84018b222c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
