INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10782, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物发展变化的方向或趋势。", "primary_collocate": null, "pronunciation": "qū xiàng", "ipa": "tɕʰy˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "巴洛克时代，通奏低音记谱法的流行进一步体现了功能和声观念的成熟；而从古典到浪漫主义时期，记谱日益趋向全面控制，力度、速度、表情记号密集出现，反映出个体情感表达在音乐中的中心地位。", "target_word": "趋向", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "专家说，今年天气的变化趋向比较稳定。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这张图可以看出价格的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的消费趋向正在改变。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现学生的兴趣趋向越来越多样。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先了解市场的发展趋向，再做决定。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司一直在研究用户喜好的趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查显示，人们的购物趋向已经变了。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的人口趋向完全不同。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上分析了今年经济的总体趋向。", "target_word": "趋向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趨向", "label": "繁体"}, {"form": "趋向性", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "趋向|名词|事物发展变化的方向或趋势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aca22b7-8bcd-478e-9e3a-da6f3d17cd93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "趋向", "is_correct": true, "explanation": "正确：“趋向”表示朝某个方向发展，“记谱日益趋向全面控制”指记谱越来越朝全面控制发展。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”指住所位置，“记谱日益地址全面控制”说不通。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体占的空间，不能表示发展方向。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能表示记谱的发展方向。"}], "explanations": {"趋向": "正确：“趋向”表示朝某个方向发展，“记谱日益趋向全面控制”指记谱越来越朝全面控制发展。", "地址": "语义：“地址”指住所位置，“记谱日益地址全面控制”说不通。", "体积": "语义：“体积”指物体占的空间，不能表示发展方向。", "颜色": "语义：“颜色”指色彩，不能表示记谱的发展方向。"}, "sentence_index": 0, "correct_answer": "趋向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他朝着学校的趋向走去。", "explanation": "这里应该用〈方向〉。“趋向”指事情发展的趋势，不指具体的行进方向。"}, {"text": "他对音乐有强烈的趋向。", "explanation": "这里应该用〈倾向〉。“趋向”指事物发展的方向，个人的爱好、习惯要用“倾向”。"}, {"text": "警方一直在追踪嫌疑人的趋向。", "explanation": "这里应该用〈动向〉。“趋向”指事物发展的方向或趋势，追踪人的行踪、活动要用“动向”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋向", "is_correct": true, "explanation": "正确：“趋向”指喜好的变化方向，与“研究用户喜好的”相合。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热的程度，与用户喜好不搭，“研究用户喜好的温度”不通顺。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，喜好不具有重量，“研究用户喜好的重量”不通顺。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，喜好没有身高，“研究用户喜好的身高”不通顺。"}], "explanations": {"趋向": "正确：“趋向”指喜好的变化方向，与“研究用户喜好的”相合。", "温度": "语义：“温度”指冷热的程度，与用户喜好不搭，“研究用户喜好的温度”不通顺。", "重量": "语义：“重量”指物体的轻重，喜好不具有重量，“研究用户喜好的重量”不通顺。", "身高": "语义：“身高”指人的高矮，喜好没有身高，“研究用户喜好的身高”不通顺。"}, "sentence_index": 6, "correct_answer": "趋向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的身体趋向一直很好。", "explanation": "这里应该用〈状态〉。“趋向”指事物发展的方向或趋势，人的身体情况要用“状态”。"}, {"text": "这座城市的交通趋向很差。", "explanation": "这里应该用〈状况〉。“趋向”指事物发展的方向或趋势，交通的现状、好坏要用“状况”。"}, {"text": "他的工作趋向很严谨。", "explanation": "这里应该用〈作风〉。“趋向”指事物发展的方向或趋势，人做事的态度与风格要用“作风”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章讨论了一只今年经济的总体趋向。", "corrected_sentence": "这篇文章讨论了今年经济的总体趋向。", "error_description": "量词误用：“趋向”不能配“只”（“只”多用于动物或成对的东西）；应去掉“一只”，说“讨论了今年经济的总体趋向”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一只很明显的趋向。", "corrected_sentence": "这是一种很明显的趋向。", "error_description": "量词误用：“趋向”是抽象名词，应该用量词“种”，不能用“只”（“只”多用于动物或成对的东西）；应改为“一种很明显的趋向”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
