INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10785, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指力量的大小或做事的强度。", "primary_collocate": null, "pronunciation": "lì dù", "ipa": "li˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "巴洛克时代，通奏低音记谱法的流行进一步体现了功能和声观念的成熟；而从古典到浪漫主义时期，记谱日益趋向全面控制，力度、速度、表情记号密集出现，反映出个体情感表达在音乐中的中心地位。", "target_word": "力度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他拍桌子的力度太大，杯子都掉了。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，写毛笔字时力度要轻一点。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在加大环保工作的力度。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次检查的力度很大，没人敢违反规定。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按摩时力度太小，没有效果。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位钢琴家弹到高潮时，力度越来越强。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他握手的力度让我吃了一惊。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对质量管理的力度比去年大。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打鼓的时候，力度要跟着音乐变化。", "target_word": "力度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "力度|名词|力量的大小或做事的强度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aca22b7-8bcd-478e-9e3a-da6f3d17cd93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10785, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力度", "is_correct": true, "explanation": "正确：“力度”指音乐中声音的强弱，与“速度、表情记号”并列相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不属于音乐的强弱记号，与“速度、表情记号”并列不合。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指线段或物体的长短，不是音乐的强弱记号。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不与“速度、表情记号”并列，乐谱记号中不说“价格”。"}], "explanations": {"力度": "正确：“力度”指音乐中声音的强弱，与“速度、表情记号”并列相合。", "颜色": "语义：“颜色”不属于音乐的强弱记号，与“速度、表情记号”并列不合。", "长度": "语义：“长度”指线段或物体的长短，不是音乐的强弱记号。", "价格": "搭配：“价格”不与“速度、表情记号”并列，乐谱记号中不说“价格”。"}, "sentence_index": 0, "correct_answer": "力度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的力度很慢。", "explanation": "这里应该用〈速度〉。“力度”说声音的强弱，说快慢要用“速度”。"}, {"text": "我今天很累，一点力度也没有。", "explanation": "这里应该用〈力气〉。人身体的劲儿要说“力气”；“力度”指用力的大小或做事的强度，不说“没有力度”来表示没劲。"}, {"text": "今天的天气很热，力度很高。", "explanation": "这里应该用〈温度〉。“力度”指力量的大小或做事的强度，不用来说气温的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力度", "is_correct": true, "explanation": "正确：“力度”指声音的强弱，与“弹到高潮时，……越来越强”相合。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”说快慢，不用“强”形容，“速度越来越强”不合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，与弹到高潮时的音乐表现无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人的重量，与弹到高潮时的音乐表现无关。"}], "explanations": {"力度": "正确：“力度”指声音的强弱，与“弹到高潮时，……越来越强”相合。", "速度": "搭配：“速度”说快慢，不用“强”形容，“速度越来越强”不合。", "身高": "语义：“身高”指人的高矮，与弹到高潮时的音乐表现无关。", "体重": "语义：“体重”指人的重量，与弹到高潮时的音乐表现无关。"}, "sentence_index": 6, "correct_answer": "力度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大楼的力度很惊人。", "explanation": "这里应该用〈高度〉。“力度”指力量的大小或做事的强度，不用来说建筑的高低。"}, {"text": "这个房间的力度太低了。", "explanation": "这里应该用〈亮度〉。“力度”不用来说光线的明暗，光线的强弱要用“亮度”。"}, {"text": "这张照片的力度很高。", "explanation": "这里应该用〈清晰度〉。“力度”不用来说图像的清楚程度，照片清不清楚要用“清晰度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演奏者要加大一只力度。", "corrected_sentence": "演奏者要加大力度。", "error_description": "量词误用：“力度”是抽象名词，不能配“只”（“只”多用于动物或成对的东西）；应去掉“一只”，说“要加大力度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乐队在第二段突然加大了一只力度。", "corrected_sentence": "乐队在第二段突然加大了力度。", "error_description": "量词错误：“力度”是抽象名词，不能用“只”；“只”多用于动物或成对的东西，这里应直接说“加大了力度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
