INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10786, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "音乐演奏中节拍的快慢程度", "primary_collocate": null, "pronunciation": "sù dù", "ipa": "su˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这首歌的速度很慢，很适合睡前听。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师要我们按节拍器的速度弹这首曲子。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段音乐开始时速度很慢，后来越来越快。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐谱上标着这首曲子的速度。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演奏时速度不稳，整首曲子就不好听。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指挥把乐队演奏的速度放慢了一点。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首舞曲的速度快，大家跳得很开心。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练琴时先慢慢弹，等熟了再加快速度。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鼓手的速度突然变快，歌曲更热闹了。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首摇滚歌的速度是每分钟一百二十拍。", "target_word": "速度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "速度记号", "label": "复合"}], "register": "中性", "sense_fingerprint": "音乐演奏的节拍快慢，即乐曲的速度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 节拍 (Zipf 3.34), 这首 (Zipf 3.83), 曲子 (Zipf 3.63)','sentence 3 above tier T1: 3 words above tier T1 (max 2): 乐谱 (Zipf 3.28), 这首 (Zipf 3.83), 曲子 (Zipf 3.63)']::text[], '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "正确答案。“这首歌的速度很慢”指节拍的快慢，与“适合睡前听”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用“很慢”来形容，句子不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是歌曲的属性，“这首歌的价格很慢”说不通。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“很慢”不能用来形容高度，高度应说“高”或“低”。"}], "explanations": {"速度": "正确答案。“这首歌的速度很慢”指节拍的快慢，与“适合睡前听”相符。", "颜色": "语义：颜色不能用“很慢”来形容，句子不通。", "价格": "语义：价格不是歌曲的属性，“这首歌的价格很慢”说不通。", "高度": "搭配：“很慢”不能用来形容高度，高度应说“高”或“低”。"}, "sentence_index": 0, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首曲子的速度很美，钢琴的音色很好听。", "explanation": "这里应该用〈音色〉。速度指节拍的快慢，不能用来形容音色的美丑。"}, {"text": "这首歌的速度很响，大家都听得清楚。", "explanation": "这里应该用〈音量〉。速度指节拍的快慢，不能用来说明声音的强弱。"}, {"text": "这首曲子从头到尾的速度是三十分钟。", "explanation": "这里应该用〈时长〉。速度指节拍快慢，整首曲子的长短要用时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "正确答案。“这首舞曲的速度快”指节拍快，与“大家跳得很开心”相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用“快”来形容，句子不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量不是乐曲的属性，“这首舞曲的重量快”说不通。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“快”不能用来形容字数，句子不通。"}], "explanations": {"速度": "正确答案。“这首舞曲的速度快”指节拍快，与“大家跳得很开心”相符。", "味道": "语义：味道不能用“快”来形容，句子不通。", "重量": "语义：重量不是乐曲的属性，“这首舞曲的重量快”说不通。", "字数": "搭配：“快”不能用来形容字数，句子不通。"}, "sentence_index": 6, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首摇滚歌的速度很重，唱起来很费力。", "explanation": "这里应该用〈重量〉。速度指节拍的快慢，不能用来说轻重。"}, {"text": "这张唱片的速度很贵，我买不起。", "explanation": "这里应该用〈价格〉。速度指节拍的快慢，买东西的贵贱要说价格。"}, {"text": "这首曲子的速度是小提琴，很好听。", "explanation": "这里应该用〈乐器〉。速度指节拍的快慢，不能说成乐器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把演奏的把速度加快了。", "corrected_sentence": "他把演奏的速度加快了。", "error_description": "错误：「把」在句中只能用一次，且要紧接在处置对象之前，这里多用了一个「把」。正确：去掉多余的「把」，写作「他把演奏的速度加快了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "指挥让乐队把速度把放慢了。", "corrected_sentence": "指挥让乐队把速度放慢了。", "error_description": "错误：「把」只能用一次，这里「速度」之后又多用了一个「把」。正确：去掉后面多余的「把」，写作「指挥让乐队把速度放慢了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
