INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10787, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10787, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过面部肌肉活动呈现出的神态，如高兴、悲伤、惊讶等。", "primary_collocate": null, "pronunciation": "biǎo qíng", "ipa": "piɑu˨˩˦ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "巴洛克时代，通奏低音记谱法的流行进一步体现了功能和声观念的成熟；而从古典到浪漫主义时期，记谱日益趋向全面控制，力度、速度、表情记号密集出现，反映出个体情感表达在音乐中的中心地位。", "target_word": "表情", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "她看到礼物，脸上露出高兴的表情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的表情很严肃，大家都不敢说话。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，妈妈的表情变了。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做了错事，脸上是害怕的表情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员用丰富的表情表现出了人物的心情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不出他是什么表情，因为他戴着口罩。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，请大家笑一笑，换个表情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗好像也有可爱的表情。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师吃惊的表情让同学们笑了。", "target_word": "表情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表情包", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "表情|名词|面部肌肉活动呈现的神态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aca22b7-8bcd-478e-9e3a-da6f3d17cd93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "正确：“表情记号”是乐谱上表示情绪表达的记号，与“力度、速度”并列。"}, {"text": "天气", "is_correct": false, "explanation": "语义：乐谱上没有“天气记号”，与“力度、速度”并列不合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与乐谱记号无关，不能与“力度、速度”并列。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指人体高矮胖瘦，不是乐谱记号。"}], "explanations": {"表情": "正确：“表情记号”是乐谱上表示情绪表达的记号，与“力度、速度”并列。", "天气": "语义：乐谱上没有“天气记号”，与“力度、速度”并列不合。", "价格": "语义：“价格”与乐谱记号无关，不能与“力度、速度”并列。", "身材": "语义：“身材”指人体高矮胖瘦，不是乐谱记号。"}, "sentence_index": 0, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家的表情一直很稳定。", "explanation": "这里应该用〈形势〉。国家的局面要说形势；表情指脸上的神态，不能用来形容局面。"}, {"text": "他买了一件新的表情。", "explanation": "这里应该用〈衣服〉。“一件”配衣服，“表情”指脸上的神态，不能用来说衣物。"}, {"text": "我对这次旅行的表情很深。", "explanation": "这里应该用〈感受〉。对经历的体会要说感受；表情指脸上的神态，不能说“表情很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表情", "is_correct": true, "explanation": "正确：句中“看不出”与“戴着口罩”指向被遮住的脸部神态，“表情”符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：人不说“是什么天气”，与“看不出他”的对象也不符。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”指快慢，“是什么速度”说不通，与看人的神态无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“是什么颜色”一般不用来问人的神情，口罩也与颜色无关。"}], "explanations": {"表情": "正确：句中“看不出”与“戴着口罩”指向被遮住的脸部神态，“表情”符合语境。", "天气": "语义：人不说“是什么天气”，与“看不出他”的对象也不符。", "速度": "语义：“速度”指快慢，“是什么速度”说不通，与看人的神态无关。", "颜色": "语义：“是什么颜色”一般不用来问人的神情，口罩也与颜色无关。"}, "sentence_index": 6, "correct_answer": "表情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生检查后，给病人开了一个表情。", "explanation": "这里应该用〈药方〉。“开”搭配药方，“表情”指脸上的神态，不能开给病人。"}, {"text": "她对这座城市有很深的表情。", "explanation": "这里应该用〈感情〉。对地方的情意要说感情；表情指脸上的神态。"}, {"text": "我们把数据填在一张表情里。", "explanation": "这里应该用〈表格〉。填写数据的纸要说表格；表情指脸上的神态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她看着我，脸上带着一只生气的表情。", "corrected_sentence": "她看着我，脸上带着一种生气的表情。", "error_description": "量词用错：“表情”应配“种”或“副”，不能配“只”。应说“一种生气的表情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他读完信，一只表情一下子变了。", "corrected_sentence": "他读完信，表情一下子变了。", "error_description": "量词误用：“表情”不能配“只”（“只”多用于动物或成对的东西）；应去掉“一只”，说“表情一下子变了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
