INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10788, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为帮助识别、记忆或传递信息而制作的特定符号或标记。", "primary_collocate": null, "pronunciation": "jì hao", "ipa": "tɕi˥˩ xaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "巴洛克时代，通奏低音记谱法的流行进一步体现了功能和声观念的成熟；而从古典到浪漫主义时期，记谱日益趋向全面控制，力度、速度、表情记号密集出现，反映出个体情感表达在音乐中的中心地位。", "target_word": "记号", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "书上有老师画的红色记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在地图上做了一个记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐谱上的记号表示这里要弹得轻一点。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在树上刻了记号，免得迷路。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到门上的记号，我就知道是他家。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，她用笔在重点旁边做记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的这个记号表示前面有危险。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李箱上有一个小记号，很好认。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在不懂的地方打个记号。", "target_word": "记号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "记号笔", "label": "复合"}, {"form": "記號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为识别、记忆或传递信息而做的符号、标记，如乐谱上的记号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aca22b7-8bcd-478e-9e3a-da6f3d17cd93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "记号", "is_correct": true, "explanation": "正确：“表情记号”是乐谱上的符号，与“力度、速度”记号并列。"}, {"text": "价格", "is_correct": false, "explanation": "语义：乐谱上不标“价格”，“表情价格”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，不是乐谱上的符号。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体占的空间，不是乐谱上的符号。"}], "explanations": {"记号": "正确：“表情记号”是乐谱上的符号，与“力度、速度”记号并列。", "价格": "语义：乐谱上不标“价格”，“表情价格”说不通。", "身高": "语义：“身高”指人的高矮，不是乐谱上的符号。", "体积": "语义：“体积”指物体占的空间，不是乐谱上的符号。"}, "sentence_index": 0, "correct_answer": "记号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这件事的记号写成了一篇文章。", "explanation": "这里应该用〈经过〉。事情发生的过程要说经过；记号指标记，不能写成文章。"}, {"text": "一位记号在现场采访了市长。", "explanation": "这里应该用〈记者〉。在现场采访的人要说记者；记号指标记。"}, {"text": "他的记号很高，同学们都很羡慕。", "explanation": "这里应该用〈身高〉。“记号”指标记，不能用来说人的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记号", "is_correct": true, "explanation": "正确：“做记号”指在重点旁边作标记，符合考前划重点的语境。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：考前用笔在重点旁做的是标记，不是食物。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“做”不搭配“风景”，要说“画风景”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的分量，不能与“做”搭配，也与重点无关。"}], "explanations": {"记号": "正确：“做记号”指在重点旁边作标记，符合考前划重点的语境。", "蛋糕": "语义：考前用笔在重点旁做的是标记，不是食物。", "风景": "搭配：“做”不搭配“风景”，要说“画风景”。", "体重": "语义：“体重”指身体的分量，不能与“做”搭配，也与重点无关。"}, "sentence_index": 6, "correct_answer": "记号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真整理工作记号。", "explanation": "这里应该用〈记录〉。整理的是文字或数据的记载，要说记录；记号指标记。"}, {"text": "他忘带了护照和记号。", "explanation": "这里应该用〈证件〉。护照、身份证之类要说证件；记号指标记，不能拿来当证件用。"}, {"text": "她记下了朋友的电话记号。", "explanation": "这里应该用〈号码〉。电话上的数字要说号码，记号指标记。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在试卷上画了一只记号。", "corrected_sentence": "老师在试卷上画了一个记号。", "error_description": "量词用错：“记号”应配“个”，不能配“只”。应说“一个记号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在书的边上做了一只记号。", "corrected_sentence": "她在书的边上做了一个记号。", "error_description": "量词误用：“记号”应配“个”，不能配“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10789, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稀疏", "is_correct": true, "explanation": "正确：稀疏指数量少、间隔大，与“密集”正相反。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地不硬，和“密集”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度快，和“密集”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线充足，和“密集”没有反义关系。"}], "correct_answer": "稀疏", "explanations": {"稀疏": "正确：稀疏指数量少、间隔大，与“密集”正相反。", "柔软": "柔软形容质地不硬，和“密集”没有反义关系。", "迅速": "迅速形容速度快，和“密集”没有反义关系。", "明亮": "明亮形容光线充足，和“密集”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10789, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稀疏", "is_correct": true, "explanation": "正确：稀疏指数量少、间隔大，与“密集”正相反。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地不硬，和“密集”没有反义关系。"}, {"text": "轻快", "is_correct": false, "explanation": "轻快形容动作或节奏灵活，和“密集”没有反义关系。"}, {"text": "灿烂", "is_correct": false, "explanation": "灿烂形容光彩耀眼，和“密集”没有反义关系。"}], "correct_answer": "稀疏", "explanations": {"稀疏": "正确：稀疏指数量少、间隔大，与“密集”正相反。", "柔软": "柔软形容质地不硬，和“密集”没有反义关系。", "轻快": "轻快形容动作或节奏灵活，和“密集”没有反义关系。", "灿烂": "灿烂形容光彩耀眼，和“密集”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10789, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指人或事物在较小的空间内数量很多、挨得很近；也指在较短的时间内接连出现得很多。", "primary_collocate": null, "pronunciation": "mì jí", "ipa": "mi˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "巴洛克时代，通奏低音记谱法的流行进一步体现了功能和声观念的成熟；而从古典到浪漫主义时期，记谱日益趋向全面控制，力度、速度、表情记号密集出现，反映出个体情感表达在音乐中的中心地位。", "target_word": "密集", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个地区人口很密集，到处都是房子。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上乌云密集，马上就要下雨了。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨点密集地打在窗户上。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市中心的商店非常密集，走几步就有一家。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天会议密集，他每天都很忙。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站里人群密集，请大家小心。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树林里的树太密集，阳光照不进来。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞭炮声密集地响起来，新年到了。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前一周，复习课排得很密集。", "target_word": "密集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "密集型", "label": "复合"}, {"form": "人口密集", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或事物在小范围内数量多、靠得近、集中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aca22b7-8bcd-478e-9e3a-da6f3d17cd93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10789, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "密集", "is_correct": true, "explanation": "正确：密集（mì jí）指许多东西或人挤在一起，靠得很近。"}, {"text": "密技", "is_correct": false, "explanation": "密技（mì jì）只是第二个音节的声调不同，意思是秘密的技巧，和“密集”不是一回事。"}, {"text": "密计", "is_correct": false, "explanation": "密计（mì jì）与 jí 的声调不同，意思是秘密的计策，不是“挤在一起”。"}, {"text": "秘计", "is_correct": false, "explanation": "秘计（mì jì）的第二个音节声调与 jí 不同，意思是秘密的计谋。"}], "explanations": {"密集": "正确：密集（mì jí）指许多东西或人挤在一起，靠得很近。", "密技": "密技（mì jì）只是第二个音节的声调不同，意思是秘密的技巧，和“密集”不是一回事。", "密计": "密计（mì jì）与 jí 的声调不同，意思是秘密的计策，不是“挤在一起”。", "秘计": "秘计（mì jì）的第二个音节声调与 jí 不同，意思是秘密的计谋。"}, "sentence_index": null, "correct_answer": "密集"}, "level_3": {"options": [{"text": "密集", "is_correct": true, "explanation": "正确：“密集出现”表示符号一个接一个地出现，和“全面控制”的语境相符。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”表示数量少，与“全面控制、记号大量出现”的语境相反。"}, {"text": "孤单", "is_correct": false, "explanation": "语义：“孤单”形容一个人的状态，不能用来形容记号的出现方式。"}, {"text": "迟缓", "is_correct": false, "explanation": "搭配：“迟缓”多修饰动作或进度，不能修饰记号出现的方式。"}], "explanations": {"密集": "正确：“密集出现”表示符号一个接一个地出现，和“全面控制”的语境相符。", "稀少": "语义：“稀少”表示数量少，与“全面控制、记号大量出现”的语境相反。", "孤单": "语义：“孤单”形容一个人的状态，不能用来形容记号的出现方式。", "迟缓": "搭配：“迟缓”多修饰动作或进度，不能修饰记号出现的方式。"}, "sentence_index": 0, "correct_answer": "密集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的注意力很密集，什么都听不进去。", "explanation": "这里应该用〈集中〉。注意力、思想要用集中，密集只指许多东西或人挤在一起。"}, {"text": "我和爸爸的关系很密集，常常一起玩。", "explanation": "这里应该用〈密切〉。关系、联系要用密切，密集不能用来形容人与人之间的关系。"}, {"text": "这把椅子很密集，坐上去很舒服。", "explanation": "这里应该用〈结实〉。密集指许多东西或人挤在一起，不能形容一把椅子；形容单件家具牢固要用结实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密集", "is_correct": true, "explanation": "正确：“车站里人群密集”指很多人挤在一起，请大家小心，正好说明情况。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”形容水或眼神等清亮透明，不能形容人群。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容孤单、没有人陪，和车站里人多的情况相反。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容人的体格或东西的坚固，不能用来形容一群人挤在一起。"}], "explanations": {"密集": "正确：“车站里人群密集”指很多人挤在一起，请大家小心，正好说明情况。", "清澈": "语义：“清澈”形容水或眼神等清亮透明，不能形容人群。", "寂寞": "语义：“寂寞”形容孤单、没有人陪，和车站里人多的情况相反。", "结实": "搭配：“结实”形容人的体格或东西的坚固，不能用来形容一群人挤在一起。"}, "sentence_index": 6, "correct_answer": "密集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她和朋友的感情很密集，常常一起玩。", "explanation": "这里应该用〈亲密〉。感情、关系要用亲密，密集只指许多东西或人挤在一起。"}, {"text": "这条河的水很密集，能看到河底的小石头。", "explanation": "这里应该用〈清〉。密集指许多东西挤在一起，不能形容水是否透明；水能看到底要用清。"}, {"text": "这锅粥很密集，勺子都插不进去。", "explanation": "这里应该用〈稠〉。密集指许多东西挤在一起，不能形容液体的浓厚；粥很浓、勺子插不进去要用稠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城里的书店得密集，走几步就有一家。", "corrected_sentence": "城里的书店很密集，走几步就有一家。", "error_description": "用词错：程度副词“很”误写成“得”。“得”只用在形容词后面做补语（如“密集得很”），修饰形容词“密集”要用“很”，应说“很密集”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街角有一排密集地小店，都是卖早点的。", "corrected_sentence": "街角有一排密集的小店，都是卖早点的。", "error_description": "结构错误：“密集”修饰名词“小店”时要用“的”，写成“密集地小店”不对。正确说法是“密集的小店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9527cb-acc3-410d-bedc-4a364913f683') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10792, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "边缘", "is_correct": true, "explanation": "正确：“边缘”指事物的外缘，与“中心”相对，是其反义词。"}, {"text": "颜色", "is_correct": false, "explanation": "非反义：“颜色”指事物的色彩，与“中心”不构成反义关系。"}, {"text": "开端", "is_correct": false, "explanation": "非反义：“开端”指事情的开始，与位置或核心部分无关。"}, {"text": "枝叶", "is_correct": false, "explanation": "非反义：“枝叶”指植物的枝和叶，与“中心”不构成反义关系。"}], "correct_answer": "边缘", "explanations": {"边缘": "正确：“边缘”指事物的外缘，与“中心”相对，是其反义词。", "颜色": "非反义：“颜色”指事物的色彩，与“中心”不构成反义关系。", "开端": "非反义：“开端”指事情的开始，与位置或核心部分无关。", "枝叶": "非反义：“枝叶”指植物的枝和叶，与“中心”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10792, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "边缘", "is_correct": true, "explanation": "正确：“边缘”指事物的外缘，与“中心”相对，是其反义词。"}, {"text": "味道", "is_correct": false, "explanation": "非反义：“味道”指食物或物质给人的感觉，与“中心”不构成反义关系。"}, {"text": "尾声", "is_correct": false, "explanation": "非反义：“尾声”指结束部分，与位置或核心部分的对立无关。"}, {"text": "声音", "is_correct": false, "explanation": "非反义：“声音”指声响，与“中心”不构成反义关系。"}], "correct_answer": "边缘", "explanations": {"边缘": "正确：“边缘”指事物的外缘，与“中心”相对，是其反义词。", "味道": "非反义：“味道”指食物或物质给人的感觉，与“中心”不构成反义关系。", "尾声": "非反义：“尾声”指结束部分，与位置或核心部分的对立无关。", "声音": "非反义：“声音”指声响，与“中心”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10792, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指跟四周距离相等的位置，或事物的核心部分。", "primary_collocate": null, "pronunciation": "zhōng xīn", "ipa": "/ʈ͡ʂʊŋ˥ ɕin˥/", "syllable_count": 2, "sentences": [{"text": "圆的中心有一个小点。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把桌子放在房间的中心。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题是我们讨论的中心。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "操场的中心画着一个大圆圈。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖的中心有一座小岛。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师站在圆圈的中心。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的中心很清楚。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把球放在了桌子的中心。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议的中心是学习新方法。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的红点是圆的中心。", "target_word": "中心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "中心点", "label": "复合"}], "register": "中性", "sense_fingerprint": "与四周距离相等的位置；事物最核心的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f59b8ca-db7c-451b-a6bc-df6abcd7de58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10792, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中心", "is_correct": true, "explanation": "正确：zhōng xīn，指与四周距离相等的位置，或事物最核心的部分。"}, {"text": "重心", "is_correct": false, "explanation": "声调不同：重心 zhòng xīn 首字为第四声，中心 zhōng xīn 首字为第一声，意思是物体重量集中的点，不是中心。"}, {"text": "中兴", "is_correct": false, "explanation": "韵尾不同：zhōng xīng（ng）与 zhōng xīn（n），意思是国家或事业再度兴盛，不是中心。"}, {"text": "中音", "is_correct": false, "explanation": "声母不同：yīn 与 xīn（零声母与 x），意思是声乐中的中等音域，不是中心。"}], "explanations": {"中心": "正确：zhōng xīn，指与四周距离相等的位置，或事物最核心的部分。", "重心": "声调不同：重心 zhòng xīn 首字为第四声，中心 zhōng xīn 首字为第一声，意思是物体重量集中的点，不是中心。", "中兴": "韵尾不同：zhōng xīng（ng）与 zhōng xīn（n），意思是国家或事业再度兴盛，不是中心。", "中音": "声母不同：yīn 与 xīn（零声母与 x），意思是声乐中的中等音域，不是中心。"}, "sentence_index": null, "correct_answer": "中心"}, "level_3": {"options": [{"text": "中心", "is_correct": true, "explanation": "正确：“圆的中心”指圆上与四周距离相等的位置，与句意相符。"}, {"text": "顶点", "is_correct": false, "explanation": "搭配：“顶点”多说三角形、锥体等有棱角的图形，圆没有顶点，不能说“圆的顶点”。"}, {"text": "角落", "is_correct": false, "explanation": "语义：圆是没有角的图形，“角落”与圆的形状相矛盾。"}, {"text": "尖端", "is_correct": false, "explanation": "体貌：“尖端”描述尖细的外形，与圆的浑圆形状不符。"}], "explanations": {"中心": "正确：“圆的中心”指圆上与四周距离相等的位置，与句意相符。", "顶点": "搭配：“顶点”多说三角形、锥体等有棱角的图形，圆没有顶点，不能说“圆的顶点”。", "角落": "语义：圆是没有角的图形，“角落”与圆的形状相矛盾。", "尖端": "体貌：“尖端”描述尖细的外形，与圆的浑圆形状不符。"}, "sentence_index": 0, "correct_answer": "中心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家装了一台中心空调，夏天很凉快。", "explanation": "这里应该用〈中央〉。固定说法是“中央空调”，“中心”不修饰空调。"}, {"text": "这家公司掌握了中心技术，产品很有竞争力。", "explanation": "这里应该用〈核心〉。“核心技术”是固定说法，“中心技术”不这么用。"}, {"text": "这些水果要通过中心商才能运到市场。", "explanation": "这里应该用〈中间〉。“中间商”指买卖之间的中介人，“中心商”不成词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中心", "is_correct": true, "explanation": "正确：“文章的中心”指文章的中心思想，与“很清楚”搭配，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：文章没有体重，“体重”只用于人或动物。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般说人的岁数，不能用来描述文章。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描述人的高矮，文章没有身高这一外形。"}], "explanations": {"中心": "正确：“文章的中心”指文章的中心思想，与“很清楚”搭配，符合句意。", "体重": "语义：文章没有体重，“体重”只用于人或动物。", "年龄": "搭配：“年龄”一般说人的岁数，不能用来描述文章。", "身高": "体貌：“身高”描述人的高矮，文章没有身高这一外形。"}, "sentence_index": 6, "correct_answer": "中心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约在下午的中心见面，别迟到了。", "explanation": "这里的“中心”指时间上的正中，而“中心”只指空间位置或事物的核心部分，不能指时间的中点。"}, {"text": "这个问题很中心，我们得先解决。", "explanation": "“中心”是名词，不能直接受副词“很”修饰表示程度；这里要表达“重要”，应说“很重要”。"}, {"text": "他总是中心地反对我的意见。", "explanation": "“中心”不表示态度的坚决，不能作状语修饰动词“反对”，应说“坚决地反对”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个圆有一条明显的中心。", "corrected_sentence": "这个圆有一个明显的中心。", "error_description": "量词错误：“中心”指一个点，应用量词“个”，不能用“条”（条多用于长条形事物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们湖的中心划船。", "corrected_sentence": "我们在湖的中心划船。", "error_description": "介词错误：表示处所的“在”不能省，“湖的中心”前应加“在”，应为“在湖的中心划船”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fa8a26-880d-4df8-ae49-30b93720d2b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10794, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升", "is_correct": true, "explanation": "反义：「升」指向上移动，与「从高处向低处移动」的「降」相对，如升旗与降旗。"}, {"text": "唱", "is_correct": false, "explanation": "与「降」在任何义项上都不构成反义，只是同为动词。"}, {"text": "读", "is_correct": false, "explanation": "与「降」在任何义项上都不构成反义，只是同为动词。"}, {"text": "吃", "is_correct": false, "explanation": "与「降」在任何义项上都不构成反义，只是同为动词。"}], "correct_answer": "升", "explanations": {"升": "反义：「升」指向上移动，与「从高处向低处移动」的「降」相对，如升旗与降旗。", "唱": "与「降」在任何义项上都不构成反义，只是同为动词。", "读": "与「降」在任何义项上都不构成反义，只是同为动词。", "吃": "与「降」在任何义项上都不构成反义，只是同为动词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
