INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从高处向低处移动。", "primary_collocate": null, "pronunciation": "jiàng", "ipa": "tɕjɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "雪花从天上慢慢降到了地上。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跳伞的人慢慢降到了田野里。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快到机场了，飞机慢慢降到了三千米。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天太热了，请把车窗降下来一点。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯从十楼一直降到了一楼。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳下山了，学校的国旗要降下来。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出结束了，舞台上的幕布慢慢降下来。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气球里的气漏了，它慢慢降到了地上。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直升机在草地上空转了一圈，然后降到了地面。", "target_word": "降", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人按了按钮，吊篮慢慢降到了地上。", "target_word": "降", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "降了", "label": "体标（了）"}, {"form": "降过", "label": "体标（过）"}, {"form": "降落", "label": "复合词"}, {"form": "下降", "label": "复合词"}], "register": "中性", "sense_fingerprint": "物体从高处向低处移动、落下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa6fc4b-3b94-4372-8dfa-3cb1d7e50379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10794, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "降", "is_correct": true, "explanation": "正确：听到的 jiàng（第四声）即「降」，意思是从高处向低处移动。"}, {"text": "讲", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是讲话。"}, {"text": "江", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是江河。"}, {"text": "健", "is_correct": false, "explanation": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是健康。"}, {"text": "姜", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是生姜。"}], "explanations": {"降": "正确：听到的 jiàng（第四声）即「降」，意思是从高处向低处移动。", "讲": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是讲话。", "江": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是江河。", "健": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是健康。", "姜": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是生姜。"}, "sentence_index": null, "correct_answer": "降"}, "level_3": {"options": [{"text": "降", "is_correct": true, "explanation": "正确：雪花从高处向低处移动，「降到地上」与句意相符。"}, {"text": "停", "is_correct": false, "explanation": "搭配：「停」表示停止，雪花向地面落下不能说「停到地上」。"}, {"text": "跑", "is_correct": false, "explanation": "语义：雪花不会「跑」，与从天上缓慢落下的语境不符。"}, {"text": "写", "is_correct": false, "explanation": "语义：雪花不是被「写」到地上的，句子说不通。"}], "explanations": {"降": "正确：雪花从高处向低处移动，「降到地上」与句意相符。", "停": "搭配：「停」表示停止，雪花向地面落下不能说「停到地上」。", "跑": "语义：雪花不会「跑」，与从天上缓慢落下的语境不符。", "写": "语义：雪花不是被「写」到地上的，句子说不通。"}, "sentence_index": 0, "correct_answer": "降"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "皇帝降旨免除了这一年的赋税。", "explanation": "这里的「降」读 jiàng，意思是下达（命令），不是「从高处向低处移动」的意思。"}, {"text": "小宝宝降生在一个冬天的早晨。", "explanation": "这里的「降」指出生，是另一种用法，不是「从高处向低处移动」的意思。"}, {"text": "城里的守军最后只好投降了。", "explanation": "这里的「降」读 xiáng，意思是服输、投降，不是「从高处向低处移动」的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10794, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "降", "is_correct": true, "explanation": "正确：听到的 jiàng（第四声）即「降」，意思是从高处向低处移动。"}, {"text": "奖", "is_correct": false, "explanation": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是奖励。"}, {"text": "将", "is_correct": false, "explanation": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是将要、将来。"}, {"text": "剑", "is_correct": false, "explanation": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是剑。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是看见。"}], "explanations": {"降": "正确：听到的 jiàng（第四声）即「降」，意思是从高处向低处移动。", "奖": "jiǎng（第三声）与 jiàng（第四声）声调不同，意思是奖励。", "将": "jiāng（第一声）与 jiàng（第四声）声调不同，意思是将要、将来。", "剑": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是剑。", "见": "jiàn 与 jiàng 韵母不同（an 与 ang），意思是看见。"}, "sentence_index": null, "correct_answer": "降"}, "level_3": {"options": [{"text": "降", "is_correct": true, "explanation": "正确：幕布从舞台上方向下移动，「慢慢降下来」与演出结束的语境相符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」表示抹去，幕布不是被擦下来的，句子说不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：幕布不会被「洗」下来，与缓慢落下的语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能用于描述幕布的动作，与「幕布慢慢……下来」不搭配。"}], "explanations": {"降": "正确：幕布从舞台上方向下移动，「慢慢降下来」与演出结束的语境相符。", "擦": "搭配：「擦」表示抹去，幕布不是被擦下来的，句子说不通。", "洗": "语义：幕布不会被「洗」下来，与缓慢落下的语境不符。", "唱": "搭配：「唱」不能用于描述幕布的动作，与「幕布慢慢……下来」不搭配。"}, "sentence_index": 6, "correct_answer": "降"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "黑夜降临了整个村庄。", "explanation": "这里的「降」读 jiàng，意思是来到、落到，不是「从高处向低处移动」的意思。"}, {"text": "她终于降服了那只烈性的猎犬。", "explanation": "这里的「降」读 xiáng，意思是使……服从，不是「从高处向低处移动」的意思。"}, {"text": "他因为工作失误被降职到了基层。", "explanation": "这里的「降」指降低职位，是抽象的另一种用法，不是「从高处向低处移动」的空间意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吊篮慢慢降上去了。", "corrected_sentence": "吊篮慢慢降下来了。", "error_description": "方向补语错误：「降」表示由高向低，应接「下来」；「上去」表示向上，与「降」的意思相矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "热气球慢慢降了到草地上。", "corrected_sentence": "热气球慢慢降到了草地上。", "error_description": "了的位置错误：「了」应放在补语「到」之后，即「降到了草地上」，不能插在「降」和「到」之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
