INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学是研究数量、结构、变化和空间等概念的学科。", "primary_collocate": null, "pronunciation": "shù xué", "ipa": "ʂu˥˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "数学是研究数量和空间的学科。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多科学都需要用到数学。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就对数学很感兴趣。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好数学需要多做练习。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师每天都要用数学计算尺寸。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学学的是数学，现在当老师。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学里的公式很难记。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的数学帮人们计算土地的面积。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学和物理常常有很深的关系。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授一辈子研究数学。", "target_word": "数学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "數學", "label": "繁体"}, {"form": "数学家", "label": "复合"}, {"form": "数学课", "label": "复合"}], "register": "中性", "sense_fingerprint": "研究数量、结构、变化和空间的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '935c507d-9a1e-4188-bb8e-3e75cd8aa9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10808, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数学", "is_correct": true, "explanation": "数学（shù xué）：句中所指的学科。"}, {"text": "输血", "is_correct": false, "explanation": "shū 与 shù、xuè 与 xué 声调都不同，输血指把血液输入人体。"}, {"text": "入学", "is_correct": false, "explanation": "rù 与 shù 声母不同（r 与 sh），入学指进入学校。"}, {"text": "助学", "is_correct": false, "explanation": "zhù 与 shù 声母不同（zh 与 sh），助学指帮助学生求学。"}, {"text": "失学", "is_correct": false, "explanation": "shī 与 shù 韵母不同（ī 与 ù）且声调不同，失学指失去上学的机会。"}], "explanations": {"数学": "数学（shù xué）：句中所指的学科。", "输血": "shū 与 shù、xuè 与 xué 声调都不同，输血指把血液输入人体。", "入学": "rù 与 shù 声母不同（r 与 sh），入学指进入学校。", "助学": "zhù 与 shù 声母不同（zh 与 sh），助学指帮助学生求学。", "失学": "shī 与 shù 韵母不同（ī 与 ù）且声调不同，失学指失去上学的机会。"}, "sentence_index": null, "correct_answer": "数学"}, "level_3": {"options": [{"text": "数学", "is_correct": true, "explanation": "数学：定义中所指的学科，与“研究数量和空间”相符。"}, {"text": "化学", "is_correct": false, "explanation": "语义：化学研究物质的组成与变化，不研究数量和空间。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐研究的是声音与旋律，不研究数量和空间。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，不用于下定义的正式学科说明。"}], "explanations": {"数学": "数学：定义中所指的学科，与“研究数量和空间”相符。", "化学": "语义：化学研究物质的组成与变化，不研究数量和空间。", "音乐": "语义：音乐研究的是声音与旋律，不研究数量和空间。", "玩意儿": "语域：“玩意儿”是口语，不用于下定义的正式学科说明。"}, "sentence_index": 0, "correct_answer": "数学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个数学太大了，我记不住。", "explanation": "这里应该用〈数字〉。数学指学科，不能用来指具体的数，“这个数学太大”不通。"}, {"text": "这批货的数学很多。", "explanation": "这里应该用〈数量〉。数学指学科，不能用来说一批货物有多少。"}, {"text": "班里学生的数学是四十个。", "explanation": "这里应该用〈数目〉。数学不表示人数，计数要用“数目”或“数量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数学", "is_correct": true, "explanation": "数学：学科名，“数学里的公式”说得通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园里没有公式，“花园里的公式”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是学习公式的地方，“厨房里的公式”句意不通。"}, {"text": "破烂", "is_correct": false, "explanation": "语域：“破烂”是口语贬义词，与“公式很难记”的书面语境不协调。"}], "explanations": {"数学": "数学：学科名，“数学里的公式”说得通。", "花园": "语义：花园里没有公式，“花园里的公式”说不通。", "厨房": "语义：厨房不是学习公式的地方，“厨房里的公式”句意不通。", "破烂": "语域：“破烂”是口语贬义词，与“公式很难记”的书面语境不协调。"}, "sentence_index": 6, "correct_answer": "数学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这学期他选了一块数学。", "explanation": "这里应该用〈门〉。作为学科，数学用“门”计量，“块”用于成块的东西。"}, {"text": "这学期他选了一条数学。", "explanation": "这里应该用〈门〉。学科数学用“门”计量，“条”用于细长的东西。"}, {"text": "他选了一首数学。", "explanation": "这里应该用〈门〉。学科数学用“门”计量，“首”用于诗歌、歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹数学很感兴趣。", "corrected_sentence": "我妹妹对数学很感兴趣。", "error_description": "错误在介词：“感兴趣”的对象要用“对”引出，应为“对数学很感兴趣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一辈子研究很数学。", "corrected_sentence": "他一辈子研究数学。", "error_description": "错误在程度副词：“很”不能修饰学科名词“数学”，应删去“很”。应为“研究数学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
