INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10811, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "先锋派是指在文学、艺术等领域中，勇于创新、打破传统，走在时代最前沿的流派或群体。", "primary_collocate": null, "pronunciation": "xiān fēng pài", "ipa": "ɕjɛn fɤŋ pʰaɪ", "syllable_count": 3, "sentences": [{"text": "与此同时，约翰·凯奇等先锋派作曲家质疑传统记谱的权威性，发展出图形谱、文字谱乃至机会音乐的开放式结构，强调演奏者的再创造权。", "target_word": "先锋派", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位画家是二十世纪的先锋派代表。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先锋派的作品常常让老人看不懂。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年轻时喜欢先锋派电影。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先锋派艺术家不愿意重复前人的路。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家美术馆专门展出先锋派的画。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先锋派打破了传统，也引来很多批评。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，先锋派的诗不太好懂。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先锋派的音乐里，常有奇怪的声音。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个剧团属于先锋派，演出很大胆。", "target_word": "先锋派", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "文学艺术领域中勇于创新、打破传统的流派或群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '935c507d-9a1e-4188-bb8e-3e75cd8aa9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先锋派", "is_correct": true, "explanation": "先锋派：句中所指的、在创新上走在前沿的流派，与“质疑传统记谱”相符。"}, {"text": "古典派", "is_correct": false, "explanation": "语义：古典派崇尚传统，不会质疑传统记谱的权威性。"}, {"text": "保守派", "is_correct": false, "explanation": "语义：保守派拥护既有规范，与“质疑传统记谱”的句意相悖。"}, {"text": "体育", "is_correct": false, "explanation": "搭配：“作曲家”前应接流派或风格，不能说“体育作曲家”。"}], "explanations": {"先锋派": "先锋派：句中所指的、在创新上走在前沿的流派，与“质疑传统记谱”相符。", "古典派": "语义：古典派崇尚传统，不会质疑传统记谱的权威性。", "保守派": "语义：保守派拥护既有规范，与“质疑传统记谱”的句意相悖。", "体育": "搭配：“作曲家”前应接流派或风格，不能说“体育作曲家”。"}, "sentence_index": 0, "correct_answer": "先锋派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们登山队的先锋派，总走在最前面。", "explanation": "这里应该用〈先锋〉。先锋派指文艺上打破传统的流派或群体，不指队伍里带头走在前面的人。"}, {"text": "战斗中，先锋派第一个冲进了城。", "explanation": "这里应该用〈先锋部队〉。先锋派是文艺流派，不指打仗时走在前面的部队。"}, {"text": "他是环保运动的先锋派，第一个站出来呼吁。", "explanation": "这里应该用〈先驱〉。先锋派指文艺上的流派或群体，不指社会运动中带头的个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先锋派", "is_correct": true, "explanation": "先锋派：能够打破传统、发表主张的群体或流派，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气无法打破传统，句意不通。"}, {"text": "鞋子", "is_correct": false, "explanation": "配价：“打破传统”需要有行动能力的施事，“鞋子”不能作施事。"}, {"text": "沙发", "is_correct": false, "explanation": "配价：“打破传统”需要有行动能力的施事，“沙发”不能作施事。"}], "explanations": {"先锋派": "先锋派：能够打破传统、发表主张的群体或流派，与句意相符。", "天气": "语义：天气无法打破传统，句意不通。", "鞋子": "配价：“打破传统”需要有行动能力的施事，“鞋子”不能作施事。", "沙发": "配价：“打破传统”需要有行动能力的施事，“沙发”不能作施事。"}, "sentence_index": 6, "correct_answer": "先锋派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工程师是中国电子工业的先锋派，培养了许多人才。", "explanation": "这里应该用〈先驱〉。先锋派指文艺上打破传统的流派或群体，不指在某个行业里开创事业的人。"}, {"text": "这支球队的先锋派今天状态很好。", "explanation": "这里应该用〈前锋〉。先锋派指文艺上的流派或群体，不指球队里的进攻队员。"}, {"text": "这家公司是手机行业的先锋派，率先推出了折叠屏。", "explanation": "这里应该用〈先锋〉。先锋派指文艺上的流派或群体，不用来形容企业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家属于一幅先锋派。", "corrected_sentence": "这位画家属于先锋派。", "error_description": "错误在量词：“幅”用于画作，不能修饰流派“先锋派”；“属于”后直接接“先锋派”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时参加了过先锋派活动。", "corrected_sentence": "他年轻时参加过先锋派活动。", "error_description": "错误在动态助词：“参加过”的“过”已表示经历，不能再加“了”叠用，应为“参加过先锋派活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
