INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10812, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提出疑问，表示对某人、某事或某种说法的真实性、正确性有怀疑，需要对方做出解释。", "primary_collocate": null, "pronunciation": "zhì yí", "ipa": "ʈʂɻ˥˩ i˧˥", "syllable_count": 2, "sentences": [{"text": "与此同时，约翰·凯奇等先锋派作曲家质疑传统记谱的权威性，发展出图形谱、文字谱乃至机会音乐的开放式结构，强调演奏者的再创造权。", "target_word": "质疑", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "学生们质疑这个数字的来源。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人质疑这份报告的结果。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当面质疑了经理的决定。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者质疑过这家公司的广告。", "target_word": "质疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家质疑他的说法，要他拿出证据。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家质疑这个方案是否安全。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不敢质疑老师的看法。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家长们质疑学校为什么涨价。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人质疑他的能力。", "target_word": "质疑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "质疑了", "label": "体标（了）"}, {"form": "质疑过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "对说法的真实性、正确性提出疑问并要求解释", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '935c507d-9a1e-4188-bb8e-3e75cd8aa9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "质疑", "is_correct": true, "explanation": "质疑：提出疑问，对说法或决定的真实性、正确性表示怀疑。"}, {"text": "制衣", "is_correct": false, "explanation": "yī（第一声）与 yí（第二声）声调不同，制衣的意思是做衣服。"}, {"text": "致意", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，致意的意思是表示问候或敬意。"}, {"text": "执意", "is_correct": false, "explanation": "zhí 与 zhì、yì 与 yí 声调都不同，执意的意思是坚持要做某事。"}, {"text": "事宜", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是有关的具体事务。"}], "explanations": {"质疑": "质疑：提出疑问，对说法或决定的真实性、正确性表示怀疑。", "制衣": "yī（第一声）与 yí（第二声）声调不同，制衣的意思是做衣服。", "致意": "yì（第四声）与 yí（第二声）声调不同，致意的意思是表示问候或敬意。", "执意": "zhí 与 zhì、yì 与 yí 声调都不同，执意的意思是坚持要做某事。", "事宜": "shì 与 zhì 声母不同（sh 与 zh），意思是有关的具体事务。"}, "sentence_index": null, "correct_answer": "质疑"}, "level_3": {"options": [{"text": "维护", "is_correct": false, "explanation": "语义：“维护”表示保卫、守护，与先锋派打破传统的立场相反。"}, {"text": "质疑", "is_correct": true, "explanation": "符合语境：先锋派对传统记谱的权威性提出疑问，与后文发展新的开放式结构相呼应。"}, {"text": "遵守", "is_correct": false, "explanation": "搭配：“遵守”的对象是规定、规则，不能遵守“权威性”这类抽象属性。"}, {"text": "咨询", "is_correct": false, "explanation": "配价：“咨询”的对象应是人或机构，不能咨询“记谱的权威性”。"}], "explanations": {"维护": "语义：“维护”表示保卫、守护，与先锋派打破传统的立场相反。", "质疑": "符合语境：先锋派对传统记谱的权威性提出疑问，与后文发展新的开放式结构相呼应。", "遵守": "搭配：“遵守”的对象是规定、规则，不能遵守“权威性”这类抽象属性。", "咨询": "配价：“咨询”的对象应是人或机构，不能咨询“记谱的权威性”。"}, "sentence_index": 0, "correct_answer": "质疑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直质疑这张桌子。", "explanation": "这里应该用〈检查〉。质疑针对说法或决定的真实性，不能用于桌子这类物品，检查桌子要用〈检查〉。"}, {"text": "他一直质疑这只猫。", "explanation": "这里应该用〈喂养〉。质疑针对说法或决定，不能用于动物，喂养猫要用〈喂养〉。"}, {"text": "大家都质疑这个苹果，说它很甜。", "explanation": "这里应该用〈尝〉。质疑针对说法或决定，不能用于水果，尝苹果的味道要用〈尝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保证", "is_correct": false, "explanation": "语义：“保证”表示肯定地担保，与“是否安全”的疑问语气冲突。"}, {"text": "质疑", "is_correct": true, "explanation": "符合语境：专家对方案的安全性提出疑问，后半句“是否安全”正是疑问的内容。"}, {"text": "赞扬", "is_correct": false, "explanation": "搭配：“赞扬”的对象通常是人或成绩，不能赞扬“方案是否安全”这种疑问。"}, {"text": "推动", "is_correct": false, "explanation": "搭配：“推动”的对象是工作或事业，不能推动一个“是否安全”的疑问。"}], "explanations": {"保证": "语义：“保证”表示肯定地担保，与“是否安全”的疑问语气冲突。", "质疑": "符合语境：专家对方案的安全性提出疑问，后半句“是否安全”正是疑问的内容。", "赞扬": "搭配：“赞扬”的对象通常是人或成绩，不能赞扬“方案是否安全”这种疑问。", "推动": "搭配：“推动”的对象是工作或事业，不能推动一个“是否安全”的疑问。"}, "sentence_index": 6, "correct_answer": "质疑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈一直质疑那盘饺子。", "explanation": "这里应该用〈包〉。质疑针对说法和决定，做饺子要用〈包〉。"}, {"text": "我质疑了这道菜，觉得味道很好。", "explanation": "这里应该用〈品尝〉。质疑不用于菜肴，评价菜的味道要用〈品尝〉。"}, {"text": "他质疑父母度过了晚年。", "explanation": "这里应该用〈陪伴〉。质疑不能用来表示陪伴他人，陪伴父母要用〈陪伴〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他当面质疑了过经理的决定。", "corrected_sentence": "他当面质疑过经理的决定。", "error_description": "“质疑”后的体标“过”表示曾经发生，不能与“了”同时使用。正确说法是“他当面质疑过经理的决定。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "没有人质疑了他的判断。", "corrected_sentence": "没有人质疑过他的判断。", "error_description": "错误在体标：否定句表示未曾发生时用“过”，“没有……了”不成立。应为“没有人质疑过他的判断。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
