INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10813, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指使人信服、信从的力量和威望。", "primary_collocate": null, "pronunciation": "quán wēi xìng", "ipa": "tɕʰɥɛn weɪ ɕiŋ", "syllable_count": 3, "sentences": [{"text": "与此同时，约翰·凯奇等先锋派作曲家质疑传统记谱的权威性，发展出图形谱、文字谱乃至机会音乐的开放式结构，强调演奏者的再创造权。", "target_word": "权威性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这本词典的权威性很高。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家的意见有很强的权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻要有权威性，不能随便写。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个机构的报告很有权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "官方网站的消息更有权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的权威性来自多年的研究。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事让老师失去了权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份杂志在业内很有权威性，大家都听它的意见。", "target_word": "权威性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院的判决具有很高的权威性。", "target_word": "权威性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "使人信服、信从的力量和威望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '935c507d-9a1e-4188-bb8e-3e75cd8aa9b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10813, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数量", "is_correct": false, "explanation": "搭配：“质疑”针对说法或决定，“数量”不能作为质疑的对象。"}, {"text": "权威性", "is_correct": true, "explanation": "符合语境：“质疑传统记谱的权威性”与后文发展新的开放式结构形成对照。"}, {"text": "体积", "is_correct": false, "explanation": "体貌：“体积”描述物体占据的空间大小，记谱的规范不具有体积。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”是人的性情，不能作为“质疑”的对象。"}], "explanations": {"数量": "搭配：“质疑”针对说法或决定，“数量”不能作为质疑的对象。", "权威性": "符合语境：“质疑传统记谱的权威性”与后文发展新的开放式结构形成对照。", "体积": "体貌：“体积”描述物体占据的空间大小，记谱的规范不具有体积。", "脾气": "搭配：“脾气”是人的性情，不能作为“质疑”的对象。"}, "sentence_index": 0, "correct_answer": "权威性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的权威性很高，所以卖得很贵。", "explanation": "这里应该用〈价格〉。权威性指使人信服的力量，衣服的价钱要用〈价格〉。"}, {"text": "这张桌子的权威性很大，不容易坏。", "explanation": "这里应该用〈承重力〉。权威性指使人信服的力量，家具能承受多大重量要用〈承重力〉。"}, {"text": "这只猫的权威性很强，它很会抓老鼠。", "explanation": "这里应该用〈本领〉。权威性指使人信服的力量，动物的捕鼠能力要用〈本领〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形数据，不能来自多年的研究。"}, {"text": "权威性", "is_correct": true, "explanation": "符合语境：后半句“来自多年的研究”说明权威性的来源。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”由市场决定，与“来自多年的研究”不相符。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：“颜色”是外观属性，不能来自多年的研究。"}], "explanations": {"身高": "体貌：“身高”是人的外形数据，不能来自多年的研究。", "权威性": "符合语境：后半句“来自多年的研究”说明权威性的来源。", "价格": "语义：“价格”由市场决定，与“来自多年的研究”不相符。", "颜色": "体貌：“颜色”是外观属性，不能来自多年的研究。"}, "sentence_index": 6, "correct_answer": "权威性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支钢笔的权威性很好，写字很流畅。", "explanation": "这里应该用〈质量〉。权威性指使人信服的力量，钢笔的书写效果要用〈质量〉。"}, {"text": "他的权威性很重，一个人搬不动。", "explanation": "这里应该用〈重量〉。权威性指使人信服的力量，物体的分量要用〈重量〉。"}, {"text": "他的权威性很多，家里的钱都归他。", "explanation": "这里应该用〈财富〉。权威性不可计数，家里的钱财要用〈财富〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家报社的新闻很权威性。", "corrected_sentence": "这家报社的新闻很有权威性。", "error_description": "“很”修饰的是“有权威性”，前面需要动词“有”。正确说法是“这家报社的新闻很有权威性。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位医生的话很有的权威性。", "corrected_sentence": "这位医生的话很有权威性。", "error_description": "“有”后面直接接名词“权威性”，中间不能加助词“的”；“很有的权威性”是错误说法。正确说法是“这位医生的话很有权威性。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021eea96-d955-4674-8e91-7f9be53b1c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
