INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指具有时间性的有利情况；机遇。", "primary_collocate": null, "pronunciation": "jī huì", "ipa": "tɕi˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这是一个难得的好机会。", "target_word": "机会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他抓住机会，开了自己的公司。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在去中国工作，机会很多。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别错过这个机会，明天就没有了。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她等了很久，终于等到了机会。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小城市里的工作机会比较少。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人应该多找机会学习新东西。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司给了我一个很好的机会。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想失去任何一个机会。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好机会不常有，你要想清楚。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "機會", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "次", "label": "量词"}], "register": "中性", "sense_fingerprint": "机会·名词·有时间性的有利时机、机遇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd295e12-7231-4a6a-a8ef-075f24fccda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机会", "is_correct": true, "explanation": "正确。机会指具有时间性的有利情况，读作 jī huì。"}, {"text": "集会", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，集会指人们聚集在一起开会。"}, {"text": "击毁", "is_correct": false, "explanation": "huǐ（第三声）与 huì（第四声）声调不同，击毁指打坏、摧毁。"}, {"text": "几回", "is_correct": false, "explanation": "jǐ 与 jī、huí 与 huì 声调都不同，几回指几次。"}, {"text": "知会", "is_correct": false, "explanation": "zhī 与 jī 声母不同（zh 与 j），知会指通知。"}], "explanations": {"机会": "正确。机会指具有时间性的有利情况，读作 jī huì。", "集会": "jí（第二声）与 jī（第一声）声调不同，集会指人们聚集在一起开会。", "击毁": "huǐ（第三声）与 huì（第四声）声调不同，击毁指打坏、摧毁。", "几回": "jǐ 与 jī、huí 与 huì 声调都不同，几回指几次。", "知会": "zhī 与 jī 声母不同（zh 与 j），知会指通知。"}, "sentence_index": null, "correct_answer": "机会"}, "level_3": {"options": [{"text": "机会", "is_correct": true, "explanation": "正确。“难得的好”修饰的是有利的时机，只有“机会”符合。"}, {"text": "错误", "is_correct": false, "explanation": "语义：“错误”指做错的事，与“好”的褒义相冲突，句子不通。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：“灾难”是坏事，不能被“难得的好”修饰，句子不通。"}, {"text": "困难", "is_correct": false, "explanation": "语义：“困难”是不利的情况，与“难得的好”所表达的有利、珍贵之意相冲突，句子不通。"}], "explanations": {"机会": "正确。“难得的好”修饰的是有利的时机，只有“机会”符合。", "错误": "语义：“错误”指做错的事，与“好”的褒义相冲突，句子不通。", "灾难": "语义：“灾难”是坏事，不能被“难得的好”修饰，句子不通。", "困难": "语义：“困难”是不利的情况，与“难得的好”所表达的有利、珍贵之意相冲突，句子不通。"}, "sentence_index": 0, "correct_answer": "机会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们需要一段机会来准备考试。", "explanation": "这里应该用〈时间〉。“一段时间”指一段时长，“机会”不能表示时长。"}, {"text": "这个月我抽机会去看了父母。", "explanation": "这里应该用〈时间〉。“抽时间”指腾出可用的时段去做某事，“机会”不能这样用。"}, {"text": "她抓住了一只机会，成功进入了这家公司。", "explanation": "量词用错。“机会”是抽象名词，应用〈个〉或〈次〉，不能用〈只〉（〈只〉多用于动物、器物等）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10814, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "机会", "is_correct": true, "explanation": "正确。机会指具有时间性的有利情况，读作 jī huì。"}, {"text": "寄回", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，huí（第二声）与 huì（第四声）也不同，寄回指寄送返还。"}, {"text": "挤回", "is_correct": false, "explanation": "jǐ 与 jī、huí 与 huì 声调都不同，挤回指用力推回或挤回去。"}, {"text": "忌讳", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，忌讳指因顾虑而避免某些言行。"}], "explanations": {"机会": "正确。机会指具有时间性的有利情况，读作 jī huì。", "寄回": "jì（第四声）与 jī（第一声）声调不同，huí（第二声）与 huì（第四声）也不同，寄回指寄送返还。", "挤回": "jǐ 与 jī、huí 与 huì 声调都不同，挤回指用力推回或挤回去。", "忌讳": "jì（第四声）与 jī（第一声）声调不同，忌讳指因顾虑而避免某些言行。"}, "sentence_index": null, "correct_answer": "机会"}, "level_3": {"options": [{"text": "机会", "is_correct": true, "explanation": "正确。“多找”后接的是可以学习的有利机会，符合语境。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“找食物”能说，但“学习新东西”的对象应是知识或技能，与“食物”不搭。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不能用来“学习新东西”，句子语义不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以寻找来学习的事物，句子语义不通。"}], "explanations": {"机会": "正确。“多找”后接的是可以学习的有利机会，符合语境。", "食物": "搭配：“找食物”能说，但“学习新东西”的对象应是知识或技能，与“食物”不搭。", "房子": "语义：“房子”不能用来“学习新东西”，句子语义不通。", "天气": "语义：“天气”不是可以寻找来学习的事物，句子语义不通。"}, "sentence_index": 6, "correct_answer": "机会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们找到了一辆很好的机会。", "explanation": "量词用错。“机会”应用〈个〉或〈次〉，〈辆〉用于车辆，不能用于“机会”。"}, {"text": "这次比赛给了我们一场难得的机会。", "explanation": "量词用错。〈场〉多用于比赛、雨等事件，“机会”应用〈个〉或〈次〉。"}, {"text": "这间屋子的机会太小，住着不舒服。", "explanation": "这里应该用〈面积〉。“机会”不能形容空间大小，应说“面积”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该珍惜每一只学习的机会。", "corrected_sentence": "我们应该珍惜每一个学习的机会。", "error_description": "“机会”是抽象名词，量词应用“个”或“次”，不能用“只”。应说“每一个学习的机会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想要一个出国学习的机会们。", "corrected_sentence": "我想要一个出国学习的机会。", "error_description": "“机会”是抽象名词，不能加表示复数的“们”（“们”只用于指人的名词）。应说“一个出国学习的机会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10815, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "封闭式", "is_correct": true, "explanation": "“封闭式”与“开放式”相反，指不对外开放、不允许别人进入或参与。"}, {"text": "狭小", "is_correct": false, "explanation": "“狭小”只说空间小，与“开放”不构成反义关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "“陈旧”指东西老旧，与“允许参与、不设限”没有反义关系。"}, {"text": "单一", "is_correct": false, "explanation": "“单一”与“多样”相对，不是“开放”的反义词。"}], "correct_answer": "封闭式", "explanations": {"封闭式": "“封闭式”与“开放式”相反，指不对外开放、不允许别人进入或参与。", "狭小": "“狭小”只说空间小，与“开放”不构成反义关系。", "陈旧": "“陈旧”指东西老旧，与“允许参与、不设限”没有反义关系。", "单一": "“单一”与“多样”相对，不是“开放”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10815, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "封闭式", "is_correct": true, "explanation": "“封闭式”与“开放式”相反，指不对外开放、不允许别人进入或参与。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”说表面质地，与“开放”无关，不构成反义关系。"}, {"text": "懒散", "is_correct": false, "explanation": "“懒散”说人的作风，不是“开放”的反义词。"}, {"text": "独特", "is_correct": false, "explanation": "“独特”强调与众不同，与“开放”没有反义关系。"}], "correct_answer": "封闭式", "explanations": {"封闭式": "“封闭式”与“开放式”相反，指不对外开放、不允许别人进入或参与。", "粗糙": "“粗糙”说表面质地，与“开放”无关，不构成反义关系。", "懒散": "“懒散”说人的作风，不是“开放”的反义词。", "独特": "“独特”强调与众不同，与“开放”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10815, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物不封闭、不限制，允许别人进入或参与。", "primary_collocate": null, "pronunciation": "kāi fàng shì", "ipa": "kʰaɪ˥ fɑŋ˥˩ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "与此同时，约翰·凯奇等先锋派作曲家质疑传统记谱的权威性，发展出图形谱、文字谱乃至机会音乐的开放式结构，强调演奏者的再创造权。", "target_word": "开放式", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首曲子是开放式的，演奏者可以自己决定顺序。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师设计了一个开放式问题，答案不止一个。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部戏的结局是开放式的，观众可以自己想。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏是开放式的，玩家想怎么玩都可以。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛采用开放式报名，谁都可以参加。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢开放式的作业，因为没有标准答案。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目是开放式的，欢迎大家一起加入。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场讨论是开放式的，每个人都能说出想法。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用开放式管理，员工可以提出自己的意见。", "target_word": "开放式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开放式厨房", "label": "复合"}], "register": "中性", "sense_fingerprint": "不封闭、不设限、允许他人参与的方式或结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6e45d9-9c82-4a41-8650-3333a5ca1ff5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10815, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开放式", "is_correct": true, "explanation": "“开放式”指结构允许演奏者再创造，与句中“强调演奏者的再创造权”相符。"}, {"text": "封闭式", "is_correct": false, "explanation": "语义：“封闭式”结构不给演奏者留余地，与“强调演奏者的再创造权”相矛盾。"}, {"text": "固定的", "is_correct": false, "explanation": "语义：“固定”的结构已经定死，演奏者无法再创造，与句意冲突。"}, {"text": "僵硬的", "is_correct": false, "explanation": "语义：“僵硬”指死板、不能变通，与句中“强调演奏者的再创造权”及机会音乐的灵活正相反。"}], "explanations": {"开放式": "“开放式”指结构允许演奏者再创造，与句中“强调演奏者的再创造权”相符。", "封闭式": "语义：“封闭式”结构不给演奏者留余地，与“强调演奏者的再创造权”相矛盾。", "固定的": "语义：“固定”的结构已经定死，演奏者无法再创造，与句意冲突。", "僵硬的": "语义：“僵硬”指死板、不能变通，与句中“强调演奏者的再创造权”及机会音乐的灵活正相反。"}, "sentence_index": 0, "correct_answer": "开放式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次讨论会是开放式的，只允许主席一个人发言，其他人一律不能开口。", "explanation": "这里的“开放式”指不限制、允许别人参与，而句中规定只让主席一人发言、其他人不能开口，前后矛盾；此处应指“封闭式”。"}, {"text": "他是一个开放式的人，从不反对别人的意见。", "explanation": "这里应该用〈开放〉。形容人的思想和态度用“开放”，“开放式”只形容结构、方式等，不说人是开放式的。"}, {"text": "我们要保持开放式的心态，愿意接受新的想法。", "explanation": "这里应该用〈开放〉。形容心态这类抽象的态度用“开放”，不用“开放式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开放式", "is_correct": true, "explanation": "“开放式”指作业没有固定答案，与“没有标准答案”相合。"}, {"text": "标准化的", "is_correct": false, "explanation": "语义：“标准化”的作业有统一答案，与“没有标准答案”相矛盾。"}, {"text": "统一的", "is_correct": false, "explanation": "语义：“统一”意味着要求一致，与“没有标准答案”冲突。"}, {"text": "严格的", "is_correct": false, "explanation": "语义：“严格”形容要求或规定的严苛，与“没有标准答案”的开放相悖，句意不通。"}], "explanations": {"开放式": "“开放式”指作业没有固定答案，与“没有标准答案”相合。", "标准化的": "语义：“标准化”的作业有统一答案，与“没有标准答案”相矛盾。", "统一的": "语义：“统一”意味着要求一致，与“没有标准答案”冲突。", "严格的": "语义：“严格”形容要求或规定的严苛，与“没有标准答案”的开放相悖，句意不通。"}, "sentence_index": 6, "correct_answer": "开放式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家社团的入会规定是开放式的，只有会长的亲戚才能加入。", "explanation": "这里的“开放式”指不设限、允许别人加入，句中却说只有会长的亲戚才能入会，与此矛盾；此处应指“封闭式”。"}, {"text": "现在这个城市的开放式风气，让大家都愿意接受新事物。", "explanation": "这里应该用〈开放〉。形容风气这类抽象的东西用“开放”，“开放式”只形容结构或方式。"}, {"text": "他对新事物的开放式看法，让同事都很佩服。", "explanation": "这里应该用〈开放〉。形容看法、态度用“开放”，不用“开放式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校举办了一次很开放式讨论，谁都可以发言。", "corrected_sentence": "学校举办了一次开放式讨论，谁都可以发言。", "error_description": "“开放式”是区别词，不能受“很”修饰，应去掉“很”，说“开放式讨论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司采用很开放式办公，员工可以自由交流。", "corrected_sentence": "这家公司采用开放式办公，员工可以自由交流。", "error_description": "“很”不能修饰“开放式”这类分类形容词，应说“采用开放式办公”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
