INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指权力，即支配、指挥或决定事务的能力。", "primary_collocate": null, "pronunciation": "quán", "ipa": "tɕʰɥɛn˧˥", "syllable_count": 1, "sentences": [{"text": "他手里有权，说话很有分量。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有权有势，没人敢得罪他。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司里的权都在老板手里。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板把权交给了儿子。", "target_word": "权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她管着公司，手里的权很大。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王的权越来越大，大臣们很担心。", "target_word": "权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想要权，所以拼命往上爬。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个家里，权都在奶奶手上。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人有权也有钱，大家都想认识他。", "target_word": "权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官不大，但是有权，不能得罪。", "target_word": "权", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "权力", "label": "复合"}, {"form": "權", "label": "繁体"}], "register": "中性", "sense_fingerprint": "支配、指挥或决定事务的权力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f5bb7cc-792b-4587-ac47-b7d173ac9402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10821, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "权", "is_correct": true, "explanation": "正确答案：权（quán），指支配、指挥或决定事务的权力。"}, {"text": "劝", "is_correct": false, "explanation": "劝（quàn）与权（quán）声调不同，第四声，意思是劝说。"}, {"text": "圈", "is_correct": false, "explanation": "圈（quān）与权（quán）声调不同，第一声，意思是圆圈。"}, {"text": "钱", "is_correct": false, "explanation": "钱（qián）与权（quán）韵母不同（介音 i 与 u），意思是钱财。"}], "explanations": {"权": "正确答案：权（quán），指支配、指挥或决定事务的权力。", "劝": "劝（quàn）与权（quán）声调不同，第四声，意思是劝说。", "圈": "圈（quān）与权（quán）声调不同，第一声，意思是圆圈。", "钱": "钱（qián）与权（quán）韵母不同（介音 i 与 u），意思是钱财。"}, "sentence_index": null, "correct_answer": "权"}, "level_3": {"options": [{"text": "权", "is_correct": true, "explanation": "“有权”表示掌握权力，与“说话很有分量”的语境相符。"}, {"text": "草", "is_correct": false, "explanation": "语义：草是植物，手里有草并不能使人“说话很有分量”。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是自然现象，手里拿不住雨，与“说话很有分量”无关。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“手里有饭”与“说话很有分量”不搭配。"}], "explanations": {"权": "“有权”表示掌握权力，与“说话很有分量”的语境相符。", "草": "语义：草是植物，手里有草并不能使人“说话很有分量”。", "雨": "语义：雨是自然现象，手里拿不住雨，与“说话很有分量”无关。", "饭": "搭配：“手里有饭”与“说话很有分量”不搭配。"}, "sentence_index": 0, "correct_answer": "权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑了很久，身上的权都用完了。", "explanation": "这里应该用〈力气〉。“权”指支配、决定事务的权力，不能指身体的体力。"}, {"text": "这块电池的权很足，可以用很久。", "explanation": "这里应该用〈电量〉。“权力”指支配、决定事务的能力，不能指电池里储存的电能，要用“电量”。"}, {"text": "他留下的权很多，够全家人吃一辈子。", "explanation": "这里应该用〈粮食〉。“权”指支配、决定事务的权力，不能用来吃，此处要用“粮食”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10821, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "权", "is_correct": true, "explanation": "正确答案：权（quán），指支配、指挥或决定事务的权力。"}, {"text": "券", "is_correct": false, "explanation": "券（quàn）与权（quán）声调不同，第四声，意思是凭证，如优惠券。"}, {"text": "前", "is_correct": false, "explanation": "前（qián）与权（quán）韵母不同（介音 i 与 u），意思是前面。"}, {"text": "悬", "is_correct": false, "explanation": "悬（xuán）与权（quán）声母不同（x 与 q），意思是悬挂。"}], "explanations": {"权": "正确答案：权（quán），指支配、指挥或决定事务的权力。", "券": "券（quàn）与权（quán）声调不同，第四声，意思是凭证，如优惠券。", "前": "前（qián）与权（quán）韵母不同（介音 i 与 u），意思是前面。", "悬": "悬（xuán）与权（quán）声母不同（x 与 q），意思是悬挂。"}, "sentence_index": null, "correct_answer": "权"}, "level_3": {"options": [{"text": "权", "is_correct": true, "explanation": "“想要权”指想获得权力，与“拼命往上爬”的语境相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：书是纸质印刷品，不能作为“拼命往上爬”要争取的目标。"}, {"text": "花", "is_correct": false, "explanation": "语义：花是植物，不能作为“拼命往上爬”的追求对象。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不能作为“拼命往上爬”要争取的目标。"}], "explanations": {"权": "“想要权”指想获得权力，与“拼命往上爬”的语境相符。", "书": "语义：书是纸质印刷品，不能作为“拼命往上爬”要争取的目标。", "花": "语义：花是植物，不能作为“拼命往上爬”的追求对象。", "石头": "语义：石头是矿物，不能作为“拼命往上爬”要争取的目标。"}, "sentence_index": 6, "correct_answer": "权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的权很大，一拳就打倒了对手。", "explanation": "这里应该用〈力量〉。“权”指支配、决定事务的权力，不能指体力。"}, {"text": "他的数学权很好，老师经常表扬他。", "explanation": "这里应该用〈成绩〉。“权力”指支配、决定事务的能力，不能指学习的成绩，要用“成绩”。"}, {"text": "天黑了，屋里没有权，什么也看不见。", "explanation": "这里应该用〈光〉。“权”指支配、决定事务的权力，不能指照明的光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理有只权决定公司的大事。", "corrected_sentence": "经理有权决定公司的大事。", "error_description": "“有权决定”中的“权”是抽象名词，前面不能加量词“只”，应删去“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位经理有只权决定招聘的人选。", "corrected_sentence": "这位经理有权决定招聘的人选。", "error_description": "“权”前不能用量词“只”。“有权决定”中的“权”不需要量词，应删去“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb97f0ec-c305-43bc-babc-013c0ba28949') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
