INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电子音乐是指使用电子乐器、电子设备或电脑技术创作和演奏的音乐。", "primary_collocate": null, "pronunciation": "diàn zǐ yīn yuè", "ipa": "tjɛn˥˩ tsɨ˨˩˦ in˥ ɥɛ˥˩", "syllable_count": 4, "sentences": [{"text": "我最喜欢听电子音乐。", "target_word": "电子音乐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位歌手用电脑做电子音乐。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电子音乐常常用电子乐器演奏。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学学习怎么创作电子音乐。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上的派对上一直放着电子音乐。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子音乐的节奏很快，让大家都想跳舞。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听过很多国家的电子音乐。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个音乐节有很多电子音乐表演。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做电子音乐需要电脑和专门的软件。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐想把她的电子音乐放到网上。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一首电子音乐", "label": "量词"}, {"form": "一段电子音乐", "label": "量词"}, {"form": "電子音樂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用电子乐器、设备或电脑技术创作演奏的音乐类型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6e45d9-9c82-4a41-8650-3333a5ca1ff5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电子音乐", "is_correct": true, "explanation": "电子音乐是用电子乐器或电脑制作的音乐，可以用“听”来欣赏，句意通顺。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不是可以“听”的对象。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“听”的对象应是声音或音乐，电脑不能被“听”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不能用“听”来欣赏。"}], "explanations": {"电子音乐": "电子音乐是用电子乐器或电脑制作的音乐，可以用“听”来欣赏，句意通顺。", "水果": "语义：水果是食物，不是可以“听”的对象。", "电脑": "搭配：“听”的对象应是声音或音乐，电脑不能被“听”。", "房子": "语义：房子是建筑，不能用“听”来欣赏。"}, "sentence_index": 0, "correct_answer": "电子音乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天睡前读一本电子音乐。", "explanation": "这里应该用〈电子书〉。电子音乐是音乐，不能用来“读”，读的是电子书。"}, {"text": "他用这台电脑修理了一台电子音乐。", "explanation": "这里应该用〈电子产品〉。电子音乐指音乐作品，不是可以修理的设备。"}, {"text": "他用电子音乐弹了一首钢琴曲。", "explanation": "这里应该用〈电子乐器〉。电子音乐是音乐作品，不能用来弹奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电子音乐", "is_correct": true, "explanation": "电子音乐是可以听的音乐，与“听过很多国家的”搭配，句意通顺。"}, {"text": "美食", "is_correct": false, "explanation": "搭配：“听过”的对象应是音乐或声音，美食不能被“听过”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能被“听过”。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是图像或纸质的资料，不能用“听”来接触。"}], "explanations": {"电子音乐": "电子音乐是可以听的音乐，与“听过很多国家的”搭配，句意通顺。", "美食": "搭配：“听过”的对象应是音乐或声音，美食不能被“听过”。", "汽车": "语义：汽车是交通工具，不能被“听过”。", "地图": "语义：地图是图像或纸质的资料，不能用“听”来接触。"}, "sentence_index": 6, "correct_answer": "电子音乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上喝一杯电子音乐。", "explanation": "这里应该用〈饮料〉。电子音乐是音乐，不是能喝的东西，喝的是饮料。"}, {"text": "他在手机上玩了一局电子音乐。", "explanation": "这里应该用〈游戏〉。电子音乐是音乐，不是可以“玩一局”的游戏。"}, {"text": "这台电子音乐能录下老师的声音。", "explanation": "这里应该用〈录音机〉。电子音乐是音乐作品，不是能录音的设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78e1a028-4e58-4fe3-a3b8-58bcdb508236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
